//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage21FrameToPhase(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, const unsigned char *Ptr3, int PatternID, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &pMask, PHASE_PTR &PhasePtr)//2+1張灰階影像解相位
{
	const char fnName[] = "CImageAPI::GrayImage21FrameToPhase";
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3) == false ) 
	{	return false; }	

	JetMemory.free_func(pMask);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pMask, fnName, "pMask")==false || 
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr")==false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(pMask);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	if ( this->GrayImage21FrameToPhase3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, PatternID, Gamma, BasePhasePtr, NoiseParam, pMask, PhasePtr) == false )
	{	
		JetMemory.free_func(pMask);
		JetMemory.free_func(PhasePtr);
		return false;
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage21FrameToPhase3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, const unsigned char *Ptr3, int PatternID, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR pMask, PHASE_PTR PhasePtr)//2+1張灰階影像解相位	
{
	if ( this->CheckGrayImage5(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, pMask, PhasePtr) == false ) 
	{	return false; }	

	int   nPhase=0;
	float phase = 0.0f;		
	PHASE_DATA d1=0, d2=0, d3=0;
	PHASE_DATA Ave=0;
	PHASE_DATA usPhase=0;
	size_t i=0, j=0, k=0, idx=0;		
	unsigned char GammaTable[256];
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);	
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	int LowContrast = NoiseParam.PhaseLowContrastA;
	int LowPotential = NoiseParam.PhaseLowPotentialA;
	int Saturation = NoiseParam.PhaseOverSaturatedA;	
	if ( PHASE_PATTERN_B == PatternID )
	{
		LowContrast = NoiseParam.PhaseLowContrastB;
		LowPotential = NoiseParam.PhaseLowPotentialB;
		Saturation = NoiseParam.PhaseOverSaturatedB;	
	}
	if ( PHASE_PATTERN_C == PatternID )
	{
		LowContrast = NoiseParam.PhaseLowContrastC;
		LowPotential = NoiseParam.PhaseLowPotentialC;
		Saturation = NoiseParam.PhaseOverSaturatedC;	
	}

	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable); }
	//::memset(pMask, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	for ( i=0; i<BufferSize; i++ )
	{	
		//注意順序
		d1 = Ptr1[i];//SIN --Double Check, Joe 20200206(Cos)
		d3 = Ptr2[i];//COS --Double Check, Joe 20200206(Sin)
		d2 = Ptr3[i];//AVE

		if ( true == bUseGamma )
		{
			d1 = GammaTable[d1];
			d2 = GammaTable[d2];
			d3 = GammaTable[d3];			
		}

		if ( Calc21PhaseParamMask(d1, d2, d3, PhaseNoiseDef, LowContrast, LowPotential, Saturation, usPhase, pMask[i]) == false )
		{	return false; }
		if ( NULL == BasePhasePtr )
		{	PhasePtr[i] = usPhase;	}
		else
		{
			nPhase = usPhase;
			nPhase -= BasePhasePtr[i];//注意若使用unsigned short則需要更大的整數來使用, 避免溢位
			if ( nPhase < 0 ) 
			{	nPhase += PHASE_PERIOD; }
			PhasePtr[i] = static_cast<PHASE_DATA>(nPhase);
		}	
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage21FrameToPhase2Exp(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, int PatternID, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &pMask, PHASE_PTR &PhasePtr)//2+1張灰階影像解相位-2曝光
{
	const char fnName[] = "CImageAPI::GrayImage21FrameToPhase2Exp";
	if ( this->CheckGrayImage6(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrC1, PtrC2, PtrC3) == false ) 
	{	return false; }	

	JetMemory.free_func(pMask);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pMask, fnName, "pMask")==false || 
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr")==false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(pMask);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	if ( this->GrayImage21FrameToPhase2Exp3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrC1, PtrC2, PtrC3, PatternID, Gamma, BasePhasePtr, NoiseParam, pMask, PhasePtr) == false )
	{	
		JetMemory.free_func(pMask);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage21FrameToPhase2Exp3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, int PatternID, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR pMask, PHASE_PTR PhasePtr)//2+1張灰階影像解相位-2曝光
{
	if ( this->CheckGrayImage8(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, pMask, PhasePtr, PtrC1, PtrC2, PtrC3) == false ) 
	{	return false; }	

	int   nPhase=0;
	int   nPhaseA=0, nPhaseC=0;
	float phase = 0.0f;		
	PHASE_DATA dA1=0, dA2=0, dA3=0;
	PHASE_DATA dC1=0, dC2=0, dC3=0;
	PHASE_DATA Ave=0;
	PHASE_DATA usPhase=0;
	MASK_DATA MaskA=0, MaskC=0;
	PHASE_DATA PhaseA=0, PhaseC=0;
	size_t i=0, j=0, k=0, idx=0;		
	unsigned char GammaTable[256];
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);	
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	int LowContrast = NoiseParam.PhaseLowContrastA;
	int LowPotential = NoiseParam.PhaseLowPotentialA;
	int Saturation = NoiseParam.PhaseOverSaturatedA;	
	if ( PHASE_PATTERN_B == PatternID )
	{
		LowContrast = NoiseParam.PhaseLowContrastB;
		LowPotential = NoiseParam.PhaseLowPotentialB;
		Saturation = NoiseParam.PhaseOverSaturatedB;	
	}
	if ( PHASE_PATTERN_C == PatternID )
	{
		LowContrast = NoiseParam.PhaseLowContrastC;
		LowPotential = NoiseParam.PhaseLowPotentialC;
		Saturation = NoiseParam.PhaseOverSaturatedC;	
	}

	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable); }
	//::memset(pMask, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	for ( i=0; i<BufferSize; i++ )
	{	
		//注意順序
		dA1 = PtrA1[i];//SIN --Double Check, Joe 20200206(Cos)
		dA3 = PtrA2[i];//COS --Double Check, Joe 20200206(Sin)
		dA2 = PtrA3[i];//AVE

		dC1 = PtrC1[i];//SIN --Double Check, Joe 20200206(Cos)
		dC3 = PtrC2[i];//COS --Double Check, Joe 20200206(Sin)
		dC2 = PtrC3[i];//AVE

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];

			dC1 = GammaTable[dC1];
			dC2 = GammaTable[dC2];
			dC3 = GammaTable[dC3];
		}

		if ( Calc21PhaseParamMask(dA1, dA2, dA3, PhaseNoiseDef, LowContrast, LowPotential, Saturation, PhaseA, MaskA) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dC1, dC2, dC3, PhaseNoiseDef, LowContrast, LowPotential, Saturation, PhaseC, MaskC) == false )
		{	return false; }

		if ( NULL != BasePhasePtr )		
		{	
			nPhase = PhaseA;
			nPhase -= BasePhasePtr[i];//注意若使用unsigned short則需要更大的整數來使用, 避免溢位
			if ( nPhase < 0 ) 
			{	nPhase += PHASE_PERIOD; }
			nPhaseA = (nPhase);

			nPhase = PhaseC;
			nPhase -= BasePhasePtr[i];//注意若使用unsigned short則需要更大的整數來使用, 避免溢位
			if ( nPhase < 0 ) 
			{	nPhase += PHASE_PERIOD; }
			nPhaseC = (nPhase);
		}	
		Merge2ExpPhaseData(MaskA, nPhaseA, MaskC, nPhaseC, pMask[i], nPhase);
		PhasePtr[i] = static_cast<PHASE_DATA>(nPhase);
	}	
	return true;
}
