bool CImageAPI::GrayImage4FrameToPhase(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, const unsigned char *Ptr3, const unsigned char *Ptr4, int PatternID, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &MaskPtr, PHASE_PTR &PhasePtr)//4張灰階影像解相位
{
	const char fnName[] = "CImageAPI::GrayImage4FrameToPhase";
	if ( this->CheckGrayImage4(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, Ptr4) == false ) 
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr")==false || 
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr")==false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}

	if ( this->GrayImage4FrameToPhase3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, Ptr4, PatternID, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr) == false )
	{		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}		
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage4FrameToPhase3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, const unsigned char *Ptr3, const unsigned char *Ptr4, int PatternID, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr)//4張灰階影像解相位
{	
#ifdef CUDA_USE
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if (SysParam.m_CudaFnEnabled == FN_ENABLE && true==IsCudaDeviceUse )
	{		
		if ( this->CheckGrayImage6(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, Ptr4, MaskPtr, PhasePtr) == false ) 
		{	return false; }	

		const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
		//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
		//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
		if ( CudaFunc.CudaSolvePhase4Frames(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, Ptr4, PatternID, Gamma, BasePhasePtr, NoiseParam, PhasePtr, MaskPtr) == false )
		{	
			SetErrorString(CudaFunc.GetErrorString());
			return false; 
		}		
		return true;	
	}
#endif//CUDA_USE

	if ( this->CheckGrayImage6(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, Ptr4, MaskPtr, PhasePtr) == false ) 
	{	return false; }	

	int   nPhase = 0;
	float phase = 0.0f;		
	float fc=0.0f;	
	PHASE_DATA usPhase=0;
	PHASE_DATA d1=0, d2=0, d3=0, d4=0;	
	size_t i=0, j=0, k=0, idx=0;	
	unsigned char GammaTable[256];	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	int LowContrast = NoiseParam.PhaseLowContrastA;
	int LowPotential = NoiseParam.PhaseLowPotentialA;
	int Saturation = NoiseParam.PhaseOverSaturatedA;
	if ( PHASE_PATTERN_B == PatternID )
	{
		LowContrast = NoiseParam.PhaseLowContrastB;
		LowPotential = NoiseParam.PhaseLowPotentialB;
		Saturation = NoiseParam.PhaseOverSaturatedB;		
	}
	if ( PHASE_PATTERN_C == PatternID )
	{
		LowContrast = NoiseParam.PhaseLowContrastC;
		LowPotential = NoiseParam.PhaseLowPotentialC;
		Saturation = NoiseParam.PhaseOverSaturatedC;
	}

	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable); }

	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	for ( i=0; i<BufferSize; i++ )
	{	
#ifdef _DEBUG
		size_t ImageX = i%ImageStep;
		size_t ImageY = i/ImageStep;		
		if ( 1885==ImageX && 1680==ImageY )
		{	i=i; }
#endif//_DEBUG
		d1 = Ptr1[i];
		d2 = Ptr2[i];
		d3 = Ptr3[i];
		d4 = Ptr4[i];

		if ( true == bUseGamma )
		{
			d1 = GammaTable[d1];
			d2 = GammaTable[d2];
			d3 = GammaTable[d3];
			d4 = GammaTable[d4];
		}
		if ( Calc4PhaseParamMask(d1, d2, d3, d4, PhaseNoiseDef, LowContrast, LowPotential, Saturation, usPhase, MaskPtr[i], PhaseNoiseDefMode) == false )
		{	return false; }

#ifdef _DEBUG			
		if ( 1960==ImageX && 854==ImageY )
		{	i=i; }
#endif//_DEBUG

		if ( NULL == BasePhasePtr )
		{	PhasePtr[i] = usPhase;	}
		else
		{			
			nPhase = usPhase;
			nPhase -= BasePhasePtr[i];//注意若使用unsigned short則需要更大的整數來使用, 避免溢位
			if ( nPhase < 0 ) 
			{	nPhase += PHASE_PERIOD; }
			PhasePtr[i] = static_cast<PHASE_DATA>(nPhase);
		}
	}
	return true;
}
