bool CImageAPI::GrayImage4FrameToPhase2Exp(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, int PatternID, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &MaskPtr, PHASE_PTR &PhasePtr)//4張灰階影像解相位-2曝光
{
	const char fnName[] = "CImageAPI::GrayImage4FrameToPhase2Exp";
	if ( this->CheckGrayImage8(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrC1, PtrC2, PtrC3, PtrC4) == false ) 
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr")==false || 
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr")==false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}

	if ( this->GrayImage4FrameToPhase2Exp3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrC1, PtrC2, PtrC3, PtrC4, PatternID, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr) == false )
	{		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}		
	return true;	
}
