bool CImageAPI::GrayImage4FrameToPhase2Exp3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, int PatternID, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr)//4張灰階影像解相位-2曝光	
{	
#ifdef CUDA_USE
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if (SysParam.m_CudaFnEnabled == FN_ENABLE && true==IsCudaDeviceUse )
	{	
		const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
		//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
		//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
		if ( CudaFunc.CudaSolvePhase4Frames(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PatternID, Gamma, BasePhasePtr, NoiseParam, PhasePtr, MaskPtr) == false )
		{	
			SetErrorString(CudaFunc.GetErrorString());
			return false; 
		}		
		return true;	
	}
#endif//CUDA_USE
	if ( this->CheckGrayImage10(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, MaskPtr, PhasePtr, PtrC1, PtrC2, PtrC3, PtrC4) == false ) 
	{	return false; }	

	int   nPhase = 0;
	int   nPhaseA = 0;
	int   nPhaseC = 0;
	float phase = 0.0f;		
	float fc=0.0f;	
	PHASE_DATA dA1=0, dA2=0, dA3=0, dA4=0;
	PHASE_DATA dC1=0, dC2=0, dC3=0, dC4=0;	
	MASK_DATA  MaskA=0, MaskC=0;
	PHASE_DATA PhaseA=0, PhaseC=0;
	size_t i=0, j=0, k=0, idx=0;	
	unsigned char GammaTable[256];
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	int LowContrast = NoiseParam.PhaseLowContrastA;
	int LowPotential = NoiseParam.PhaseLowPotentialA;
	int Saturation = NoiseParam.PhaseOverSaturatedA;
	if ( PHASE_PATTERN_B == PatternID )
	{
		LowContrast = NoiseParam.PhaseLowContrastB;
		LowPotential = NoiseParam.PhaseLowPotentialB;
		Saturation = NoiseParam.PhaseOverSaturatedB;		
	}
	if ( PHASE_PATTERN_C == PatternID )
	{
		LowContrast = NoiseParam.PhaseLowContrastC;
		LowPotential = NoiseParam.PhaseLowPotentialC;
		Saturation = NoiseParam.PhaseOverSaturatedC;
	}

	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable); }

	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	for ( i=0; i<BufferSize; i++ )
	{	
#ifdef _DEBUG
		size_t ImageX = i%ImageStep;
		size_t ImageY = i/ImageStep;		
		if ( 1960==ImageX && 854==ImageY )
		{	i=i; }
#endif//_DEBUG
		dA1 = PtrA1[i];
		dA2 = PtrA2[i];
		dA3 = PtrA3[i];
		dA4 = PtrA4[i];

		dC1 = PtrC1[i];
		dC2 = PtrC2[i];
		dC3 = PtrC3[i];
		dC4 = PtrC4[i];

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];
			dA4 = GammaTable[dA4];

			dC1 = GammaTable[dC1];
			dC2 = GammaTable[dC2];
			dC3 = GammaTable[dC3];
			dC4 = GammaTable[dC4];
		}
		if ( Calc4PhaseParamMask(dA1, dA2, dA3, dA4, PhaseNoiseDef, LowContrast, LowPotential, Saturation, PhaseA, MaskA, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dC1, dC2, dC3, dC4, PhaseNoiseDef, LowContrast, LowPotential, Saturation, PhaseC, MaskC, PhaseNoiseDefMode) == false )
		{	return false; }

#ifdef _DEBUG			
		if ( 1960==ImageX && 854==ImageY )
		{	i=i; }
#endif//_DEBUG

		if ( NULL != BasePhasePtr )
		{
			nPhase = PhaseA;
			nPhase -= BasePhasePtr[i];//注意若使用unsigned short則需要更大的整數來使用, 避免溢位
			if ( nPhase < 0 ) 
			{	nPhase += PHASE_PERIOD; }
			nPhaseA = (nPhase);		

			nPhase = PhaseC;
			nPhase -= BasePhasePtr[i];//注意若使用unsigned short則需要更大的整數來使用, 避免溢位
			if ( nPhase < 0 ) 
			{	nPhase += PHASE_PERIOD; }
			nPhaseC = (nPhase);
		}
		this->Merge2ExpPhaseData(MaskA, nPhaseA, MaskC, nPhaseC, MaskPtr[i], nPhase);
		PhasePtr[i] = static_cast<PHASE_DATA>(nPhase);
	}
	return true;
}
