bool CImageAPI::PhaseImage2PeriodeToPhase(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const PHASE_PTR PPtr1, const MASK_PTR MPtr1, double P1, const PHASE_PTR PPtr2, const MASK_PTR MPtr2, double P2, const PHASE_PTR BasePhasePtr, PHASE_PTR &PPtrM, MASK_PTR &MPtrM, double &NewP, int CombineMode)//雙相位算出新相位
{
	const char fnName[] = "CImageAPI::PhaseImage2PeriodeToPhase";
	if ( this->CheckGrayImage4(ImageW, ImageH, ImageStep, PPtr1, MPtr1, PPtr2, MPtr2) == false )
	{	return false; }

	JetMemory.free_func(PPtrM);
	JetMemory.free_func(MPtrM);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, PPtrM, fnName, "PPtrM") == false || 
		JetMemory.alloc_func(BufferSize, MPtrM, fnName, "MPtrM") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(PPtrM);
		JetMemory.free_func(MPtrM);
		return false;
	}

	if ( this->PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PPtr1, MPtr1, P1, PPtr2, MPtr2, P2, BasePhasePtr, PPtrM, MPtrM, NewP, CombineMode) == false )
	{
		JetMemory.free_func(PPtrM);
		JetMemory.free_func(MPtrM);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PhaseImage2PeriodeToPhase3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const PHASE_PTR PPtr1, const MASK_PTR MPtr1, double P1, const PHASE_PTR PPtr2, const MASK_PTR MPtr2, double P2, const PHASE_PTR BasePhasePtr, PHASE_PTR PPtrM, MASK_PTR MPtrM, double &NewP, int CombineMode)//雙相位算出新相位
{	
	if ( COMBINE_PHASE_SIBLING_PERIOD == CombineMode )//鄰近週期
	{	return CImageAPI::PhaseImage2PeriodeToPhase3_SiblingPeriod(ImageW, ImageH, ImageStep, PPtr1, MPtr1, P1, PPtr2, MPtr2, P2, BasePhasePtr, PPtrM, MPtrM, NewP); }
	return CImageAPI::PhaseImage2PeriodeToPhase3_MaxMinPeriod(ImageW, ImageH, ImageStep, PPtr1, MPtr1, P1, PPtr2, MPtr2, P2, BasePhasePtr, PPtrM, MPtrM, NewP);//大小週期
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PhaseImage2PeriodeToPhase3_SiblingPeriod(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const PHASE_PTR PPtr1, const MASK_PTR MPtr1, double P1, const PHASE_PTR PPtr2, const MASK_PTR MPtr2, double P2, const PHASE_PTR BasePhasePtr, PHASE_PTR PPtrM, MASK_PTR MPtrM, double &NewP)//雙相位算出新相位-鄰近週期
{
	if ( CheckGrayImage6(ImageW, ImageH, ImageStep, PPtr1, MPtr1, PPtr2, MPtr2, PPtrM, MPtrM) == false )
	{	return false; }
	//PPtr1:Ptr for Phase 1
	//PPtr2:Ptr for Phase 2
	//MPtr1:Ptr for Mask 1
	//MPtr2:Ptr for Mask 2

	//int範圍為-2147483647 ~ 2147483647, 
	//unsigned short範圍為 0 ~ 65535,
	//所以相加減後為2x65535, 所以剩餘精度為16384
	//在比例倍數上[P2/(P2-P1)]，預留10倍, 1638
	//所以保留的精度為1000
	const unsigned int Precision = 1000;//千倍精度, 

	int Phase1 = 0;
	int Phase2 = 0;	
	int Phase1T = 0;
	int Phase2T = 0;	
	int nPhase = 0;
	size_t i=0;
	int MaxPhase = 0;
	int PhaseM = 0;
	int PhaseMT = 0;	
	int PhaseMNew = 0;
	int PhaseMFull = 0;
	int PhaseMFullNew = 0;
	int nPeriod = 0;	
	double dPeriod = 0.0;
	double dRatio = 0;
	double dRatio1 = 0;
	double dRatio2 = 0;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);		
	//P1 = 16;
	//P2 = 20;	
	//::memset(MPtrM, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PPtrM, 0x00, sizeof(PHASE_DATA)*BufferSize);
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用
	const double PP1 = __min(P1, P2);
	const double PP2 = __max(P1, P2);
	if ( P2 > P1 )//P2 為主
	{	
		//dRatio = PP1*Precision/(PP2-PP1); 		
		dRatio1 = PP2/(PP2-PP1);
		dRatio2 = PP1/(PP2-PP1);
	}
	else //P1為主 
	{	
		//dRatio = PP2*Precision/(PP2-PP1);	
		dRatio1 = PP1/(PP2-PP1);
		dRatio2 = PP2/(PP2-PP1);
	}	
	NewP = P1*P2/fabs(P2-P1);
	const int PhaseDummy = PHASE_PERIOD_HALF;//增加特定周期
	const int FullPeriodM1 = (int)(dRatio1*PHASE_PERIOD);//以第1週期為主的大週期
	const int FullPeriodM2 = (int)(dRatio2*PHASE_PERIOD);//以第2週期為主的大週期

														 //基本公式如下
														 //1.相位差=相位1-相位2
														 //2.如果相位差<0，則相位差加上周期
														 //3.將相位差x比例1則可得到還原後的相位1
														 //4.將相位差x比例2則可得到還原後的相位2	
	const double PhaseOffset = 0.0;
	CalcCombinePhasePeriodRatio(COMBINE_PHASE_SIBLING_PERIOD, P1, P2, dRatio);//計算合併比例
	MaxPhase = static_cast<int>(dRatio*PHASE_PERIOD);
	if ( P1 < P2 )
	{		
		for ( i=0; i<BufferSize; i++ )
		{
			Phase1 = PPtr1[i];
			Phase2 = PPtr2[i];
			PhaseM = CombinePhasePeriod_Sibling(Phase1, Phase2, dRatio);
			PPtrM[i] = static_cast<PHASE_DATA>(PhaseM);
			MPtrM[i] = CombinePhaseMask(MPtr1[i], MPtr2[i]);//合併大小週期遮罩
		}
	}
	else
	{		
		for ( i=0; i<BufferSize; i++ )
		{
			Phase1 = PPtr1[i];
			Phase2 = PPtr2[i];
			PhaseM = CombinePhasePeriod_Sibling(Phase2, Phase1, dRatio);
			PPtrM[i] = static_cast<PHASE_DATA>(PhaseM);
			MPtrM[i] = CombinePhaseMask(MPtr1[i], MPtr2[i]);//合併大小週期遮罩						
		}		
	}

	if ( NULL != BasePhasePtr )
	{
		for ( i=0; i<BufferSize; i++ )
		{	
			nPhase = PPtrM[i];			
			DeductBasePhase(BasePhasePtr[i], nPhase);			
			PPtrM[i] = static_cast<PHASE_DATA>(nPhase);
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PhaseImage2PeriodeToPhase3_MaxMinPeriod(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const PHASE_PTR PPtr1, const MASK_PTR MPtr1, double P1, const PHASE_PTR PPtr2, const MASK_PTR MPtr2, double P2, const PHASE_PTR BasePhasePtr, PHASE_PTR PPtrM, MASK_PTR MPtrM, double &NewP)//雙相位算出新相位-大小週期
{
	if ( CheckGrayImage6(ImageW, ImageH, ImageStep, PPtr1, MPtr1, PPtr2, MPtr2, PPtrM, MPtrM) == false )
	{	return false; }

	//PPtr1:Ptr for Phase 1
	//PPtr2:Ptr for Phase 2
	//MPtr1:Ptr for Mask 1
	//MPtr2:Ptr for Mask 2

	//int範圍為-2147483647 ~ 2147483647, 
	//unsigned short範圍為 0 ~ 65535,
	//所以相加減後為2x65535, 所以剩餘精度為16384
	//在比例倍數上[P2/(P2-P1)]，預留10倍, 1638
	//所以保留的精度為1000
	const unsigned int Precision = 1000;//千倍精度, 

	int Phase1 = 0;
	int Phase2 = 0;	
	int Phase1T = 0;
	int Phase2T = 0;	
	int nPhase = 0;
	size_t i=0;
	int MaxPhase = 0;
	int PhaseM = 0;
	int PhaseMT = 0;	
	int PhaseMNew = 0;
	int PhaseMFull = 0;
	int PhaseMFullNew = 0;
	int nPeriod = 0;	
	int Gray=0;
	double dValue=0.0;
	double dPeriod = 0.0;
	double dRatio = 0;
	double dRatio1 = 0;
	double dRatio2 = 0;	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);		

#ifdef _DEBUG
	IMAGE_SIZE ImageX=0;
	IMAGE_SIZE ImageY=0;
#endif//_DEBUG
	//::memset(MPtrM, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PPtrM, 0x00, sizeof(PHASE_DATA)*BufferSize);
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用
	const double PP1 = __min(P1, P2);
	const double PP2 = __max(P1, P2);
	if ( P2 > P1 )//P2 為主
	{	
		dRatio1 = P2/P1;
		dRatio2 = 1;
	}
	else //P1為主 
	{	
		dRatio1 = 1;
		dRatio2 = P1/P2;		
	}	
	//NewP = P1*P2/fabs(P2-P1);	
	NewP = __max(P1, P2);
	const int PhaseDummy = PHASE_PERIOD_HALF;//增加特定周期
	const int FullPeriodM1 = (int)(dRatio1*PHASE_PERIOD);//以第1週期為主的大週期
	const int FullPeriodM2 = (int)(dRatio2*PHASE_PERIOD);//以第2週期為主的大週期	

														 //基本公式如下
														 //1.相位差=相位1-相位2
														 //2.如果相位差<0，則相位差加上周期
														 //3.將相位差x比例1則可得到還原後的相位1
														 //4.將相位差x比例2則可得到還原後的相位2
	CalcCombinePhasePeriodRatio(COMBINE_PHASE_MAX_MIN_PERIOD, P1, P2, dRatio);//計算合併比例
	MaxPhase = static_cast<int>(dRatio*PHASE_PERIOD);//PHASE_PERIOD, PHASE_MAX
	if ( P1 < P2 )
	{		
		for ( i=0; i<BufferSize; i++ )
		{
#ifdef _DEBUG
			ImageX = i%ImageStep;
			ImageY = i/ImageStep;
			if ( 2467==ImageX && 2453==ImageY )
			{	i = i;	}
#endif//_DEBUG				
			PhaseM = CombinePhasePeriod_MaxMin(PPtr1[i], PPtr2[i], dRatio);
			//MPtrM[i] = PHASE_MASK_VALID;
			PPtrM[i] = static_cast<PHASE_DATA>(PhaseM);
			MPtrM[i] = CombinePhaseMask(MPtr1[i], MPtr2[i]);//合併大小週期遮罩
		}
	}
	else
	{
		for ( i=0; i<BufferSize; i++ )
		{
			PhaseM = CombinePhasePeriod_MaxMin(PPtr2[i], PPtr1[i], dRatio);//注意相位次序
																		   //MPtrM[i] = PHASE_MASK_VALID;
			PPtrM[i] = static_cast<PHASE_DATA>(PhaseM);		
			MPtrM[i] = CombinePhaseMask(MPtr1[i], MPtr2[i]);//合併大小週期遮罩
		}
	}

	if ( NULL != BasePhasePtr )
	{
		for ( i=0; i<BufferSize; i++ )
		{	
			nPhase = PPtrM[i];
			DeductBasePhase(BasePhasePtr[i], nPhase);
			PPtrM[i] = static_cast<PHASE_DATA>(nPhase);
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage3FrameTo2Phase(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, double PerB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &MaskPtr, PHASE_PTR &PhasePtr, double &PerD)//2個3張灰階影像解相位
{
	const char fnName[] = "CImageAPI::GrayImage3FrameTo2Phase";
	if ( this->CheckGrayImage6(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrB1, PtrB2, PtrB3) == false ) 
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false ||
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	if ( this->GrayImage3FrameTo2Phase3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PerA, PtrB1, PtrB2, PtrB3, PerB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD) == false )	
	{		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}		
	return true;
}
