bool CImageAPI::GrayImage3FrameTo2Phase3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, double PerB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//2個3張灰階影像解相位
{
	//return this->GrayImage3FrameTo2Phase3_I(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PerA, PtrB1, PtrB2, PtrB3, PerB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);//合成大週期, 雜訊多, 勿使用
	return this->GrayImage3FrameTo2Phase3_II(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PerA, PtrB1, PtrB2, PtrB3, PerB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage3FrameTo2Phase3_I(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, double PerB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//2個3張灰階影像解相位
{
	//PS::合併在一起沒有比GrayImage3FrameTo2Phase3_II來得快, 原因待查!??
	if ( this->CheckGrayImage8(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrB1, PtrB2, PtrB3, MaskPtr, PhasePtr) == false ) 
	{	return false; }

	int   nPhase = 0;
	float phase = 0.0f;		
	int   Phase1 = 0;
	int   Phase2 = 0;	
	int   PhaseM = 0;
	int   PhaseM2 = 0;
	int   PhaseM3 = 0;
	int   PhaseM4 = 0;
	int   nPeriod = 0;
	MASK_DATA  MaskA=0, MaskB=0;	
	PHASE_DATA dA1=0, dA2=0, dA3=0;
	PHASE_DATA dB1=0, dB2=0, dB3=0;	
	PHASE_DATA PhaseA=0, PhaseB=0;	
	size_t i=0, j=0, k=0, idx=0;	
	unsigned char GammaTable[256];	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;		
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();		
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);

	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用
	double dRatio = 1.0;
	const double PP1 = __min(PerA, PerB);
	const double PP2 = __max(PerA, PerB);
	if ( PerB > PerA )//P2 為主
	{	dRatio = PP1/(PP2-PP1);	}
	else //P1為主 
	{	dRatio = PP2/(PP2-PP1);	}	
	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable);	}

	PerD = Calc2PhaseNewPeriode(PerA, PerB);
	CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatio);
	for ( i=0; i<BufferSize; i++ )
	{	
		dA1 = PtrA1[i];
		dA2 = PtrA2[i];
		dA3 = PtrA3[i];		

		dB1 = PtrB1[i];
		dB2 = PtrB2[i];
		dB3 = PtrB3[i];

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];

			dB1 = GammaTable[dB1];
			dB2 = GammaTable[dB2];
			dB3 = GammaTable[dB3];
		}

		if ( Calc3PhaseParamMask(dA1, dA2, dA3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA, MaskA) == false )
		{	return false; }
		if ( Calc3PhaseParamMask(dB1, dB2, dB3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB, MaskB) == false )
		{	return false; }

		//雙週期相位合併		
		if ( PerA < PerB )
		{
			Phase1 = PhaseA;
			Phase2 = PhaseB;			
		}
		else
		{
			Phase1 = PhaseB;//注意相位次序
			Phase2 = PhaseA;//
		}	
		PhaseM = CombinePhasePeriod(CombinePeriodMode, Phase1, Phase2, dRatio);

		if ( NULL != BasePhasePtr )//扣除相平面
		{	DeductBasePhase(BasePhasePtr[i], PhaseM);}
		PhasePtr[i] = static_cast<PHASE_DATA>(PhaseM);		
		MaskPtr[i] = CombinePhaseMask(MaskA, MaskB);//合併大小週期遮罩
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage3FrameTo2Phase3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, double PerB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//2個3張灰階影像解相位
{
	if ( this->CheckGrayImage8(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrB1, PtrB2, PtrB3, MaskPtr, PhasePtr) == false ) 
	{	return false; }	

	int PatternID = 0;
	unsigned char *MaskPtrA=NULL, *MaskPtrB=NULL;
	PHASE_PTR PhasePtrA=NULL;
	PHASE_PTR PhasePtrB=NULL;	
	const int CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;

	PatternID = PHASE_PATTERN_A;
	if ( this->GrayImage3FrameToPhase(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PatternID, Gamma, NULL, NoiseParam, MaskPtrA, PhasePtrA) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		return false;
	}

	PatternID = PHASE_PATTERN_B;
	if ( this->GrayImage3FrameToPhase(ImageW, ImageH, ImageStep, PtrB1, PtrB2, PtrB3, PatternID, Gamma, NULL, NoiseParam, MaskPtrB, PhasePtrB) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		return false;
	}
	//雙週期合併
	if ( this->PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrA, MaskPtrA, PerA, PhasePtrB, MaskPtrB, PerB, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode) == false )
	{	
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		return false;
	}	
	JetMemory.free_func(MaskPtrA);
	JetMemory.free_func(PhasePtrA);
	JetMemory.free_func(MaskPtrB);
	JetMemory.free_func(PhasePtrB);
	return true;
}
