bool CImageAPI::GrayImage4FrameTo2Phase2Exp(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrD1, const unsigned char *PtrD2, const unsigned char *PtrD3, const unsigned char *PtrD4, double PerB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &MaskPtr, PHASE_PTR &PhasePtr, double &PerD)//2個4張灰階影像解相位-2曝光
{
	const char fnName[] = "CImageAPI::GrayImage4FrameTo2Phase2Exp";
	if ( this->CheckGrayImage16(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, PtrC1, PtrC2, PtrC3, PtrC4, PtrD1, PtrD2, PtrD3, PtrD4) == false ) 
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false ||
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	//	::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//	::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);  
	if ( this->GrayImage4FrameTo2Phase2Exp3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrC1, PtrC2, PtrC3, PtrC4, PerA, PtrB1, PtrB2, PtrB3, PtrB4, PtrD1, PtrD2, PtrD3, PtrD4, PerB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD) == false )	
	{		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage4FrameTo2Phase2Exp3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrD1, const unsigned char *PtrD2, const unsigned char *PtrD3, const unsigned char *PtrD4, double PerB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//2個4張灰階影像解相位-2曝光
{
#ifdef CUDA_USE
	if ( this->CheckGrayImage18(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, MaskPtr, PhasePtr, PtrC1, PtrC2, PtrC3, PtrC4, PtrD1, PtrD2, PtrD3, PtrD4) == false ) 
	{	return false; }	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if (SysParam.m_CudaFnEnabled==FN_ENABLE && true== IsCudaDeviceUse )
	{
		if ( CudaFunc.CudaSolvePhase4Frames2Period2Exp(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, PtrC1, PtrC2, PtrC3, PtrC4, PtrD1, PtrD2, PtrD3, PtrD4, PerA, PerB, Gamma, BasePhasePtr, NoiseParam, PhasePtr, MaskPtr) == false )
		{	
			SetErrorString(CudaFunc.GetErrorString());
			return false; 
		}		
		return true;	
	}	
#endif//CUDA_USE	
	//return GrayImage4FrameTo2Phase2Exp3_I(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrC1, PtrC2, PtrC3, PtrC4, PerA, PtrB1, PtrB2, PtrB3, PtrB4, PtrD1, PtrD2, PtrD3, PtrD4, PerB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);//合成大週期, 雜訊多, 勿使用
	return GrayImage4FrameTo2Phase2Exp3_II(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrC1, PtrC2, PtrC3, PtrC4, PerA, PtrB1, PtrB2, PtrB3, PtrB4, PtrD1, PtrD2, PtrD3, PtrD4, PerB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage4FrameTo2Phase2Exp3_I(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrD1, const unsigned char *PtrD2, const unsigned char *PtrD3, const unsigned char *PtrD4, double PerB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//2個4張灰階影像解相位-2曝光
{
	//PS::合併在一起沒有比GrayImage4FrameTo2Phase3_II來得快, 原因待查!??
	if ( this->CheckGrayImage18(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, MaskPtr, PhasePtr, PtrC1, PtrC2, PtrC3, PtrC4, PtrD1, PtrD2, PtrD3, PtrD4) == false ) 
	{	return false; }	

	int   nPhase = 0;
	float phase = 0.0f;		
	int   PhaseM_AB = 0;
	int   PhaseM_CD = 0;
	int    nPeriod=0;
	double dPeriod=0.0;	
	MASK_DATA  MaskA=0, MaskB=0;
	MASK_DATA  MaskC=0, MaskD=0;
	MASK_DATA  MaskAB=0, MaskCD=0;	
	PHASE_DATA dA1=0, dA2=0, dA3=0, dA4=0;
	PHASE_DATA dB1=0, dB2=0, dB3=0, dB4=0;
	PHASE_DATA dC1=0, dC2=0, dC3=0, dC4=0;
	PHASE_DATA dD1=0, dD2=0, dD3=0, dD4=0;	
	PHASE_DATA PhaseA=0, PhaseB=0;	
	PHASE_DATA PhaseC=0, PhaseD=0;
	size_t i=0, j=0, k=0, idx=0;		
	unsigned char GammaTable[256];
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);		
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	

	double dRatio1 = 0;
	double dRatio2 = 0;	
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用	
	if ( PerB > PerA )//P2 為主
	{	
		dRatio1 = PerB/PerA;
		dRatio2 = 1;
	}
	else //P1為主 
	{	
		dRatio1 = 1;
		dRatio2 = PerA/PerB;
	}

	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable); }

	PerD = Calc2PhaseNewPeriode(PerA, PerB);	
	CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatio1);
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	for ( i=0; i<BufferSize; i++ )
	{	
		dA1 = PtrA1[i];
		dA2 = PtrA2[i];
		dA3 = PtrA3[i];
		dA4 = PtrA4[i];

		dB1 = PtrB1[i];
		dB2 = PtrB2[i];
		dB3 = PtrB3[i];
		dB4 = PtrB4[i];

		dC1 = PtrC1[i];
		dC2 = PtrC2[i];
		dC3 = PtrC3[i];
		dC4 = PtrC4[i];

		dD1 = PtrD1[i];
		dD2 = PtrD2[i];
		dD3 = PtrD3[i];
		dD4 = PtrD4[i];

		if ( 10552820 == i )
		{	i = i; }

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];
			dA4 = GammaTable[dA4];

			dB1 = GammaTable[dB1];
			dB2 = GammaTable[dB2];
			dB3 = GammaTable[dB3];
			dB4 = GammaTable[dB4];

			dC1 = GammaTable[dC1];
			dC2 = GammaTable[dC2];
			dC3 = GammaTable[dC3];
			dC4 = GammaTable[dC4];

			dD1 = GammaTable[dD1];
			dD2 = GammaTable[dD2];
			dD3 = GammaTable[dD3];
			dD4 = GammaTable[dD4];
		}

		if ( Calc4PhaseParamMask(dA1, dA2, dA3, dA4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA, MaskA, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dB1, dB2, dB3, dB4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB, MaskB, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dC1, dC2, dC3, dC4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseC, MaskC, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dD1, dD2, dD3, dD4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseD, MaskD, PhaseNoiseDefMode) == false )
		{	return false; }

		//雙週期相位合併		
		if ( PerA < PerB )
		{
			PhaseM_AB = CombinePhasePeriod(CombinePeriodMode, PhaseA, PhaseB, dRatio1);
			PhaseM_CD = CombinePhasePeriod(CombinePeriodMode, PhaseC, PhaseD, dRatio1);			
		}
		else
		{
			PhaseM_AB = CombinePhasePeriod(CombinePeriodMode, PhaseB, PhaseA, dRatio1);//注意相位次序
			PhaseM_CD = CombinePhasePeriod(CombinePeriodMode, PhaseD, PhaseC, dRatio1);//注意相位次序			
		}
		if ( NULL != BasePhasePtr )//扣除相平面
		{	
			DeductBasePhase(BasePhasePtr[i], PhaseM_AB);	
			DeductBasePhase(BasePhasePtr[i], PhaseM_CD);	
		}		
		MaskAB = CombinePhaseMask(MaskA, MaskB);//合併大小週期遮罩
		MaskCD = CombinePhaseMask(MaskC, MaskD);//合併大小週期遮罩		
		Merge2ExpPhaseData(MaskAB, PhaseM_AB, MaskCD, PhaseM_CD, MaskPtr[i], nPhase);		
		PhasePtr[i] = static_cast<PHASE_DATA>(nPhase);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage4FrameTo2Phase2Exp3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrD1, const unsigned char *PtrD2, const unsigned char *PtrD3, const unsigned char *PtrD4, double PerB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//2個4張灰階影像解相位-2曝光
{
	if ( this->CheckGrayImage18(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, MaskPtr, PhasePtr, PtrC1, PtrC2, PtrC3, PtrC4, PtrD1, PtrD2, PtrD3, PtrD4) == false ) 
	{	return false; }	

	int PatternID = 0;
	unsigned char *MaskPtrA=NULL, *MaskPtrB=NULL;
	unsigned char *MaskPtrC=NULL, *MaskPtrD=NULL;
	PHASE_PTR PhasePtrA=NULL;
	PHASE_PTR PhasePtrB=NULL;
	PHASE_PTR PhasePtrC=NULL;
	PHASE_PTR PhasePtrD=NULL;
	const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);
	const int    CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;

	PatternID = PHASE_PATTERN_A;
	if ( GrayImage4FrameToPhase(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PatternID, Gamma, NULL, NoiseParam, MaskPtrA, PhasePtrA) == false )
	{	
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}
	PatternID = PHASE_PATTERN_A;
	if ( GrayImage4FrameToPhase(ImageW, ImageH, ImageStep, PtrC1, PtrC2, PtrC3, PtrC4, PatternID, Gamma, NULL, NoiseParam, MaskPtrC, PhasePtrC) == false )
	{	
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}

	PatternID = PHASE_PATTERN_B;
	if ( GrayImage4FrameToPhase(ImageW, ImageH, ImageStep, PtrB1, PtrB2, PtrB3, PtrB4, PatternID, Gamma, NULL, NoiseParam, MaskPtrB, PhasePtrB) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}
	PatternID = PHASE_PATTERN_B;
	if ( GrayImage4FrameToPhase(ImageW, ImageH, ImageStep, PtrD1, PtrD2, PtrD3, PtrD4, PatternID, Gamma, NULL, NoiseParam, MaskPtrD, PhasePtrD) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}
	//雙週期合併
	if ( this->PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrA, MaskPtrA, PerA, PhasePtrB, MaskPtrB, PerB, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}	
	//暫借PhaseA, MaskA記憶體空間
	::memcpy(MaskPtrA, MaskPtr, sizeof(MASK_DATA)*BufferSize);
	::memcpy(PhasePtrA, PhasePtr, sizeof(PHASE_DATA)*BufferSize);

	if ( this->PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrC, MaskPtrC, PerA, PhasePtrD, MaskPtrD, PerB, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}	
	//暫借PhaseA, MaskA記憶體空間
	::memcpy(MaskPtrC, MaskPtr, sizeof(MASK_DATA)*BufferSize);
	::memcpy(PhasePtrC, PhasePtr, sizeof(PHASE_DATA)*BufferSize);

	const bool bOpenMP = false;
	if ( Merge2ExpPhaseImage3(ImageW, ImageH, ImageStep, PhasePtrA, MaskPtrA, PhasePtrC, MaskPtrC, bOpenMP, PhasePtr, MaskPtr) == false )
	{
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}

	JetMemory.free_func(MaskPtrA);
	JetMemory.free_func(PhasePtrA);
	JetMemory.free_func(MaskPtrB);
	JetMemory.free_func(PhasePtrB);
	JetMemory.free_func(MaskPtrC);
	JetMemory.free_func(PhasePtrC);
	JetMemory.free_func(MaskPtrD);
	JetMemory.free_func(PhasePtrD);
	return true;
}
