bool CImageAPI::GrayImage5FrameTo2Phase2Exp(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrA5, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, const unsigned char *PtrC5, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrB5, const unsigned char *PtrD1, const unsigned char *PtrD2, const unsigned char *PtrD3, const unsigned char *PtrD4, const unsigned char *PtrD5, double PerB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &MaskPtr, PHASE_PTR &PhasePtr, double &PerD)//2個5張灰階影像解相位-2曝光 
{
	const char fnName[] = "CImageAPI::GrayImage5FrameTo2Phase2Exp";
	if ( this->CheckGrayImage20(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PtrC1, PtrC2, PtrC3, PtrC4, PtrC5, PtrD1, PtrD2, PtrD3, PtrD4, PtrD5) == false ) 
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false ||
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}	
	if ( this->GrayImage5FrameTo2Phase2Exp3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PtrC1, PtrC2, PtrC3, PtrC4, PtrC5, PerA, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PtrD1, PtrD2, PtrD3, PtrD4, PtrD5, PerB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD) == false )	
	{		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}			
	return true;
}
