bool CImageAPI::GrayImage5FrameTo2Phase2Exp3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrA5, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, const unsigned char *PtrC5, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrB5, const unsigned char *PtrD1, const unsigned char *PtrD2, const unsigned char *PtrD3, const unsigned char *PtrD4, const unsigned char *PtrD5, double PerB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//2個5張灰階影像解相位-2曝光 
{
	//return this->GrayImage5FrameTo2Phase2Exp3_I(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PtrC1, PtrC2, PtrC3, PtrC4, PtrC5, PerA, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PtrD1, PtrD2, PtrD3, PtrD4, PtrD5, PerB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);//合成大週期, 雜訊多, 勿使用
	return this->GrayImage5FrameTo2Phase2Exp3_II(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PtrC1, PtrC2, PtrC3, PtrC4, PtrC5, PerA, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PtrD1, PtrD2, PtrD3, PtrD4, PtrD5, PerB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage5FrameTo2Phase2Exp3_I(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrA5, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, const unsigned char *PtrC5, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrB5, const unsigned char *PtrD1, const unsigned char *PtrD2, const unsigned char *PtrD3, const unsigned char *PtrD4, const unsigned char *PtrD5, double PerB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//2個5張灰階影像解相位-2曝光 
{
	//PS::合併在一起沒有比GrayImage5FrameTo2Phase3_II來得快, 原因待查!??
	if ( this->CheckGrayImage22(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, MaskPtr, PhasePtr, PtrC1, PtrC2, PtrC3, PtrC4, PtrC5, PtrD1, PtrD2, PtrD3, PtrD4, PtrD5) == false ) 
	{	return false; }	

	int   nPhase = 0;
	float phase = 0.0f;		
	int   PhaseM_AB = 0;
	int   PhaseM_CD = 0;
	MASK_DATA  MaskA=0, MaskB=0;
	MASK_DATA  MaskC=0, MaskD=0;
	MASK_DATA  MaskAB=0, MaskCD=0;	
	PHASE_DATA dA1=0, dA2=0, dA3=0, dA4=0, dA5=0;
	PHASE_DATA dB1=0, dB2=0, dB3=0, dB4=0, dB5=0;
	PHASE_DATA dC1=0, dC2=0, dC3=0, dC4=0, dC5=0;
	PHASE_DATA dD1=0, dD2=0, dD3=0, dD4=0, dD5=0;	
	PHASE_DATA PhaseA=0, PhaseB=0;	
	PHASE_DATA PhaseC=0, PhaseD=0;		
	size_t i=0, j=0, k=0, idx=0;
	unsigned char GammaTable[256];
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;

	double dRatio1 = 0;
	double dRatio2 = 0;	
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用	
	if ( PerB > PerA )//P2 為主
	{	
		dRatio1 = PerB/PerA;
		dRatio2 = 1;
	}
	else //P1為主 
	{	
		dRatio1 = 1;
		dRatio2 = PerA/PerB;
	}

	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);

	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable); }

	PerD = Calc2PhaseNewPeriode(PerA, PerB);
	CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatio1);
	for ( i=0; i<BufferSize; i++ )
	{
		dA1 = PtrA1[i];
		dA2 = PtrA2[i];
		dA3 = PtrA3[i];
		dA4 = PtrA4[i];
		dA5 = PtrA5[i];

		dB1 = PtrB1[i];
		dB2 = PtrB2[i];
		dB3 = PtrB3[i];
		dB4 = PtrB4[i];
		dB5 = PtrB5[i];

		dC1 = PtrC1[i];
		dC2 = PtrC2[i];
		dC3 = PtrC3[i];
		dC4 = PtrC4[i];
		dC5 = PtrC5[i];

		dD1 = PtrD1[i];
		dD2 = PtrD2[i];
		dD3 = PtrD3[i];
		dD4 = PtrD4[i];
		dD5 = PtrD5[i];

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];
			dA4 = GammaTable[dA4];
			dA5 = GammaTable[dA5];

			dB1 = GammaTable[dB1];
			dB2 = GammaTable[dB2];
			dB3 = GammaTable[dB3];
			dB4 = GammaTable[dB4];
			dB5 = GammaTable[dB5];

			dC1 = GammaTable[dC1];
			dC2 = GammaTable[dC2];
			dC3 = GammaTable[dC3];
			dC4 = GammaTable[dC4];
			dC5 = GammaTable[dC5];

			dD1 = GammaTable[dD1];
			dD2 = GammaTable[dD2];
			dD3 = GammaTable[dD3];
			dD4 = GammaTable[dD4];
			dD5 = GammaTable[dD5];
		}

		if ( Calc5PhaseParamMask(dA1, dA2, dA3, dA4, dA5, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA, MaskA) == false )
		{	return false; }
		if ( Calc5PhaseParamMask(dB1, dB2, dB3, dB4, dB5, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB, MaskB) == false )
		{	return false; }
		if ( Calc5PhaseParamMask(dC1, dC2, dC3, dC4, dC5, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseC, MaskC) == false )
		{	return false; }
		if ( Calc5PhaseParamMask(dD1, dD2, dD3, dD4, dD5, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseD, MaskD) == false )
		{	return false; }

		//雙週期相位合併		
		if ( PerA < PerB )
		{
			PhaseM_AB = CombinePhasePeriod(CombinePeriodMode, PhaseA, PhaseB, dRatio1);
			PhaseM_CD = CombinePhasePeriod(CombinePeriodMode, PhaseC, PhaseD, dRatio1);			
		}
		else
		{
			PhaseM_AB = CombinePhasePeriod(CombinePeriodMode, PhaseB, PhaseA, dRatio1);//注意相位次序
			PhaseM_CD = CombinePhasePeriod(CombinePeriodMode, PhaseD, PhaseC, dRatio1);//注意相位次序			
		}			

		if ( NULL != BasePhasePtr )//扣除相平面
		{	
			DeductBasePhase(BasePhasePtr[i], PhaseM_AB);	
			DeductBasePhase(BasePhasePtr[i], PhaseM_CD);	
		}

		MaskAB = CombinePhaseMask(MaskA, MaskB);//合併大小週期遮罩
		MaskCD = CombinePhaseMask(MaskC, MaskD);//合併大小週期遮罩		
		Merge2ExpPhaseData(MaskAB, PhaseM_AB, MaskCD, PhaseM_CD, MaskPtr[i], nPhase);
		PhasePtr[i] = static_cast<PHASE_DATA>(nPhase);	
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage5FrameTo2Phase2Exp3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrA5, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, const unsigned char *PtrC5, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrB5, const unsigned char *PtrD1, const unsigned char *PtrD2, const unsigned char *PtrD3, const unsigned char *PtrD4, const unsigned char *PtrD5, double PerB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//2個5張灰階影像解相位-2曝光 
{	
	if ( this->CheckGrayImage22(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, MaskPtr, PhasePtr, PtrC1, PtrC2, PtrC3, PtrC4, PtrC5, PtrD1, PtrD2, PtrD3, PtrD4, PtrD5) == false ) 
	{	return false; }	

	int PatternID = 0;
	unsigned char *MaskPtrA=NULL, *MaskPtrB=NULL;
	unsigned char *MaskPtrC=NULL, *MaskPtrD=NULL;
	PHASE_PTR PhasePtrA=NULL;
	PHASE_PTR PhasePtrB=NULL;
	PHASE_PTR PhasePtrC=NULL;
	PHASE_PTR PhasePtrD=NULL;
	const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);
	const int    CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;

	PatternID = PHASE_PATTERN_A;
	if ( GrayImage5FrameToPhase(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PatternID, Gamma, NULL, NoiseParam, MaskPtrA, PhasePtrA) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}
	PatternID = PHASE_PATTERN_A;
	if ( GrayImage5FrameToPhase(ImageW, ImageH, ImageStep, PtrC1, PtrC2, PtrC3, PtrC4, PtrC5, PatternID, Gamma, NULL, NoiseParam, MaskPtrC, PhasePtrC) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}

	PatternID = PHASE_PATTERN_B;
	if ( GrayImage5FrameToPhase(ImageW, ImageH, ImageStep, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PatternID, Gamma, NULL, NoiseParam, MaskPtrB, PhasePtrB) == false )
	{
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}
	PatternID = PHASE_PATTERN_B;
	if ( GrayImage5FrameToPhase(ImageW, ImageH, ImageStep, PtrD1, PtrD2, PtrD3, PtrD4, PtrD5, PatternID, Gamma, NULL, NoiseParam, MaskPtrD, PhasePtrD) == false )
	{
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}
	//雙週期合併
	if ( PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrA, MaskPtrA, PerA, PhasePtrB, MaskPtrB, PerB, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}	
	//暫借PhaseA, MaskA記憶體空間
	::memcpy(MaskPtrA, MaskPtr, sizeof(MASK_DATA)*BufferSize);
	::memcpy(PhasePtrA, PhasePtr, sizeof(PHASE_DATA)*BufferSize);

	if ( PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrC, MaskPtrC, PerA, PhasePtrD, MaskPtrD, PerB, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}	
	//暫借PhaseA, MaskA記憶體空間
	::memcpy(MaskPtrC, MaskPtr, sizeof(MASK_DATA)*BufferSize);
	::memcpy(PhasePtrC, PhasePtr, sizeof(PHASE_DATA)*BufferSize);

	const bool bOpenMP = false;
	if ( Merge2ExpPhaseImage3(ImageW, ImageH, ImageStep, PhasePtrA, MaskPtrA, PhasePtrC, MaskPtrC, bOpenMP, PhasePtr, MaskPtr) == false )
	{
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		JetMemory.free_func(MaskPtrD);
		JetMemory.free_func(PhasePtrD);
		return false;
	}

	JetMemory.free_func(MaskPtrA);
	JetMemory.free_func(PhasePtrA);
	JetMemory.free_func(MaskPtrB);
	JetMemory.free_func(PhasePtrB);
	JetMemory.free_func(MaskPtrC);
	JetMemory.free_func(PhasePtrC);
	JetMemory.free_func(MaskPtrD);
	JetMemory.free_func(PhasePtrD);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage221FrameTo2Phase(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, double PerA, int ExpTimeA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, double PerB, int ExpTimeB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &MaskPtr, PHASE_PTR &PhasePtr, double &PerD)//2+2張灰階影像解相位
{
	const char fnName[] = "CImageAPI::GrayImage221FrameTo2Phase";
	if ( this->CheckGrayImage5(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrB1, PtrB2, PtrB3) == false ) 
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false ||
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	//	::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//	::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	if ( this->GrayImage221FrameTo2Phase3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PerA, ExpTimeA, PtrB1, PtrB2, PtrB3, PerB, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD) == false )	
	{		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage221FrameTo2Phase3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, double PerA, int ExpTimeA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, double PerB, int ExpTimeB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//2+2張灰階影像解相位	
{
	if (this->CheckGrayImage7(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrB1, PtrB2, PtrB3, MaskPtr, PhasePtr) == false) { return false; }
#ifdef CUDA_USE	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if (SysParam.m_CudaFnEnabled==FN_ENABLE && true== IsCudaDeviceUse )
	{
		if ( CudaFunc.CudaSolvePhase221Frames2Period(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrB1, PtrB2, PtrB3, PerA, PerB, ExpTimeA, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, PhasePtr, MaskPtr) == false )
		{	
			SetErrorString(CudaFunc.GetErrorString());
			return false; 
		}		
		return true;	
	}	
#endif//CUDA_USE

	if (false == IsCudaDeviceUse)
	{
#pragma region CPU
		//if (this->CheckGrayImage7(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrB1, PtrB2, PtrB3, MaskPtr, PhasePtr) == false) { return false; }
		PHASE_DATA PhaseA = 0, PhaseB = 0, PhaseM = 0;
		MASK_DATA MaskA = 0, MaskB = 0, MaskM = 0;
		PHASE_DATA dA1 = 0, dA2 = 0, dB1 = 0, dB2 = 0, dB3 = 0;
		int SinA = 0, CosA = 0, SinB = 0, CosB = 0;

		unsigned char GammaTable[256];
		//const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
		const int CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
		const bool bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();
		const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
		const int LowContrastA = NoiseParam.PhaseLowContrastA;
		const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
		const int SaturationA = NoiseParam.PhaseOverSaturatedA;
		const int LowContrastB = NoiseParam.PhaseLowContrastB;
		const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
		const int SaturationB = NoiseParam.PhaseOverSaturatedB;
		const float ExpTimeRatio = (float)(ExpTimeB*1.0f / ExpTimeA);
		double dRatio = 0;

		if (true == bUseGamma) { BuildGammaLookUpTable(Gamma, GammaTable); }

		PerD = Calc2PhaseNewPeriode(PerA, PerB);
		CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatio);

		for (size_t i = 0; i < BufferSize; i++)
		{
			dA1 = PtrA1[i]; dA2 = PtrA2[i];//Period 1, cos, -sin(cos90)
			dB1 = PtrB1[i]; dB2 = PtrB2[i];//Period 2, cos, -sin(cos90)
			dB3 = PtrB3[i];//Average
			if (true == bUseGamma)
			{
				dA1 = GammaTable[dA1];
				dA2 = GammaTable[dA2];

				dB1 = GammaTable[dB1];
				dB2 = GammaTable[dB2];
				dB3 = GammaTable[dB3];
			}

			if (Calc21PhaseParamMask(dA1, dB3, dA2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA, MaskA) == false) { return false; }
			if (Calc21PhaseParamMask(dB1, dB3, dB2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB, MaskB) == false) { return false; }

			//SinA = dA2 - dB3;
			//CosA = dA1 - dB3;
			//SinB = dB2 - dB3;
			//CosB = dB1 - dB3;
			//if (this->CalcArctangent(SinA, CosA, PhaseA) == false) { return false; }
			//if (this->CalcArctangent(SinB, CosB, PhaseB) == false) { return false; }

			if (PerB > PerA) { PhaseM = CombinePhasePeriod(CombinePeriodMode, PhaseA, PhaseB, dRatio); }
			else { PhaseM = CombinePhasePeriod(CombinePeriodMode, PhaseB, PhaseA, dRatio); }

			if (NULL != BasePhasePtr)
			{
				PhaseM -= BasePhasePtr[i];//注意若使用unsigned short則需要更大的整數來使用, 避免溢位
				if (PhaseM < 0) { PhaseM += PHASE_PERIOD; }
				else if (PhaseM > PHASE_PERIOD) { PhaseM -= PHASE_PERIOD; }
			}

			MaskM = CombinePhaseMask(MaskA, MaskB);

			MaskPtr[i] = MaskM;
			PhasePtr[i] = PhaseM;
		}
		return true;
#pragma endregion
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage221FrameTo2Phase2Exp(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrC1, const unsigned char *PtrC2, double PerA, int ExpTimeA, int ExpTimeC, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrD1, const unsigned char *PtrD2, const unsigned char *PtrD3, double PerB, int ExpTimeB, int ExpTimeD, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &MaskPtr, PHASE_PTR &PhasePtr, double &PerD)//2+2張灰階影像解相位-2曝光
{
	const char fnName[] = "CImageAPI::GrayImage221FrameTo2Phase2Exp";
	if ( this->CheckGrayImage10(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrB1, PtrB2, PtrB3, PtrC1, PtrC2, PtrD1, PtrD2, PtrD3) == false ) 
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false ||
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	//	::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//	::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);  
	if ( this->GrayImage221FrameTo2Phase2Exp3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrC1, PtrC2, PerA, ExpTimeA, ExpTimeC, PtrB1, PtrB2, PtrB3, PtrD1, PtrD2, PtrD3, PerB, ExpTimeB, ExpTimeD, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD) == false )	
	{		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage221FrameTo2Phase2Exp3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrC1, const unsigned char *PtrC2, double PerA, int ExpTimeA, int ExpTimeC, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrD1, const unsigned char *PtrD2, const unsigned char *PtrD3, double PerB, int ExpTimeB, int ExpTimeD, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//2+2張灰階影像解相位-2曝光
{
	if ( this->CheckGrayImage12(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrB1, PtrB2, PtrB3, MaskPtr, PhasePtr, PtrC1, PtrC2, PtrD1, PtrD2, PtrD3) == false ) 
	{	return false; }	
#ifdef CUDA_USE	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if (SysParam.m_CudaFnEnabled==FN_ENABLE && true== IsCudaDeviceUse )
	{
		if ( CudaFunc.CudaSolvePhase221Frames2Period2Exp(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrB1, PtrB2, PtrB3, PtrC1, PtrC2, PtrD1, PtrD2, PtrD3, PerA, PerB, ExpTimeA, ExpTimeB, ExpTimeC, ExpTimeD, Gamma, BasePhasePtr, NoiseParam, PhasePtr, MaskPtr) == false )
		{	
			SetErrorString(CudaFunc.GetErrorString());
			return false; 
		}		
		return true;	
	}	
#endif//CUDA_USE		

	if (false == IsCudaDeviceUse)
	{
#pragma region CPU
		//if (this->CheckGrayImage12(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrB1, PtrB2, PtrB3, MaskPtr, PhasePtr, PtrC1, PtrC2, PtrD1, PtrD2, PtrD3) == false) { return false; }
		int nPhase = 0;
		PHASE_DATA PhaseA = 0, PhaseB = 0, PhaseAB = 0, PhaseC = 0, PhaseD = 0, PhaseCD = 0;
		MASK_DATA MaskA = 0, MaskB = 0, MaskAB = 0, MaskC = 0, MaskD = 0, MaskCD = 0;
		PHASE_DATA dA1 = 0, dA2 = 0, dB1 = 0, dB2 = 0, dB3 = 0;
		PHASE_DATA dC1 = 0, dC2 = 0, dD1 = 0, dD2 = 0, dD3 = 0;
		int SinA = 0, CosA = 0, SinB = 0, CosB = 0, SinC = 0, CosC = 0, SinD = 0, CosD = 0;

		unsigned char GammaTable[256];
		//const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
		const int CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
		const bool bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();
		const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
		const int LowContrastA = NoiseParam.PhaseLowContrastA;
		const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
		const int SaturationA = NoiseParam.PhaseOverSaturatedA;
		const int LowContrastB = NoiseParam.PhaseLowContrastB;
		const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
		const int SaturationB = NoiseParam.PhaseOverSaturatedB;
		const float ExpTimeRatio = (float)(ExpTimeB*1.0f / ExpTimeA);
		double dRatio = 0;

		if (true == bUseGamma) { BuildGammaLookUpTable(Gamma, GammaTable); }

		PerD = Calc2PhaseNewPeriode(PerA, PerB);
		CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatio);

		for (size_t i = 0; i < BufferSize; i++)
		{
			//Exp1
			dA1 = PtrA1[i]; dA2 = PtrA2[i];//Period 1, cos, -sin
			dB1 = PtrB1[i]; dB2 = PtrB2[i];//Period 2, cos, -sin
			dB3 = PtrB3[i];//Average
						   //Exp 2
			dC1 = PtrC1[i]; dC2 = PtrC2[i];//Period 1, cos, -sin
			dD1 = PtrD1[i]; dD2 = PtrD2[i];//Period 2, cos, -sin
			dD3 = PtrD3[i];//Average
			if (true == bUseGamma)
			{
				dA1 = GammaTable[dA1];
				dA2 = GammaTable[dA2];

				dB1 = GammaTable[dB1];
				dB2 = GammaTable[dB2];
				dB3 = GammaTable[dB3];

				dC1 = GammaTable[dC1];
				dC2 = GammaTable[dC2];

				dD1 = GammaTable[dD1];
				dD2 = GammaTable[dD2];
				dD3 = GammaTable[dD3];
			}

			if (Calc21PhaseParamMask(dA1, dB3, dA2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA, MaskA) == false) { return false; }
			if (Calc21PhaseParamMask(dB1, dB3, dB2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB, MaskB) == false) { return false; }
			if (Calc21PhaseParamMask(dC1, dD3, dC2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseC, MaskC) == false) { return false; }
			if (Calc21PhaseParamMask(dD1, dD3, dD2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseD, MaskD) == false) { return false; }

			//SinA = dA2 - dB3;
			//CosA = dA1 - dB3;
			//SinB = dB2 - dB3;
			//CosB = dB1 - dB3;
			//SinC = dC2 - dD3;
			//CosC = dC1 - dD3;
			//SinD = dD2 - dD3;
			//CosD = dD1 - dD3;
			//if (this->CalcArctangent(SinA, CosA, PhaseA) == false) { return false; }
			//if (this->CalcArctangent(SinB, CosB, PhaseB) == false) { return false; }
			//if (this->CalcArctangent(SinC, CosC, PhaseC) == false) { return false; }
			//if (this->CalcArctangent(SinD, CosD, PhaseD) == false) { return false; }

			if (PerB > PerA)
			{
				PhaseAB = CombinePhasePeriod(CombinePeriodMode, PhaseA, PhaseB, dRatio);
				PhaseCD = CombinePhasePeriod(CombinePeriodMode, PhaseC, PhaseD, dRatio);
			}
			else
			{
				PhaseAB = CombinePhasePeriod(CombinePeriodMode, PhaseB, PhaseA, dRatio);
				PhaseCD = CombinePhasePeriod(CombinePeriodMode, PhaseD, PhaseC, dRatio);
			}

			if (NULL != BasePhasePtr)
			{
				PhaseAB -= BasePhasePtr[i];//注意若使用unsigned short則需要更大的整數來使用, 避免溢位
				if (PhaseAB < 0) { PhaseAB += PHASE_PERIOD; }
				else if (PhaseAB > PHASE_PERIOD) { PhaseAB -= PHASE_PERIOD; }

				PhaseCD -= BasePhasePtr[i];//注意若使用unsigned short則需要更大的整數來使用, 避免溢位
				if (PhaseCD < 0) { PhaseCD += PHASE_PERIOD; }
				else if (PhaseCD > PHASE_PERIOD) { PhaseCD -= PHASE_PERIOD; }
			}

			MaskAB = CombinePhaseMask(MaskA, MaskB);
			MaskCD = CombinePhaseMask(MaskC, MaskD);

			Merge2ExpPhaseData(MaskAB, PhaseAB, MaskCD, PhaseCD, MaskPtr[i], nPhase);

			PhasePtr[i] = static_cast<PHASE_DATA>(nPhase);
		}
		return true;
#pragma endregion
	}

	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage42FrameTo2Phase(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, double PerA, int ExpTimeA, const unsigned char *PtrB1, const unsigned char *PtrB2, double PerB, int ExpTimeB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &MaskPtr, PHASE_PTR &PhasePtr, double &PerD)//4+2張灰階影像解相位
{
	const char fnName[] = "CImageAPI::GrayImage42FrameTo2Phase";
	if ( this->CheckGrayImage6(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2) == false ) 
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false ||
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	//	::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//	::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	if ( this->GrayImage42FrameTo2Phase3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PerA, ExpTimeA, PtrB1, PtrB2, PerB, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD) == false )	
	{		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage42FrameTo2Phase3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, double PerA, int ExpTimeA, const unsigned char *PtrB1, const unsigned char *PtrB2, double PerB, int ExpTimeB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//4+2張灰階影像解相位
{
#ifdef CUDA_USE
	if ( this->CheckGrayImage8(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, MaskPtr, PhasePtr) == false ) 
	{	return false; }	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if (SysParam.m_CudaFnEnabled==FN_ENABLE && true== IsCudaDeviceUse )
	{
		if ( CudaFunc.CudaSolvePhase42Frames2Period(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PerA, PerB, ExpTimeA, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, PhasePtr, MaskPtr) == false )
		{	
			SetErrorString(CudaFunc.GetErrorString());
			return false; 
		}		
		return true;	
	}	
#endif//CUDA_USE
	return GrayImage42FrameTo2Phase3_II(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PerA, ExpTimeA, PtrB1, PtrB2, PerB, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage42FrameTo2Phase3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, double PerA, int ExpTimeA, const unsigned char *PtrB1, const unsigned char *PtrB2, double PerB, int ExpTimeB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//4+2張灰階影像解相位
{
	//PS::合併在一起沒有比GrayImage4FrameTo2Phase3_II來得快, 原因待查!??
	if ( this->CheckGrayImage8(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, MaskPtr, PhasePtr) == false ) 
	{	return false; }	

	int   nPhase = 0;
	float phase = 0.0f;		
	int   Phase1 = 0;
	int   Phase2 = 0;	
	int   PhaseM = 0;
	int   PhaseMT = 0;	
	int   PhaseMNew = 0;	
	int   PhaseMFull = 0;
	int   PhaseMFullNew = 0;	
	int    nPeriod=0;
	double dPeriod=0.0;
	MASK_DATA  MaskA=0, MaskB=0;	
	PHASE_DATA dA1=0, dA2=0, dA3=0, dA4=0;
	PHASE_DATA dB1=0, dB2=0, dB3=0;	
	PHASE_DATA PhaseA=0, PhaseB=0;	
	size_t i=0, j=0, k=0, idx=0;		
	unsigned char GammaTable[256];
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);		
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	
	const float ExpTimeRatio = (float)(ExpTimeB*1.0f/ExpTimeA);

	double dRatio1 = 0;
	double dRatio2 = 0;	
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用	
	if ( PerB > PerA )//P2 為主
	{	
		dRatio1 = PerB/PerA;
		dRatio2 = 1;
	}
	else //P1為主 
	{	
		dRatio1 = 1;
		dRatio2 = PerA/PerB;
	}

	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable); }

	PerD = Calc2PhaseNewPeriode(PerA, PerB);	
	CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatio1);
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	for ( i=0; i<BufferSize; i++ )
	{	
		dA1 = PtrA1[i];
		dA2 = PtrA2[i];
		dA3 = PtrA3[i];
		dA4 = PtrA4[i];

		dB1 = PtrB1[i];
		dB3 = PtrB2[i];		
		dB2 = (dA1+dA2+dA3+dA4)>>2;		
		dB2 = (int)((ExpTimeRatio*dB2)+0.5f);

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];
			dA4 = GammaTable[dA4];

			dB1 = GammaTable[dB1];
			dB2 = GammaTable[dB2];
			dB3 = GammaTable[dB3];			
		}

		if ( Calc4PhaseParamMask(dA1, dA2, dA3, dA4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA, MaskA, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dB1, dB2, dB3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB, MaskB) == false )
		{	return false; }

		//雙週期相位合併		
		if ( PerA < PerB )
		{
			Phase1 = PhaseA;
			Phase2 = PhaseB;			
		}
		else
		{
			Phase1 = PhaseB;//注意相位次序
			Phase2 = PhaseA;//			
		}
		PhaseM = CombinePhasePeriod(CombinePeriodMode, Phase1, Phase2, dRatio1);

		if ( NULL != BasePhasePtr )//扣除相平面
		{	DeductBasePhase(BasePhasePtr[i], PhaseM);	}
		PhasePtr[i] = static_cast<PHASE_DATA>(PhaseM);
		MaskPtr[i] = CombinePhaseMask(MaskA, MaskB);//合併大小週期遮罩		
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage42FrameTo2Phase2Exp(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, double PerA, int ExpTimeA, int ExpTimeC, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrD1, const unsigned char *PtrD2, double PerB, int ExpTimeB, int ExpTimeD, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &MaskPtr, PHASE_PTR &PhasePtr, double &PerD)//4+2張灰階影像解相位-2曝光
{
	const char fnName[] = "CImageAPI::GrayImage42FrameTo2Phase2Exp";
	if ( this->CheckGrayImage12(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrC1, PtrC2, PtrC3, PtrC4, PtrD1, PtrD2) == false ) 
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false ||
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	//	::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//	::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);  
	if ( this->GrayImage42FrameTo2Phase2Exp3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrC1, PtrC2, PtrC3, PtrC4, PerA, ExpTimeA, ExpTimeC, PtrB1, PtrB2, PtrD1, PtrD2, PerB, ExpTimeB, ExpTimeD, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD) == false )	
	{		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage42FrameTo2Phase2Exp3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, double PerA, int ExpTimeA, int ExpTimeC, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrD1, const unsigned char *PtrD2, double PerB, int ExpTimeB, int ExpTimeD, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//4+2張灰階影像解相位-2曝光
{
#ifdef CUDA_USE
	if ( this->CheckGrayImage14(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, MaskPtr, PhasePtr, PtrC1, PtrC2, PtrC3, PtrC4, PtrD1, PtrD2) == false ) 
	{	return false; }	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if (SysParam.m_CudaFnEnabled==FN_ENABLE && true== IsCudaDeviceUse )
	{
		if ( CudaFunc.CudaSolvePhase42Frames2Period2Exp(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrC1, PtrC2, PtrC3, PtrC4, PtrD1, PtrD2, PerA, PerB, ExpTimeA, ExpTimeB, ExpTimeC, ExpTimeD, Gamma, BasePhasePtr, NoiseParam, PhasePtr, MaskPtr) == false )
		{	
			SetErrorString(CudaFunc.GetErrorString());
			return false; 
		}		
		return true;	
	}	
#endif//CUDA_USE	
	return GrayImage42FrameTo2Phase2Exp3_II(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrC1, PtrC2, PtrC3, PtrC4, PerA, ExpTimeA, ExpTimeC, PtrB1, PtrB2, PtrD1, PtrD2, PerB, ExpTimeB, ExpTimeD, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage42FrameTo2Phase2Exp3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, double PerA, int ExpTimeA, int ExpTimeC, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrD1, const unsigned char *PtrD2, double PerB, int ExpTimeB, int ExpTimeD, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//4+2張灰階影像解相位-2曝光
{
	//PS::合併在一起沒有比GrayImage4FrameTo2Phase3_II來得快, 原因待查!??
	if ( this->CheckGrayImage14(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, MaskPtr, PhasePtr, PtrC1, PtrC2, PtrC3, PtrC4, PtrD1, PtrD2) == false ) 
	{	return false; }	

	int   nPhase = 0;
	float phase = 0.0f;		
	int   PhaseM_AB = 0;
	int   PhaseM_CD = 0;			
	int    nPeriod=0;
	double dPeriod=0.0;	
	MASK_DATA  MaskA=0, MaskB=0;
	MASK_DATA  MaskC=0, MaskD=0;
	MASK_DATA  MaskAB=0, MaskCD=0;	
	PHASE_DATA dA1=0, dA2=0, dA3=0, dA4=0;
	PHASE_DATA dB1=0, dB2=0, dB3=0;
	PHASE_DATA dC1=0, dC2=0, dC3=0, dC4=0;
	PHASE_DATA dD1=0, dD2=0, dD3=0;	
	PHASE_DATA PhaseA=0, PhaseB=0;	
	PHASE_DATA PhaseC=0, PhaseD=0;
	size_t i=0, j=0, k=0, idx=0;		
	unsigned char GammaTable[256];
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	
	const float ExpTimeRatioAB = (float)(ExpTimeB*1.0f/ExpTimeA);
	const float ExpTimeRatioCD = (float)(ExpTimeD*1.0f/ExpTimeC);

	double dRatio1 = 0;
	double dRatio2 = 0;	
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用	
	if ( PerB > PerA )//P2 為主
	{	
		dRatio1 = PerB/PerA;
		dRatio2 = 1;
	}
	else //P1為主 
	{	
		dRatio1 = 1;
		dRatio2 = PerA/PerB;
	}

	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable); }

	PerD = Calc2PhaseNewPeriode(PerA, PerB);	
	CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatio1);
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	for ( i=0; i<BufferSize; i++ )
	{	
		dA1 = PtrA1[i];
		dA2 = PtrA2[i];
		dA3 = PtrA3[i];
		dA4 = PtrA4[i];

		dC1 = PtrC1[i];
		dC2 = PtrC2[i];
		dC3 = PtrC3[i];
		dC4 = PtrC4[i];

		dB1 = PtrB1[i];
		dB3 = PtrB2[i];
		dB2 = (dA1+dA2+dA3+dA4)>>2;
		dB2 = (int)((dB2*ExpTimeRatioAB)+0.5);

		dD1 = PtrD1[i];
		dD3 = PtrD2[i];
		dD2 = (dC1+dC2+dC3+dC4)>>2;
		dD2 = (int)((dD2*ExpTimeRatioCD)+0.5);

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];
			dA4 = GammaTable[dA4];

			dB1 = GammaTable[dB1];
			dB2 = GammaTable[dB2];
			dB3 = GammaTable[dB3];			

			dC1 = GammaTable[dC1];
			dC2 = GammaTable[dC2];
			dC3 = GammaTable[dC3];
			dC4 = GammaTable[dC4];

			dD1 = GammaTable[dD1];
			dD2 = GammaTable[dD2];
			dD3 = GammaTable[dD3];
		}

		if ( Calc4PhaseParamMask(dA1, dA2, dA3, dA4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA, MaskA, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dB1, dB2, dB3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB, MaskB) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dC1, dC2, dC3, dC4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseC, MaskC, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dD1, dD2, dD3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseD, MaskD) == false )
		{	return false; }

		//雙週期相位合併		
		if ( PerA < PerB )
		{
			PhaseM_AB = CombinePhasePeriod(CombinePeriodMode, PhaseA, PhaseB, dRatio1);
			PhaseM_CD = CombinePhasePeriod(CombinePeriodMode, PhaseC, PhaseD, dRatio1);			
		}
		else
		{
			PhaseM_AB = CombinePhasePeriod(CombinePeriodMode, PhaseB, PhaseA, dRatio1);//注意相位次序
			PhaseM_CD = CombinePhasePeriod(CombinePeriodMode, PhaseD, PhaseC, dRatio1);//注意相位次序			
		}
		if ( NULL != BasePhasePtr )//扣除相平面
		{	
			DeductBasePhase(BasePhasePtr[i], PhaseM_AB);	
			DeductBasePhase(BasePhasePtr[i], PhaseM_CD);	
		}		
		MaskAB = CombinePhaseMask(MaskA, MaskB);//合併大小週期遮罩
		MaskCD = CombinePhaseMask(MaskC, MaskD);//合併大小週期遮罩		
		Merge2ExpPhaseData(MaskAB, PhaseM_AB, MaskCD, PhaseM_CD, MaskPtr[i], nPhase);		
		PhasePtr[i] = static_cast<PHASE_DATA>(nPhase);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage44GCFrameTo2Phase(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, double PerA, int ExpTimeA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, double PerB, int ExpTimeB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &MaskPtr, PHASE_PTR &PhasePtr, double &PerD)//4+4GC張灰階影像解相位
{
	const char fnName[] = "CImageAPI::GrayImage44GCFrameTo2Phase";
	if ( this->CheckGrayImage8(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4) == false ) 
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false ||
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	if ( this->GrayImage44GCFrameTo2Phase3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PerA, ExpTimeA, PtrB1, PtrB2, PtrB3, PtrB4, PerB, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD) == false )	
	{		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage44GCFrameTo2Phase3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, double PerA, int ExpTimeA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, double PerB, int ExpTimeB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//4+4GC張灰階影像解相位
{
#ifdef CUDA_USE
	if ( this->CheckGrayImage10(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, MaskPtr, PhasePtr) == false ) 
	{	return false; }	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if (SysParam.m_CudaFnEnabled==FN_ENABLE && true== IsCudaDeviceUse )
	{
		if ( CudaFunc.CudaSolvePhase44GCFrames2Period(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PerA, ExpTimeA, PtrB1, PtrB2, PtrB3, PtrB4, PerB, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, PhasePtr, MaskPtr) == false )
		{	
			SetErrorString(CudaFunc.GetErrorString());
			return false; 
		}		

		bool bDebugCuda=false;
		if ( true == bDebugCuda )
		{
			size_t i=0;
			size_t Mask_ErrCnt=0;
			size_t Phase_ErrCnt=0;
			int Mask_Cuda=0, Mask_PC=0, Mask_Err=0, Mask_ErrMax=0;
			int Phase_Cuda=0, Phase_PC=0, Phase_Err=0, Phase_ErrMax=0;

			MASK_PTR MaskPtr_PC=NULL;
			PHASE_PTR PhasePtr_PC=NULL;
			const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);
			const char fnName[] = "GrayImage44GCFrameTo2Phase3_Debug";
			if ( JetMemory.alloc_func(BufferSize, MaskPtr_PC, fnName, "MaskPtr_PC") == false ||
				JetMemory.alloc_func(BufferSize, PhasePtr_PC, fnName, "PhasePtr_PC") == false )
			{
				JetMemory.free_func(MaskPtr_PC);
				JetMemory.free_func(PhasePtr_PC);
				return true;
			}
			if ( GrayImage44GCFrameTo2Phase3_II(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PerA, ExpTimeA, PtrB1, PtrB2, PtrB3, PtrB4, PerB, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, MaskPtr_PC, PhasePtr_PC, PerD) == true )
			{
				for ( i=0; i<BufferSize; i++ )
				{
					Mask_Cuda = MaskPtr[i];
					Mask_PC = MaskPtr_PC[i];

					Phase_Cuda = PhasePtr[i];
					Phase_PC = PhasePtr_PC[i];

					Mask_Err=Mask_Cuda-Mask_PC;					
					Phase_Err=Phase_Cuda-Phase_PC;

					if ( 0 != Mask_Err ) 
					{	Mask_ErrCnt ++; }
					if ( abs(Phase_Err) > 1 )
					{	Phase_ErrCnt ++; }					
				}
			}
			JetMemory.free_func(MaskPtr_PC);
			JetMemory.free_func(PhasePtr_PC);
		}
		return true;
	}	
#endif//CUDA_USE
	return GrayImage44GCFrameTo2Phase3_II(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PerA, ExpTimeA, PtrB1, PtrB2, PtrB3, PtrB4, PerB, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage44GCFrameTo2Phase3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, double PerA, int ExpTimeA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, double PerB, int ExpTimeB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//4+4GC張灰階影像解相位
{
	if ( this->CheckGrayImage10(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, MaskPtr, PhasePtr) == false ) 
	{	return false; }	

	int   nPhase = 0;
	float phase = 0.0f;		
	int   Phase1 = 0;
	int   Phase2 = 0;	
	int   PhaseM = 0;
	int   PhaseMT = 0;	
	int   PhaseMNew = 0;	
	int   PhaseMFull = 0;
	int   PhaseMFullNew = 0;	
	int    nPeriod=0;
	double dPeriod=0.0;
	float  BinThreshold=0;
	MASK_DATA  MaskA=0, MaskB=0;	
	PHASE_DATA dA1=0, dA2=0, dA3=0, dA4=0;
	PHASE_DATA dB1=0, dB2=0, dB3=0, dB4=0;	
	PHASE_DATA PhaseA=0, PhaseB=0;	
	size_t i=0, j=0, k=0, idx=0;		
	unsigned char GammaTable[256];
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);		
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	
	const float ExpTimeRatio = (float)(ExpTimeB*1.0f/ExpTimeA);

	int           k1=0, k2=0;	
	//unsigned char Code=0x00;
	//unsigned char Code1=0x00;
	//unsigned char Code2=0x00;
	const int MaxN=8;//最多8個16週期			
	const int Period=PHASE_PERIOD;
	const int PeriodQar1=Period/4;
	const int PeriodQar3=3*Period/4;
	const int FullPeriodM = (int)(MaxN*Period);//以第1週期為主的大週期	
	const bool bGrayCodeInvert=false;//16G->32G->64G->128G->256B	
	std::vector<unsigned char> CodeMap1;
	std::vector<unsigned char> CodeMap2;	
	BuildGrayCodeMapTable(3, CodeMap1);
	BuildGrayCodeMapTable(4, CodeMap2);

	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable); }

	PerD = PerA*MaxN;
	//CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatio1);
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	for ( i=0; i<BufferSize; i++ )
	{	
		dA1 = PtrA1[i];	dA2 = PtrA2[i];	dA3 = PtrA3[i];	dA4 = PtrA4[i];
		dB1 = PtrB1[i];	dB2 = PtrB2[i];	dB3 = PtrB3[i];	dB4 = PtrB4[i];

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];
			dA4 = GammaTable[dA4];

			dB1 = GammaTable[dB1];
			dB2 = GammaTable[dB2];
			dB3 = GammaTable[dB3];
			dB4 = GammaTable[dB4];			
		}

		BinThreshold=(dA1+dA2+dA3+dA4)/4.0f;
		BinThreshold=(float)(BinThreshold*ExpTimeRatio);
		Calc4GrayCodeParam(dB1, dB2, dB3, dB4, BinThreshold, CodeMap1.data(), CodeMap2.data(), k1, k2);
		/*
		Code = 0x00;
		Code1 = Code2 = Code;		
		if ( dB1 > BinThreshold ) 
		{	Code2 |= 0x01;	}
		if ( dB2 > BinThreshold ) 
		{	
		Code1 |= 0x01;	
		Code2 |= 0x02;	
		}		
		if ( dB3 > BinThreshold ) 
		{	
		Code1 |= 0x02;	
		Code2 |= 0x04;	
		}
		if ( dB4 > BinThreshold ) 
		{	
		Code1 |= 0x04;	
		Code2 |= 0x08;	
		}		
		k1 = CodeMap1[Code1];
		k2 = CodeMap2[Code2];
		k2 = (k2+1)/2;
		*/
		if ( Calc4PhaseParamMask(dA1, dA2, dA3, dA4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA, MaskA, PhaseNoiseDefMode) == false )
		{	return false; }

		PhaseMT = PhaseA;		
		if ( PhaseMT < PeriodQar1 ) 
		{	PhaseM=PhaseMT+(Period*k2); }
		else if ( PhaseMT > PeriodQar3 ) 
		{	PhaseM=PhaseMT+(Period*k2)-(Period); }
		else
		{	PhaseM=PhaseMT+(Period*k1); }		
		PhaseM = (PhaseM/MaxN);
		if ( PhaseM > Period )
		{	PhaseM -= Period; }

		/*
		double Phase=0;
		double PhaseRaw=atan2f(dA4-dA2, dA1-dA3);
		const double fPI = 3.1415926535897932384626433832795;
		if ( PhaseRaw<0 ) { Phase = PhaseRaw+(2*fPI); }
		else { Phase = PhaseRaw; }
		const double PhaseRaw2=Phase;
		const double DegreeRaw=PhaseRaw*180/fPI;
		const double DegreeRaw2=PhaseRaw2*180/fPI;		
		const double FullPeriodM_PI = (double)(MaxN*2*fPI);
		if ( DegreeRaw2 < 90 ) 
		{	Phase=Phase+(2*fPI*k2); }
		else if ( DegreeRaw2 > 270 ) 
		{	Phase=Phase+(2*fPI*k2)-(2*fPI); }
		else
		{	Phase=Phase+(2*fPI*k1); }
		double PhaseRes=Phase/FullPeriodM_PI;
		PhaseMT=(int)(PhaseRes*Period);		
		if ( PhaseMT > Period )
		{	PhaseMT -= Period; }
		if ( PhaseMT != PhaseM )
		{	PhaseMT = PhaseMT; }		
		//PhaseM = PhaseMT;
		*/

		//PhaseM = CombinePhasePeriod(CombinePeriodMode, Phase1, Phase2, dRatio1);

		if ( NULL != BasePhasePtr )//扣除相平面
		{	DeductBasePhase(BasePhasePtr[i], PhaseM);	}
		PhasePtr[i] = static_cast<PHASE_DATA>(PhaseM);
		MaskPtr[i] = CombinePhaseMask(MaskA, MaskB);//合併大小週期遮罩		
	}	
	return true;
}
