//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage45GCFrameTo2Phase3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, double PerA, int ExpTimeA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrB5, double PerB, int ExpTimeB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//4+GC張灰階影像解相位
{
#ifdef CUDA_USE
	if ( this->CheckGrayImage11(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, MaskPtr, PhasePtr) == false ) 
	{	return false; }	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if (SysParam.m_CudaFnEnabled==FN_ENABLE && true== IsCudaDeviceUse )
	{
		if ( CudaFunc.CudaSolvePhase45GCFrames2Period(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PerA, ExpTimeA, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PerB, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, PhasePtr, MaskPtr) == false )
		{	
			SetErrorString(CudaFunc.GetErrorString());
			return false; 
		}		

		bool bDebugCuda=false;
		if ( true == bDebugCuda )
		{
			size_t i=0;
			size_t Mask_ErrCnt=0;
			size_t Phase_ErrCnt=0;
			int Mask_Cuda=0, Mask_PC=0, Mask_Err=0, Mask_ErrMax=0;
			int Phase_Cuda=0, Phase_PC=0, Phase_Err=0, Phase_ErrMax=0;

			MASK_PTR MaskPtr_PC=NULL;
			PHASE_PTR PhasePtr_PC=NULL;
			const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);
			const char fnName[] = "GrayImage45GCFrameTo2Phase3_Debug";
			if ( JetMemory.alloc_func(BufferSize, MaskPtr_PC, fnName, "MaskPtr_PC") == false ||
				JetMemory.alloc_func(BufferSize, PhasePtr_PC, fnName, "PhasePtr_PC") == false )
			{
				JetMemory.free_func(MaskPtr_PC);
				JetMemory.free_func(PhasePtr_PC);
				return true;
			}
			if ( GrayImage45GCFrameTo2Phase3_II(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PerA, ExpTimeA, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PerB, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, MaskPtr_PC, PhasePtr_PC, PerD) == true )
			{
				for ( i=0; i<BufferSize; i++ )
				{
					Mask_Cuda = MaskPtr[i];
					Mask_PC = MaskPtr_PC[i];

					Phase_Cuda = PhasePtr[i];
					Phase_PC = PhasePtr_PC[i];

					Mask_Err=Mask_Cuda-Mask_PC;					
					Phase_Err=Phase_Cuda-Phase_PC;

					if ( 0 != Mask_Err ) 
					{	Mask_ErrCnt ++; }
					if ( abs(Phase_Err) > 1 ) 
					{	Phase_ErrCnt ++; }					
				}
			}
			JetMemory.free_func(MaskPtr_PC);
			JetMemory.free_func(PhasePtr_PC);
		}
		return true;
	}	
#endif//CUDA_USE
	return GrayImage45GCFrameTo2Phase3_II(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PerA, ExpTimeA, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PerB, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage45GCFrameTo2Phase3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, double PerA, int ExpTimeA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrB5, double PerB, int ExpTimeB, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//4+GC張灰階影像解相位
{	
	if ( this->CheckGrayImage11(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, MaskPtr, PhasePtr) == false ) 
	{	return false; }	

	int   nPhase = 0;
	float phase = 0.0f;		
	int   Phase1 = 0;
	int   Phase2 = 0;	
	int   PhaseM = 0;
	int   PhaseMT = 0;	
	int   PhaseMNew = 0;	
	int   PhaseMFull = 0;
	int   PhaseMFullNew = 0;	
	int    nPeriod=0;
	double dPeriod=0.0;
	float  BinThreshold=0;
	MASK_DATA  MaskA=0, MaskB=0;	
	PHASE_DATA dA1=0, dA2=0, dA3=0, dA4=0;
	PHASE_DATA dB1=0, dB2=0, dB3=0, dB4=0, dB5=0;	
	PHASE_DATA PhaseA=0, PhaseB=0;	
	size_t i=0, j=0, k=0, idx=0;		
	unsigned char GammaTable[256];
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);		
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	
	const float ExpTimeRatio = (float)(ExpTimeB*1.0f/ExpTimeA);

	int           k1=0, k2=0;
	//unsigned char Code=0x00;
	//unsigned char Code4=0x00;
	//unsigned char Code5=0x00;
	const int MaxN=16;//最多16個16週期			
	const int Period=PHASE_PERIOD;
	const int PeriodQar1=Period/4;
	const int PeriodQar3=3*Period/4;
	const int FullPeriodM = (int)(MaxN*Period);//以第1週期為主的大週期	
	const bool bGrayCodeInvert=false;//16G->32G->64G->128G->256B	
	std::vector<unsigned char> CodeMap4;
	std::vector<unsigned char> CodeMap5;	
	BuildGrayCodeMapTable(4, CodeMap4);
	BuildGrayCodeMapTable(5, CodeMap5);

	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable); }

	PerD = PerA*MaxN;
	//CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatio1);
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	for ( i=0; i<BufferSize; i++ )
	{	
		dA1 = PtrA1[i];	dA2 = PtrA2[i];	dA3 = PtrA3[i];	dA4 = PtrA4[i];
		dB1 = PtrB1[i];	dB2 = PtrB2[i];	dB3 = PtrB3[i];	dB4 = PtrB4[i];	dB5 = PtrB5[i];

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];
			dA4 = GammaTable[dA4];

			dB1 = GammaTable[dB1];
			dB2 = GammaTable[dB2];
			dB3 = GammaTable[dB3];
			dB4 = GammaTable[dB4];
			dB5 = GammaTable[dB5];
		}

		BinThreshold=(dA1+dA2+dA3+dA4)/4.0f;
		BinThreshold=(float)(BinThreshold*ExpTimeRatio);

		Calc5GrayCodeParam(dB1, dB2, dB3, dB4, dB5, BinThreshold, CodeMap4.data(), CodeMap5.data(), k1, k2);
		/*
		Code = 0x00;
		Code4 = Code5 = Code;		
		if ( dB1 > BinThreshold ) 
		{	Code5 |= 0x01;	}
		if ( dB2 > BinThreshold ) 
		{	
		Code4 |= 0x01;	
		Code5 |= 0x02;	
		}		
		if ( dB3 > BinThreshold ) 
		{	
		Code4 |= 0x02;	
		Code5 |= 0x04;	
		}
		if ( dB4 > BinThreshold ) 
		{	
		Code4 |= 0x04;	
		Code5 |= 0x08;	
		}
		if ( dB5 > BinThreshold ) 
		{	
		Code4 |= 0x08;	
		Code5 |= 0x10;	
		}
		k1 = CodeMap4[Code4];//N4
		k2 = CodeMap5[Code5];//N5
		k2 = (k2+1)/2;
		*/
		if ( Calc4PhaseParamMask(dA1, dA2, dA3, dA4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA, MaskA, PhaseNoiseDefMode) == false )
		{	return false; }

		PhaseMT = PhaseA;		
		if ( PhaseMT < PeriodQar1 ) 
		{	PhaseM=PhaseMT+(Period*k2); }
		else if ( PhaseMT > PeriodQar3 ) 
		{	PhaseM=PhaseMT+(Period*k2)-(Period); }
		else
		{	PhaseM=PhaseMT+(Period*k1); }		
		PhaseM = (PhaseM/MaxN);
		if ( PhaseM > Period )
		{	PhaseM -= Period; }

		/*
		double Phase=0;
		double PhaseRaw=atan2f(dA4-dA2, dA1-dA3);
		const double fPI = 3.1415926535897932384626433832795;
		if ( PhaseRaw<0 ) { Phase = PhaseRaw+(2*fPI); }
		else { Phase = PhaseRaw; }
		const double PhaseRaw2=Phase;
		const double DegreeRaw=PhaseRaw*180/fPI;
		const double DegreeRaw2=PhaseRaw2*180/fPI;		
		const double FullPeriodM_PI = (double)(MaxN*2*fPI);
		if ( DegreeRaw2 < 90 ) 
		{	Phase=Phase+(2*fPI*k2); }
		else if ( DegreeRaw2 > 270 ) 
		{	Phase=Phase+(2*fPI*k2)-(2*fPI); }
		else
		{	Phase=Phase+(2*fPI*k1); }
		double PhaseRes=Phase/FullPeriodM_PI;
		PhaseMT=(int)(PhaseRes*Period);		
		if ( PhaseMT > Period )
		{	PhaseMT -= Period; }
		if ( PhaseMT != PhaseM )
		{	PhaseMT = PhaseMT; }		
		//PhaseM = PhaseMT;
		*/

		//PhaseM = CombinePhasePeriod(CombinePeriodMode, Phase1, Phase2, dRatio1);

		if ( NULL != BasePhasePtr )//扣除相平面
		{	DeductBasePhase(BasePhasePtr[i], PhaseM);	}
		PhasePtr[i] = static_cast<PHASE_DATA>(PhaseM);
		MaskPtr[i] = CombinePhaseMask(MaskA, MaskB);//合併大小週期遮罩		
	}	
	return true;
}
