bool CImageAPI::GrayImage45GCFrameTo2Phase2Exp3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, double PerA, int ExpTimeA, int ExpTimeC, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrB5, const unsigned char *PtrD1, const unsigned char *PtrD2, const unsigned char *PtrD3, const unsigned char *PtrD4, const unsigned char *PtrD5, double PerB, int ExpTimeB, int ExpTimeD, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//2個4張+5GC灰階影像解相位-2曝光
{
	const char fnName[] = "CImageAPI::GrayImage45GCFrameTo2Phase2Exp3_II";
	if ( this->CheckGrayImage20(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, MaskPtr, PhasePtr, PtrC1, PtrC2, PtrC3, PtrC4, PtrD1, PtrD2, PtrD3, PtrD4, PtrD5) == false ) 
	{	return false; }	

	double   PerAB=0;
	double   PerCD=0;
	MASK_PTR MaskPtr_AB=NULL;
	MASK_PTR MaskPtr_CD=NULL;
	PHASE_PTR PhasePtr_AB=NULL;
	PHASE_PTR PhasePtr_CD=NULL;
	const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);	
	if ( JetMemory.alloc_func(BufferSize, MaskPtr_AB, fnName, "MaskPtr_AB") == false ||
		JetMemory.alloc_func(BufferSize, MaskPtr_CD, fnName, "MaskPtr_CD") == false ||
		JetMemory.alloc_func(BufferSize, PhasePtr_AB, fnName, "PhasePtr_AB") == false ||
		JetMemory.alloc_func(BufferSize, PhasePtr_CD, fnName, "PhasePtr_CD") == false )
	{
		JetMemory.free_func(MaskPtr_AB);
		JetMemory.free_func(MaskPtr_CD);
		JetMemory.free_func(PhasePtr_AB);
		JetMemory.free_func(PhasePtr_CD);
		return false;
	}

	if ( GrayImage45GCFrameTo2Phase3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PerA, ExpTimeA, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PerB, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, MaskPtr_AB, PhasePtr_AB, PerAB) == false )
	{
		JetMemory.free_func(MaskPtr_AB);
		JetMemory.free_func(MaskPtr_CD);
		JetMemory.free_func(PhasePtr_AB);
		JetMemory.free_func(PhasePtr_CD);
		return false; 
	}

	if ( GrayImage45GCFrameTo2Phase3(ImageW, ImageH, ImageStep, PtrC1, PtrC2, PtrC3, PtrC4, PerA, ExpTimeC, PtrD1, PtrD2, PtrD3, PtrD4, PtrD5, PerB, ExpTimeB, Gamma, BasePhasePtr, NoiseParam, MaskPtr_CD, PhasePtr_CD, PerCD) == false )
	{
		JetMemory.free_func(MaskPtr_AB);
		JetMemory.free_func(MaskPtr_CD);
		JetMemory.free_func(PhasePtr_AB);
		JetMemory.free_func(PhasePtr_CD);
		return false; 
	}

	const bool bOpenMP = false;
	if ( Merge2ExpPhaseImage3(ImageW, ImageH, ImageStep, PhasePtr_AB, MaskPtr_AB, PhasePtr_CD, MaskPtr_CD, bOpenMP, PhasePtr, MaskPtr) == false )
	{
		JetMemory.free_func(MaskPtr_AB);
		JetMemory.free_func(MaskPtr_CD);
		JetMemory.free_func(PhasePtr_AB);
		JetMemory.free_func(PhasePtr_CD);
		return false;
	}

	JetMemory.free_func(MaskPtr_AB);
	JetMemory.free_func(MaskPtr_CD);
	JetMemory.free_func(PhasePtr_AB);
	JetMemory.free_func(PhasePtr_CD);
	return true;
}
