bool CImageAPI::GrayImage46GCFrameTo2Phase2Exp(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, double PerA, int ExpTimeA, int ExpTimeC, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrB5, const unsigned char *PtrB6, const unsigned char *PtrD1, const unsigned char *PtrD2, const unsigned char *PtrD3, const unsigned char *PtrD4, const unsigned char *PtrD5, const unsigned char *PtrD6, double PerB, int ExpTimeB, int ExpTimeD, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &MaskPtr, PHASE_PTR &PhasePtr, double &PerD)//2個4張+6GC灰階影像解相位-2曝光
{
	const char fnName[] = "CImageAPI::GrayImage46GCFrameTo2Phase2Exp";
	if ( this->CheckGrayImage20(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PtrB6, PtrC1, PtrC2, PtrC3, PtrC4, PtrD1, PtrD2, PtrD3, PtrD4, PtrD5, PtrD6) == false ) 
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false ||
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	//	::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//	::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);  
	if ( this->GrayImage46GCFrameTo2Phase2Exp3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrC1, PtrC2, PtrC3, PtrC4, PerA, ExpTimeA, ExpTimeC, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PtrB6, PtrD1, PtrD2, PtrD3, PtrD4, PtrD5, PtrD6, PerB, ExpTimeB, ExpTimeD, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD) == false )	
	{		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	return true;
}
