//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage3FrameTo3Phase3_I(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, double PerB, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, double PerC, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//3個3張灰階影像解相位
{
	//PS::合併在一起沒有比GrayImage3FrameTo3Phase3_II來得快, 原因待查!??	
	if ( this->CheckGrayImage11(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrB1, PtrB2, PtrB3, PtrC1, PtrC2, PtrC3, MaskPtr, PhasePtr) == false ) 
	{	return false; }	

	int   Phase1 = 0;
	int   Phase2 = 0;
	int   PhaseM = 0;

	int   iPhase1 = 0;
	int   iPhase2 = 0;
	int   PhaseAB = 0;
	int   PhaseBC = 0;
	int   PhaseCA = 0;	
	MASK_DATA  MaskA=0, MaskB=0, MaskC=0;	
	PHASE_DATA dA1=0, dA2=0, dA3=0;
	PHASE_DATA dB1=0, dB2=0, dB3=0;
	PHASE_DATA dC1=0, dC2=0, dC3=0;	
	PHASE_DATA PhaseA=0, PhaseB=0, PhaseC=0;	
	size_t i=0, j=0, k=0, idx=0;
	unsigned char GammaTable[256];
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;
	const int LowContrastC = NoiseParam.PhaseLowContrastC;
	const int LowPotentialC = NoiseParam.PhaseLowPotentialC;
	const int SaturationC = NoiseParam.PhaseOverSaturatedC;

	//Calc2PhaseNewPeriode
	double P1=0, P2=0;
	const double PerAB = Calc2PhaseNewPeriode(PerA, PerB);
	const double PerBC = Calc2PhaseNewPeriode(PerB, PerC);
	const double PerCA = Calc2PhaseNewPeriode(PerC, PerA);
	const double PerAB_BC = Calc2PhaseNewPeriode(PerAB, PerBC);
	const double PerBC_CA = Calc2PhaseNewPeriode(PerBC, PerCA);
	const double PerCA_AB = Calc2PhaseNewPeriode(PerCA, PerAB);

	int       TriMode   = 0;
	const int ModeAB_BC = 1;
	const int ModeBC_CA = 2;
	const int ModeCA_AB = 3;

	PerD = __max(PerAB_BC, PerBC_CA);
	PerD = __max(PerD, PerCA_AB);

	if ( PerCA_AB == PerD )
	{	TriMode = ModeCA_AB;	}
	else if ( PerBC_CA == PerD )
	{	TriMode = ModeBC_CA;	}
	else
	{	TriMode = ModeAB_BC;	}

	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable); }

	for ( i=0; i<BufferSize; i++ )
	{	
		dA1 = PtrA1[i];
		dA2 = PtrA2[i];
		dA3 = PtrA3[i];		

		dB1 = PtrB1[i];
		dB2 = PtrB2[i];
		dB3 = PtrB3[i];		

		dC1 = PtrC1[i];
		dC2 = PtrC2[i];
		dC3 = PtrC3[i];		

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];			

			dB1 = GammaTable[dB1];
			dB2 = GammaTable[dB2];
			dB3 = GammaTable[dB3];

			dC1 = GammaTable[dC1];
			dC2 = GammaTable[dC2];
			dC3 = GammaTable[dC3];
		}
		if ( Calc3PhaseParamMask(dA1, dA2, dA3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA, MaskA) == false )
		{	return false; }
		if ( Calc3PhaseParamMask(dB1, dB2, dB3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB, MaskB) == false )
		{	return false; }
		if ( Calc3PhaseParamMask(dC1, dC2, dC3, PhaseNoiseDef, LowContrastC, LowPotentialC, SaturationC, PhaseC, MaskC) == false )
		{	return false; }

		//雙週期相位合併-AB
		P1 = PerA;
		P2 = PerB;
		iPhase1 = PhaseA;
		iPhase2 = PhaseB;
		if ( P1 < P2 )
		{
			Phase1 = iPhase1;
			Phase2 = iPhase2;
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}
		else
		{
			Phase1 = iPhase2;//注意相位次序
			Phase2 = iPhase1;//
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}	
		PhaseAB = PhaseM;

		//雙週期相位合併-BC
		P1 = PerB;
		P2 = PerC;
		iPhase1 = PhaseB;
		iPhase2 = PhaseC;
		if ( P1 < P2 )
		{
			Phase1 = iPhase1;
			Phase2 = iPhase2;
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}
		else
		{
			Phase1 = iPhase2;//注意相位次序
			Phase2 = iPhase1;//
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}	
		PhaseBC = PhaseM;

		//雙週期相位合併-CA
		P1 = PerC;
		P2 = PerA;
		iPhase1 = PhaseC;
		iPhase2 = PhaseA;
		if ( P1 < P2 )
		{
			Phase1 = iPhase1;
			Phase2 = iPhase2;
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}
		else
		{
			Phase1 = iPhase2;//注意相位次序
			Phase2 = iPhase1;//
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}	
		PhaseCA = PhaseM;

		//第2次雙週期合併-找最後週期最長得來用
		if ( ModeCA_AB == TriMode )
		{
			P1 = PerCA;
			P2 = PerAB;
			iPhase1 = PhaseCA;
			iPhase2 = PhaseAB;
		}
		else if ( PerBC_CA == TriMode )
		{
			P1 = PerBC;
			P2 = PerCA;
			iPhase1 = PhaseBC;
			iPhase2 = PhaseCA;
		}
		else//ModeAB_BC
		{
			P1 = PerAB;
			P2 = PerBC;
			iPhase1 = PhaseAB;
			iPhase2 = PhaseBC;
		}
		if ( P1 < P2 )
		{
			Phase1 = iPhase1;
			Phase2 = iPhase2;
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}
		else
		{
			Phase1 = iPhase2;//注意相位次序
			Phase2 = iPhase1;//
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}		
		if ( NULL != BasePhasePtr )//扣除相平面
		{	
			PhaseM -= BasePhasePtr[i];//注意若使用unsigned short則需要更大的整數來使用, 避免溢位			
			if ( PhaseM < 0 ) 
			{	PhaseM += PHASE_PERIOD; }			
			else if ( PhaseM > PHASE_PERIOD ) 
			{	PhaseM -= PHASE_PERIOD; }	
		}
		PhasePtr[i] = static_cast<PHASE_DATA>(PhaseM);
		if ( (MaskA&PHASE_MASK_LOW_CONTRAST)!=0 || (MaskB&PHASE_MASK_LOW_CONTRAST)!=0 || (MaskC&PHASE_MASK_LOW_CONTRAST)!=0 )
		{	MaskPtr[i] = PHASE_MASK_LOW_CONTRAST;	}
		else if ( (MaskA&PHASE_MASK_OVER_SATURATED)!=0 || (MaskB&PHASE_MASK_OVER_SATURATED)!=0 || (MaskC&PHASE_MASK_OVER_SATURATED)!=0 )
		{	MaskPtr[i] = PHASE_MASK_OVER_SATURATED;	}
		else if ( (MaskA&PHASE_MASK_LOW_POTENTIAL)!=0 || (MaskB&PHASE_MASK_LOW_POTENTIAL)!=0 || (MaskC&PHASE_MASK_LOW_POTENTIAL)!=0 )
		{	MaskPtr[i] = PHASE_MASK_LOW_POTENTIAL;	}
		else
		{	MaskPtr[i] = PHASE_MASK_VALID;	}		
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage3FrameTo3Phase3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, double PerB, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, double PerC, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//3個3張灰階影像解相位
{
	if ( this->CheckGrayImage11(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrB1, PtrB2, PtrB3, PtrC1, PtrC2, PtrC3, MaskPtr, PhasePtr) == false ) 
	{	return false; }	

	int PatternID = 0;	
	unsigned char *MaskPtrA=NULL, *MaskPtrB=NULL, *MaskPtrC=NULL;	
	unsigned char *MaskPtrAB=NULL, *MaskPtrBC=NULL, *MaskPtrCA=NULL;
	PHASE_PTR PhasePtrA=NULL;
	PHASE_PTR PhasePtrB=NULL;
	PHASE_PTR PhasePtrC=NULL;
	PHASE_PTR PhasePtrAB=NULL;
	PHASE_PTR PhasePtrBC=NULL;
	PHASE_PTR PhasePtrCA=NULL;	

	double PerAB = 0;
	double PerBC = 0;
	double PerCA = 0;
	double PerAB_BC = 0;
	double PerBC_CA = 0;
	double PerCA_AB = 0;
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;

	PatternID = PHASE_PATTERN_A;
	if ( GrayImage3FrameToPhase(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PatternID, Gamma, NULL, NoiseParam, MaskPtrA, PhasePtrA) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		return false;
	}

	PatternID = PHASE_PATTERN_B;
	if ( GrayImage3FrameToPhase(ImageW, ImageH, ImageStep, PtrB1, PtrB2, PtrB3, PatternID, Gamma, NULL, NoiseParam, MaskPtrB, PhasePtrB) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		return false;
	}

	PatternID = PHASE_PATTERN_C;
	if ( GrayImage3FrameToPhase(ImageW, ImageH, ImageStep, PtrC1, PtrC2, PtrC3, PatternID, Gamma, NULL, NoiseParam, MaskPtrC, PhasePtrC) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);		
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		return false;
	}

	//雙週期合併-AB
	if ( PhaseImage2PeriodeToPhase(ImageW, ImageH, ImageStep, PhasePtrA, MaskPtrA, PerA, PhasePtrB, MaskPtrB, PerB, NULL, PhasePtrAB, MaskPtrAB, PerAB, CombinePeriodMode) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);		
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);

		JetMemory.free_func(MaskPtrAB);
		JetMemory.free_func(PhasePtrAB);
		JetMemory.free_func(MaskPtrBC);
		JetMemory.free_func(PhasePtrBC);
		JetMemory.free_func(MaskPtrCA);
		JetMemory.free_func(PhasePtrCA);
		return false;
	}
	//雙週期合併-BC
	if ( PhaseImage2PeriodeToPhase(ImageW, ImageH, ImageStep, PhasePtrB, MaskPtrB, PerB, PhasePtrC, MaskPtrC, PerC, NULL, PhasePtrBC, MaskPtrBC, PerBC, CombinePeriodMode) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);

		JetMemory.free_func(MaskPtrAB);
		JetMemory.free_func(PhasePtrAB);
		JetMemory.free_func(MaskPtrBC);
		JetMemory.free_func(PhasePtrBC);
		JetMemory.free_func(MaskPtrCA);
		JetMemory.free_func(PhasePtrCA);
		return false;
	}
	//雙週期合併-CA
	if ( PhaseImage2PeriodeToPhase(ImageW, ImageH, ImageStep, PhasePtrC, MaskPtrC, PerC, PhasePtrA, MaskPtrA, PerA, NULL, PhasePtrCA, MaskPtrCA, PerCA, CombinePeriodMode) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);

		JetMemory.free_func(MaskPtrAB);
		JetMemory.free_func(PhasePtrAB);
		JetMemory.free_func(MaskPtrBC);
		JetMemory.free_func(PhasePtrBC);
		JetMemory.free_func(MaskPtrCA);
		JetMemory.free_func(PhasePtrCA);
		return false;
	}

	bool IsOK = true;
	PerAB_BC = Calc2PhaseNewPeriode(PerAB, PerBC);
	PerBC_CA = Calc2PhaseNewPeriode(PerBC, PerCA);
	PerCA_AB = Calc2PhaseNewPeriode(PerCA, PerAB);

	PerD = __max(PerAB_BC, PerBC_CA);
	PerD = __max(PerD, PerCA_AB);
	if ( PerCA_AB == PerD )
	{	IsOK = PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrCA, MaskPtrCA, PerCA, PhasePtrAB, MaskPtrAB, PerAB, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode);	}
	else if ( PerBC_CA == PerD )
	{	IsOK = PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrBC, MaskPtrBC, PerBC, PhasePtrCA, MaskPtrCA, PerCA, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode);	}
	else
	{	IsOK = PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrAB, MaskPtrAB, PerAB, PhasePtrBC, MaskPtrBC, PerBC, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode);	}
	if ( false == IsOK )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);

		JetMemory.free_func(MaskPtrAB);
		JetMemory.free_func(PhasePtrAB);
		JetMemory.free_func(MaskPtrBC);
		JetMemory.free_func(PhasePtrBC);
		JetMemory.free_func(MaskPtrCA);
		JetMemory.free_func(PhasePtrCA);
		return false;
	}	

	JetMemory.free_func(MaskPtrA);
	JetMemory.free_func(PhasePtrA);
	JetMemory.free_func(MaskPtrB);
	JetMemory.free_func(PhasePtrB);
	JetMemory.free_func(MaskPtrC);
	JetMemory.free_func(PhasePtrC);

	JetMemory.free_func(MaskPtrAB);
	JetMemory.free_func(PhasePtrAB);
	JetMemory.free_func(MaskPtrBC);
	JetMemory.free_func(PhasePtrBC);
	JetMemory.free_func(MaskPtrCA);
	JetMemory.free_func(PhasePtrCA);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage4FrameTo3Phase(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, double PerB, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, double PerC, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &MaskPtr, PHASE_PTR &PhasePtr, double &PerD)//3個4張灰階影像解相位
{
	const char fnName[] = "CImageAPI::GrayImage4FrameTo3Phase";
	if ( this->CheckGrayImage12(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, PtrC1, PtrC2, PtrC3, PtrC4) == false ) 
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(PhasePtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false ||
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}

	//	::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//	::memset(PhasePtr, 0x00, sizeof(PHASE_DATA)*BufferSize);
	if ( this->GrayImage4FrameTo3Phase3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PerA, PtrB1, PtrB2, PtrB3, PtrB4, PerB, PtrC1, PtrC2, PtrC3, PtrC4, PerC, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD) == false )	
	{		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage4FrameTo3Phase3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, double PerB, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, double PerC, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//3個4張灰階影像解相位
{
	//return this->GrayImage4FrameTo3Phase3_I(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PerA, PtrB1, PtrB2, PtrB3, PtrB4, PerB, PtrC1, PtrC2, PtrC3, PtrC4, PerC, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);
	return this->GrayImage4FrameTo3Phase3_II(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PerA, PtrB1, PtrB2, PtrB3, PtrB4, PerB, PtrC1, PtrC2, PtrC3, PtrC4, PerC, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage4FrameTo3Phase3_I(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, double PerB, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, double PerC, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//3個4張灰階影像解相位
{
	//PS::合併在一起沒有比GrayImage4FrameTo3Phase3_II來得快, 原因待查!??
	if ( this->CheckGrayImage14(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, PtrC1, PtrC2, PtrC3, PtrC4, MaskPtr, PhasePtr) == false ) 
	{	return false; }	

	int   idx = 0;	
	int   Phase1 = 0;
	int   Phase2 = 0;
	int   PhaseM = 0;

	int   iPhase1 = 0;
	int   iPhase2 = 0;
	int   PhaseAB = 0;
	int   PhaseBC = 0;
	int   PhaseCA = 0;		
	MASK_DATA  MaskA=0, MaskB=0, MaskC=0;	
	PHASE_DATA dA1=0, dA2=0, dA3=0, dA4=0;
	PHASE_DATA dB1=0, dB2=0, dB3=0, dB4=0;
	PHASE_DATA dC1=0, dC2=0, dC3=0, dC4=0;	
	PHASE_DATA PhaseA=0, PhaseB=0, PhaseC=0;	
	size_t i=0, j=0, k=0;
	unsigned char GammaTable[256];
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;
	const int LowContrastC = NoiseParam.PhaseLowContrastC;
	const int LowPotentialC = NoiseParam.PhaseLowPotentialC;
	const int SaturationC = NoiseParam.PhaseOverSaturatedC;

	//Calc2PhaseNewPeriode
	double P1=0, P2=0;	
	const double PerAB = Calc2PhaseNewPeriode(PerA, PerB);
	const double PerBC = Calc2PhaseNewPeriode(PerB, PerC);
	const double PerCA = Calc2PhaseNewPeriode(PerC, PerA);
	const double PerAB_BC = Calc2PhaseNewPeriode(PerAB, PerBC);
	const double PerBC_CA = Calc2PhaseNewPeriode(PerBC, PerCA);
	const double PerCA_AB = Calc2PhaseNewPeriode(PerCA, PerAB);

	int       TriMode   = 0;
	const int ModeAB_BC = 1;
	const int ModeBC_CA = 2;
	const int ModeCA_AB = 3;

	int          P1_Int=0, P2_Int=0;
	const int    PerA_Int = (int)(PerA*1000);
	const int    PerB_Int = (int)(PerB*1000);
	const int    PerC_Int = (int)(PerC*1000);
	const int    PerAB_Int = (int)(PerAB*1000);
	const int    PerBC_Int = (int)(PerBC*1000);
	const int    PerCA_Int = (int)(PerCA*1000);
	const int    PerAB_BC_Int = (int)(PerAB_BC*1000);
	const int    PerBC_CA_Int = (int)(PerBC_CA*1000);
	const int    PerCA_AB_Int = (int)(PerCA_AB*1000);

	PerD = __max(PerAB_BC, PerBC_CA);
	PerD = __max(PerD, PerCA_AB);

	if ( PerCA_AB == PerD )
	{	TriMode = ModeCA_AB;	}
	else if ( PerBC_CA == PerD )
	{	TriMode = ModeBC_CA;	}
	else
	{	TriMode = ModeAB_BC;	}

	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable); }

	for ( i=0; i<BufferSize; i++ )
	{	
		dA1 = PtrA1[i];
		dA2 = PtrA2[i];
		dA3 = PtrA3[i];
		dA4 = PtrA4[i];

		dB1 = PtrB1[i];
		dB2 = PtrB2[i];
		dB3 = PtrB3[i];
		dB4 = PtrB4[i];

		dC1 = PtrC1[i];
		dC2 = PtrC2[i];
		dC3 = PtrC3[i];
		dC4 = PtrC4[i];

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];
			dA4 = GammaTable[dA4];

			dB1 = GammaTable[dB1];
			dB2 = GammaTable[dB2];
			dB3 = GammaTable[dB3];
			dB4 = GammaTable[dB4];

			dC1 = GammaTable[dC1];
			dC2 = GammaTable[dC2];
			dC3 = GammaTable[dC3];
			dC4 = GammaTable[dC4];
		}

		if ( Calc4PhaseParamMask(dA1, dA2, dA3, dA4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA, MaskA, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dB1, dB2, dB3, dB4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB, MaskB, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dC1, dC2, dC3, dC4, PhaseNoiseDef, LowContrastC, LowPotentialC, SaturationC, PhaseC, MaskC, PhaseNoiseDefMode) == false )
		{	return false; }
		//雙週期相位合併-AB
		//P1 = PerA;
		//P2 = PerB;
		//iPhase1 = PhaseA;
		//iPhase2 = PhaseB;
		//if ( PerA < PerB )
		if ( PerA_Int < PerB_Int )		
		{
			Phase1 = PhaseA;
			Phase2 = PhaseB;
			if ( Phase2 > Phase1 )
			{	
				//PhaseAB = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	
				PhaseAB = (Phase1-Phase2+PHASE_PERIOD);	
			}
			else
			{	PhaseAB = Phase1-Phase2;	}
		}		
		else
		{
			Phase1 = PhaseB;//注意相位次序
			Phase2 = PhaseA;//
			if ( Phase2 > Phase1 )
			{	
				//PhaseAB = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	
				PhaseAB = (Phase1-Phase2+PHASE_PERIOD);	
			}
			else
			{	PhaseAB = Phase1-Phase2;	}
		}		
		//PhaseAB = PhaseM;

		//雙週期相位合併-BC
		//P1 = PerB;
		//P2 = PerC;
		//iPhase1 = PhaseB;
		//iPhase2 = PhaseC;
		//if ( PerB < PerC )
		if ( PerB_Int < PerC_Int )		
		{
			Phase1 = PhaseB;
			Phase2 = PhaseC;
			if ( Phase2 > Phase1 )
			{	PhaseBC = (Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseBC = Phase1-Phase2;	}
		}		
		else
		{
			Phase1 = PhaseC;//注意相位次序
			Phase2 = PhaseB;//
			if ( Phase2 > Phase1 )
			{	PhaseBC = (Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseBC = Phase1-Phase2;	}
		}		
		//PhaseBC = PhaseM;

		//雙週期相位合併-CA
		//P1 = PerC;
		//P2 = PerA;
		//iPhase1 = PhaseC;
		//iPhase2 = PhaseA;
		//if ( PerC < PerA )
		if ( PerC_Int < PerA_Int )		
		{
			Phase1 = PhaseC;
			Phase2 = PhaseA;
			if ( Phase2 > Phase1 )
			{	PhaseCA = (Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseCA = Phase1-Phase2;	}
		}		
		else
		{
			Phase1 = PhaseA;//注意相位次序
			Phase2 = PhaseC;//
			if ( Phase2 > Phase1 )
			{	PhaseCA = (Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseCA = Phase1-Phase2;	}
		}		
		//PhaseCA = PhaseM;		

		//第2次雙週期合併-找最後週期最長得來用		
		if ( ModeCA_AB == TriMode )
		{
			//	P1 = PerCA;
			//	P2 = PerAB;
			P1_Int = PerCA_Int;
			P2_Int = PerAB_Int;
			iPhase1 = PhaseCA;
			iPhase2 = PhaseAB;
		}
		else if ( PerBC_CA == TriMode )
		{
			//	P1 = PerBC;
			//	P2 = PerCA;
			P1_Int = PerBC_Int;
			P2_Int = PerCA_Int;
			iPhase1 = PhaseBC;
			iPhase2 = PhaseCA;
		}		
		else//ModeAB_BC
		{
			//	P1 = PerAB;
			//	P2 = PerBC;
			P1_Int = PerAB_Int;
			P2_Int = PerBC_Int;
			iPhase1 = PhaseAB;
			iPhase2 = PhaseBC;
		}		

		//if ( P1 < P2 )
		if ( P1_Int < P2_Int )		
		{
			Phase1 = iPhase1;
			Phase2 = iPhase2;
			if ( Phase2 > Phase1 )
			{	PhaseM = (Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}		
		else
		{
			Phase1 = iPhase2;//注意相位次序
			Phase2 = iPhase1;//
			if ( Phase2 > Phase1 )
			{	PhaseM = (Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}		
		if ( NULL != BasePhasePtr )//扣除相平面
		{	
			PhaseM -= BasePhasePtr[i];//注意若使用unsigned short則需要更大的整數來使用, 避免溢位			
			if ( PhaseM < 0 ) 
			{	PhaseM += PHASE_PERIOD; }
			else if ( PhaseM > PHASE_PERIOD ) 
			{	PhaseM -= PHASE_PERIOD; }
		}
		PhasePtr[i] = static_cast<PHASE_DATA>(PhaseM);		
		if ( (MaskA&PHASE_MASK_LOW_CONTRAST)!=0 || (MaskB&PHASE_MASK_LOW_CONTRAST)!=0 || (MaskC&PHASE_MASK_LOW_CONTRAST)!=0 )
		{	MaskPtr[i] = PHASE_MASK_LOW_CONTRAST;	}
		else if ( (MaskA&PHASE_MASK_OVER_SATURATED)!=0 || (MaskB&PHASE_MASK_OVER_SATURATED)!=0 || (MaskC&PHASE_MASK_OVER_SATURATED)!=0 )
		{	MaskPtr[i] = PHASE_MASK_OVER_SATURATED;	}
		else if ( (MaskA&PHASE_MASK_LOW_POTENTIAL)!=0 || (MaskB&PHASE_MASK_LOW_POTENTIAL)!=0 || (MaskC&PHASE_MASK_LOW_POTENTIAL)!=0 )
		{	MaskPtr[i] = PHASE_MASK_LOW_POTENTIAL;	}
		else
		{	MaskPtr[i] = PHASE_MASK_VALID;	}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage4FrameTo3Phase3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, double PerB, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, double PerC, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//3個4張灰階影像解相位
{
	if ( this->CheckGrayImage14(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrB1, PtrB2, PtrB3, PtrB4, PtrC1, PtrC2, PtrC3, PtrC4, MaskPtr, PhasePtr) == false ) 
	{	return false; }	

	int PatternID = 0;
	unsigned char *MaskPtrA=NULL, *MaskPtrB=NULL, *MaskPtrC=NULL;
	unsigned char *MaskPtrAB=NULL, *MaskPtrBC=NULL, *MaskPtrCA=NULL;
	PHASE_PTR PhasePtrA=NULL;
	PHASE_PTR PhasePtrB=NULL;
	PHASE_PTR PhasePtrC=NULL;	
	PHASE_PTR PhasePtrAB=NULL;
	PHASE_PTR PhasePtrBC=NULL;
	PHASE_PTR PhasePtrCA=NULL;	

	double PerAB = 0;
	double PerBC = 0;
	double PerCA = 0;
	double PerAB_BC = 0;
	double PerBC_CA = 0;
	double PerCA_AB = 0;
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;

	PatternID = PHASE_PATTERN_A;
	if ( GrayImage4FrameToPhase(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PatternID, Gamma, NULL, NoiseParam, MaskPtrA, PhasePtrA) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		return false;
	}

	PatternID = PHASE_PATTERN_B;
	if ( GrayImage4FrameToPhase(ImageW, ImageH, ImageStep, PtrB1, PtrB2, PtrB3, PtrB4, PatternID, Gamma, NULL, NoiseParam, MaskPtrB, PhasePtrB) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		return false;
	}

	PatternID = PHASE_PATTERN_C;
	if ( GrayImage4FrameToPhase(ImageW, ImageH, ImageStep, PtrC1, PtrC2, PtrC3, PtrC4, PatternID, Gamma, NULL, NoiseParam, MaskPtrC, PhasePtrC) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		return false;
	}

	//雙週期合併-AB
	if ( PhaseImage2PeriodeToPhase(ImageW, ImageH, ImageStep, PhasePtrA, MaskPtrA, PerA, PhasePtrB, MaskPtrB, PerB, NULL, PhasePtrAB, MaskPtrAB, PerAB, CombinePeriodMode) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);

		JetMemory.free_func(MaskPtrAB);
		JetMemory.free_func(PhasePtrAB);
		JetMemory.free_func(MaskPtrBC);
		JetMemory.free_func(PhasePtrBC);
		JetMemory.free_func(MaskPtrCA);
		JetMemory.free_func(PhasePtrCA);
		return false;
	}
	//雙週期合併-BC
	if ( PhaseImage2PeriodeToPhase(ImageW, ImageH, ImageStep, PhasePtrB, MaskPtrB, PerB, PhasePtrC, MaskPtrC, PerC, NULL, PhasePtrBC, MaskPtrBC, PerBC, CombinePeriodMode) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);

		JetMemory.free_func(MaskPtrAB);
		JetMemory.free_func(PhasePtrAB);
		JetMemory.free_func(MaskPtrBC);
		JetMemory.free_func(PhasePtrBC);
		JetMemory.free_func(MaskPtrCA);
		JetMemory.free_func(PhasePtrCA);
		return false;
	}
	//雙週期合併-CA
	if ( PhaseImage2PeriodeToPhase(ImageW, ImageH, ImageStep, PhasePtrC, MaskPtrC, PerC, PhasePtrA, MaskPtrA, PerA, NULL, PhasePtrCA, MaskPtrCA, PerCA, CombinePeriodMode) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);

		JetMemory.free_func(MaskPtrAB);
		JetMemory.free_func(PhasePtrAB);
		JetMemory.free_func(MaskPtrBC);
		JetMemory.free_func(PhasePtrBC);
		JetMemory.free_func(MaskPtrCA);
		JetMemory.free_func(PhasePtrCA);
		return false;
	}

	bool IsOK = true;
	PerAB_BC = Calc2PhaseNewPeriode(PerAB, PerBC);
	PerBC_CA = Calc2PhaseNewPeriode(PerBC, PerCA);
	PerCA_AB = Calc2PhaseNewPeriode(PerCA, PerAB);

	PerD = __max(PerAB_BC, PerBC_CA);
	PerD = __max(PerD, PerCA_AB);
	if ( PerCA_AB == PerD )
	{	IsOK = PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrCA, MaskPtrCA, PerCA, PhasePtrAB, MaskPtrAB, PerAB, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode);	}
	else if ( PerBC_CA == PerD )
	{	IsOK = PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrBC, MaskPtrBC, PerBC, PhasePtrCA, MaskPtrCA, PerCA, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode);	}
	else
	{	IsOK = PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrAB, MaskPtrAB, PerAB, PhasePtrBC, MaskPtrBC, PerBC, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode);	}
	if ( false == IsOK )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);

		JetMemory.free_func(MaskPtrAB);
		JetMemory.free_func(PhasePtrAB);
		JetMemory.free_func(MaskPtrBC);
		JetMemory.free_func(PhasePtrBC);
		JetMemory.free_func(MaskPtrCA);
		JetMemory.free_func(PhasePtrCA);
		return false;
	}	

	JetMemory.free_func(MaskPtrA);
	JetMemory.free_func(PhasePtrA);
	JetMemory.free_func(MaskPtrB);
	JetMemory.free_func(PhasePtrB);
	JetMemory.free_func(MaskPtrC);
	JetMemory.free_func(PhasePtrC);

	JetMemory.free_func(MaskPtrAB);
	JetMemory.free_func(PhasePtrAB);
	JetMemory.free_func(MaskPtrBC);
	JetMemory.free_func(PhasePtrBC);
	JetMemory.free_func(MaskPtrCA);
	JetMemory.free_func(PhasePtrCA);

	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage5FrameTo3Phase(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrA5, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrB5, double PerB, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, const unsigned char *PtrC5, double PerC, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR &MaskPtr, PHASE_PTR &PhasePtr, double &PerD)//3個5張灰階影像解相位
{
	const char fnName[] = "CImageAPI::GrayImage5FrameTo3Phase";
	if ( this->CheckGrayImage15(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PtrC1, PtrC2, PtrC3, PtrC4, PtrC5) == false ) 
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(PhasePtr);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false ||
		JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}
	if ( this->GrayImage5FrameTo3Phase3(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PerA, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PerB, PtrC1, PtrC2, PtrC3, PtrC4, PtrC5, PerC, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD) == false )	
	{		
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(PhasePtr);
		return false;
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage5FrameTo3Phase3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrA5, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrB5, double PerB, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, const unsigned char *PtrC5, double PerC, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//3個5張灰階影像解相位
{
	//return this->GrayImage5FrameTo3Phase3_(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PerA, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PerB, PtrC1, PtrC2, PtrC3, PtrC4, PtrC5, PerC, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);
	return this->GrayImage5FrameTo3Phase3_II(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PerA, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PerB, PtrC1, PtrC2, PtrC3, PtrC4, PtrC5, PerC, Gamma, BasePhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage5FrameTo3Phase3_I(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrA5, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrB5, double PerB, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, const unsigned char *PtrC5, double PerC, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//3個5張灰階影像解相位
{
	//PS::合併在一起沒有比GrayImage5FrameTo3Phase3_II來得快, 原因待查!??
	if ( this->CheckGrayImage17(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PtrC1, PtrC2, PtrC3, PtrB4, PtrB5, MaskPtr, PhasePtr) == false ) 
	{	return false; }

	int   Phase1 = 0;
	int   Phase2 = 0;
	int   PhaseM = 0;

	int   iPhase1 = 0;
	int   iPhase2 = 0;
	int   PhaseAB = 0;
	int   PhaseBC = 0;
	int   PhaseCA = 0;	
	MASK_DATA  MaskA=0, MaskB=0, MaskC=0;	
	PHASE_DATA dA1=0, dA2=0, dA3=0, dA4=0, dA5=0;
	PHASE_DATA dB1=0, dB2=0, dB3=0, dB4=0, dB5=0;
	PHASE_DATA dC1=0, dC2=0, dC3=0, dC4=0, dC5=0;
	PHASE_DATA PhaseA=0, PhaseB=0, PhaseC=0;	
	size_t i=0, j=0, k=0, idx=0;		
	unsigned char GammaTable[256];
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();		
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;
	const int LowContrastC = NoiseParam.PhaseLowContrastC;
	const int LowPotentialC = NoiseParam.PhaseLowPotentialC;
	const int SaturationC = NoiseParam.PhaseOverSaturatedC;

	//Calc2PhaseNewPeriode
	double P1=0, P2=0;
	const double PerAB = Calc2PhaseNewPeriode(PerA, PerB);
	const double PerBC = Calc2PhaseNewPeriode(PerB, PerC);
	const double PerCA = Calc2PhaseNewPeriode(PerC, PerA);
	const double PerAB_BC = Calc2PhaseNewPeriode(PerAB, PerBC);
	const double PerBC_CA = Calc2PhaseNewPeriode(PerBC, PerCA);
	const double PerCA_AB = Calc2PhaseNewPeriode(PerCA, PerAB);

	int       TriMode   = 0;
	const int ModeAB_BC = 1;
	const int ModeBC_CA = 2;
	const int ModeCA_AB = 3;

	PerD = __max(PerAB_BC, PerBC_CA);
	PerD = __max(PerD, PerCA_AB);

	if ( PerCA_AB == PerD )
	{	TriMode = ModeCA_AB;	}
	else if ( PerBC_CA == PerD )
	{	TriMode = ModeBC_CA;	}
	else
	{	TriMode = ModeAB_BC;	}

	if ( true == bUseGamma )
	{	BuildGammaLookUpTable(Gamma, GammaTable); }

	for ( i=0; i<BufferSize; i++ )
	{	
		dA1 = PtrA1[i];
		dA2 = PtrA2[i];
		dA3 = PtrA3[i];
		dA4 = PtrA4[i];
		dA5 = PtrA5[i];

		dB1 = PtrB1[i];
		dB2 = PtrB2[i];
		dB3 = PtrB3[i];
		dB4 = PtrB4[i];
		dB5 = PtrB5[i];

		dC1 = PtrC1[i];
		dC2 = PtrC2[i];
		dC3 = PtrC3[i];
		dC4 = PtrC4[i];
		dC5 = PtrC5[i];

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];
			dA4 = GammaTable[dA4];
			dA5 = GammaTable[dA5];

			dB1 = GammaTable[dB1];
			dB2 = GammaTable[dB2];
			dB3 = GammaTable[dB3];
			dB4 = GammaTable[dB4];
			dB5 = GammaTable[dB5];

			dC1 = GammaTable[dC1];
			dC2 = GammaTable[dC2];
			dC3 = GammaTable[dC3];
			dC4 = GammaTable[dC4];
			dC5 = GammaTable[dC5];
		}

		if ( Calc5PhaseParamMask(dA1, dA2, dA3, dA4, dA5, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA, MaskA) == false )
		{	return false; }
		if ( Calc5PhaseParamMask(dB1, dB2, dB3, dB4, dB5, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB, MaskB) == false )
		{	return false; }
		if ( Calc5PhaseParamMask(dC1, dC2, dC3, dC4, dC5, PhaseNoiseDef, LowContrastC, LowPotentialC, SaturationC, PhaseC, MaskC) == false )
		{	return false; }

		//雙週期相位合併-AB
		P1 = PerA;
		P2 = PerB;
		iPhase1 = PhaseA;
		iPhase2 = PhaseB;
		if ( P1 < P2 )
		{
			Phase1 = iPhase1;
			Phase2 = iPhase2;
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}
		else
		{
			Phase1 = iPhase2;//注意相位次序
			Phase2 = iPhase1;//
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}	
		PhaseAB = PhaseM;

		//雙週期相位合併-BC
		P1 = PerB;
		P2 = PerC;
		iPhase1 = PhaseB;
		iPhase2 = PhaseC;
		if ( P1 < P2 )
		{
			Phase1 = iPhase1;
			Phase2 = iPhase2;
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}
		else
		{
			Phase1 = iPhase2;//注意相位次序
			Phase2 = iPhase1;//
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}	
		PhaseBC = PhaseM;

		//雙週期相位合併-CA
		P1 = PerC;
		P2 = PerA;
		iPhase1 = PhaseC;
		iPhase2 = PhaseA;
		if ( P1 < P2 )
		{
			Phase1 = iPhase1;
			Phase2 = iPhase2;
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}
		else
		{
			Phase1 = iPhase2;//注意相位次序
			Phase2 = iPhase1;//
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}	
		PhaseCA = PhaseM;

		//第2次雙週期合併-找最後週期最長得來用
		if ( ModeCA_AB == TriMode )
		{
			P1 = PerCA;
			P2 = PerAB;
			iPhase1 = PhaseCA;
			iPhase2 = PhaseAB;
		}
		else if ( PerBC_CA == TriMode )
		{
			P1 = PerBC;
			P2 = PerCA;
			iPhase1 = PhaseBC;
			iPhase2 = PhaseCA;
		}
		else//ModeAB_BC
		{
			P1 = PerAB;
			P2 = PerBC;
			iPhase1 = PhaseAB;
			iPhase2 = PhaseBC;
		}
		if ( P1 < P2 )
		{
			Phase1 = iPhase1;
			Phase2 = iPhase2;
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}
		else
		{
			Phase1 = iPhase2;//注意相位次序
			Phase2 = iPhase1;//
			if ( Phase2 > Phase1 )
			{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
			else
			{	PhaseM = Phase1-Phase2;	}
		}		
		if ( NULL != BasePhasePtr )//扣除相平面
		{	
			PhaseM -= BasePhasePtr[i];//注意若使用unsigned short則需要更大的整數來使用, 避免溢位			
			if ( PhaseM < 0 ) 
			{	PhaseM += PHASE_PERIOD; }			
			else if ( PhaseM > PHASE_PERIOD ) 
			{	PhaseM -= PHASE_PERIOD; }			
		}
		PhasePtr[i] = static_cast<PHASE_DATA>(PhaseM);		
		if ( (MaskA&PHASE_MASK_LOW_CONTRAST)!=0 || (MaskB&PHASE_MASK_LOW_CONTRAST)!=0 || (MaskC&PHASE_MASK_LOW_CONTRAST)!=0 )
		{	MaskPtr[i] = PHASE_MASK_LOW_CONTRAST;	}
		else if ( (MaskA&PHASE_MASK_OVER_SATURATED)!=0 || (MaskB&PHASE_MASK_OVER_SATURATED)!=0 || (MaskC&PHASE_MASK_OVER_SATURATED)!=0 )
		{	MaskPtr[i] = PHASE_MASK_OVER_SATURATED;	}
		else if ( (MaskA&PHASE_MASK_LOW_POTENTIAL)!=0 || (MaskB&PHASE_MASK_LOW_POTENTIAL)!=0 || (MaskC&PHASE_MASK_LOW_POTENTIAL)!=0 )
		{	MaskPtr[i] = PHASE_MASK_LOW_POTENTIAL;	}
		else
		{	MaskPtr[i] = PHASE_MASK_VALID;	}				
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImage5FrameTo3Phase3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *PtrA1, const unsigned char *PtrA2, const unsigned char *PtrA3, const unsigned char *PtrA4, const unsigned char *PtrA5, double PerA, const unsigned char *PtrB1, const unsigned char *PtrB2, const unsigned char *PtrB3, const unsigned char *PtrB4, const unsigned char *PtrB5, double PerB, const unsigned char *PtrC1, const unsigned char *PtrC2, const unsigned char *PtrC3, const unsigned char *PtrC4, const unsigned char *PtrC5, double PerC, float Gamma, const PHASE_PTR BasePhasePtr, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, PHASE_PTR PhasePtr, double &PerD)//3個5張灰階影像解相位
{
	if ( CheckGrayImage17(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PtrC1, PtrC2, PtrC3, PtrB4, PtrB5, MaskPtr, PhasePtr) == false ) 
	{	return false; }	

	int PatternID = 0;
	unsigned char *MaskPtrA=NULL, *MaskPtrB=NULL, *MaskPtrC=NULL;	
	unsigned char *MaskPtrAB=NULL, *MaskPtrBC=NULL, *MaskPtrCA=NULL;
	PHASE_PTR PhasePtrA=NULL;
	PHASE_PTR PhasePtrB=NULL;
	PHASE_PTR PhasePtrC=NULL;
	PHASE_PTR PhasePtrAB=NULL;
	PHASE_PTR PhasePtrBC=NULL;
	PHASE_PTR PhasePtrCA=NULL;	

	double PerAB = 0;
	double PerBC = 0;
	double PerCA = 0;
	double PerAB_BC = 0;
	double PerBC_CA = 0;
	double PerCA_AB = 0;
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;

	PatternID = PHASE_PATTERN_A;
	if ( GrayImage5FrameToPhase(ImageW, ImageH, ImageStep, PtrA1, PtrA2, PtrA3, PtrA4, PtrA5, PatternID, Gamma, NULL, NoiseParam, MaskPtrA, PhasePtrA) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		return false;
	}

	PatternID = PHASE_PATTERN_B;
	if ( GrayImage5FrameToPhase(ImageW, ImageH, ImageStep, PtrB1, PtrB2, PtrB3, PtrB4, PtrB5, PatternID, Gamma, NULL, NoiseParam, MaskPtrB, PhasePtrB) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		return false;
	}

	PatternID = PHASE_PATTERN_C;
	if ( GrayImage5FrameToPhase(ImageW, ImageH, ImageStep, PtrC1, PtrC2, PtrC3, PtrC4, PtrC5, PatternID, Gamma, NULL, NoiseParam, MaskPtrC, PhasePtrC) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);
		return false;
	}

	//雙週期合併-AB
	if ( PhaseImage2PeriodeToPhase(ImageW, ImageH, ImageStep, PhasePtrA, MaskPtrA, PerA, PhasePtrB, MaskPtrB, PerB, NULL, PhasePtrAB, MaskPtrAB, PerAB, CombinePeriodMode) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);

		JetMemory.free_func(MaskPtrAB);
		JetMemory.free_func(PhasePtrAB);
		JetMemory.free_func(MaskPtrBC);
		JetMemory.free_func(PhasePtrBC);
		JetMemory.free_func(MaskPtrCA);
		JetMemory.free_func(PhasePtrCA);
		return false;
	}
	//雙週期合併-BC
	if ( PhaseImage2PeriodeToPhase(ImageW, ImageH, ImageStep, PhasePtrB, MaskPtrB, PerB, PhasePtrC, MaskPtrC, PerC, NULL, PhasePtrBC, MaskPtrBC, PerBC, CombinePeriodMode) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);

		JetMemory.free_func(MaskPtrAB);
		JetMemory.free_func(PhasePtrAB);
		JetMemory.free_func(MaskPtrBC);
		JetMemory.free_func(PhasePtrBC);
		JetMemory.free_func(MaskPtrCA);
		JetMemory.free_func(PhasePtrCA);
		return false;
	}
	//雙週期合併-CA
	if ( PhaseImage2PeriodeToPhase(ImageW, ImageH, ImageStep, PhasePtrC, MaskPtrC, PerC, PhasePtrA, MaskPtrA, PerA, NULL, PhasePtrCA, MaskPtrCA, PerCA, CombinePeriodMode) == false )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);

		JetMemory.free_func(MaskPtrAB);
		JetMemory.free_func(PhasePtrAB);
		JetMemory.free_func(MaskPtrBC);
		JetMemory.free_func(PhasePtrBC);
		JetMemory.free_func(MaskPtrCA);
		JetMemory.free_func(PhasePtrCA);
		return false;
	}

	bool IsOK = true;
	PerAB_BC = Calc2PhaseNewPeriode(PerAB, PerBC);
	PerBC_CA = Calc2PhaseNewPeriode(PerBC, PerCA);
	PerCA_AB = Calc2PhaseNewPeriode(PerCA, PerAB);

	PerD = __max(PerAB_BC, PerBC_CA);
	PerD = __max(PerD, PerCA_AB);
	if ( PerCA_AB == PerD )
	{	IsOK = PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrCA, MaskPtrCA, PerCA, PhasePtrAB, MaskPtrAB, PerAB, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode);	}
	else if ( PerBC_CA == PerD )
	{	IsOK = PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrBC, MaskPtrBC, PerBC, PhasePtrCA, MaskPtrCA, PerCA, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode);	}
	else
	{	IsOK = PhaseImage2PeriodeToPhase3(ImageW, ImageH, ImageStep, PhasePtrAB, MaskPtrAB, PerAB, PhasePtrBC, MaskPtrBC, PerBC, BasePhasePtr, PhasePtr, MaskPtr, PerD, CombinePeriodMode);	}
	if ( false == IsOK )
	{		
		JetMemory.free_func(MaskPtrA);
		JetMemory.free_func(PhasePtrA);
		JetMemory.free_func(MaskPtrB);
		JetMemory.free_func(PhasePtrB);
		JetMemory.free_func(MaskPtrC);
		JetMemory.free_func(PhasePtrC);

		JetMemory.free_func(MaskPtrAB);
		JetMemory.free_func(PhasePtrAB);
		JetMemory.free_func(MaskPtrBC);
		JetMemory.free_func(PhasePtrBC);
		JetMemory.free_func(MaskPtrCA);
		JetMemory.free_func(PhasePtrCA);
		return false;
	}	

	JetMemory.free_func(MaskPtrA);
	JetMemory.free_func(PhasePtrA);
	JetMemory.free_func(MaskPtrB);
	JetMemory.free_func(PhasePtrB);
	JetMemory.free_func(MaskPtrC);
	JetMemory.free_func(PhasePtrC);

	JetMemory.free_func(MaskPtrAB);
	JetMemory.free_func(PhasePtrAB);
	JetMemory.free_func(MaskPtrBC);
	JetMemory.free_func(PhasePtrBC);
	JetMemory.free_func(MaskPtrCA);
	JetMemory.free_func(PhasePtrCA);	
	return true;
}
