bool CImageAPI::CorrectPhaseZero_Joe(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const PHASE_PTR SrcPtr, PHASE_PTR &DstPtr, int Times)//相平面濾波
{
	const char fnName[] = "CImageAPI::CorrectPhaseZero_Joe";
	if ( CheckGrayImage(ImageW, ImageH, ImageStep, SrcPtr) == false )	
	{	return false; }

	JetMemory.free_func(DstPtr);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, DstPtr, fnName, "DstPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());		
		return false;
	}

	if ( CorrectPhaseZero_Joe3(ImageW, ImageH, ImageStep, SrcPtr, DstPtr, Times) == false )
	{		
		JetMemory.free_func(DstPtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CorrectPhaseZero_Joe3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const PHASE_PTR SrcPtr, PHASE_PTR DstPtr, int Times)//相平面濾波
{
	if ( CheckGrayImage2(ImageW, ImageH, ImageStep, SrcPtr, DstPtr) == false )	
	{	return false; }
	if ( CheckPtrNoRepeat2(SrcPtr, DstPtr) == false )
	{	return false; }

	int SrcType=CV_8U;
	int DstType=CV_8U;	
	double PhaseMax = PHASE_PERIOD;	
#if PHASE_TYPE == DATA_SHORT
	SrcType=CV_16S;
	DstType=CV_16S;
#elif PHASE_TYPE == DATA_USORT
	SrcType=CV_16U;
	DstType=CV_16U;
#endif//PHASE_TYPE

	JET::alg::CRegression Regression;
	const int OpenMPCount = AOIDataCollect.GetOpenMPCount_General();	
	Regression.SetMultiThreadNum(OpenMPCount);	
	Regression.Calibrate_BasePhase(SrcPtr, DstPtr, ImageStep, ImageH, SrcType, DstType, PhaseMax, Times);
	return true;
}
