bool CImageAPI::PatternCast1ToSpace3_II_MP_Fn_4X4GC(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//1投光影像轉成高度資料
{
	const int BufferSize = (int)(ImageStep*ImageH);
	if ( index<0 || index>=BufferSize ) { return false; }

	int   nPhase = 0;
	float phase = 0.0f;		
	int   Phase1 = 0;
	int   Phase2 = 0;	
	int   PhaseM_1 = 0;
	int   k1_1 = 0, k2_1 = 0;
	float Threshold_1=0.0f;
	float Space_1=0.0f,Space_M=0.0f;
	MASK_DATA  Mask_1=0;	
	MASK_DATA  Mask_M=0;
	MASK_DATA  MaskA_1=0, MaskB_1=0;	

	IMAGE_DATA *PtrA1_1=NULL, *PtrA2_1=NULL, *PtrA3_1=NULL, *PtrA4_1=NULL;
	IMAGE_DATA *PtrB1_1=NULL, *PtrB2_1=NULL, *PtrB3_1=NULL, *PtrB4_1=NULL;
	PHASE_DATA *BasePhasePtr_1=NULL;
	SPACE_DATA *HeightFactorPtr_1=NULL;
	SPACE_DATA *HeightFactorPtr_1_2=NULL;
	double     *HeightFactor0_1 = NULL;
	double     *HeightFactor1_1 = NULL;
	double     *HeightFactor2_1 = NULL;
	unsigned char *GammaTablePtr_1=NULL;
	unsigned char *CodeK1MapPtr_1=NULL;
	unsigned char *CodeK2MapPtr_1=NULL;

	PHASE_DATA PhaseA_1=0, PhaseB_1=0;
	PHASE_DATA PhaseA_2=0, PhaseB_2=0;	
	PHASE_DATA dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	PHASE_DATA dB1_1=0, dB2_1=0, dB3_1=0, dB4_1=0;

	int    ImageX=0, ImageY=0;	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int   PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;

	const int MaxN = 8;//最多8個16週期
	const int Period = PHASE_PERIOD;

	const double PerA = CastParam.PerA;
	const double PerB = CastParam.PerB;
	const double PerD = PerB;	
	const float  ExpTimeRatio_1=(1.0f*CastParam.ExpTimeB/CastParam.ExpTimeA);	

	PtrA1_1 = CastParam.PtrA1;	PtrA2_1 = CastParam.PtrA2;	PtrA3_1 = CastParam.PtrA3;	PtrA4_1 = CastParam.PtrA4;
	PtrB1_1 = CastParam.PtrB1;	PtrB2_1 = CastParam.PtrB2;	PtrB3_1 = CastParam.PtrB3;	PtrB4_1 = CastParam.PtrB4;
	BasePhasePtr_1 = CastParam.ZeroPhasePtr;
	HeightFactorPtr_1 = CastParam.HeightFactorPtr;
	HeightFactor0_1 = (double*)CastParam.HeightFactor0;
	HeightFactor1_1 = (double*)CastParam.HeightFactor1;
	HeightFactor2_1 = (double*)CastParam.HeightFactor2;
	GammaTablePtr_1=CastParam.GammaTablePtr;
	CodeK1MapPtr_1=CastParam.GCK1MapPtr;
	CodeK2MapPtr_1=CastParam.GCK2MapPtr;

	//CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatioA);

	const int i = index;
	const int x = i%ImageStep;
	const int y = i/ImageStep;
	{
		dA1_1 = PtrA1_1[i];	dA2_1 = PtrA2_1[i];	dA3_1 = PtrA3_1[i];	dA4_1 = PtrA4_1[i];
		dB1_1 = PtrB1_1[i];	dB2_1 = PtrB2_1[i];	dB3_1 = PtrB3_1[i];	dB4_1 = PtrB4_1[i];

		if ( NULL != GammaTablePtr_1 )
		{
			dA1_1 = GammaTablePtr_1[dA1_1];
			dA2_1 = GammaTablePtr_1[dA2_1];
			dA3_1 = GammaTablePtr_1[dA3_1];
			dA4_1 = GammaTablePtr_1[dA4_1];
			dB1_1 = GammaTablePtr_1[dB1_1];
			dB2_1 = GammaTablePtr_1[dB2_1];
			dB3_1 = GammaTablePtr_1[dB3_1];
			dB4_1 = GammaTablePtr_1[dB4_1];			
		}		

		Threshold_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
		Threshold_1=(float)(Threshold_1*ExpTimeRatio_1);

		Calc4GrayCodeParam(dB1_1, dB2_1, dB3_1, dB4_1, Threshold_1, CodeK1MapPtr_1, CodeK2MapPtr_1, k1_1, k2_1);

		if ( Calc4PhaseParamMask(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_1, MaskA_1, PhaseNoiseDefMode) == false )
		{	return false; }		

		//雙週期相位合併
		PhaseM_1 = CombinePhasePeriod_GrayCode(PhaseA_1, Period, MaxN, k1_1, k2_1);

		if ( NULL != BasePhasePtr_1 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_1[i], PhaseM_1);	}		

		Space_1 = PhaseM_1;

		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_1);

		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);		

		Mask_1 = MaskA_1;
		Mask_M = Mask_1;
		Space_M = Space_1;
		MaskPtr[i] = Mask_M;		
		SpacePtr[i] = Space_M;		

		if ( NULL != CastParam.PtrMask )	{	CastParam.PtrMask[i] = Mask_M;	}
		if ( NULL != CastParam.PtrSpace )	{	CastParam.PtrSpace[i] = Space_M;	}
	}
	return true;
}
