//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast1ToSpace2Exp(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam, TPhaseNoiseParam &NoiseParam, bool bOpenMP, MASK_PTR &MaskPtr, SPACE_PTR &SpacePtr)//1投光2曝光影像轉成高度資料
{
	const char fnName[] = "CImageAPI::PatternCast1ToSpace2Exp";
	if ( CheckCastParamExp2(CastParam) == false )
	{	return false; }		
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam) == false )
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(SpacePtr);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false ||
		JetMemory.alloc_func(BufferSize, SpacePtr, fnName, "SpacePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(SpacePtr);
		return false;
	}

	if ( PatternCast1ToSpace2Exp3(ImageW, ImageH, ImageStep, CastParam, NoiseParam, bOpenMP, MaskPtr, SpacePtr) == false )
	{
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(SpacePtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast1ToSpace2Exp3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam, TPhaseNoiseParam &NoiseParam, bool bOpenMP, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//1投光2曝光影像轉成高度資料
{
	bool IsOK = true;
	//IsOK = PatternCast1ToSpace2Exp3_I(ImageW, ImageH, ImageStep, CastParam, NoiseParam, bOpenMP, MaskPtr, SpacePtr);
	IsOK = PatternCast1ToSpace2Exp3_II(ImageW, ImageH, ImageStep, CastParam, NoiseParam, bOpenMP, MaskPtr, SpacePtr);
	if ( false == IsOK )
	{	return false; }
	return true;

	size_t  i=0;
	const char fnName[] = "CImageAPI::PatternCast1ToSpace2Exp3";
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);
	const int CudaBlockNumber = SysParam.m_CudaBlockNumber;
	const int CudaThreadNumber = SysParam.m_CudaThreadNumber;
	MASK_PTR  MaskTmpPtr=NULL;
	SPACE_PTR SpaceTmpPtr=NULL;
	if ( JetMemory.alloc_func(BufferSize, MaskTmpPtr, fnName, "MaskTmpPtr") == false || 
		JetMemory.alloc_func(BufferSize, SpaceTmpPtr, fnName, "SpaceTmpPtr") == false )
	{
		JetMemory.free_func(MaskTmpPtr);
		JetMemory.free_func(SpaceTmpPtr);
		return true;
	}	
	if ( CudaFunc.CudaSolveSpace4Frames2Period1Cast2Exp(ImageW, ImageH, ImageStep, CastParam, NoiseParam, MaskTmpPtr, SpaceTmpPtr, CudaThreadNumber, CudaBlockNumber) == false )
	{
		JetMemory.free_func(MaskTmpPtr);
		JetMemory.free_func(SpaceTmpPtr);
		return true;
	}

	int MaskErrCnt=0;
	int SpaceErrCnt=0;
	double SpaceError=0;
	double SpaceErrorMax=0;
	for ( i=0; i<BufferSize; i++ )
	{
		if ( MaskTmpPtr[i] != MaskPtr[i] )
		{	MaskErrCnt ++ ; }

		SpaceError = fabs(SpacePtr[i]-SpaceTmpPtr[i]);
		if ( SpaceErrorMax < SpaceError )
		{	SpaceErrorMax = SpaceError; }
		if ( SpaceError > 1 )
		{	SpaceErrCnt ++; }

		if ( SpaceError > 1000 )
		{	SpaceErrorMax = SpaceErrorMax; }
	}
	JetMemory.free_func(MaskTmpPtr);
	JetMemory.free_func(SpaceTmpPtr);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast1ToSpace2Exp3_I(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam, TPhaseNoiseParam &NoiseParam, bool bOpenMP, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//1投光2曝光影像轉成高度資料
{	
#ifdef CUDA_USE
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if ( SysParam.m_CudaFnEnabled==FN_ENABLE && true== IsCudaDeviceUse )
	{
		const int CudaBlockNumber = SysParam.m_CudaBlockNumber;
		const int CudaThreadNumber = SysParam.m_CudaThreadNumber;		
		if ( CudaFunc.CudaSolveSpace4Frames2Period1Cast2Exp(ImageW, ImageH, ImageStep, CastParam, NoiseParam, MaskPtr, SpacePtr, CudaThreadNumber, CudaBlockNumber) == false )
		{
			SetErrorString(CudaFunc.GetErrorString());
			return false;
		}
		return true;
	}	
#endif//CUDA_USE
	const char fnName[] = "CImageAPI::PatternCast1ToSpace2Exp3_I";	
	if ( CheckCastParamExp2(CastParam) == false )
	{	return false; }		
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam) == false )
	{	return false; }
	PHASE_PTR PhasePtr = NULL;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}

	bool IsOK = false;
	double PerD = 0;
	int    PatternID = 0;
	float  Gamma = CastParam.Gamma;	
	DECODE_PHASE_MODE DecodeMode = CastParam.DecodeMode;
	switch ( DecodeMode )
	{
	case DECODE_PHASE_3STEP_1:
		PatternID = PHASE_PATTERN_A;
		IsOK = GrayImage3FrameToPhase2Exp3(ImageW, ImageH, ImageStep, CastParam.PtrA1, CastParam.PtrA2, CastParam.PtrA3, CastParam.PtrC1, CastParam.PtrC2, CastParam.PtrC3, PatternID, Gamma, CastParam.ZeroPhasePtr, NoiseParam, MaskPtr, PhasePtr);
		break;
	case DECODE_PHASE_4STEP_1:
		PatternID = PHASE_PATTERN_A;
		IsOK = GrayImage4FrameToPhase2Exp3(ImageW, ImageH, ImageStep, CastParam.PtrA1, CastParam.PtrA2, CastParam.PtrA3, CastParam.PtrA4, CastParam.PtrC1, CastParam.PtrC2, CastParam.PtrC3, CastParam.PtrC4, PatternID, Gamma, CastParam.ZeroPhasePtr, NoiseParam, MaskPtr, PhasePtr);
		break;
	case DECODE_PHASE_5STEP_1:
		PatternID = PHASE_PATTERN_A;
		IsOK = GrayImage5FrameToPhase2Exp3(ImageW, ImageH, ImageStep, CastParam.PtrA1, CastParam.PtrA2, CastParam.PtrA3, CastParam.PtrA4, CastParam.PtrA5, CastParam.PtrC1, CastParam.PtrC2, CastParam.PtrC3, CastParam.PtrC4, CastParam.PtrC5, PatternID, Gamma, CastParam.ZeroPhasePtr, NoiseParam, MaskPtr, PhasePtr);
		break;
	case DECODE_PHASE_3_3STEP_2:
		IsOK = GrayImage3FrameTo2Phase2Exp3(ImageW, ImageH, ImageStep, CastParam.PtrA1, CastParam.PtrA2, CastParam.PtrA3, CastParam.PtrC1, CastParam.PtrC2, CastParam.PtrC3, CastParam.PerA, CastParam.PtrB1, CastParam.PtrB2, CastParam.PtrB3, CastParam.PtrD1, CastParam.PtrD2, CastParam.PtrD3, CastParam.PerB, Gamma, CastParam.ZeroPhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);
		break;
	case DECODE_PHASE_4_4STEP_2:
		IsOK = GrayImage4FrameTo2Phase2Exp3(ImageW, ImageH, ImageStep, CastParam.PtrA1, CastParam.PtrA2, CastParam.PtrA3, CastParam.PtrA4, CastParam.PtrC1, CastParam.PtrC2, CastParam.PtrC3, CastParam.PtrC4, CastParam.PerA, CastParam.PtrB1, CastParam.PtrB2, CastParam.PtrB3, CastParam.PtrB4, CastParam.PtrD1, CastParam.PtrD2, CastParam.PtrD3, CastParam.PtrD4, CastParam.PerB, Gamma, CastParam.ZeroPhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);
		break;
	case DECODE_PHASE_5_5STEP_2:
		IsOK = GrayImage5FrameTo2Phase2Exp3(ImageW, ImageH, ImageStep, CastParam.PtrA1, CastParam.PtrA2, CastParam.PtrA3, CastParam.PtrA4, CastParam.PtrA5, CastParam.PtrC1, CastParam.PtrC2, CastParam.PtrC3, CastParam.PtrC4, CastParam.PtrC5, CastParam.PerA, CastParam.PtrB1, CastParam.PtrB2, CastParam.PtrB3, CastParam.PtrB4, CastParam.PtrB5, CastParam.PtrD1, CastParam.PtrD2, CastParam.PtrD3, CastParam.PtrD4, CastParam.PtrD5, CastParam.PerB, Gamma, CastParam.ZeroPhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);
		break;
	case DECODE_PHASE_2_2STEP_2:
		IsOK = GrayImage221FrameTo2Phase2Exp3(ImageW, ImageH, ImageStep, CastParam.PtrA1, CastParam.PtrA2, CastParam.PtrC1, CastParam.PtrC2, CastParam.PerA, CastParam.ExpTimeA, CastParam.ExpTimeC, CastParam.PtrB1, CastParam.PtrB2, CastParam.PtrB3, CastParam.PtrD1, CastParam.PtrD2, CastParam.PtrD3, CastParam.PerB, CastParam.ExpTimeB, CastParam.ExpTimeD, Gamma, CastParam.ZeroPhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);
		break;
	case DECODE_PHASE_4_2STEP_2:
		IsOK = GrayImage42FrameTo2Phase2Exp3(ImageW, ImageH, ImageStep, CastParam.PtrA1, CastParam.PtrA2, CastParam.PtrA3, CastParam.PtrA4, CastParam.PtrC1, CastParam.PtrC2, CastParam.PtrC3, CastParam.PtrC4, CastParam.PerA, CastParam.ExpTimeA, CastParam.ExpTimeC, CastParam.PtrB1, CastParam.PtrB2, CastParam.PtrD1, CastParam.PtrD2, CastParam.PerB, CastParam.ExpTimeB, CastParam.ExpTimeD, Gamma, CastParam.ZeroPhasePtr, NoiseParam, MaskPtr, PhasePtr, PerD);
		break;
	}
	if ( false == IsOK )
	{	
		JetMemory.free_func(PhasePtr);
		return false;
	}

	const int PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	if ( PHASE_CONVERT_HEIGHT_SCALE == PhaseConvertHeightMode )
	{
		if ( PhaseImageToSpaceImage3(ImageW, ImageH, ImageStep, PhasePtr, CastParam.HeightFactorPtr, MaskPtr, SpacePtr) == false )
		{
			JetMemory.free_func(PhasePtr);
			return false;
		}
	}
	else
	{
		const int SX = 0;
		const int SY = 0;
		const double *T0 = CastParam.HeightFactor0;
		const double *T1 = CastParam.HeightFactor1;
		const double *T2 = CastParam.HeightFactor2;
		if ( PhaseImageToSpaceImageByMapping3(PhaseConvertHeightMode, ImageW, ImageH, ImageStep, PhasePtr, SX, SY, T0, T1, T2, MaskPtr, SpacePtr) == false )
		{
			JetMemory.free_func(PhasePtr);
			return false;
		}
	}
	JetMemory.free_func(PhasePtr);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast1ToSpace2Exp3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam, TPhaseNoiseParam &NoiseParam, bool bOpenMP, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//1投光2曝光影像轉成高度資料
{
#ifdef CUDA_USE
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if ( SysParam.m_CudaFnEnabled==FN_ENABLE && true== IsCudaDeviceUse )
	{
		const int CudaBlockNumber = SysParam.m_CudaBlockNumber;
		const int CudaThreadNumber = SysParam.m_CudaThreadNumber;		
		if ( CudaFunc.CudaSolveSpace4Frames2Period1Cast2Exp(ImageW, ImageH, ImageStep, CastParam, NoiseParam, MaskPtr, SpacePtr, CudaThreadNumber, CudaBlockNumber) == false )
		{
			SetErrorString(CudaFunc.GetErrorString());
			return false;
		}
		return true;
	}	
#endif//CUDA_USE

	bool IsOK = true;	
	const int nImageSize = (ImageW)*(ImageH);
	const bool OpenMPUsed = AOIDataCollect.CheckOpenMPUsed_CalcPhase(nImageSize);
	if ( false == OpenMPUsed )
	{	bOpenMP = false; }
	if ( true == bOpenMP )
	{	IsOK = PatternCast1ToSpace2Exp3_II_MP(ImageW, ImageH, ImageStep, CastParam, NoiseParam, MaskPtr, SpacePtr);	}
	else
	{	IsOK = PatternCast1ToSpace2Exp3_II_SP(ImageW, ImageH, ImageStep, CastParam, NoiseParam, MaskPtr, SpacePtr);	}
	return IsOK;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast1ToSpace2Exp3_II_SP(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam1, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//1投光2曝光影像轉成高度資料
{
	if ( CheckCastParamExp2(CastParam1) == false )
	{	return false; }			
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam1) == false )
	{	return false; }	
	//if ( 16!=CastParam1.ImageCount )
	//{	return false; }	

	int           i=0;
	float         Gamma_1=1.0f;
	int           ImageX=0, ImageY=0;		
	unsigned char GammaTable_1[256];
	const int     BufferSize = (int)(ImageStep*ImageH);	
	const bool    bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();

	Gamma_1 = CastParam1.Gamma;	
	if ( true == bUseGamma )
	{	
		BuildGammaLookUpTable(Gamma_1, GammaTable_1); 		
		CastParam1.GammaTablePtr = GammaTable_1;		
	}
	else
	{	CastParam1.GammaTablePtr = NULL;	}

	std::vector<unsigned char> CodeMap3;
	std::vector<unsigned char> CodeMap4;
	std::vector<unsigned char> CodeMap5;
	std::vector<unsigned char> CodeMap6;
	BuildGrayCodeMapTable(3, CodeMap3);
	BuildGrayCodeMapTable(4, CodeMap4);
	BuildGrayCodeMapTable(5, CodeMap5);
	BuildGrayCodeMapTable(6, CodeMap6);
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam1) == false )
	{	return false; }	

	for ( i=0; i<BufferSize; i++ )
	{			
#ifdef _DEBUG
		ImageX = i%ImageStep;
		ImageY = i/ImageStep;
		if ( 2240==ImageX && 584==ImageY )
		{	i = i; }
#endif//ImageX=0, ImageY=0;
		//20190530
		//if ( 3145728 == i )//Compare JET6500
		//{	i = 3145728;	}			
		if ( PatternCast1ToSpace2Exp3_II_MP_Fn(i, ImageW, ImageH, ImageStep, CastParam1, NoiseParam, MaskPtr, SpacePtr) == false )
		{
			CastParam1.GammaTablePtr = NULL;			
			return false; 
		}
	}	
	CastParam1.GammaTablePtr = NULL;		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast1ToSpace2Exp3_II_MP(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam1, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//1投光2曝光影像轉成高度資料
{
	if ( CheckCastParamExp2(CastParam1) == false )
	{	return false; }	
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam1) == false )
	{	return false; }
	//if ( 16 != CastParam1.ImageCount )
	//{	return false; }

	unsigned char GammaTable_1[256];			
	float Gamma_1=1.0f;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();

	Gamma_1 = CastParam1.Gamma;	
	if ( true == bUseGamma )
	{	
		BuildGammaLookUpTable(Gamma_1, GammaTable_1); 		
		CastParam1.GammaTablePtr = GammaTable_1;		
	}
	else
	{	CastParam1.GammaTablePtr = NULL;	}

	std::vector<unsigned char> CodeMap3;
	std::vector<unsigned char> CodeMap4;
	std::vector<unsigned char> CodeMap5;
	std::vector<unsigned char> CodeMap6;
	BuildGrayCodeMapTable(3, CodeMap3);
	BuildGrayCodeMapTable(4, CodeMap4);
	BuildGrayCodeMapTable(5, CodeMap5);
	BuildGrayCodeMapTable(6, CodeMap6);
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam1) == false )
	{	return false; }	

	const int BufferSize = (int)(ImageStep*ImageH);
	const int OpenMPCount = AOIDataCollect.GetOpenMPCount_General();
#pragma omp parallel for num_threads(OpenMPCount)
	for ( int i=0; i<BufferSize; i++ )
	{	PatternCast1ToSpace2Exp3_II_MP_Fn(i, ImageW, ImageH, ImageStep, CastParam1, NoiseParam, MaskPtr, SpacePtr);	}

	CastParam1.GammaTablePtr = NULL;
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast1ToSpace2Exp3_II_MP_Fn(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//1投光2曝光影像轉成高度資料
{
	bool IsOK = true;
	switch ( CastParam1.DecodeMode )
	{
	case DECODE_PHASE_2_2STEP_2:
		IsOK = PatternCast1ToSpace2Exp3_II_MP_Fn_2X2(index, ImageW, ImageH, ImageStep, CastParam1, NoiseParam, MaskPtr, SpacePtr);
		break;
	case DECODE_PHASE_4_2STEP_2:
		IsOK = PatternCast1ToSpace2Exp3_II_MP_Fn_4X2(index, ImageW, ImageH, ImageStep, CastParam1, NoiseParam, MaskPtr, SpacePtr);
		break;
	case DECODE_PHASE_4STEP_4GC_2:
		IsOK = PatternCast1ToSpace2Exp3_II_MP_Fn_4X4GC(index, ImageW, ImageH, ImageStep, CastParam1, NoiseParam, MaskPtr, SpacePtr);
		break;
	case DECODE_PHASE_4STEP_5GC_2:
		IsOK = PatternCast1ToSpace2Exp3_II_MP_Fn_4X5GC(index, ImageW, ImageH, ImageStep, CastParam1, NoiseParam, MaskPtr, SpacePtr);
		break;
	case DECODE_PHASE_4STEP_6GC_2:
		IsOK = PatternCast1ToSpace2Exp3_II_MP_Fn_4X6GC(index, ImageW, ImageH, ImageStep, CastParam1, NoiseParam, MaskPtr, SpacePtr);
		break;
	default:
		IsOK = PatternCast1ToSpace2Exp3_II_MP_Fn_4X4(index, ImageW, ImageH, ImageStep, CastParam1, NoiseParam, MaskPtr, SpacePtr);;
		break;
	}
	return IsOK;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast1ToSpace2Exp3_II_MP_Fn_2X2(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//1投光2曝光影像轉成高度資料
{
	const int BufferSize = (int)(ImageStep*ImageH);
	if (index<0 || index >= BufferSize) { return false; }

	int   PhaseM_1 = 0;
	int   PhaseM_AB_1 = 0;
	int   PhaseM_CD_1 = 0;
	int   PhaseZero_1 = 0;
	float Mean_AB_1=0.0f;
	float Mean_CD_1=0.0f;
	float Space_1 = 0.0f;
	float Space_AB_1 = 0.0f, Space_CD_1 = 0.0f;
	MASK_DATA  Mask_1 = 0;
	MASK_DATA  Mask_AB_1 = 0;
	MASK_DATA  Mask_CD_1 = 0;
	MASK_DATA  MaskA_1 = 0, MaskB_1 = 0;
	MASK_DATA  MaskC_1 = 0, MaskD_1 = 0;

	IMAGE_DATA *PtrA1_1 = NULL, *PtrA2_1 = NULL;
	IMAGE_DATA *PtrB1_1 = NULL, *PtrB2_1 = NULL, *PtrB3_1 = NULL;
	IMAGE_DATA *PtrC1_1 = NULL, *PtrC2_1 = NULL;
	IMAGE_DATA *PtrD1_1 = NULL, *PtrD2_1 = NULL, *PtrD3_1 = NULL;
	PHASE_DATA *BasePhasePtr_1 = NULL;
	SPACE_DATA *HeightFactorPtr_1 = NULL;
	SPACE_DATA *HeightFactorPtr_1_2 = NULL;
	double     *HeightFactor0_1 = NULL;
	double     *HeightFactor1_1 = NULL;
	double     *HeightFactor2_1 = NULL;
	unsigned char *GammaTablePtr_1 = NULL;

	PHASE_DATA PhaseA_1 = 0, PhaseB_1 = 0;
	PHASE_DATA PhaseC_1 = 0, PhaseD_1 = 0;

	PHASE_DATA dA1_1 = 0, dA2_1 = 0;
	PHASE_DATA dB1_1 = 0, dB2_1 = 0, dB3_1 = 0;
	PHASE_DATA dC1_1 = 0, dC2_1 = 0;
	PHASE_DATA dD1_1 = 0, dD2_1 = 0, dD3_1 = 0;

	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int   PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;

	const double PerA = CastParam1.PerA;
	const double PerB = CastParam1.PerB;
	//const double PerD = Calc2PhaseNewPeriode(PerA, PerB);

	PtrA1_1 = CastParam1.PtrA1;	PtrA2_1 = CastParam1.PtrA2;
	PtrB1_1 = CastParam1.PtrB1;	PtrB2_1 = CastParam1.PtrB2;	PtrB3_1 = CastParam1.PtrB3;

	PtrC1_1 = CastParam1.PtrC1;	PtrC2_1 = CastParam1.PtrC2;
	PtrD1_1 = CastParam1.PtrD1;	PtrD2_1 = CastParam1.PtrD2;	PtrD3_1 = CastParam1.PtrD3;

	BasePhasePtr_1 = CastParam1.ZeroPhasePtr;
	HeightFactorPtr_1 = CastParam1.HeightFactorPtr;
	HeightFactor0_1 = (double*)CastParam1.HeightFactor0;
	HeightFactor1_1 = (double*)CastParam1.HeightFactor1;
	HeightFactor2_1 = (double*)CastParam1.HeightFactor2;
	GammaTablePtr_1 = CastParam1.GammaTablePtr;

	double dRatio = 1.0;
	const float SpaceZero = 3000;
	CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatio);

	const int i = index;
	const int x = i%ImageStep;
	const int y = i/ImageStep;
	{
		dA1_1 = PtrA1_1[i];	dA2_1 = PtrA2_1[i];//cos sin
		dB1_1 = PtrB1_1[i];	dB2_1 = PtrB2_1[i];	dB3_1 = PtrB3_1[i];//cos sin average

		dC1_1 = PtrC1_1[i];	dC2_1 = PtrC2_1[i];
		dD1_1 = PtrD1_1[i];	dD2_1 = PtrD2_1[i];	dD3_1 = PtrD3_1[i];

		if (NULL != GammaTablePtr_1)
		{
			dA1_1 = GammaTablePtr_1[dA1_1];	dA2_1 = GammaTablePtr_1[dA2_1];
			dB1_1 = GammaTablePtr_1[dB1_1];	dB2_1 = GammaTablePtr_1[dB2_1];	dB3_1 = GammaTablePtr_1[dB3_1];
			dC1_1 = GammaTablePtr_1[dC1_1];	dC2_1 = GammaTablePtr_1[dC2_1];
			dD1_1 = GammaTablePtr_1[dD1_1];	dD2_1 = GammaTablePtr_1[dD2_1];	dD3_1 = GammaTablePtr_1[dD3_1];
		}

		if (Calc21PhaseParamMask(dA1_1, dB3_1, dA2_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_1, MaskA_1) == false)
		{
			return false;
		}
		if (Calc21PhaseParamMask(dB1_1, dB3_1, dB2_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_1, MaskB_1) == false)
		{
			return false;
		}

		if (Calc21PhaseParamMask(dC1_1, dD3_1, dC2_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseC_1, MaskC_1) == false)
		{
			return false;
		}
		if (Calc21PhaseParamMask(dD1_1, dD3_1, dD2_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseD_1, MaskD_1) == false)
		{
			return false;
		}

		//雙週期相位合併		
		if (PerA < PerB)
		{
			PhaseM_AB_1 = CombinePhasePeriod(CombinePeriodMode, PhaseA_1, PhaseB_1, dRatio);
			PhaseM_CD_1 = CombinePhasePeriod(CombinePeriodMode, PhaseC_1, PhaseD_1, dRatio);
		}
		else
		{
			PhaseM_AB_1 = CombinePhasePeriod(CombinePeriodMode, PhaseB_1, PhaseA_1, dRatio);//注意相位次序
			PhaseM_CD_1 = CombinePhasePeriod(CombinePeriodMode, PhaseD_1, PhaseC_1, dRatio);//注意相位次序
		}

		if (NULL != BasePhasePtr_1)//扣除相平面
		{
			DeductBasePhase(BasePhasePtr_1[i], PhaseM_AB_1);
			DeductBasePhase(BasePhasePtr_1[i], PhaseM_CD_1);
		}

		Mask_AB_1 = CombinePhaseMask(MaskA_1, MaskB_1);
		Mask_CD_1 = CombinePhaseMask(MaskC_1, MaskD_1);

		ConvertSpaceToPhase(PhaseConvertHeightMode, i, SpaceZero, HeightFactorPtr_1, HeightFactorPtr_1_2, PhaseZero_1);
		ConvertSpaceToPhaseMapFunc(PhaseConvertHeightMode, x, y, SpaceZero, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, PhaseZero_1);

		//Merge2ExpPhaseData(Mask_AB_1, PhaseM_AB_1, Mask_CD_1, PhaseM_CD_1, Mask_1, PhaseM_1);
		Merge2ExpPhaseData_II(Mask_AB_1, PhaseM_AB_1, Mask_CD_1, PhaseM_CD_1, Mask_1, PhaseM_1, PhaseZero_1);

		Space_1 = PhaseM_1;	Space_AB_1 = PhaseM_AB_1; Space_CD_1 = PhaseM_CD_1;

		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_1);
		//ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_AB_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_AB_1);
		//ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_CD_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_CD_1);

		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		//ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_AB_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_AB_1);
		//ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_CD_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_CD_1);

		MaskPtr[i] = Mask_1;
		SpacePtr[i] = Space_1;
		if (NULL != CastParam1.PtrMask) { CastParam1.PtrMask[i] = Mask_1; }
		if (NULL != CastParam1.PtrSpace) { CastParam1.PtrSpace[i] = Space_1; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast1ToSpace2Exp3_II_MP_Fn_4X2(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//1投光2曝光影像轉成高度資料
{
	const int BufferSize = (int)(ImageStep*ImageH);
	if ( index<0 || index>=BufferSize ) { return false; }

	int   nPhase = 0;
	float phase = 0.0f;
	int   PhaseM_1 = 0;
	int   PhaseM_2 = 0;		
	int   PhaseM_AB_1 = 0;	
	int   PhaseM_CD_1 = 0;			
	int   PhaseZero_1 = 0;	
	float Mean_AB_1=0.0f;
	float Mean_CD_1=0.0f;
	float Space_1=0.0f, Space_M=0.0f;
	float Space_AB_1=0.0f, Space_CD_1=0.0f;
	MASK_DATA  Mask_1=0;	
	MASK_DATA  Mask_M=0;
	MASK_DATA  Mask_AB_1=0;	
	MASK_DATA  Mask_CD_1=0;			
	MASK_DATA  MaskA_1=0, MaskB_1=0;	
	MASK_DATA  MaskC_1=0, MaskD_1=0;		

	IMAGE_DATA *PtrA1_1=NULL, *PtrA2_1=NULL, *PtrA3_1=NULL, *PtrA4_1=NULL;
	IMAGE_DATA *PtrB1_1=NULL, *PtrB2_1=NULL;	
	IMAGE_DATA *PtrC1_1=NULL, *PtrC2_1=NULL, *PtrC3_1=NULL, *PtrC4_1=NULL;
	IMAGE_DATA *PtrD1_1=NULL, *PtrD2_1=NULL;	
	PHASE_DATA *BasePhasePtr_1=NULL;
	SPACE_DATA *HeightFactorPtr_1=NULL;
	SPACE_DATA *HeightFactorPtr_1_2=NULL;
	double     *HeightFactor0_1 = NULL;
	double     *HeightFactor1_1 = NULL;
	double     *HeightFactor2_1 = NULL;
	unsigned char *GammaTablePtr_1=NULL;

	PHASE_DATA PhaseA_1=0, PhaseB_1=0;	
	PHASE_DATA PhaseC_1=0, PhaseD_1=0;		

	PHASE_DATA dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	PHASE_DATA dB1_1=0, dB2_1=0, dB3_1=0;	
	PHASE_DATA dC1_1=0, dC2_1=0, dC3_1=0, dC4_1=0;
	PHASE_DATA dD1_1=0, dD2_1=0, dD3_1=0;	

	int    ImageX=0, ImageY=0;	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int   PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	
	const int IntensityMergeMode = NoiseParam.SpaceMultiIntensityMergeMode;

	const double PerA = CastParam1.PerA;
	const double PerB = CastParam1.PerB;
	const double PerD = Calc2PhaseNewPeriode(PerA, PerB);	
	const float  ExpTimeRatioAB = (1.0f*CastParam1.ExpTimeB/CastParam1.ExpTimeA);
	const float  ExpTimeRatioCD = (1.0f*CastParam1.ExpTimeD/CastParam1.ExpTimeC);

	PtrA1_1 = CastParam1.PtrA1;	PtrA2_1 = CastParam1.PtrA2;	PtrA3_1 = CastParam1.PtrA3;	PtrA4_1 = CastParam1.PtrA4;
	PtrB1_1 = CastParam1.PtrB1;	PtrB2_1 = CastParam1.PtrB2;

	PtrC1_1 = CastParam1.PtrC1;	PtrC2_1 = CastParam1.PtrC2;	PtrC3_1 = CastParam1.PtrC3;	PtrC4_1 = CastParam1.PtrC4;
	PtrD1_1 = CastParam1.PtrD1;	PtrD2_1 = CastParam1.PtrD2;

	BasePhasePtr_1 = CastParam1.ZeroPhasePtr;	
	HeightFactorPtr_1 = CastParam1.HeightFactorPtr;	
	HeightFactor0_1 = (double*)CastParam1.HeightFactor0;
	HeightFactor1_1 = (double*)CastParam1.HeightFactor1;
	HeightFactor2_1 = (double*)CastParam1.HeightFactor2;
	GammaTablePtr_1=CastParam1.GammaTablePtr;	

	double dRatioA=1.0;
	double dRatioB=1.0;	
	const float SpaceZero = 3000;
	if ( PerB > PerA )//PB 為主
	{	
		dRatioA = PerB/PerA;
		dRatioB = 1;
	}
	else //PA為主 
	{	
		dRatioA = 1;
		dRatioB = PerA/PerB;
	}
	CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatioA);

	const int i = index;
	const int x = i%ImageStep;
	const int y = i/ImageStep;
	{
		dA1_1 = PtrA1_1[i];	dA2_1 = PtrA2_1[i];	dA3_1 = PtrA3_1[i];	dA4_1 = PtrA4_1[i];
		dB1_1 = PtrB1_1[i];	dB3_1 = PtrB2_1[i];
		dC1_1 = PtrC1_1[i];	dC2_1 = PtrC2_1[i];	dC3_1 = PtrC3_1[i];	dC4_1 = PtrC4_1[i];
		dD1_1 = PtrD1_1[i];	dD3_1 = PtrD2_1[i];
		dB2_1 = (dA1_1+dA2_1+dA3_1+dA4_1)>>2;
		dD2_1 = (dC1_1+dC2_1+dC3_1+dC4_1)>>2;
		dB2_1 = (int)((dB2_1*ExpTimeRatioAB)+0.5f);
		dD2_1 = (int)((dD2_1*ExpTimeRatioCD)+0.5f);

		if ( NULL != GammaTablePtr_1 )
		{
			dA1_1 = GammaTablePtr_1[dA1_1];	dA2_1 = GammaTablePtr_1[dA2_1];	dA3_1 = GammaTablePtr_1[dA3_1];	dA4_1 = GammaTablePtr_1[dA4_1];
			dB1_1 = GammaTablePtr_1[dB1_1];	dB2_1 = GammaTablePtr_1[dB2_1];	dB3_1 = GammaTablePtr_1[dB3_1];
			dC1_1 = GammaTablePtr_1[dC1_1];	dC2_1 = GammaTablePtr_1[dC2_1];	dC3_1 = GammaTablePtr_1[dC3_1];	dC4_1 = GammaTablePtr_1[dC4_1];
			dD1_1 = GammaTablePtr_1[dD1_1];	dD2_1 = GammaTablePtr_1[dD2_1];	dD3_1 = GammaTablePtr_1[dD3_1];
		}		

		if ( Calc4PhaseParamMask(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_1, MaskA_1, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dB1_1, dB2_1, dB3_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_1, MaskB_1) == false )
		{	return false; }		

		if ( Calc4PhaseParamMask(dC1_1, dC2_1, dC3_1, dC4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseC_1, MaskC_1, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dD1_1, dD2_1, dD3_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseD_1, MaskD_1) == false )
		{	return false; }

		//雙週期相位合併		
		if ( PerA < PerB )
		{				
			PhaseM_AB_1 = CombinePhasePeriod(CombinePeriodMode, PhaseA_1, PhaseB_1, dRatioA);
			PhaseM_CD_1 = CombinePhasePeriod(CombinePeriodMode, PhaseC_1, PhaseD_1, dRatioA);									
		}
		else
		{
			PhaseM_AB_1 = CombinePhasePeriod(CombinePeriodMode, PhaseB_1, PhaseA_1, dRatioA);//注意相位次序
			PhaseM_CD_1 = CombinePhasePeriod(CombinePeriodMode, PhaseD_1, PhaseC_1, dRatioA);//注意相位次序									
		}	
		//
		if ( NULL != BasePhasePtr_1 )//扣除相平面
		{	
			DeductBasePhase(BasePhasePtr_1[i], PhaseM_AB_1);
			DeductBasePhase(BasePhasePtr_1[i], PhaseM_CD_1);
		}

		Mask_AB_1 = CombinePhaseMask(MaskA_1, MaskB_1);
		Mask_CD_1 = CombinePhaseMask(MaskC_1, MaskD_1);

		ConvertSpaceToPhase(PhaseConvertHeightMode, i, SpaceZero, HeightFactorPtr_1, HeightFactorPtr_1_2, PhaseZero_1);
		ConvertSpaceToPhaseMapFunc(PhaseConvertHeightMode, x, y, SpaceZero, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, PhaseZero_1);

		//Merge2ExpPhaseData(Mask_AB_1, PhaseM_AB_1, Mask_CD_1, PhaseM_CD_1, Mask_1, PhaseM_1);	
		//Merge2ExpPhaseData_II(Mask_AB_1, PhaseM_AB_1, Mask_CD_1, PhaseM_CD_1, Mask_1, PhaseM_1, PhaseZero_1);			
		if ( MULTI_INTENSITY_MERGE_MODE_MEAN != IntensityMergeMode )
		{
			float A_AB_1=0.0f, B_AB_1=0.0f, CV_AB_1=0.0f, A_CD_1=0.0f, B_CD_1=0.0f, CV_CD_1=0.0f;			
			Calc4PhaseMeanContrastRatio(dA1_1, dA2_1, dA3_1, dA4_1, A_AB_1, B_AB_1, CV_AB_1);							
			Calc4PhaseMeanContrastRatio(dC1_1, dC2_1, dC3_1, dC4_1, A_CD_1, B_CD_1, CV_CD_1);									
			if ( MULTI_INTENSITY_MERGE_MODE_MAXB == IntensityMergeMode )
			{	Merge2ExpPhaseDataByMaxB(Mask_AB_1, PhaseM_AB_1, A_AB_1, B_AB_1, Mask_CD_1, PhaseM_CD_1, A_CD_1, B_CD_1, Mask_1, PhaseM_1); }
			else if ( MULTI_INTENSITY_MERGE_MODE_MAXCV == IntensityMergeMode )
			{	Merge2ExpPhaseDataByMaxCV(Mask_AB_1, PhaseM_AB_1, A_AB_1, B_AB_1, Mask_CD_1, PhaseM_CD_1, A_CD_1, B_CD_1, Mask_1, PhaseM_1); }
		}
		else
		{
			Mean_AB_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;	Mean_CD_1=(dC1_1+dC2_1+dC3_1+dC4_1)/4.0f;
			Merge2ExpPhaseDataByMean(Mask_AB_1, PhaseM_AB_1, Mean_AB_1, Mask_CD_1, PhaseM_CD_1, Mean_CD_1, Mask_1, PhaseM_1);
		}

		Space_1 = PhaseM_1;	Space_AB_1 = PhaseM_AB_1;	Space_CD_1 = PhaseM_CD_1;

		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_1);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_AB_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_AB_1);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_CD_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_CD_1);

		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_AB_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_AB_1);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_CD_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_CD_1);

		Mask_M = Mask_1;
		Space_M = Space_1;
		MaskPtr[i] = Mask_M;		
		SpacePtr[i] = Space_M;

		if ( NULL != CastParam1.PtrMask )	{	CastParam1.PtrMask[i] = Mask_1;	}
		if ( NULL != CastParam1.PtrSpace )	{	CastParam1.PtrSpace[i] = Space_1;	}
	}
	return true;
}
