bool CImageAPI::PatternCast1ToSpace2Exp3_II_MP_Fn_4X4(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//1投光2曝光影像轉成高度資料
{
	const int BufferSize = (int)(ImageStep*ImageH);
	if ( index<0 || index>=BufferSize ) { return false; }

	int   nPhase = 0;
	float phase = 0.0f;
	int   PhaseM_1 = 0;
	int   PhaseM_2 = 0;		
	int   PhaseM_AB_1 = 0;	
	int   PhaseM_CD_1 = 0;			
	int   PhaseZero_1 = 0;	
	float Mean_AB_1=0.0f;
	float Mean_CD_1=0.0f;
	float Space_1=0.0f, Space_M=0.0f;
	float Space_AB_1=0.0f, Space_CD_1=0.0f;
	MASK_DATA  Mask_1=0;	
	MASK_DATA  Mask_M=0;
	MASK_DATA  Mask_AB_1=0;	
	MASK_DATA  Mask_CD_1=0;			
	MASK_DATA  MaskA_1=0, MaskB_1=0;	
	MASK_DATA  MaskC_1=0, MaskD_1=0;		

	IMAGE_DATA *PtrA1_1=NULL, *PtrA2_1=NULL, *PtrA3_1=NULL, *PtrA4_1=NULL;
	IMAGE_DATA *PtrB1_1=NULL, *PtrB2_1=NULL, *PtrB3_1=NULL, *PtrB4_1=NULL;	
	IMAGE_DATA *PtrC1_1=NULL, *PtrC2_1=NULL, *PtrC3_1=NULL, *PtrC4_1=NULL;
	IMAGE_DATA *PtrD1_1=NULL, *PtrD2_1=NULL, *PtrD3_1=NULL, *PtrD4_1=NULL;	
	PHASE_DATA *BasePhasePtr_1=NULL;
	SPACE_DATA *HeightFactorPtr_1=NULL;
	SPACE_DATA *HeightFactorPtr_1_2=NULL;
	double     *HeightFactor0_1 = NULL;
	double     *HeightFactor1_1 = NULL;
	double     *HeightFactor2_1 = NULL;
	unsigned char *GammaTablePtr_1=NULL;

	PHASE_DATA PhaseA_1=0, PhaseB_1=0;	
	PHASE_DATA PhaseC_1=0, PhaseD_1=0;		

	PHASE_DATA dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	PHASE_DATA dB1_1=0, dB2_1=0, dB3_1=0, dB4_1=0;	
	PHASE_DATA dC1_1=0, dC2_1=0, dC3_1=0, dC4_1=0;
	PHASE_DATA dD1_1=0, dD2_1=0, dD3_1=0, dD4_1=0;	

	int    ImageX=0, ImageY=0;	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int   PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	
	const int IntensityMergeMode = NoiseParam.SpaceMultiIntensityMergeMode;

	const double PerA = CastParam1.PerA;
	const double PerB = CastParam1.PerB;
	const double PerD = Calc2PhaseNewPeriode(PerA, PerB);	

	PtrA1_1 = CastParam1.PtrA1;	PtrA2_1 = CastParam1.PtrA2;	PtrA3_1 = CastParam1.PtrA3;	PtrA4_1 = CastParam1.PtrA4;
	PtrB1_1 = CastParam1.PtrB1;	PtrB2_1 = CastParam1.PtrB2;	PtrB3_1 = CastParam1.PtrB3;	PtrB4_1 = CastParam1.PtrB4;	

	PtrC1_1 = CastParam1.PtrC1;	PtrC2_1 = CastParam1.PtrC2;	PtrC3_1 = CastParam1.PtrC3;	PtrC4_1 = CastParam1.PtrC4;
	PtrD1_1 = CastParam1.PtrD1;	PtrD2_1 = CastParam1.PtrD2;	PtrD3_1 = CastParam1.PtrD3;	PtrD4_1 = CastParam1.PtrD4;	

	BasePhasePtr_1 = CastParam1.ZeroPhasePtr;	
	HeightFactorPtr_1 = CastParam1.HeightFactorPtr;	
	HeightFactor0_1 = (double*)CastParam1.HeightFactor0;
	HeightFactor1_1 = (double*)CastParam1.HeightFactor1;
	HeightFactor2_1 = (double*)CastParam1.HeightFactor2;
	GammaTablePtr_1=CastParam1.GammaTablePtr;	

	double dRatioA=1.0;
	double dRatioB=1.0;	
	const float SpaceZero = 3000;
	if ( PerB > PerA )//PB 為主
	{	
		dRatioA = PerB/PerA;
		dRatioB = 1;
	}
	else //PA為主 
	{	
		dRatioA = 1;
		dRatioB = PerA/PerB;
	}
	CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatioA);

	const int i = index;
	const int x = i%ImageStep;
	const int y = i/ImageStep;
	{
		dA1_1 = PtrA1_1[i];	dA2_1 = PtrA2_1[i];	dA3_1 = PtrA3_1[i];	dA4_1 = PtrA4_1[i];
		dB1_1 = PtrB1_1[i];	dB2_1 = PtrB2_1[i];	dB3_1 = PtrB3_1[i];	dB4_1 = PtrB4_1[i];		
		dC1_1 = PtrC1_1[i];	dC2_1 = PtrC2_1[i];	dC3_1 = PtrC3_1[i];	dC4_1 = PtrC4_1[i];
		dD1_1 = PtrD1_1[i];	dD2_1 = PtrD2_1[i];	dD3_1 = PtrD3_1[i];	dD4_1 = PtrD4_1[i];		

		if ( NULL != GammaTablePtr_1 )
		{
			dA1_1 = GammaTablePtr_1[dA1_1];	dA2_1 = GammaTablePtr_1[dA2_1];	dA3_1 = GammaTablePtr_1[dA3_1];	dA4_1 = GammaTablePtr_1[dA4_1];
			dB1_1 = GammaTablePtr_1[dB1_1];	dB2_1 = GammaTablePtr_1[dB2_1];	dB3_1 = GammaTablePtr_1[dB3_1];	dB4_1 = GammaTablePtr_1[dB4_1];
			dC1_1 = GammaTablePtr_1[dC1_1];	dC2_1 = GammaTablePtr_1[dC2_1];	dC3_1 = GammaTablePtr_1[dC3_1];	dC4_1 = GammaTablePtr_1[dC4_1];
			dD1_1 = GammaTablePtr_1[dD1_1];	dD2_1 = GammaTablePtr_1[dD2_1];	dD3_1 = GammaTablePtr_1[dD3_1];	dD4_1 = GammaTablePtr_1[dD4_1];
		}		

		if ( Calc4PhaseParamMask(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_1, MaskA_1, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dB1_1, dB2_1, dB3_1, dB4_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_1, MaskB_1, PhaseNoiseDefMode) == false )
		{	return false; }		

		if ( Calc4PhaseParamMask(dC1_1, dC2_1, dC3_1, dC4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseC_1, MaskC_1, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dD1_1, dD2_1, dD3_1, dD4_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseD_1, MaskD_1, PhaseNoiseDefMode) == false )
		{	return false; }	

		//雙週期相位合併		
		if ( PerA < PerB )
		{				
			PhaseM_AB_1 = CombinePhasePeriod(CombinePeriodMode, PhaseA_1, PhaseB_1, dRatioA);
			PhaseM_CD_1 = CombinePhasePeriod(CombinePeriodMode, PhaseC_1, PhaseD_1, dRatioA);									
		}
		else
		{
			PhaseM_AB_1 = CombinePhasePeriod(CombinePeriodMode, PhaseB_1, PhaseA_1, dRatioA);//注意相位次序
			PhaseM_CD_1 = CombinePhasePeriod(CombinePeriodMode, PhaseD_1, PhaseC_1, dRatioA);//注意相位次序									
		}	
		//
		if ( NULL != BasePhasePtr_1 )//扣除相平面
		{	
			DeductBasePhase(BasePhasePtr_1[i], PhaseM_AB_1);
			DeductBasePhase(BasePhasePtr_1[i], PhaseM_CD_1);
		}

		Mask_AB_1 = CombinePhaseMask(MaskA_1, MaskB_1);
		Mask_CD_1 = CombinePhaseMask(MaskC_1, MaskD_1);

		ConvertSpaceToPhase(PhaseConvertHeightMode, i, SpaceZero, HeightFactorPtr_1, HeightFactorPtr_1_2, PhaseZero_1);		
		ConvertSpaceToPhaseMapFunc(PhaseConvertHeightMode, x, y, SpaceZero, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, PhaseZero_1);

		//Merge2ExpPhaseData(Mask_AB_1, PhaseM_AB_1, Mask_CD_1, PhaseM_CD_1, Mask_1, PhaseM_1);	
		//Merge2ExpPhaseData_II(Mask_AB_1, PhaseM_AB_1, Mask_CD_1, PhaseM_CD_1, Mask_1, PhaseM_1, PhaseZero_1);			
		if ( MULTI_INTENSITY_MERGE_MODE_MEAN != IntensityMergeMode )
		{
			float A_AB_1=0.0f, B_AB_1=0.0f, CV_AB_1=0.0f, A_CD_1=0.0f, B_CD_1=0.0f, CV_CD_1=0.0f;			
			Calc4PhaseMeanContrastRatio(dA1_1, dA2_1, dA3_1, dA4_1, A_AB_1, B_AB_1, CV_AB_1);							
			Calc4PhaseMeanContrastRatio(dC1_1, dC2_1, dC3_1, dC4_1, A_CD_1, B_CD_1, CV_CD_1);									
			if ( MULTI_INTENSITY_MERGE_MODE_MAXB == IntensityMergeMode )
			{	Merge2ExpPhaseDataByMaxB(Mask_AB_1, PhaseM_AB_1, A_AB_1, B_AB_1, Mask_CD_1, PhaseM_CD_1, A_CD_1, B_CD_1, Mask_1, PhaseM_1); }
			else if ( MULTI_INTENSITY_MERGE_MODE_MAXCV == IntensityMergeMode )
			{	Merge2ExpPhaseDataByMaxCV(Mask_AB_1, PhaseM_AB_1, A_AB_1, B_AB_1, Mask_CD_1, PhaseM_CD_1, A_CD_1, B_CD_1, Mask_1, PhaseM_1); }				
		}
		else
		{
			Mean_AB_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;	Mean_CD_1=(dC1_1+dC2_1+dC3_1+dC4_1)/4.0f;
			Merge2ExpPhaseDataByMean(Mask_AB_1, PhaseM_AB_1, Mean_AB_1, Mask_CD_1, PhaseM_CD_1, Mean_CD_1, Mask_1, PhaseM_1);
		}

		Space_1 = PhaseM_1;	Space_AB_1 = PhaseM_AB_1;	Space_CD_1 = PhaseM_CD_1;

		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_1);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_AB_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_AB_1);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_CD_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_CD_1);		

		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_AB_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_AB_1);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_CD_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_CD_1);

		Mask_M = Mask_1;
		Space_M = Space_1;
		MaskPtr[i] = Mask_M;		
		SpacePtr[i] = Space_M;

		if ( NULL != CastParam1.PtrMask )	{	CastParam1.PtrMask[i] = Mask_1;	}
		if ( NULL != CastParam1.PtrSpace )	{	CastParam1.PtrSpace[i] = Space_1;	}		
	}
	return true;
}
