	float Space_CD_1=0.0f,Space_CD_2=0.0f,Space_CD_3=0.0f;
	float Space_1=0.0f,Space_2=0.0f,Space_3=0.0f, Space_M=0.0f;
	MASK_DATA  Mask_1=0;
	MASK_DATA  Mask_2=0;
	MASK_DATA  Mask_3=0;	
	MASK_DATA  Mask_M=0;
	MASK_DATA  Mask_AB_1=0;
	MASK_DATA  Mask_AB_2=0;
	MASK_DATA  Mask_AB_3=0;	
