			dB1_1 = GammaTablePtr_1[dB1_1];	dB2_1 = GammaTablePtr_1[dB2_1];	dB3_1 = GammaTablePtr_1[dB3_1];	dB4_1 = GammaTablePtr_1[dB4_1];	dB5_1 = GammaTablePtr_1[dB5_1];	dB6_1 = GammaTablePtr_1[dB6_1];
