		Mean_CD_3=(dC1_3+dC2_3+dC3_3+dC4_3)/4.0f;
		Threshold_CD_3=(float)(Mean_CD_3*ExpTimeRatio_CD_3);		

		Calc6GrayCodeParam(dB1_1, dB2_1, dB3_1, dB4_1, dB5_1, dB6_1, Threshold_AB_1, CodeK1MapPtr_1, CodeK2MapPtr_1, k1_AB_1, k2_AB_1);
		Calc6GrayCodeParam(dB1_2, dB2_2, dB3_2, dB4_2, dB5_2, dB6_2, Threshold_AB_2, CodeK1MapPtr_2, CodeK2MapPtr_2, k1_AB_2, k2_AB_2);
		Calc6GrayCodeParam(dB1_3, dB2_3, dB3_3, dB4_3, dB5_3, dB6_3, Threshold_AB_3, CodeK1MapPtr_3, CodeK2MapPtr_3, k1_AB_3, k2_AB_3);		
		Calc6GrayCodeParam(dD1_1, dD2_1, dD3_1, dD4_1, dD5_1, dD6_1, Threshold_CD_1, CodeK1MapPtr_1, CodeK2MapPtr_1, k1_CD_1, k2_CD_1);
		Calc6GrayCodeParam(dD1_2, dD2_2, dD3_2, dD4_2, dD5_2, dD6_2, Threshold_CD_2, CodeK1MapPtr_2, CodeK2MapPtr_2, k1_CD_2, k2_CD_2);
		Calc6GrayCodeParam(dD1_3, dD2_3, dD3_3, dD4_3, dD5_3, dD6_3, Threshold_CD_3, CodeK1MapPtr_3, CodeK2MapPtr_3, k1_CD_3, k2_CD_3);		

		if ( Calc4PhaseParamMask(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_1, MaskA_1, PhaseNoiseDefMode) == false )
		{	return false; }		
		if ( Calc4PhaseParamMask(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_2, MaskA_2, PhaseNoiseDefMode) == false )
		{	return false; }		
		if ( Calc4PhaseParamMask(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_3, MaskA_3, PhaseNoiseDefMode) == false )
		{	return false; }	

		if ( Calc4PhaseParamMask(dC1_1, dC2_1, dC3_1, dC4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseC_1, MaskC_1, PhaseNoiseDefMode) == false )
		{	return false; }		
		if ( Calc4PhaseParamMask(dC1_2, dC2_2, dC3_2, dC4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseC_2, MaskC_2, PhaseNoiseDefMode) == false )
		{	return false; }		
		if ( Calc4PhaseParamMask(dC1_3, dC2_3, dC3_3, dC4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseC_3, MaskC_3, PhaseNoiseDefMode) == false )
		{	return false; }				

		//雙週期相位合併
		Mask_AB_1 = MaskA_1;
		Mask_AB_2 = MaskA_2;
		Mask_AB_3 = MaskA_3;		

		Mask_CD_1 = MaskC_1;
		Mask_CD_2 = MaskC_2;
		Mask_CD_3 = MaskC_3;

		PhaseM_AB_1 = CombinePhasePeriod_GrayCode(PhaseA_1, Period, MaxN, k1_AB_1, k2_AB_1);
		PhaseM_AB_2 = CombinePhasePeriod_GrayCode(PhaseA_2, Period, MaxN, k1_AB_2, k2_AB_2);
		PhaseM_AB_3 = CombinePhasePeriod_GrayCode(PhaseA_3, Period, MaxN, k1_AB_3, k2_AB_3);		

		PhaseM_CD_1 = CombinePhasePeriod_GrayCode(PhaseC_1, Period, MaxN, k1_CD_1, k2_CD_1);
		PhaseM_CD_2 = CombinePhasePeriod_GrayCode(PhaseC_2, Period, MaxN, k1_CD_2, k2_CD_2);
		PhaseM_CD_3 = CombinePhasePeriod_GrayCode(PhaseC_3, Period, MaxN, k1_CD_3, k2_CD_3);

		if ( NULL != BasePhasePtr_1 )//扣除相平面
		{	
			DeductBasePhase(BasePhasePtr_1[i], PhaseM_AB_1);
			DeductBasePhase(BasePhasePtr_1[i], PhaseM_CD_1);
		}		
		if ( NULL != BasePhasePtr_2 )//扣除相平面
		{	
			DeductBasePhase(BasePhasePtr_2[i], PhaseM_AB_2);
			DeductBasePhase(BasePhasePtr_2[i], PhaseM_CD_2);	
		}
