//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace3_I(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam1, TCastParam &CastParam2, TCastParam &CastParam3, TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, bool bOpenMP, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料	
{
#ifdef CUDA_USE
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if ( SysParam.m_CudaFnEnabled==FN_ENABLE && true==IsCudaDeviceUse )
	{
		const int CudaBlockNumber = SysParam.m_CudaBlockNumber;
		const int CudaThreadNumber = SysParam.m_CudaThreadNumber;
		if ( CudaFunc.CudaSolveSpace4Frames2Period4Cast(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr, CudaThreadNumber, CudaBlockNumber) == false )
		{
			SetErrorString(CudaFunc.GetErrorString());
			return false;
		}
		return true;
	}	
#endif//CUDA_USE

	const char fnName[] = "CImageAPI::PatternCast4ToSpace3_I";
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam1) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam2) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam3) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam4) == false )
	{	return false; }

	MASK_PTR MaskPtr1 = NULL;
	MASK_PTR MaskPtr2 = NULL;
	MASK_PTR MaskPtr3 = NULL;
	MASK_PTR MaskPtr4 = NULL;
	SPACE_PTR SpacePtr1 = NULL;
	SPACE_PTR SpacePtr2 = NULL;	
	SPACE_PTR SpacePtr3 = NULL;	
	SPACE_PTR SpacePtr4 = NULL;	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);	
	if ( JetMemory.alloc_func(BufferSize, MaskPtr1, fnName, "MaskPtr1") == false ||
		JetMemory.alloc_func(BufferSize, MaskPtr2, fnName, "MaskPtr2") == false ||
		JetMemory.alloc_func(BufferSize, MaskPtr3, fnName, "MaskPtr3") == false ||
		JetMemory.alloc_func(BufferSize, MaskPtr4, fnName, "MaskPtr4") == false ||
		JetMemory.alloc_func(BufferSize, SpacePtr1, fnName, "SpacePtr1") == false ||
		JetMemory.alloc_func(BufferSize, SpacePtr2, fnName, "SpacePtr2") == false ||
		JetMemory.alloc_func(BufferSize, SpacePtr3, fnName, "SpacePtr3") == false ||
		JetMemory.alloc_func(BufferSize, SpacePtr4, fnName, "SpacePtr4") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(MaskPtr1);
		JetMemory.free_func(MaskPtr2);
		JetMemory.free_func(MaskPtr3);
		JetMemory.free_func(MaskPtr4);
		JetMemory.free_func(SpacePtr1);
		JetMemory.free_func(SpacePtr2);
		JetMemory.free_func(SpacePtr3);
		JetMemory.free_func(SpacePtr4);
		return false;
	}

	if ( PatternCast1ToSpace3(ImageW, ImageH, ImageStep, CastParam1, NoiseParam, bOpenMP, MaskPtr1, SpacePtr1) == false ||
		PatternCast1ToSpace3(ImageW, ImageH, ImageStep, CastParam2, NoiseParam, bOpenMP, MaskPtr2, SpacePtr2) == false ||
		PatternCast1ToSpace3(ImageW, ImageH, ImageStep, CastParam3, NoiseParam, bOpenMP, MaskPtr3, SpacePtr3) == false ||
		PatternCast1ToSpace3(ImageW, ImageH, ImageStep, CastParam4, NoiseParam, bOpenMP, MaskPtr4, SpacePtr4) == false )
	{
		JetMemory.free_func(MaskPtr1);
		JetMemory.free_func(MaskPtr2);
		JetMemory.free_func(MaskPtr3);
		JetMemory.free_func(MaskPtr4);
		JetMemory.free_func(SpacePtr1);
		JetMemory.free_func(SpacePtr2);
		JetMemory.free_func(SpacePtr3);
		JetMemory.free_func(SpacePtr4);
		return false;
	}

	if ( Merge4SpaceImage3(ImageW, ImageH, ImageStep, SpacePtr1, MaskPtr1, SpacePtr2, MaskPtr2, SpacePtr3, MaskPtr3, SpacePtr4, MaskPtr4, bOpenMP, SpacePtr, MaskPtr) == false )
	{
		JetMemory.free_func(MaskPtr1);
		JetMemory.free_func(MaskPtr2);
		JetMemory.free_func(MaskPtr3);
		JetMemory.free_func(MaskPtr4);
		JetMemory.free_func(SpacePtr1);
		JetMemory.free_func(SpacePtr2);
		JetMemory.free_func(SpacePtr3);
		JetMemory.free_func(SpacePtr4);
		return false;
	}
	if ( NULL != CastParam1.PtrMask )	{ ::memcpy(CastParam1.PtrMask, MaskPtr1, sizeof(MASK_DATA)*BufferSize); }
	if ( NULL != CastParam1.PtrSpace )	{ ::memcpy(CastParam1.PtrSpace, SpacePtr1, sizeof(SPACE_DATA)*BufferSize); }
	if ( NULL != CastParam2.PtrMask )	{ ::memcpy(CastParam2.PtrMask, MaskPtr2, sizeof(MASK_DATA)*BufferSize); }
	if ( NULL != CastParam2.PtrSpace )	{ ::memcpy(CastParam2.PtrSpace, SpacePtr2, sizeof(SPACE_DATA)*BufferSize); }
	if ( NULL != CastParam3.PtrMask )	{ ::memcpy(CastParam3.PtrMask, MaskPtr3, sizeof(MASK_DATA)*BufferSize); }
	if ( NULL != CastParam3.PtrSpace )	{ ::memcpy(CastParam3.PtrSpace, SpacePtr3, sizeof(SPACE_DATA)*BufferSize); }
	if ( NULL != CastParam4.PtrMask )	{ ::memcpy(CastParam4.PtrMask, MaskPtr4, sizeof(MASK_DATA)*BufferSize); }
	if ( NULL != CastParam4.PtrSpace )	{ ::memcpy(CastParam4.PtrSpace, SpacePtr4, sizeof(SPACE_DATA)*BufferSize); }

	JetMemory.free_func(MaskPtr1);
	JetMemory.free_func(MaskPtr2);
	JetMemory.free_func(MaskPtr3);
	JetMemory.free_func(MaskPtr4);
	JetMemory.free_func(SpacePtr1);
	JetMemory.free_func(SpacePtr2);
	JetMemory.free_func(SpacePtr3);
	JetMemory.free_func(SpacePtr4);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam1, TCastParam &CastParam2, TCastParam &CastParam3, TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, bool bOpenMP, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料
{	
#ifdef CUDA_USE
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if ( SysParam.m_CudaFnEnabled==FN_ENABLE && true==IsCudaDeviceUse )
	{
		const int CudaBlockNumber = SysParam.m_CudaBlockNumber;
		const int CudaThreadNumber = SysParam.m_CudaThreadNumber;
		if ( CudaFunc.CudaSolveSpace4Frames2Period4Cast(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr, CudaThreadNumber, CudaBlockNumber) == false )
		{
			SetErrorString(CudaFunc.GetErrorString());
			return false;
		}
		return true;
	}	
#endif//CUDA_USE

	bool IsOK = true;	
	const int nImageSize = (ImageW)*(ImageH);
	const bool OpenMPUsed = AOIDataCollect.CheckOpenMPUsed_CalcPhase(nImageSize);
	if ( false == OpenMPUsed )
	{	bOpenMP = false; }
	if ( true == bOpenMP )
	{	IsOK = PatternCast4ToSpace3_II_MP(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);	}
	else
	{	IsOK = PatternCast4ToSpace3_II_SP(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);	}
	if ( false == IsOK )
	{	return false; }
	if ( SysParam.m_SpaceNoiseMultiCastPatchSize > 0 ) 
	{	IsOK = Merge4SpaceImage3(ImageW, ImageH, ImageStep, CastParam1.PtrSpace, CastParam1.PtrMask, CastParam2.PtrSpace, CastParam2.PtrMask, CastParam3.PtrSpace, CastParam3.PtrMask, CastParam4.PtrSpace, CastParam4.PtrMask, bOpenMP, SpacePtr, MaskPtr);	}
	return IsOK;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace3_II_SP(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam1, TCastParam &CastParam2, TCastParam &CastParam3, TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料-序列計算
{	
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam1) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam2) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam3) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam4) == false )
	{	return false; }	
	//if ( 8!=CastParam1.ImageCount || 8!=CastParam2.ImageCount || 8!=CastParam3.ImageCount || 8!=CastParam4.ImageCount)
	//{	return false; }

	int           i=0;
	int           ImageX=0, ImageY=0;		
	unsigned char GammaTable_1[256];
	unsigned char GammaTable_2[256];
	unsigned char GammaTable_3[256];
	unsigned char GammaTable_4[256];	
	const int     BufferSize = (int)(ImageStep*ImageH);
	float         Gamma_1=1.0f, Gamma_2=1.0f, Gamma_3=1.0f, Gamma_4=1.0f;
	const bool    bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();

	Gamma_1 = CastParam1.Gamma;
	Gamma_2 = CastParam2.Gamma;
	Gamma_3 = CastParam3.Gamma;
	Gamma_4 = CastParam4.Gamma;	
	if ( true == bUseGamma )
	{	
		BuildGammaLookUpTable(Gamma_1, GammaTable_1); 
		BuildGammaLookUpTable(Gamma_2, GammaTable_2); 
		BuildGammaLookUpTable(Gamma_3, GammaTable_3); 
		BuildGammaLookUpTable(Gamma_4, GammaTable_4); 
		CastParam1.GammaTablePtr = GammaTable_1;
		CastParam2.GammaTablePtr = GammaTable_2;
		CastParam3.GammaTablePtr = GammaTable_3;
		CastParam4.GammaTablePtr = GammaTable_4;
	}
	else
	{
		CastParam1.GammaTablePtr = NULL;
		CastParam2.GammaTablePtr = NULL;
		CastParam3.GammaTablePtr = NULL;
		CastParam4.GammaTablePtr = NULL;
	}	

	std::vector<unsigned char> CodeMap3;
	std::vector<unsigned char> CodeMap4;
	std::vector<unsigned char> CodeMap5;
	std::vector<unsigned char> CodeMap6;
	BuildGrayCodeMapTable(3, CodeMap3);
	BuildGrayCodeMapTable(4, CodeMap4);
	BuildGrayCodeMapTable(5, CodeMap5);
	BuildGrayCodeMapTable(6, CodeMap6);
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam1) == false )
	{	return false; }
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam2) == false )
	{	return false; }
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam3) == false )
	{	return false; }
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam4) == false )
	{	return false; }

	for ( i=0; i<BufferSize; i++ )
	{			
#ifdef _DEBUG
		ImageX = i%ImageStep;
		ImageY = i/ImageStep;
		if ( 2240==ImageX && 584==ImageY )
		{	i = i; }
#endif//ImageX=0, ImageY=0;
		//20190530
		//if ( 3145728 == i )//Compare JET6500
		//{	i = 3145728;	}

		if ( PatternCast4ToSpace3_II_MP_Fn(i, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr) == false )
		{
			CastParam1.GammaTablePtr = NULL;
			CastParam2.GammaTablePtr = NULL;
			CastParam3.GammaTablePtr = NULL;
			CastParam4.GammaTablePtr = NULL;
			CastParam1.GCK1MapPtr = CastParam1.GCK2MapPtr = NULL;
			CastParam2.GCK1MapPtr = CastParam2.GCK2MapPtr = NULL;
			CastParam3.GCK1MapPtr = CastParam3.GCK2MapPtr = NULL;
			CastParam4.GCK1MapPtr = CastParam4.GCK2MapPtr = NULL;
			return false;
		}
	}

	CastParam1.GammaTablePtr = NULL;
	CastParam2.GammaTablePtr = NULL;
	CastParam3.GammaTablePtr = NULL;
	CastParam4.GammaTablePtr = NULL;
	CastParam1.GCK1MapPtr = CastParam1.GCK2MapPtr = NULL;
	CastParam2.GCK1MapPtr = CastParam2.GCK2MapPtr = NULL;
	CastParam3.GCK1MapPtr = CastParam3.GCK2MapPtr = NULL;
	CastParam4.GCK1MapPtr = CastParam4.GCK2MapPtr = NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace3_II_MP(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam1, TCastParam &CastParam2, TCastParam &CastParam3, TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料-平行計算
{
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam1) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam2) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam3) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam4) == false )
	{	return false; }		
	//if ( 8!=CastParam1.ImageCount || 8!=CastParam2.ImageCount || 8!=CastParam3.ImageCount || 8!=CastParam4.ImageCount)
	//{	return false; }

	unsigned char GammaTable_1[256];
	unsigned char GammaTable_2[256];
	unsigned char GammaTable_3[256];
	unsigned char GammaTable_4[256];
	float Gamma_1=1.0f, Gamma_2=1.0f, Gamma_3=1.0f, Gamma_4=1.0f;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();

	Gamma_1 = CastParam1.Gamma;
	Gamma_2 = CastParam2.Gamma;
	Gamma_3 = CastParam3.Gamma;
	Gamma_4 = CastParam4.Gamma;
	if ( true == bUseGamma )
	{	
		BuildGammaLookUpTable(Gamma_1, GammaTable_1); 
		BuildGammaLookUpTable(Gamma_2, GammaTable_2); 
		BuildGammaLookUpTable(Gamma_3, GammaTable_3); 
		BuildGammaLookUpTable(Gamma_4, GammaTable_4); 
		CastParam1.GammaTablePtr = GammaTable_1;
		CastParam2.GammaTablePtr = GammaTable_2;
		CastParam3.GammaTablePtr = GammaTable_3;
		CastParam4.GammaTablePtr = GammaTable_4;
	}
	else
	{
		CastParam1.GammaTablePtr = NULL;
		CastParam2.GammaTablePtr = NULL;
		CastParam3.GammaTablePtr = NULL;
		CastParam4.GammaTablePtr = NULL;
	}

	std::vector<unsigned char> CodeMap3;
	std::vector<unsigned char> CodeMap4;
	std::vector<unsigned char> CodeMap5;
	std::vector<unsigned char> CodeMap6;
	BuildGrayCodeMapTable(3, CodeMap3);
	BuildGrayCodeMapTable(4, CodeMap4);
	BuildGrayCodeMapTable(5, CodeMap5);
	BuildGrayCodeMapTable(6, CodeMap6);
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam1) == false )
	{	return false; }
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam2) == false )
	{	return false; }
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam3) == false )
	{	return false; }
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam4) == false )
	{	return false; }

	const int BufferSize = (int)(ImageStep*ImageH);
	const int OpenMPCount = AOIDataCollect.GetOpenMPCount_General();
#pragma omp parallel for num_threads(OpenMPCount)
	for ( int i=0; i<BufferSize; i++ )
	{	PatternCast4ToSpace3_II_MP_Fn(i, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);	}

	CastParam1.GammaTablePtr = NULL;
	CastParam2.GammaTablePtr = NULL;
	CastParam3.GammaTablePtr = NULL;
	CastParam4.GammaTablePtr = NULL;
	CastParam1.GCK1MapPtr = CastParam1.GCK2MapPtr = NULL;
	CastParam2.GCK1MapPtr = CastParam2.GCK2MapPtr = NULL;
	CastParam3.GCK1MapPtr = CastParam3.GCK2MapPtr = NULL;
	CastParam4.GCK1MapPtr = CastParam4.GCK2MapPtr = NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace3_II_MP_Fn(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, const TCastParam &CastParam2, const TCastParam &CastParam3, const TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料-平行計算
{
	bool IsOK = true;
	//return PatternCast4ToSpace3_II_MP_Fn_4_2Step(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);	
	//return PatternCast4ToSpace3_II_MP_Fn_4_3Step(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);	
	switch ( CastParam1.DecodeMode )
	{
	case DECODE_PHASE_2_2STEP_2:
		IsOK = PatternCast4ToSpace3_II_MP_Fn_2X2(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);
		break;
	case DECODE_PHASE_4_2STEP_2:
		IsOK = PatternCast4ToSpace3_II_MP_Fn_4X2(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);
		break;
	case DECODE_PHASE_4STEP_4GC_2:		
		IsOK = PatternCast4ToSpace3_II_MP_Fn_4X4GC(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);
		break;
	case DECODE_PHASE_4STEP_5GC_2:		
		IsOK = PatternCast4ToSpace3_II_MP_Fn_4X5GC(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);
		break;
	case DECODE_PHASE_4STEP_6GC_2:		
		IsOK = PatternCast4ToSpace3_II_MP_Fn_4X6GC(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);
		break;
	default:
		IsOK = PatternCast4ToSpace3_II_MP_Fn_4X4(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);
		break;
	}
	return IsOK;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace3_II_MP_Fn_2X2(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, const TCastParam &CastParam2, const TCastParam &CastParam3, const TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料-平行計算
{
	const int BufferSize = (int)(ImageStep*ImageH);
	if (index<0 || index >= BufferSize) { return false; }

	int   PhaseM_1 = 0;
	int   PhaseM_2 = 0;
	int   PhaseM_3 = 0;
	int   PhaseM_4 = 0;
	float Space_1 = 0.0f, Space_2 = 0.0f, Space_3 = 0.0f, Space_4 = 0.0f, Space_M = 0.0f;
	MASK_DATA  Mask_1 = 0;
	MASK_DATA  Mask_2 = 0;
	MASK_DATA  Mask_3 = 0;
	MASK_DATA  Mask_4 = 0;
	MASK_DATA  Mask_M = 0;
	MASK_DATA  MaskA_1 = 0, MaskB_1 = 0;
	MASK_DATA  MaskA_2 = 0, MaskB_2 = 0;
	MASK_DATA  MaskA_3 = 0, MaskB_3 = 0;
	MASK_DATA  MaskA_4 = 0, MaskB_4 = 0;

	IMAGE_DATA *PtrA1_1 = NULL, *PtrA2_1 = NULL;
	IMAGE_DATA *PtrB1_1 = NULL, *PtrB2_1 = NULL, *PtrB3_1 = NULL;
	IMAGE_DATA *PtrA1_2 = NULL, *PtrA2_2 = NULL;
	IMAGE_DATA *PtrB1_2 = NULL, *PtrB2_2 = NULL, *PtrB3_2 = NULL;
	IMAGE_DATA *PtrA1_3 = NULL, *PtrA2_3 = NULL;
	IMAGE_DATA *PtrB1_3 = NULL, *PtrB2_3 = NULL, *PtrB3_3 = NULL;
	IMAGE_DATA *PtrA1_4 = NULL, *PtrA2_4 = NULL;
	IMAGE_DATA *PtrB1_4 = NULL, *PtrB2_4 = NULL, *PtrB3_4 = NULL;
	PHASE_DATA *BasePhasePtr_1 = NULL, *BasePhasePtr_2 = NULL, *BasePhasePtr_3 = NULL, *BasePhasePtr_4 = NULL;
	SPACE_DATA *HeightFactorPtr_1 = NULL, *HeightFactorPtr_2 = NULL, *HeightFactorPtr_3 = NULL, *HeightFactorPtr_4 = NULL;
	SPACE_DATA *HeightFactorPtr_1_2 = NULL, *HeightFactorPtr_2_2 = NULL, *HeightFactorPtr_3_2 = NULL, *HeightFactorPtr_4_2 = NULL;
	double     *HeightFactor0_1 = NULL, *HeightFactor0_2 = NULL, *HeightFactor0_3 = NULL, *HeightFactor0_4 = NULL;
	double     *HeightFactor1_1 = NULL, *HeightFactor1_2 = NULL, *HeightFactor1_3 = NULL, *HeightFactor1_4 = NULL;
	double     *HeightFactor2_1 = NULL, *HeightFactor2_2 = NULL, *HeightFactor2_3 = NULL, *HeightFactor2_4 = NULL;
	unsigned char *GammaTablePtr_1 = NULL, *GammaTablePtr_2 = NULL, *GammaTablePtr_3 = NULL, *GammaTablePtr_4 = NULL;

	PHASE_DATA PhaseA_1 = 0, PhaseB_1 = 0;
	PHASE_DATA PhaseA_2 = 0, PhaseB_2 = 0;
	PHASE_DATA PhaseA_3 = 0, PhaseB_3 = 0;
	PHASE_DATA PhaseA_4 = 0, PhaseB_4 = 0;
	PHASE_DATA dA1_1 = 0, dA2_1 = 0;
	PHASE_DATA dB1_1 = 0, dB2_1 = 0, dB3_1 = 0;
	PHASE_DATA dA1_2 = 0, dA2_2 = 0;
	PHASE_DATA dB1_2 = 0, dB2_2 = 0, dB3_2 = 0;
	PHASE_DATA dA1_3 = 0, dA2_3 = 0;
	PHASE_DATA dB1_3 = 0, dB2_3 = 0, dB3_3 = 0;
	PHASE_DATA dA1_4 = 0, dA2_4 = 0;
	PHASE_DATA dB1_4 = 0, dB2_4 = 0, dB3_4 = 0;

	const int CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int   PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;

	const double PerA = CastParam1.PerA;
	const double PerB = CastParam1.PerB;
	//const double PerD = Calc2PhaseNewPeriode(PerA, PerB);

	PtrA1_1 = CastParam1.PtrA1;	PtrA2_1 = CastParam1.PtrA2;
	PtrB1_1 = CastParam1.PtrB1;	PtrB2_1 = CastParam1.PtrB2;	PtrB3_1 = CastParam1.PtrB3;
	PtrA1_2 = CastParam2.PtrA1;	PtrA2_2 = CastParam2.PtrA2;
	PtrB1_2 = CastParam2.PtrB1;	PtrB2_2 = CastParam2.PtrB2;	PtrB3_2 = CastParam2.PtrB3;
	PtrA1_3 = CastParam3.PtrA1;	PtrA2_3 = CastParam3.PtrA2;
	PtrB1_3 = CastParam3.PtrB1;	PtrB2_3 = CastParam3.PtrB2;	PtrB3_3 = CastParam3.PtrB3;
	PtrA1_4 = CastParam4.PtrA1;	PtrA2_4 = CastParam4.PtrA2;
	PtrB1_4 = CastParam4.PtrB1;	PtrB2_4 = CastParam4.PtrB2;	PtrB3_4 = CastParam4.PtrB3;
	BasePhasePtr_1 = CastParam1.ZeroPhasePtr;
	BasePhasePtr_2 = CastParam2.ZeroPhasePtr;
	BasePhasePtr_3 = CastParam3.ZeroPhasePtr;
	BasePhasePtr_4 = CastParam4.ZeroPhasePtr;
	HeightFactorPtr_1 = CastParam1.HeightFactorPtr;
	HeightFactorPtr_2 = CastParam2.HeightFactorPtr;
	HeightFactorPtr_3 = CastParam3.HeightFactorPtr;
	HeightFactorPtr_4 = CastParam4.HeightFactorPtr;
	HeightFactor0_1 = (double*)CastParam1.HeightFactor0;
	HeightFactor1_1 = (double*)CastParam1.HeightFactor1;
	HeightFactor2_1 = (double*)CastParam1.HeightFactor2;
	HeightFactor0_2 = (double*)CastParam2.HeightFactor0;
	HeightFactor1_2 = (double*)CastParam2.HeightFactor1;
	HeightFactor2_2 = (double*)CastParam2.HeightFactor2;
	HeightFactor0_3 = (double*)CastParam3.HeightFactor0;
	HeightFactor1_3 = (double*)CastParam3.HeightFactor1;
	HeightFactor2_3 = (double*)CastParam3.HeightFactor2;
	HeightFactor0_4 = (double*)CastParam4.HeightFactor0;
	HeightFactor1_4 = (double*)CastParam4.HeightFactor1;
	HeightFactor2_4 = (double*)CastParam4.HeightFactor2;
	GammaTablePtr_1 = CastParam1.GammaTablePtr;
	GammaTablePtr_2 = CastParam2.GammaTablePtr;
	GammaTablePtr_3 = CastParam3.GammaTablePtr;
	GammaTablePtr_4 = CastParam4.GammaTablePtr;

	double dRatio = 0;
	CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatio);

	const int i = index;
	const int x = i%ImageStep;
	const int y = i/ImageStep;
	{
		dA1_1 = PtrA1_1[i];	dA2_1 = PtrA2_1[i];//cos, sin
		dB1_1 = PtrB1_1[i];	dB2_1 = PtrB2_1[i];	dB3_1 = PtrB3_1[i];//cos, sin, average
		dA1_2 = PtrA1_2[i];	dA2_2 = PtrA2_2[i];
		dB1_2 = PtrB1_2[i];	dB2_2 = PtrB2_2[i];	dB3_2 = PtrB3_2[i];
		dA1_3 = PtrA1_3[i];	dA2_3 = PtrA2_3[i];
		dB1_3 = PtrB1_3[i];	dB2_3 = PtrB2_3[i];	dB3_3 = PtrB3_3[i];
		dA1_4 = PtrA1_4[i];	dA2_4 = PtrA2_4[i];
		dB1_4 = PtrB1_4[i];	dB2_4 = PtrB2_4[i];	dB3_4 = PtrB3_4[i];

		if (NULL != GammaTablePtr_1)
		{
			dA1_1 = GammaTablePtr_1[dA1_1];
			dA2_1 = GammaTablePtr_1[dA2_1];
			dB1_1 = GammaTablePtr_1[dB1_1];
			dB2_1 = GammaTablePtr_1[dB2_1];
			dB3_1 = GammaTablePtr_1[dB3_1];
		}
		if (NULL != GammaTablePtr_2)
		{
			dA1_2 = GammaTablePtr_2[dA1_2];
			dA2_2 = GammaTablePtr_2[dA2_2];
			dB1_2 = GammaTablePtr_2[dB1_2];
			dB2_2 = GammaTablePtr_2[dB2_2];
			dB3_2 = GammaTablePtr_2[dB3_2];
		}
		if (NULL != GammaTablePtr_3)
		{
			dA1_3 = GammaTablePtr_3[dA1_3];
			dA2_3 = GammaTablePtr_3[dA2_3];
			dB1_3 = GammaTablePtr_3[dB1_3];
			dB2_3 = GammaTablePtr_3[dB2_3];
			dB3_3 = GammaTablePtr_3[dB3_3];
		}
		if (NULL != GammaTablePtr_4)
		{
			dA1_4 = GammaTablePtr_4[dA1_4];
			dA2_4 = GammaTablePtr_4[dA2_4];
			dB1_4 = GammaTablePtr_4[dB1_4];
			dB2_4 = GammaTablePtr_4[dB2_4];
			dB3_4 = GammaTablePtr_4[dB3_4];
		}

		if (Calc21PhaseParamMask(dA1_1, dB3_1, dA2_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_1, MaskA_1) == false) { return false; }
		if (Calc21PhaseParamMask(dB1_1, dB3_1, dB2_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_1, MaskB_1) == false) { return false; }
		if (Calc21PhaseParamMask(dA1_2, dB3_2, dA2_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_2, MaskA_2) == false) { return false; }
		if (Calc21PhaseParamMask(dB1_2, dB3_2, dB2_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_2, MaskB_2) == false) { return false; }
		if (Calc21PhaseParamMask(dA1_3, dB3_3, dA2_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_3, MaskA_3) == false) { return false; }
		if (Calc21PhaseParamMask(dB1_3, dB3_3, dB2_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_3, MaskB_3) == false) { return false; }
		if (Calc21PhaseParamMask(dA1_4, dB3_4, dA2_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_4, MaskA_4) == false) { return false; }
		if (Calc21PhaseParamMask(dB1_4, dB3_4, dB2_4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_4, MaskB_4) == false) { return false; }

		//雙週期相位合併		
		if (PerA < PerB)
		{
			PhaseM_1 = CombinePhasePeriod(CombinePeriodMode, PhaseA_1, PhaseB_1, dRatio);
			PhaseM_2 = CombinePhasePeriod(CombinePeriodMode, PhaseA_2, PhaseB_2, dRatio);
			PhaseM_3 = CombinePhasePeriod(CombinePeriodMode, PhaseA_3, PhaseB_3, dRatio);
			PhaseM_4 = CombinePhasePeriod(CombinePeriodMode, PhaseA_4, PhaseB_4, dRatio);
		}
		else
		{
			PhaseM_1 = CombinePhasePeriod(CombinePeriodMode, PhaseB_1, PhaseA_1, dRatio);//注意相位次序
			PhaseM_2 = CombinePhasePeriod(CombinePeriodMode, PhaseB_2, PhaseA_2, dRatio);//注意相位次序			
			PhaseM_3 = CombinePhasePeriod(CombinePeriodMode, PhaseB_3, PhaseA_3, dRatio);//注意相位次序
			PhaseM_4 = CombinePhasePeriod(CombinePeriodMode, PhaseB_4, PhaseA_4, dRatio);//注意相位次序
		}

		if (NULL != BasePhasePtr_1)//扣除相平面
		{
			DeductBasePhase(BasePhasePtr_1[i], PhaseM_1);
		}
		if (NULL != BasePhasePtr_2)//扣除相平面
		{
			DeductBasePhase(BasePhasePtr_2[i], PhaseM_2);
		}
		if (NULL != BasePhasePtr_3)//扣除相平面
		{
			DeductBasePhase(BasePhasePtr_3[i], PhaseM_3);
		}
		if (NULL != BasePhasePtr_4)//扣除相平面
		{
			DeductBasePhase(BasePhasePtr_4[i], PhaseM_4);
		}

		Space_1 = PhaseM_1;
		Space_2 = PhaseM_2;
		Space_3 = PhaseM_3;
		Space_4 = PhaseM_4;

		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_1);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_2, HeightFactorPtr_2, HeightFactorPtr_2_2, Space_2);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_3, HeightFactorPtr_3, HeightFactorPtr_3_2, Space_3);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_4, HeightFactorPtr_4, HeightFactorPtr_4_2, Space_4);

		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_2, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_3, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_4, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);

		Mask_1 = CombinePhaseMask(MaskA_1, MaskB_1);
		Mask_2 = CombinePhaseMask(MaskA_2, MaskB_2);
		Mask_3 = CombinePhaseMask(MaskA_3, MaskB_3);
		Mask_4 = CombinePhaseMask(MaskA_4, MaskB_4);

		//Compare4OppositeGray(cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);//小週期
		if (Compare4SpaceHeight(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M) == false)
		{
			Merge4SpaceData(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M);
		}
		MaskPtr[i] = Mask_M;
		SpacePtr[i] = Space_M;
		if (NULL != CastParam1.PtrMask) { CastParam1.PtrMask[i] = Mask_1; }
		if (NULL != CastParam1.PtrSpace) { CastParam1.PtrSpace[i] = Space_1; }
		if (NULL != CastParam2.PtrMask) { CastParam2.PtrMask[i] = Mask_2; }
		if (NULL != CastParam2.PtrSpace) { CastParam2.PtrSpace[i] = Space_2; }
		if (NULL != CastParam3.PtrMask) { CastParam3.PtrMask[i] = Mask_3; }
		if (NULL != CastParam3.PtrSpace) { CastParam3.PtrSpace[i] = Space_3; }
		if (NULL != CastParam4.PtrMask) { CastParam4.PtrMask[i] = Mask_4; }
		if (NULL != CastParam4.PtrSpace) { CastParam4.PtrSpace[i] = Space_4; }
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace3_II_MP_Fn_4X2(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, const TCastParam &CastParam2, const TCastParam &CastParam3, const TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料-平行計算
{
	const int BufferSize = (int)(ImageStep*ImageH);
	if ( index<0 || index>=BufferSize ) { return false; }

	int   nPhase = 0;
	float phase = 0.0f;		
	int   Phase1 = 0;
	int   Phase2 = 0;	
	int   PhaseM_1 = 0;
	int   PhaseM_2 = 0;
	int   PhaseM_3 = 0;
	int   PhaseM_4 = 0;	
	float Space_1=0.0f,Space_2=0.0f,Space_3=0.0f,Space_4=0.0f, Space_M=0.0f;
	MASK_DATA  Mask_1=0;
	MASK_DATA  Mask_2=0;
	MASK_DATA  Mask_3=0;
	MASK_DATA  Mask_4=0;
	MASK_DATA  Mask_M=0;
	MASK_DATA  MaskA_1=0, MaskB_1=0;
	MASK_DATA  MaskA_2=0, MaskB_2=0;
	MASK_DATA  MaskA_3=0, MaskB_3=0;
	MASK_DATA  MaskA_4=0, MaskB_4=0;

	IMAGE_DATA *PtrA1_1=NULL, *PtrA2_1=NULL, *PtrA3_1=NULL, *PtrA4_1=NULL;
	IMAGE_DATA *PtrB1_1=NULL, *PtrB2_1=NULL;
	IMAGE_DATA *PtrA1_2=NULL, *PtrA2_2=NULL, *PtrA3_2=NULL, *PtrA4_2=NULL;
	IMAGE_DATA *PtrB1_2=NULL, *PtrB2_2=NULL;
	IMAGE_DATA *PtrA1_3=NULL, *PtrA2_3=NULL, *PtrA3_3=NULL, *PtrA4_3=NULL;
	IMAGE_DATA *PtrB1_3=NULL, *PtrB2_3=NULL;
	IMAGE_DATA *PtrA1_4=NULL, *PtrA2_4=NULL, *PtrA3_4=NULL, *PtrA4_4=NULL;
	IMAGE_DATA *PtrB1_4=NULL, *PtrB2_4=NULL;
	PHASE_DATA *BasePhasePtr_1=NULL, *BasePhasePtr_2=NULL,*BasePhasePtr_3=NULL,*BasePhasePtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1=NULL, *HeightFactorPtr_2=NULL, *HeightFactorPtr_3=NULL, *HeightFactorPtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1_2=NULL, *HeightFactorPtr_2_2=NULL, *HeightFactorPtr_3_2=NULL, *HeightFactorPtr_4_2=NULL;
	double     *HeightFactor0_1 = NULL, *HeightFactor0_2 = NULL, *HeightFactor0_3 = NULL, *HeightFactor0_4 = NULL;
	double     *HeightFactor1_1 = NULL, *HeightFactor1_2 = NULL, *HeightFactor1_3 = NULL, *HeightFactor1_4 = NULL;
	double     *HeightFactor2_1 = NULL, *HeightFactor2_2 = NULL, *HeightFactor2_3 = NULL, *HeightFactor2_4 = NULL;
	unsigned char *GammaTablePtr_1=NULL, *GammaTablePtr_2=NULL, *GammaTablePtr_3=NULL, *GammaTablePtr_4=NULL;

	PHASE_DATA PhaseA_1=0, PhaseB_1=0;
	PHASE_DATA PhaseA_2=0, PhaseB_2=0;
	PHASE_DATA PhaseA_3=0, PhaseB_3=0;
	PHASE_DATA PhaseA_4=0, PhaseB_4=0;
	PHASE_DATA dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	PHASE_DATA dB1_1=0, dB2_1=0, dB3_1=0;
	PHASE_DATA dA1_2=0, dA2_2=0, dA3_2=0, dA4_2=0;
	PHASE_DATA dB1_2=0, dB2_2=0, dB3_2=0;
	PHASE_DATA dA1_3=0, dA2_3=0, dA3_3=0, dA4_3=0;
	PHASE_DATA dB1_3=0, dB2_3=0, dB3_3=0;
	PHASE_DATA dA1_4=0, dA2_4=0, dA3_4=0, dA4_4=0;
	PHASE_DATA dB1_4=0, dB2_4=0, dB3_4=0;	

	int    ImageX=0, ImageY=0;	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int   PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	

	const double PerA = CastParam1.PerA;
	const double PerB = CastParam1.PerB;
	const double PerD = Calc2PhaseNewPeriode(PerA, PerB);	
	const float  ExpTimeRatio_1=(1.0f*CastParam1.ExpTimeB/CastParam1.ExpTimeA);	
	const float  ExpTimeRatio_2=(1.0f*CastParam2.ExpTimeB/CastParam2.ExpTimeA);	
	const float  ExpTimeRatio_3=(1.0f*CastParam3.ExpTimeB/CastParam3.ExpTimeA);	
	const float  ExpTimeRatio_4=(1.0f*CastParam4.ExpTimeB/CastParam4.ExpTimeA);	

	PtrA1_1 = CastParam1.PtrA1;	PtrA2_1 = CastParam1.PtrA2;	PtrA3_1 = CastParam1.PtrA3;	PtrA4_1 = CastParam1.PtrA4;
	PtrB1_1 = CastParam1.PtrB1;	PtrB2_1 = CastParam1.PtrB2;
	PtrA1_2 = CastParam2.PtrA1;	PtrA2_2 = CastParam2.PtrA2;	PtrA3_2 = CastParam2.PtrA3;	PtrA4_2 = CastParam2.PtrA4;
	PtrB1_2 = CastParam2.PtrB1;	PtrB2_2 = CastParam2.PtrB2;
	PtrA1_3 = CastParam3.PtrA1;	PtrA2_3 = CastParam3.PtrA2;	PtrA3_3 = CastParam3.PtrA3;	PtrA4_3 = CastParam3.PtrA4;
	PtrB1_3 = CastParam3.PtrB1;	PtrB2_3 = CastParam3.PtrB2;
	PtrA1_4 = CastParam4.PtrA1;	PtrA2_4 = CastParam4.PtrA2;	PtrA3_4 = CastParam4.PtrA3;	PtrA4_4 = CastParam4.PtrA4;
	PtrB1_4 = CastParam4.PtrB1;	PtrB2_4 = CastParam4.PtrB2;
	BasePhasePtr_1 = CastParam1.ZeroPhasePtr;
	BasePhasePtr_2 = CastParam2.ZeroPhasePtr;
	BasePhasePtr_3 = CastParam3.ZeroPhasePtr;
	BasePhasePtr_4 = CastParam4.ZeroPhasePtr;
	HeightFactorPtr_1 = CastParam1.HeightFactorPtr;
	HeightFactorPtr_2 = CastParam2.HeightFactorPtr;
	HeightFactorPtr_3 = CastParam3.HeightFactorPtr;
	HeightFactorPtr_4 = CastParam4.HeightFactorPtr;
	HeightFactor0_1 = (double*)CastParam1.HeightFactor0;
	HeightFactor1_1 = (double*)CastParam1.HeightFactor1;
	HeightFactor2_1 = (double*)CastParam1.HeightFactor2;
	HeightFactor0_2 = (double*)CastParam2.HeightFactor0;
	HeightFactor1_2 = (double*)CastParam2.HeightFactor1;
	HeightFactor2_2 = (double*)CastParam2.HeightFactor2;
	HeightFactor0_3 = (double*)CastParam3.HeightFactor0;
	HeightFactor1_3 = (double*)CastParam3.HeightFactor1;
	HeightFactor2_3 = (double*)CastParam3.HeightFactor2;
	HeightFactor0_4 = (double*)CastParam4.HeightFactor0;
	HeightFactor1_4 = (double*)CastParam4.HeightFactor1;
	HeightFactor2_4 = (double*)CastParam4.HeightFactor2;
	GammaTablePtr_1=CastParam1.GammaTablePtr;
	GammaTablePtr_2=CastParam2.GammaTablePtr;
	GammaTablePtr_3=CastParam3.GammaTablePtr;
	GammaTablePtr_4=CastParam4.GammaTablePtr;	

	double dRatioA=1.0;
	double dRatioB=1.0;	
	if ( PerB > PerA )//PB 為主
	{	
		dRatioA = PerB/PerA;
		dRatioB = 1;
	}
	else //PA為主 
	{	
		dRatioA = 1;
		dRatioB = PerA/PerB;
	}
	CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatioA);

	const int i = index;
	const int x = i%ImageStep;
	const int y = i/ImageStep;
	{
		dA1_1 = PtrA1_1[i];	dA2_1 = PtrA2_1[i];	dA3_1 = PtrA3_1[i];	dA4_1 = PtrA4_1[i];
		dB1_1 = PtrB1_1[i];	dB3_1 = PtrB2_1[i];
		dA1_2 = PtrA1_2[i];	dA2_2 = PtrA2_2[i];	dA3_2 = PtrA3_2[i];	dA4_2 = PtrA4_2[i];
		dB1_2 = PtrB1_2[i];	dB3_2 = PtrB2_2[i];
		dA1_3 = PtrA1_3[i];	dA2_3 = PtrA2_3[i];	dA3_3 = PtrA3_3[i];	dA4_3 = PtrA4_3[i];
		dB1_3 = PtrB1_3[i];	dB3_3 = PtrB2_3[i];
		dA1_4 = PtrA1_4[i];	dA2_4 = PtrA2_4[i];	dA3_4 = PtrA3_4[i];	dA4_4 = PtrA4_4[i];
		dB1_4 = PtrB1_4[i];	dB3_4 = PtrB2_4[i];

		dB2_1 = (dA1_1+dA2_1+dA3_1+dA4_1)>>2;
		dB2_2 = (dA1_2+dA2_2+dA3_2+dA4_2)>>2;
		dB2_3 = (dA1_3+dA2_3+dA3_3+dA4_3)>>2;
		dB2_4 = (dA1_4+dA2_4+dA3_4+dA4_4)>>2;
		dB2_1 = (int)((ExpTimeRatio_1*dB2_1)+0.5f);
		dB2_2 = (int)((ExpTimeRatio_2*dB2_2)+0.5f);
		dB2_3 = (int)((ExpTimeRatio_3*dB2_3)+0.5f);
		dB2_4 = (int)((ExpTimeRatio_4*dB2_4)+0.5f);

		if ( NULL != GammaTablePtr_1 )
		{
			dA1_1 = GammaTablePtr_1[dA1_1];
			dA2_1 = GammaTablePtr_1[dA2_1];
			dA3_1 = GammaTablePtr_1[dA3_1];
			dA4_1 = GammaTablePtr_1[dA4_1];
			dB1_1 = GammaTablePtr_1[dB1_1];
			dB2_1 = GammaTablePtr_1[dB2_1];
			dB3_1 = GammaTablePtr_1[dB3_1];			
		}

		if ( NULL != GammaTablePtr_2 )
		{
			dA1_2 = GammaTablePtr_2[dA1_2];
			dA2_2 = GammaTablePtr_2[dA2_2];
			dA3_2 = GammaTablePtr_2[dA3_2];
			dA4_2 = GammaTablePtr_2[dA4_2];
			dB1_2 = GammaTablePtr_2[dB1_2];
			dB2_2 = GammaTablePtr_2[dB2_2];
			dB3_2 = GammaTablePtr_2[dB3_2];
		}

		if ( NULL != GammaTablePtr_3 )
		{
			dA1_3 = GammaTablePtr_3[dA1_3];
			dA2_3 = GammaTablePtr_3[dA2_3];
			dA3_3 = GammaTablePtr_3[dA3_3];
			dA4_3 = GammaTablePtr_3[dA4_3];
			dB1_3 = GammaTablePtr_3[dB1_3];
			dB2_3 = GammaTablePtr_3[dB2_3];
			dB3_3 = GammaTablePtr_3[dB3_3];
		}

		if ( NULL != GammaTablePtr_4 )
		{
			dA1_4 = GammaTablePtr_4[dA1_4];
			dA2_4 = GammaTablePtr_4[dA2_4];
			dA3_4 = GammaTablePtr_4[dA3_4];
			dA4_4 = GammaTablePtr_4[dA4_4];
			dB1_4 = GammaTablePtr_4[dB1_4];
			dB2_4 = GammaTablePtr_4[dB2_4];
			dB3_4 = GammaTablePtr_4[dB3_4];
		}

		if ( Calc4PhaseParamMask(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_1, MaskA_1, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dB1_1, dB2_1, dB3_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_1, MaskB_1) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_2, MaskA_2, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dB1_2, dB2_2, dB3_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_2, MaskB_2) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_3, MaskA_3, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dB1_3, dB2_3, dB3_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_3, MaskB_3) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_4, MaskA_4, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dB1_4, dB2_4, dB3_4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_4, MaskB_4) == false )
		{	return false; }

		//雙週期相位合併		
		if ( PerA < PerB )
		{	
			PhaseM_1 = CombinePhasePeriod(CombinePeriodMode, PhaseA_1, PhaseB_1, dRatioA);
			PhaseM_2 = CombinePhasePeriod(CombinePeriodMode, PhaseA_2, PhaseB_2, dRatioA);
			PhaseM_3 = CombinePhasePeriod(CombinePeriodMode, PhaseA_3, PhaseB_3, dRatioA);
			PhaseM_4 = CombinePhasePeriod(CombinePeriodMode, PhaseA_4, PhaseB_4, dRatioA);			
		}
		else
		{
			PhaseM_1 = CombinePhasePeriod(CombinePeriodMode, PhaseB_1, PhaseA_1, dRatioA);//注意相位次序
			PhaseM_2 = CombinePhasePeriod(CombinePeriodMode, PhaseB_2, PhaseA_2, dRatioA);//注意相位次序			
			PhaseM_3 = CombinePhasePeriod(CombinePeriodMode, PhaseB_3, PhaseA_3, dRatioA);//注意相位次序
			PhaseM_4 = CombinePhasePeriod(CombinePeriodMode, PhaseB_4, PhaseA_4, dRatioA);//注意相位次序
		}	

		if ( NULL != BasePhasePtr_1 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_1[i], PhaseM_1);	}		
		if ( NULL != BasePhasePtr_2 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_2[i], PhaseM_2);	}
		if ( NULL != BasePhasePtr_3 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_3[i], PhaseM_3);	}
		if ( NULL != BasePhasePtr_4 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_4[i], PhaseM_4);	}

		Space_1 = PhaseM_1;
		Space_2 = PhaseM_2;
		Space_3 = PhaseM_3;
		Space_4 = PhaseM_4;

		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_1);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_2, HeightFactorPtr_2, HeightFactorPtr_2_2, Space_2);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_3, HeightFactorPtr_3, HeightFactorPtr_3_2, Space_3);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_4, HeightFactorPtr_4, HeightFactorPtr_4_2, Space_4);

		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_2, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_3, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_4, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);

		Mask_1 = CombinePhaseMask(MaskA_1, MaskB_1);
		Mask_2 = CombinePhaseMask(MaskA_2, MaskB_2);
		Mask_3 = CombinePhaseMask(MaskA_3, MaskB_3);
		Mask_4 = CombinePhaseMask(MaskA_4, MaskB_4);

		//Compare4OppositeGray(cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);//小週期
		if ( Compare4SpaceHeight(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M) == false ) 
		{	Merge4SpaceData(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M);	}
		MaskPtr[i] = Mask_M;		
		SpacePtr[i] = Space_M;
		if ( NULL != CastParam1.PtrMask ) { CastParam1.PtrMask[i] = Mask_1; }
		if ( NULL != CastParam1.PtrSpace ) { CastParam1.PtrSpace[i] = Space_1; }
		if ( NULL != CastParam2.PtrMask ) { CastParam2.PtrMask[i] = Mask_2; }
		if ( NULL != CastParam2.PtrSpace ) { CastParam2.PtrSpace[i] = Space_2; }
		if ( NULL != CastParam3.PtrMask ) { CastParam3.PtrMask[i] = Mask_3; }
		if ( NULL != CastParam3.PtrSpace ) { CastParam3.PtrSpace[i] = Space_3; }
		if ( NULL != CastParam4.PtrMask ) { CastParam4.PtrMask[i] = Mask_4; }
		if ( NULL != CastParam4.PtrSpace ) { CastParam4.PtrSpace[i] = Space_4; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace3_II_MP_Fn_4X4(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, const TCastParam &CastParam2, const TCastParam &CastParam3, const TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料-平行計算	
{
	const int BufferSize = (int)(ImageStep*ImageH);
	if ( index<0 || index>=BufferSize ) { return false; }

	int   nPhase = 0;
	float phase = 0.0f;		
	int   Phase1 = 0;
	int   Phase2 = 0;	
	int   PhaseM_1 = 0;
	int   PhaseM_2 = 0;
	int   PhaseM_3 = 0;
	int   PhaseM_4 = 0;			
	float Space_1=0.0f,Space_2=0.0f,Space_3=0.0f,Space_4=0.0f, Space_M=0.0f;
	float Weight_1=1.0f, Weight_2=1.0f, Weight_3=1.0f, Weight_4=1.0f, Weight_All=0.0f;
	MASK_DATA  Mask_1=0;
	MASK_DATA  Mask_2=0;
	MASK_DATA  Mask_3=0;
	MASK_DATA  Mask_4=0;
	MASK_DATA  Mask_M=0;
	MASK_DATA  MaskA_1=0, MaskB_1=0;
	MASK_DATA  MaskA_2=0, MaskB_2=0;
	MASK_DATA  MaskA_3=0, MaskB_3=0;
	MASK_DATA  MaskA_4=0, MaskB_4=0;

	IMAGE_DATA *PtrA1_1=NULL, *PtrA2_1=NULL, *PtrA3_1=NULL, *PtrA4_1=NULL;
	IMAGE_DATA *PtrB1_1=NULL, *PtrB2_1=NULL, *PtrB3_1=NULL, *PtrB4_1=NULL;
	IMAGE_DATA *PtrA1_2=NULL, *PtrA2_2=NULL, *PtrA3_2=NULL, *PtrA4_2=NULL;
	IMAGE_DATA *PtrB1_2=NULL, *PtrB2_2=NULL, *PtrB3_2=NULL, *PtrB4_2=NULL;
	IMAGE_DATA *PtrA1_3=NULL, *PtrA2_3=NULL, *PtrA3_3=NULL, *PtrA4_3=NULL;
	IMAGE_DATA *PtrB1_3=NULL, *PtrB2_3=NULL, *PtrB3_3=NULL, *PtrB4_3=NULL;
	IMAGE_DATA *PtrA1_4=NULL, *PtrA2_4=NULL, *PtrA3_4=NULL, *PtrA4_4=NULL;
	IMAGE_DATA *PtrB1_4=NULL, *PtrB2_4=NULL, *PtrB3_4=NULL, *PtrB4_4=NULL;
	PHASE_DATA *BasePhasePtr_1=NULL, *BasePhasePtr_2=NULL,*BasePhasePtr_3=NULL,*BasePhasePtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1=NULL, *HeightFactorPtr_2=NULL, *HeightFactorPtr_3=NULL, *HeightFactorPtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1_2=NULL, *HeightFactorPtr_2_2=NULL, *HeightFactorPtr_3_2=NULL, *HeightFactorPtr_4_2=NULL;
	double     *HeightFactor0_1 = NULL, *HeightFactor0_2 = NULL, *HeightFactor0_3 = NULL, *HeightFactor0_4 = NULL;
	double     *HeightFactor1_1 = NULL, *HeightFactor1_2 = NULL, *HeightFactor1_3 = NULL, *HeightFactor1_4 = NULL;
	double     *HeightFactor2_1 = NULL, *HeightFactor2_2 = NULL, *HeightFactor2_3 = NULL, *HeightFactor2_4 = NULL;
	unsigned char *GammaTablePtr_1=NULL, *GammaTablePtr_2=NULL, *GammaTablePtr_3=NULL, *GammaTablePtr_4=NULL;

	PHASE_DATA PhaseA_1=0, PhaseB_1=0;
	PHASE_DATA PhaseA_2=0, PhaseB_2=0;
	PHASE_DATA PhaseA_3=0, PhaseB_3=0;
	PHASE_DATA PhaseA_4=0, PhaseB_4=0;
	PHASE_DATA dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	PHASE_DATA dB1_1=0, dB2_1=0, dB3_1=0, dB4_1=0;
	PHASE_DATA dA1_2=0, dA2_2=0, dA3_2=0, dA4_2=0;
	PHASE_DATA dB1_2=0, dB2_2=0, dB3_2=0, dB4_2=0;
	PHASE_DATA dA1_3=0, dA2_3=0, dA3_3=0, dA4_3=0;
	PHASE_DATA dB1_3=0, dB2_3=0, dB3_3=0, dB4_3=0;
	PHASE_DATA dA1_4=0, dA2_4=0, dA3_4=0, dA4_4=0;
	PHASE_DATA dB1_4=0, dB2_4=0, dB3_4=0, dB4_4=0;	

	int    ImageX=0, ImageY=0;	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int   PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	

	const double PerA = CastParam1.PerA;
	const double PerB = CastParam1.PerB;
	const double PerD = Calc2PhaseNewPeriode(PerA, PerB);	

	PtrA1_1 = CastParam1.PtrA1;	PtrA2_1 = CastParam1.PtrA2;	PtrA3_1 = CastParam1.PtrA3;	PtrA4_1 = CastParam1.PtrA4;
	PtrB1_1 = CastParam1.PtrB1;	PtrB2_1 = CastParam1.PtrB2;	PtrB3_1 = CastParam1.PtrB3;	PtrB4_1 = CastParam1.PtrB4;
	PtrA1_2 = CastParam2.PtrA1;	PtrA2_2 = CastParam2.PtrA2;	PtrA3_2 = CastParam2.PtrA3;	PtrA4_2 = CastParam2.PtrA4;
	PtrB1_2 = CastParam2.PtrB1;	PtrB2_2 = CastParam2.PtrB2;	PtrB3_2 = CastParam2.PtrB3;	PtrB4_2 = CastParam2.PtrB4;
	PtrA1_3 = CastParam3.PtrA1;	PtrA2_3 = CastParam3.PtrA2;	PtrA3_3 = CastParam3.PtrA3;	PtrA4_3 = CastParam3.PtrA4;
	PtrB1_3 = CastParam3.PtrB1;	PtrB2_3 = CastParam3.PtrB2;	PtrB3_3 = CastParam3.PtrB3;	PtrB4_3 = CastParam3.PtrB4;
	PtrA1_4 = CastParam4.PtrA1;	PtrA2_4 = CastParam4.PtrA2;	PtrA3_4 = CastParam4.PtrA3;	PtrA4_4 = CastParam4.PtrA4;
	PtrB1_4 = CastParam4.PtrB1;	PtrB2_4 = CastParam4.PtrB2;	PtrB3_4 = CastParam4.PtrB3;	PtrB4_4 = CastParam4.PtrB4;
	BasePhasePtr_1 = CastParam1.ZeroPhasePtr;
	BasePhasePtr_2 = CastParam2.ZeroPhasePtr;
	BasePhasePtr_3 = CastParam3.ZeroPhasePtr;
	BasePhasePtr_4 = CastParam4.ZeroPhasePtr;
	HeightFactorPtr_1 = CastParam1.HeightFactorPtr;
	HeightFactorPtr_2 = CastParam2.HeightFactorPtr;
	HeightFactorPtr_3 = CastParam3.HeightFactorPtr;
	HeightFactorPtr_4 = CastParam4.HeightFactorPtr;
	HeightFactor0_1 = (double*)CastParam1.HeightFactor0;
	HeightFactor1_1 = (double*)CastParam1.HeightFactor1;
	HeightFactor2_1 = (double*)CastParam1.HeightFactor2;
	HeightFactor0_2 = (double*)CastParam2.HeightFactor0;
	HeightFactor1_2 = (double*)CastParam2.HeightFactor1;
	HeightFactor2_2 = (double*)CastParam2.HeightFactor2;
	HeightFactor0_3 = (double*)CastParam3.HeightFactor0;
	HeightFactor1_3 = (double*)CastParam3.HeightFactor1;
	HeightFactor2_3 = (double*)CastParam3.HeightFactor2;
	HeightFactor0_4 = (double*)CastParam4.HeightFactor0;
	HeightFactor1_4 = (double*)CastParam4.HeightFactor1;
	HeightFactor2_4 = (double*)CastParam4.HeightFactor2;
	GammaTablePtr_1=CastParam1.GammaTablePtr;
	GammaTablePtr_2=CastParam2.GammaTablePtr;
	GammaTablePtr_3=CastParam3.GammaTablePtr;
	GammaTablePtr_4=CastParam4.GammaTablePtr;	

	double dRatioA=1.0;
	double dRatioB=1.0;	
	if ( PerB > PerA )//PB 為主
	{	
		dRatioA = PerB/PerA;
		dRatioB = 1;
	}
	else //PA為主 
	{	
		dRatioA = 1;
		dRatioB = PerA/PerB;
	}
	CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatioA);

	const int i = index;
	const int x = i%ImageStep;
	const int y = i/ImageStep;
	{
		dA1_1 = PtrA1_1[i];	dA2_1 = PtrA2_1[i];	dA3_1 = PtrA3_1[i];	dA4_1 = PtrA4_1[i];
		dB1_1 = PtrB1_1[i];	dB2_1 = PtrB2_1[i];	dB3_1 = PtrB3_1[i];	dB4_1 = PtrB4_1[i];
		dA1_2 = PtrA1_2[i];	dA2_2 = PtrA2_2[i];	dA3_2 = PtrA3_2[i];	dA4_2 = PtrA4_2[i];
		dB1_2 = PtrB1_2[i];	dB2_2 = PtrB2_2[i];	dB3_2 = PtrB3_2[i];	dB4_2 = PtrB4_2[i];
		dA1_3 = PtrA1_3[i];	dA2_3 = PtrA2_3[i];	dA3_3 = PtrA3_3[i];	dA4_3 = PtrA4_3[i];
		dB1_3 = PtrB1_3[i];	dB2_3 = PtrB2_3[i];	dB3_3 = PtrB3_3[i];	dB4_3 = PtrB4_3[i];
		dA1_4 = PtrA1_4[i];	dA2_4 = PtrA2_4[i];	dA3_4 = PtrA3_4[i];	dA4_4 = PtrA4_4[i];
		dB1_4 = PtrB1_4[i];	dB2_4 = PtrB2_4[i];	dB3_4 = PtrB3_4[i];	dB4_4 = PtrB4_4[i];

		if ( NULL != GammaTablePtr_1 )
		{
			dA1_1 = GammaTablePtr_1[dA1_1];
			dA2_1 = GammaTablePtr_1[dA2_1];
			dA3_1 = GammaTablePtr_1[dA3_1];
			dA4_1 = GammaTablePtr_1[dA4_1];
			dB1_1 = GammaTablePtr_1[dB1_1];
			dB2_1 = GammaTablePtr_1[dB2_1];
			dB3_1 = GammaTablePtr_1[dB3_1];
			dB4_1 = GammaTablePtr_1[dB4_1];
		}

		if ( NULL != GammaTablePtr_2 )
		{
			dA1_2 = GammaTablePtr_2[dA1_2];
			dA2_2 = GammaTablePtr_2[dA2_2];
			dA3_2 = GammaTablePtr_2[dA3_2];
			dA4_2 = GammaTablePtr_2[dA4_2];
			dB1_2 = GammaTablePtr_2[dB1_2];
			dB2_2 = GammaTablePtr_2[dB2_2];
			dB3_2 = GammaTablePtr_2[dB3_2];
			dB4_2 = GammaTablePtr_2[dB4_2];
		}

		if ( NULL != GammaTablePtr_3 )
		{
			dA1_3 = GammaTablePtr_3[dA1_3];
			dA2_3 = GammaTablePtr_3[dA2_3];
			dA3_3 = GammaTablePtr_3[dA3_3];
			dA4_3 = GammaTablePtr_3[dA4_3];
			dB1_3 = GammaTablePtr_3[dB1_3];
			dB2_3 = GammaTablePtr_3[dB2_3];
			dB3_3 = GammaTablePtr_3[dB3_3];
			dB4_3 = GammaTablePtr_3[dB4_3];
		}

		if ( NULL != GammaTablePtr_4 )
		{
			dA1_4 = GammaTablePtr_4[dA1_4];
			dA2_4 = GammaTablePtr_4[dA2_4];
			dA3_4 = GammaTablePtr_4[dA3_4];
			dA4_4 = GammaTablePtr_4[dA4_4];
			dB1_4 = GammaTablePtr_4[dB1_4];
			dB2_4 = GammaTablePtr_4[dB2_4];
			dB3_4 = GammaTablePtr_4[dB3_4];
			dB4_4 = GammaTablePtr_4[dB4_4];
		}

		if ( Calc4PhaseParamMask(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_1, MaskA_1, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dB1_1, dB2_1, dB3_1, dB4_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_1, MaskB_1, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_2, MaskA_2, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dB1_2, dB2_2, dB3_2, dB4_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_2, MaskB_2, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_3, MaskA_3, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dB1_3, dB2_3, dB3_3, dB4_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_3, MaskB_3, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_4, MaskA_4, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dB1_4, dB2_4, dB3_4, dB4_4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_4, MaskB_4, PhaseNoiseDefMode) == false )
		{	return false; }

		//雙週期相位合併		
		if ( PerA < PerB )
		{	
			PhaseM_1 = CombinePhasePeriod(CombinePeriodMode, PhaseA_1, PhaseB_1, dRatioA);
			PhaseM_2 = CombinePhasePeriod(CombinePeriodMode, PhaseA_2, PhaseB_2, dRatioA);
			PhaseM_3 = CombinePhasePeriod(CombinePeriodMode, PhaseA_3, PhaseB_3, dRatioA);
			PhaseM_4 = CombinePhasePeriod(CombinePeriodMode, PhaseA_4, PhaseB_4, dRatioA);			
		}
		else
		{
			PhaseM_1 = CombinePhasePeriod(CombinePeriodMode, PhaseB_1, PhaseA_1, dRatioA);//注意相位次序
			PhaseM_2 = CombinePhasePeriod(CombinePeriodMode, PhaseB_2, PhaseA_2, dRatioA);//注意相位次序			
			PhaseM_3 = CombinePhasePeriod(CombinePeriodMode, PhaseB_3, PhaseA_3, dRatioA);//注意相位次序
			PhaseM_4 = CombinePhasePeriod(CombinePeriodMode, PhaseB_4, PhaseA_4, dRatioA);//注意相位次序
		}	

		if ( NULL != BasePhasePtr_1 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_1[i], PhaseM_1);	}		
		if ( NULL != BasePhasePtr_2 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_2[i], PhaseM_2);	}
		if ( NULL != BasePhasePtr_3 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_3[i], PhaseM_3);	}
		if ( NULL != BasePhasePtr_4 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_4[i], PhaseM_4);	}

		Space_1 = PhaseM_1;
		Space_2 = PhaseM_2;
		Space_3 = PhaseM_3;
		Space_4 = PhaseM_4;

		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_1);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_2, HeightFactorPtr_2, HeightFactorPtr_2_2, Space_2);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_3, HeightFactorPtr_3, HeightFactorPtr_3_2, Space_3);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_4, HeightFactorPtr_4, HeightFactorPtr_4_2, Space_4);

		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_2, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_3, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_4, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);

		Mask_1 = CombinePhaseMask(MaskA_1, MaskB_1);
		Mask_2 = CombinePhaseMask(MaskA_2, MaskB_2);
		Mask_3 = CombinePhaseMask(MaskA_3, MaskB_3);
		Mask_4 = CombinePhaseMask(MaskA_4, MaskB_4);		

		//Compare4OppositeGray(cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);//小週期
		bool bUseWeight=true;			
		if ( false == bUseWeight )
		{
			if ( Compare4SpaceHeight(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M) == false ) 
			{	Merge4SpaceData(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M);	}
		}
		else
		{
			float Th = 0.230;		
			Weight_1 = Calc4PhaseContrast(dA1_1, dA2_1, dA3_1, dA4_1);
			Weight_2 = Calc4PhaseContrast(dA1_2, dA2_2, dA3_2, dA4_2);
			Weight_3 = Calc4PhaseContrast(dA1_3, dA2_3, dA3_3, dA4_3);
			Weight_4 = Calc4PhaseContrast(dA1_4, dA2_4, dA3_4, dA4_4);
			Weight_All=Weight_1+Weight_2+Weight_3+Weight_4;
			if ( Weight_All > 0.001 )
			{
				Weight_1 /= Weight_All;
				Weight_2 /= Weight_All;
				Weight_3 /= Weight_All;
				Weight_4 /= Weight_All;
				if ( Weight_1 < Th )
				{
					if ( (Mask_1&PHASE_MASK_NOISE)==NULL )
					{	Mask_1 = PHASE_MASK_OVER_SATURATED; }
				}
				if ( Weight_2 < Th )
				{
					if ( (Mask_2&PHASE_MASK_NOISE)==NULL )
					{	Mask_2 = PHASE_MASK_OVER_SATURATED; }
				}
				if ( Weight_3 < Th )
				{
					if ( (Mask_1&PHASE_MASK_NOISE)==NULL )
					{	Mask_3 = PHASE_MASK_OVER_SATURATED; }
				}
				if ( Weight_4 < Th )
				{
					if ( (Mask_4&PHASE_MASK_NOISE)==NULL )
					{	Mask_4 = PHASE_MASK_OVER_SATURATED; }
				}
			}			
			if ( Compare4SpaceHeight(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M) == false ) 
			{	Merge4SpaceData(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M);	}
		}


		MaskPtr[i] = Mask_M;		
		SpacePtr[i] = Space_M;
		if ( NULL != CastParam1.PtrMask ) { CastParam1.PtrMask[i] = Mask_1; }
		if ( NULL != CastParam1.PtrSpace ) { CastParam1.PtrSpace[i] = Space_1; }
		if ( NULL != CastParam2.PtrMask ) { CastParam2.PtrMask[i] = Mask_2; }
		if ( NULL != CastParam2.PtrSpace ) { CastParam2.PtrSpace[i] = Space_2; }
		if ( NULL != CastParam3.PtrMask ) { CastParam3.PtrMask[i] = Mask_3; }
		if ( NULL != CastParam3.PtrSpace ) { CastParam3.PtrSpace[i] = Space_3; }
		if ( NULL != CastParam4.PtrMask ) { CastParam4.PtrMask[i] = Mask_4; }
		if ( NULL != CastParam4.PtrSpace ) { CastParam4.PtrSpace[i] = Space_4; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace3_II_MP_Fn_4X4GC(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, const TCastParam &CastParam2, const TCastParam &CastParam3, const TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4X4GC投光影像轉成高度資料-平行計算
{
	const int BufferSize = (int)(ImageStep*ImageH);
	if ( index<0 || index>=BufferSize ) { return false; }

	int   nPhase = 0;
	float phase = 0.0f;		
	int   Phase1 = 0;
	int   Phase2 = 0;	
	int   PhaseM_1 = 0;
	int   PhaseM_2 = 0;
	int   PhaseM_3 = 0;
	int   PhaseM_4 = 0;		
	int   k1_1 = 0, k2_1 = 0;
	int   k1_2 = 0, k2_2 = 0;
	int   k1_3 = 0, k2_3 = 0;
	int   k1_4 = 0, k2_4 = 0;
	int   Raw_1[4], Raw_2[4], Raw_3[4], Raw_4[4];
	float Threshold_1=0.0f, Threshold_2=0.0f, Threshold_3=0.0f, Threshold_4=0.0f;
	float Space_1=0.0f,Space_2=0.0f,Space_3=0.0f,Space_4=0.0f, Space_M=0.0f;
	MASK_DATA  Mask_1=0;
	MASK_DATA  Mask_2=0;
	MASK_DATA  Mask_3=0;
	MASK_DATA  Mask_4=0;
	MASK_DATA  Mask_M=0;
	MASK_DATA  MaskA_1=0, MaskB_1=0;
	MASK_DATA  MaskA_2=0, MaskB_2=0;
	MASK_DATA  MaskA_3=0, MaskB_3=0;
	MASK_DATA  MaskA_4=0, MaskB_4=0;

	IMAGE_DATA *PtrA1_1=NULL, *PtrA2_1=NULL, *PtrA3_1=NULL, *PtrA4_1=NULL;
	IMAGE_DATA *PtrB1_1=NULL, *PtrB2_1=NULL, *PtrB3_1=NULL, *PtrB4_1=NULL;
	IMAGE_DATA *PtrA1_2=NULL, *PtrA2_2=NULL, *PtrA3_2=NULL, *PtrA4_2=NULL;
	IMAGE_DATA *PtrB1_2=NULL, *PtrB2_2=NULL, *PtrB3_2=NULL, *PtrB4_2=NULL;
	IMAGE_DATA *PtrA1_3=NULL, *PtrA2_3=NULL, *PtrA3_3=NULL, *PtrA4_3=NULL;
	IMAGE_DATA *PtrB1_3=NULL, *PtrB2_3=NULL, *PtrB3_3=NULL, *PtrB4_3=NULL;
	IMAGE_DATA *PtrA1_4=NULL, *PtrA2_4=NULL, *PtrA3_4=NULL, *PtrA4_4=NULL;
	IMAGE_DATA *PtrB1_4=NULL, *PtrB2_4=NULL, *PtrB3_4=NULL, *PtrB4_4=NULL;
	PHASE_DATA *BasePhasePtr_1=NULL, *BasePhasePtr_2=NULL,*BasePhasePtr_3=NULL,*BasePhasePtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1=NULL, *HeightFactorPtr_2=NULL, *HeightFactorPtr_3=NULL, *HeightFactorPtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1_2=NULL, *HeightFactorPtr_2_2=NULL, *HeightFactorPtr_3_2=NULL, *HeightFactorPtr_4_2=NULL;
	double     *HeightFactor0_1 = NULL, *HeightFactor0_2 = NULL, *HeightFactor0_3 = NULL, *HeightFactor0_4 = NULL;
	double     *HeightFactor1_1 = NULL, *HeightFactor1_2 = NULL, *HeightFactor1_3 = NULL, *HeightFactor1_4 = NULL;
	double     *HeightFactor2_1 = NULL, *HeightFactor2_2 = NULL, *HeightFactor2_3 = NULL, *HeightFactor2_4 = NULL;
	unsigned char *GammaTablePtr_1=NULL, *GammaTablePtr_2=NULL, *GammaTablePtr_3=NULL, *GammaTablePtr_4=NULL;
	unsigned char *CodeK1MapPtr_1=NULL, *CodeK1MapPtr_2=NULL, *CodeK1MapPtr_3=NULL, *CodeK1MapPtr_4=NULL;
	unsigned char *CodeK2MapPtr_1=NULL, *CodeK2MapPtr_2=NULL, *CodeK2MapPtr_3=NULL, *CodeK2MapPtr_4=NULL;

	PHASE_DATA PhaseA_1=0, PhaseB_1=0;
	PHASE_DATA PhaseA_2=0, PhaseB_2=0;
	PHASE_DATA PhaseA_3=0, PhaseB_3=0;
	PHASE_DATA PhaseA_4=0, PhaseB_4=0;
	PHASE_DATA dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	PHASE_DATA dB1_1=0, dB2_1=0, dB3_1=0, dB4_1=0;
	PHASE_DATA dA1_2=0, dA2_2=0, dA3_2=0, dA4_2=0;
	PHASE_DATA dB1_2=0, dB2_2=0, dB3_2=0, dB4_2=0;
	PHASE_DATA dA1_3=0, dA2_3=0, dA3_3=0, dA4_3=0;
	PHASE_DATA dB1_3=0, dB2_3=0, dB3_3=0, dB4_3=0;
	PHASE_DATA dA1_4=0, dA2_4=0, dA3_4=0, dA4_4=0;
	PHASE_DATA dB1_4=0, dB2_4=0, dB3_4=0, dB4_4=0;	

	int    ImageX=0, ImageY=0;	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int   PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;

	const int MaxN = 8;//最多8個16週期
	const int Period = PHASE_PERIOD;

	const double PerA = CastParam1.PerA;
	const double PerB = CastParam1.PerB;
	const double PerD = PerB;	
	const float  ExpTimeRatio_1=(1.0f*CastParam1.ExpTimeB/CastParam1.ExpTimeA);	
	const float  ExpTimeRatio_2=(1.0f*CastParam2.ExpTimeB/CastParam2.ExpTimeA);	
	const float  ExpTimeRatio_3=(1.0f*CastParam3.ExpTimeB/CastParam3.ExpTimeA);	
	const float  ExpTimeRatio_4=(1.0f*CastParam4.ExpTimeB/CastParam4.ExpTimeA);	

	PtrA1_1 = CastParam1.PtrA1;	PtrA2_1 = CastParam1.PtrA2;	PtrA3_1 = CastParam1.PtrA3;	PtrA4_1 = CastParam1.PtrA4;
	PtrB1_1 = CastParam1.PtrB1;	PtrB2_1 = CastParam1.PtrB2;	PtrB3_1 = CastParam1.PtrB3;	PtrB4_1 = CastParam1.PtrB4;
	PtrA1_2 = CastParam2.PtrA1;	PtrA2_2 = CastParam2.PtrA2;	PtrA3_2 = CastParam2.PtrA3;	PtrA4_2 = CastParam2.PtrA4;
	PtrB1_2 = CastParam2.PtrB1;	PtrB2_2 = CastParam2.PtrB2;	PtrB3_2 = CastParam2.PtrB3;	PtrB4_2 = CastParam2.PtrB4;
	PtrA1_3 = CastParam3.PtrA1;	PtrA2_3 = CastParam3.PtrA2;	PtrA3_3 = CastParam3.PtrA3;	PtrA4_3 = CastParam3.PtrA4;
	PtrB1_3 = CastParam3.PtrB1;	PtrB2_3 = CastParam3.PtrB2;	PtrB3_3 = CastParam3.PtrB3;	PtrB4_3 = CastParam3.PtrB4;
	PtrA1_4 = CastParam4.PtrA1;	PtrA2_4 = CastParam4.PtrA2;	PtrA3_4 = CastParam4.PtrA3;	PtrA4_4 = CastParam4.PtrA4;
	PtrB1_4 = CastParam4.PtrB1;	PtrB2_4 = CastParam4.PtrB2;	PtrB3_4 = CastParam4.PtrB3;	PtrB4_4 = CastParam4.PtrB4;
	BasePhasePtr_1 = CastParam1.ZeroPhasePtr;
	BasePhasePtr_2 = CastParam2.ZeroPhasePtr;
	BasePhasePtr_3 = CastParam3.ZeroPhasePtr;
	BasePhasePtr_4 = CastParam4.ZeroPhasePtr;
	HeightFactorPtr_1 = CastParam1.HeightFactorPtr;
	HeightFactorPtr_2 = CastParam2.HeightFactorPtr;
	HeightFactorPtr_3 = CastParam3.HeightFactorPtr;
	HeightFactorPtr_4 = CastParam4.HeightFactorPtr;
	HeightFactor0_1 = (double*)CastParam1.HeightFactor0;
	HeightFactor1_1 = (double*)CastParam1.HeightFactor1;
	HeightFactor2_1 = (double*)CastParam1.HeightFactor2;
	HeightFactor0_2 = (double*)CastParam2.HeightFactor0;
	HeightFactor1_2 = (double*)CastParam2.HeightFactor1;
	HeightFactor2_2 = (double*)CastParam2.HeightFactor2;
	HeightFactor0_3 = (double*)CastParam3.HeightFactor0;
	HeightFactor1_3 = (double*)CastParam3.HeightFactor1;
	HeightFactor2_3 = (double*)CastParam3.HeightFactor2;
	HeightFactor0_4 = (double*)CastParam4.HeightFactor0;
	HeightFactor1_4 = (double*)CastParam4.HeightFactor1;
	HeightFactor2_4 = (double*)CastParam4.HeightFactor2;
	GammaTablePtr_1=CastParam1.GammaTablePtr;
	GammaTablePtr_2=CastParam2.GammaTablePtr;
	GammaTablePtr_3=CastParam3.GammaTablePtr;
	GammaTablePtr_4=CastParam4.GammaTablePtr;
	CodeK1MapPtr_1=CastParam1.GCK1MapPtr;
	CodeK1MapPtr_2=CastParam2.GCK1MapPtr;
	CodeK1MapPtr_3=CastParam3.GCK1MapPtr;
	CodeK1MapPtr_4=CastParam4.GCK1MapPtr;
	CodeK2MapPtr_1=CastParam1.GCK2MapPtr;
	CodeK2MapPtr_2=CastParam2.GCK2MapPtr;
	CodeK2MapPtr_3=CastParam3.GCK2MapPtr;
	CodeK2MapPtr_4=CastParam4.GCK2MapPtr;

	//CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatioA);

	const int i = index;
	const int x = i%ImageStep;
	const int y = i/ImageStep;
	{
		dA1_1 = PtrA1_1[i];	dA2_1 = PtrA2_1[i];	dA3_1 = PtrA3_1[i];	dA4_1 = PtrA4_1[i];
		dB1_1 = PtrB1_1[i];	dB2_1 = PtrB2_1[i];	dB3_1 = PtrB3_1[i];	dB4_1 = PtrB4_1[i];
		dA1_2 = PtrA1_2[i];	dA2_2 = PtrA2_2[i];	dA3_2 = PtrA3_2[i];	dA4_2 = PtrA4_2[i];
		dB1_2 = PtrB1_2[i];	dB2_2 = PtrB2_2[i];	dB3_2 = PtrB3_2[i];	dB4_2 = PtrB4_2[i];
		dA1_3 = PtrA1_3[i];	dA2_3 = PtrA2_3[i];	dA3_3 = PtrA3_3[i];	dA4_3 = PtrA4_3[i];
		dB1_3 = PtrB1_3[i];	dB2_3 = PtrB2_3[i];	dB3_3 = PtrB3_3[i];	dB4_3 = PtrB4_3[i];
		dA1_4 = PtrA1_4[i];	dA2_4 = PtrA2_4[i];	dA3_4 = PtrA3_4[i];	dA4_4 = PtrA4_4[i];
		dB1_4 = PtrB1_4[i];	dB2_4 = PtrB2_4[i];	dB3_4 = PtrB3_4[i];	dB4_4 = PtrB4_4[i];

		if ( NULL != GammaTablePtr_1 )
		{
			dA1_1 = GammaTablePtr_1[dA1_1];
			dA2_1 = GammaTablePtr_1[dA2_1];
			dA3_1 = GammaTablePtr_1[dA3_1];
			dA4_1 = GammaTablePtr_1[dA4_1];
			dB1_1 = GammaTablePtr_1[dB1_1];
			dB2_1 = GammaTablePtr_1[dB2_1];
			dB3_1 = GammaTablePtr_1[dB3_1];
			dB4_1 = GammaTablePtr_1[dB4_1];			
		}

		if ( NULL != GammaTablePtr_2 )
		{
			dA1_2 = GammaTablePtr_2[dA1_2];
			dA2_2 = GammaTablePtr_2[dA2_2];
			dA3_2 = GammaTablePtr_2[dA3_2];
			dA4_2 = GammaTablePtr_2[dA4_2];
			dB1_2 = GammaTablePtr_2[dB1_2];
			dB2_2 = GammaTablePtr_2[dB2_2];
			dB3_2 = GammaTablePtr_2[dB3_2];
			dB4_2 = GammaTablePtr_2[dB4_2];
		}

		if ( NULL != GammaTablePtr_3 )
		{
			dA1_3 = GammaTablePtr_3[dA1_3];
			dA2_3 = GammaTablePtr_3[dA2_3];
			dA3_3 = GammaTablePtr_3[dA3_3];
			dA4_3 = GammaTablePtr_3[dA4_3];
			dB1_3 = GammaTablePtr_3[dB1_3];
			dB2_3 = GammaTablePtr_3[dB2_3];
			dB3_3 = GammaTablePtr_3[dB3_3];
			dB4_3 = GammaTablePtr_3[dB4_3];
		}

		if ( NULL != GammaTablePtr_4 )
		{
			dA1_4 = GammaTablePtr_4[dA1_4];
			dA2_4 = GammaTablePtr_4[dA2_4];
			dA3_4 = GammaTablePtr_4[dA3_4];
			dA4_4 = GammaTablePtr_4[dA4_4];
			dB1_4 = GammaTablePtr_4[dB1_4];
			dB2_4 = GammaTablePtr_4[dB2_4];
			dB3_4 = GammaTablePtr_4[dB3_4];
			dB4_4 = GammaTablePtr_4[dB4_4];
		}

		Threshold_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
		Threshold_1=(float)(Threshold_1*ExpTimeRatio_1);
		Threshold_2=(dA1_2+dA2_2+dA3_2+dA4_2)/4.0f;
		Threshold_2=(float)(Threshold_2*ExpTimeRatio_2);
		Threshold_3=(dA1_3+dA2_3+dA3_3+dA4_3)/4.0f;
		Threshold_3=(float)(Threshold_3*ExpTimeRatio_3);
		Threshold_4=(dA1_4+dA2_4+dA3_4+dA4_4)/4.0f;
		Threshold_4=(float)(Threshold_4*ExpTimeRatio_4);

		Calc4GrayCodeParam(dB1_1, dB2_1, dB3_1, dB4_1, Threshold_1, CodeK1MapPtr_1, CodeK2MapPtr_1, k1_1, k2_1);
		Calc4GrayCodeParam(dB1_2, dB2_2, dB3_2, dB4_2, Threshold_2, CodeK1MapPtr_2, CodeK2MapPtr_2, k1_2, k2_2);
		Calc4GrayCodeParam(dB1_3, dB2_3, dB3_3, dB4_3, Threshold_3, CodeK1MapPtr_3, CodeK2MapPtr_3, k1_3, k2_3);
		Calc4GrayCodeParam(dB1_4, dB2_4, dB3_4, dB4_4, Threshold_4, CodeK1MapPtr_4, CodeK2MapPtr_4, k1_4, k2_4);

		if ( Calc4PhaseParamMask(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_1, MaskA_1, PhaseNoiseDefMode) == false )
		{	return false; }		
		if ( Calc4PhaseParamMask(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_2, MaskA_2, PhaseNoiseDefMode) == false )
		{	return false; }		
		if ( Calc4PhaseParamMask(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_3, MaskA_3, PhaseNoiseDefMode) == false )
		{	return false; }		
		if ( Calc4PhaseParamMask(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_4, MaskA_4, PhaseNoiseDefMode) == false )
		{	return false; }		

		//雙週期相位合併
		PhaseM_1 = CombinePhasePeriod_GrayCode(PhaseA_1, Period, MaxN, k1_1, k2_1);
		PhaseM_2 = CombinePhasePeriod_GrayCode(PhaseA_2, Period, MaxN, k1_2, k2_2);
		PhaseM_3 = CombinePhasePeriod_GrayCode(PhaseA_3, Period, MaxN, k1_3, k2_3);
		PhaseM_4 = CombinePhasePeriod_GrayCode(PhaseA_4, Period, MaxN, k1_4, k2_4);

		if ( NULL != BasePhasePtr_1 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_1[i], PhaseM_1);	}		
		if ( NULL != BasePhasePtr_2 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_2[i], PhaseM_2);	}
		if ( NULL != BasePhasePtr_3 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_3[i], PhaseM_3);	}
		if ( NULL != BasePhasePtr_4 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_4[i], PhaseM_4);	}

		Space_1 = PhaseM_1;
		Space_2 = PhaseM_2;
		Space_3 = PhaseM_3;
		Space_4 = PhaseM_4;

		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_1);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_2, HeightFactorPtr_2, HeightFactorPtr_2_2, Space_2);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_3, HeightFactorPtr_3, HeightFactorPtr_3_2, Space_3);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_4, HeightFactorPtr_4, HeightFactorPtr_4_2, Space_4);

		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_2, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_3, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_4, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);

		Mask_1 = MaskA_1;
		Mask_2 = MaskA_2;
		Mask_3 = MaskA_3;
		Mask_4 = MaskA_4;

		if ( MULTI_CAST_MERGE_MODE_JOE_1 == CastMergeMode )
		{
			Raw_1[0]=dA1_1;	Raw_1[1]=dA2_1;	Raw_1[2]=dA3_1;	Raw_1[3]=dA4_1;
			Raw_2[0]=dA1_2;	Raw_2[1]=dA2_2;	Raw_2[2]=dA3_2;	Raw_2[3]=dA4_2;
			Raw_3[0]=dA1_3;	Raw_3[1]=dA2_3;	Raw_3[2]=dA3_3;	Raw_3[3]=dA4_3;
			Raw_4[0]=dA1_4;	Raw_4[1]=dA2_4;	Raw_4[2]=dA3_4;	Raw_4[3]=dA4_4;
			Merge4SpaceData_Joe(NoiseParam, Raw_1, Mask_1, Space_1, Raw_2, Mask_2, Space_2, Raw_3, Mask_3, Space_3, Raw_4, Mask_4, Space_4, Mask_M, Space_M);
		}
		else
		{
			//Compare4OppositeGray(cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);//小週期
			if ( Compare4SpaceHeight(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M) == false ) 
			{	Merge4SpaceData(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M);	}
		}
		MaskPtr[i] = Mask_M;		
		SpacePtr[i] = Space_M;
		if ( NULL != CastParam1.PtrMask ) { CastParam1.PtrMask[i] = Mask_1; }
		if ( NULL != CastParam1.PtrSpace ) { CastParam1.PtrSpace[i] = Space_1; }
		if ( NULL != CastParam2.PtrMask ) { CastParam2.PtrMask[i] = Mask_2; }
		if ( NULL != CastParam2.PtrSpace ) { CastParam2.PtrSpace[i] = Space_2; }
		if ( NULL != CastParam3.PtrMask ) { CastParam3.PtrMask[i] = Mask_3; }
		if ( NULL != CastParam3.PtrSpace ) { CastParam3.PtrSpace[i] = Space_3; }
		if ( NULL != CastParam4.PtrMask ) { CastParam4.PtrMask[i] = Mask_4; }
		if ( NULL != CastParam4.PtrSpace ) { CastParam4.PtrSpace[i] = Space_4; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace3_II_MP_Fn_4X5GC(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, const TCastParam &CastParam2, const TCastParam &CastParam3, const TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料-平行計算
{
	const int BufferSize = (int)(ImageStep*ImageH);
	if ( index<0 || index>=BufferSize ) { return false; }

	int   nPhase = 0;
	float phase = 0.0f;		
	int   Phase1 = 0;
	int   Phase2 = 0;	
	int   PhaseM_1 = 0;
	int   PhaseM_2 = 0;
	int   PhaseM_3 = 0;
	int   PhaseM_4 = 0;		
	int   k1_1 = 0, k2_1 = 0;
	int   k1_2 = 0, k2_2 = 0;
	int   k1_3 = 0, k2_3 = 0;
	int   k1_4 = 0, k2_4 = 0;
	int   Raw_1[4], Raw_2[4], Raw_3[4], Raw_4[4];
	float Threshold_1=0.0f, Threshold_2=0.0f, Threshold_3=0.0f, Threshold_4=0.0f;
	float Space_1=0.0f,Space_2=0.0f,Space_3=0.0f,Space_4=0.0f, Space_M=0.0f;
	MASK_DATA  Mask_1=0;
	MASK_DATA  Mask_2=0;
	MASK_DATA  Mask_3=0;
	MASK_DATA  Mask_4=0;
	MASK_DATA  Mask_M=0;
	MASK_DATA  MaskA_1=0, MaskB_1=0;
	MASK_DATA  MaskA_2=0, MaskB_2=0;
	MASK_DATA  MaskA_3=0, MaskB_3=0;
	MASK_DATA  MaskA_4=0, MaskB_4=0;

	IMAGE_DATA *PtrA1_1=NULL, *PtrA2_1=NULL, *PtrA3_1=NULL, *PtrA4_1=NULL;
	IMAGE_DATA *PtrB1_1=NULL, *PtrB2_1=NULL, *PtrB3_1=NULL, *PtrB4_1=NULL, *PtrB5_1=NULL;
	IMAGE_DATA *PtrA1_2=NULL, *PtrA2_2=NULL, *PtrA3_2=NULL, *PtrA4_2=NULL;
	IMAGE_DATA *PtrB1_2=NULL, *PtrB2_2=NULL, *PtrB3_2=NULL, *PtrB4_2=NULL, *PtrB5_2=NULL;
	IMAGE_DATA *PtrA1_3=NULL, *PtrA2_3=NULL, *PtrA3_3=NULL, *PtrA4_3=NULL;
	IMAGE_DATA *PtrB1_3=NULL, *PtrB2_3=NULL, *PtrB3_3=NULL, *PtrB4_3=NULL, *PtrB5_3=NULL;
	IMAGE_DATA *PtrA1_4=NULL, *PtrA2_4=NULL, *PtrA3_4=NULL, *PtrA4_4=NULL;
	IMAGE_DATA *PtrB1_4=NULL, *PtrB2_4=NULL, *PtrB3_4=NULL, *PtrB4_4=NULL, *PtrB5_4=NULL;
	PHASE_DATA *BasePhasePtr_1=NULL, *BasePhasePtr_2=NULL,*BasePhasePtr_3=NULL,*BasePhasePtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1=NULL, *HeightFactorPtr_2=NULL, *HeightFactorPtr_3=NULL, *HeightFactorPtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1_2=NULL, *HeightFactorPtr_2_2=NULL, *HeightFactorPtr_3_2=NULL, *HeightFactorPtr_4_2=NULL;
	double     *HeightFactor0_1 = NULL, *HeightFactor0_2 = NULL, *HeightFactor0_3 = NULL, *HeightFactor0_4 = NULL;
	double     *HeightFactor1_1 = NULL, *HeightFactor1_2 = NULL, *HeightFactor1_3 = NULL, *HeightFactor1_4 = NULL;
	double     *HeightFactor2_1 = NULL, *HeightFactor2_2 = NULL, *HeightFactor2_3 = NULL, *HeightFactor2_4 = NULL;
	unsigned char *GammaTablePtr_1=NULL, *GammaTablePtr_2=NULL, *GammaTablePtr_3=NULL, *GammaTablePtr_4=NULL;
	unsigned char *CodeK1MapPtr_1=NULL, *CodeK1MapPtr_2=NULL, *CodeK1MapPtr_3=NULL, *CodeK1MapPtr_4=NULL;
	unsigned char *CodeK2MapPtr_1=NULL, *CodeK2MapPtr_2=NULL, *CodeK2MapPtr_3=NULL, *CodeK2MapPtr_4=NULL;

	PHASE_DATA PhaseA_1=0, PhaseB_1=0;
	PHASE_DATA PhaseA_2=0, PhaseB_2=0;
	PHASE_DATA PhaseA_3=0, PhaseB_3=0;
	PHASE_DATA PhaseA_4=0, PhaseB_4=0;
	PHASE_DATA dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	PHASE_DATA dB1_1=0, dB2_1=0, dB3_1=0, dB4_1=0, dB5_1=0;
	PHASE_DATA dA1_2=0, dA2_2=0, dA3_2=0, dA4_2=0;
	PHASE_DATA dB1_2=0, dB2_2=0, dB3_2=0, dB4_2=0, dB5_2=0;
	PHASE_DATA dA1_3=0, dA2_3=0, dA3_3=0, dA4_3=0;
	PHASE_DATA dB1_3=0, dB2_3=0, dB3_3=0, dB4_3=0, dB5_3=0;
	PHASE_DATA dA1_4=0, dA2_4=0, dA3_4=0, dA4_4=0;
	PHASE_DATA dB1_4=0, dB2_4=0, dB3_4=0, dB4_4=0, dB5_4=0;	

	int    ImageX=0, ImageY=0;	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int   PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;

	const int MaxN = 16;//最多16個16週期
	const int Period = PHASE_PERIOD;

	const double PerA = CastParam1.PerA;
	const double PerB = CastParam1.PerB;
	const double PerD = PerB;	
	const float  ExpTimeRatio_1=(1.0f*CastParam1.ExpTimeB/CastParam1.ExpTimeA);	
	const float  ExpTimeRatio_2=(1.0f*CastParam2.ExpTimeB/CastParam2.ExpTimeA);	
	const float  ExpTimeRatio_3=(1.0f*CastParam3.ExpTimeB/CastParam3.ExpTimeA);	
	const float  ExpTimeRatio_4=(1.0f*CastParam4.ExpTimeB/CastParam4.ExpTimeA);	

	PtrA1_1 = CastParam1.PtrA1;	PtrA2_1 = CastParam1.PtrA2;	PtrA3_1 = CastParam1.PtrA3;	PtrA4_1 = CastParam1.PtrA4;
	PtrB1_1 = CastParam1.PtrB1;	PtrB2_1 = CastParam1.PtrB2;	PtrB3_1 = CastParam1.PtrB3;	PtrB4_1 = CastParam1.PtrB4;	PtrB5_1 = CastParam1.PtrB5; 
	PtrA1_2 = CastParam2.PtrA1;	PtrA2_2 = CastParam2.PtrA2;	PtrA3_2 = CastParam2.PtrA3;	PtrA4_2 = CastParam2.PtrA4;
	PtrB1_2 = CastParam2.PtrB1;	PtrB2_2 = CastParam2.PtrB2;	PtrB3_2 = CastParam2.PtrB3;	PtrB4_2 = CastParam2.PtrB4;	PtrB5_2 = CastParam2.PtrB5; 
	PtrA1_3 = CastParam3.PtrA1;	PtrA2_3 = CastParam3.PtrA2;	PtrA3_3 = CastParam3.PtrA3;	PtrA4_3 = CastParam3.PtrA4;
	PtrB1_3 = CastParam3.PtrB1;	PtrB2_3 = CastParam3.PtrB2;	PtrB3_3 = CastParam3.PtrB3;	PtrB4_3 = CastParam3.PtrB4;	PtrB5_3 = CastParam3.PtrB5;
	PtrA1_4 = CastParam4.PtrA1;	PtrA2_4 = CastParam4.PtrA2;	PtrA3_4 = CastParam4.PtrA3;	PtrA4_4 = CastParam4.PtrA4;
	PtrB1_4 = CastParam4.PtrB1;	PtrB2_4 = CastParam4.PtrB2;	PtrB3_4 = CastParam4.PtrB3;	PtrB4_4 = CastParam4.PtrB4;	PtrB5_4 = CastParam4.PtrB5; 
	BasePhasePtr_1 = CastParam1.ZeroPhasePtr;
	BasePhasePtr_2 = CastParam2.ZeroPhasePtr;
	BasePhasePtr_3 = CastParam3.ZeroPhasePtr;
	BasePhasePtr_4 = CastParam4.ZeroPhasePtr;
	HeightFactorPtr_1 = CastParam1.HeightFactorPtr;
	HeightFactorPtr_2 = CastParam2.HeightFactorPtr;
	HeightFactorPtr_3 = CastParam3.HeightFactorPtr;
	HeightFactorPtr_4 = CastParam4.HeightFactorPtr;
	HeightFactor0_1 = (double*)CastParam1.HeightFactor0;
	HeightFactor1_1 = (double*)CastParam1.HeightFactor1;
	HeightFactor2_1 = (double*)CastParam1.HeightFactor2;
	HeightFactor0_2 = (double*)CastParam2.HeightFactor0;
	HeightFactor1_2 = (double*)CastParam2.HeightFactor1;
	HeightFactor2_2 = (double*)CastParam2.HeightFactor2;
	HeightFactor0_3 = (double*)CastParam3.HeightFactor0;
	HeightFactor1_3 = (double*)CastParam3.HeightFactor1;
	HeightFactor2_3 = (double*)CastParam3.HeightFactor2;
	HeightFactor0_4 = (double*)CastParam4.HeightFactor0;
	HeightFactor1_4 = (double*)CastParam4.HeightFactor1;
	HeightFactor2_4 = (double*)CastParam4.HeightFactor2;
	GammaTablePtr_1=CastParam1.GammaTablePtr;
	GammaTablePtr_2=CastParam2.GammaTablePtr;
	GammaTablePtr_3=CastParam3.GammaTablePtr;
	GammaTablePtr_4=CastParam4.GammaTablePtr;
	CodeK1MapPtr_1=CastParam1.GCK1MapPtr;
	CodeK1MapPtr_2=CastParam2.GCK1MapPtr;
	CodeK1MapPtr_3=CastParam3.GCK1MapPtr;
	CodeK1MapPtr_4=CastParam4.GCK1MapPtr;
	CodeK2MapPtr_1=CastParam1.GCK2MapPtr;
	CodeK2MapPtr_2=CastParam2.GCK2MapPtr;
	CodeK2MapPtr_3=CastParam3.GCK2MapPtr;
	CodeK2MapPtr_4=CastParam4.GCK2MapPtr;

	//CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatioA);
	const int i = index;
	const int x = i%ImageStep;
	const int y = i/ImageStep;
	{
		dA1_1 = PtrA1_1[i];	dA2_1 = PtrA2_1[i];	dA3_1 = PtrA3_1[i];	dA4_1 = PtrA4_1[i];
		dB1_1 = PtrB1_1[i];	dB2_1 = PtrB2_1[i];	dB3_1 = PtrB3_1[i];	dB4_1 = PtrB4_1[i];	dB5_1 = PtrB5_1[i];
		dA1_2 = PtrA1_2[i];	dA2_2 = PtrA2_2[i];	dA3_2 = PtrA3_2[i];	dA4_2 = PtrA4_2[i];
		dB1_2 = PtrB1_2[i];	dB2_2 = PtrB2_2[i];	dB3_2 = PtrB3_2[i];	dB4_2 = PtrB4_2[i];	dB5_2 = PtrB5_2[i];
		dA1_3 = PtrA1_3[i];	dA2_3 = PtrA2_3[i];	dA3_3 = PtrA3_3[i];	dA4_3 = PtrA4_3[i];
		dB1_3 = PtrB1_3[i];	dB2_3 = PtrB2_3[i];	dB3_3 = PtrB3_3[i];	dB4_3 = PtrB4_3[i];	dB5_3 = PtrB5_3[i];
		dA1_4 = PtrA1_4[i];	dA2_4 = PtrA2_4[i];	dA3_4 = PtrA3_4[i];	dA4_4 = PtrA4_4[i];
		dB1_4 = PtrB1_4[i];	dB2_4 = PtrB2_4[i];	dB3_4 = PtrB3_4[i];	dB4_4 = PtrB4_4[i];	dB5_4 = PtrB5_4[i];

		if ( NULL != GammaTablePtr_1 )
		{
			dA1_1 = GammaTablePtr_1[dA1_1];
			dA2_1 = GammaTablePtr_1[dA2_1];
			dA3_1 = GammaTablePtr_1[dA3_1];
			dA4_1 = GammaTablePtr_1[dA4_1];
			dB1_1 = GammaTablePtr_1[dB1_1];
			dB2_1 = GammaTablePtr_1[dB2_1];
			dB3_1 = GammaTablePtr_1[dB3_1];
			dB4_1 = GammaTablePtr_1[dB4_1];
			dB5_1 = GammaTablePtr_1[dB5_1];
		}

		if ( NULL != GammaTablePtr_2 )
		{
			dA1_2 = GammaTablePtr_2[dA1_2];
			dA2_2 = GammaTablePtr_2[dA2_2];
			dA3_2 = GammaTablePtr_2[dA3_2];
			dA4_2 = GammaTablePtr_2[dA4_2];
			dB1_2 = GammaTablePtr_2[dB1_2];
			dB2_2 = GammaTablePtr_2[dB2_2];
			dB3_2 = GammaTablePtr_2[dB3_2];
			dB4_2 = GammaTablePtr_2[dB4_2];
			dB5_2 = GammaTablePtr_2[dB5_2];
		}

		if ( NULL != GammaTablePtr_3 )
		{
			dA1_3 = GammaTablePtr_3[dA1_3];
			dA2_3 = GammaTablePtr_3[dA2_3];
			dA3_3 = GammaTablePtr_3[dA3_3];
			dA4_3 = GammaTablePtr_3[dA4_3];
			dB1_3 = GammaTablePtr_3[dB1_3];
			dB2_3 = GammaTablePtr_3[dB2_3];
			dB3_3 = GammaTablePtr_3[dB3_3];
			dB4_3 = GammaTablePtr_3[dB4_3];
			dB5_3 = GammaTablePtr_3[dB5_3];
		}

		if ( NULL != GammaTablePtr_4 )
		{
			dA1_4 = GammaTablePtr_4[dA1_4];
			dA2_4 = GammaTablePtr_4[dA2_4];
			dA3_4 = GammaTablePtr_4[dA3_4];
			dA4_4 = GammaTablePtr_4[dA4_4];
			dB1_4 = GammaTablePtr_4[dB1_4];
			dB2_4 = GammaTablePtr_4[dB2_4];
			dB3_4 = GammaTablePtr_4[dB3_4];
			dB4_4 = GammaTablePtr_4[dB4_4];
			dB5_4 = GammaTablePtr_4[dB5_4];
		}

		Threshold_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
		Threshold_1=(float)(Threshold_1*ExpTimeRatio_1);
		Threshold_2=(dA1_2+dA2_2+dA3_2+dA4_2)/4.0f;
		Threshold_2=(float)(Threshold_2*ExpTimeRatio_2);
		Threshold_3=(dA1_3+dA2_3+dA3_3+dA4_3)/4.0f;
		Threshold_3=(float)(Threshold_3*ExpTimeRatio_3);
		Threshold_4=(dA1_4+dA2_4+dA3_4+dA4_4)/4.0f;
		Threshold_4=(float)(Threshold_4*ExpTimeRatio_4);

		Calc5GrayCodeParam(dB1_1, dB2_1, dB3_1, dB4_1, dB5_1, Threshold_1, CodeK1MapPtr_1, CodeK2MapPtr_1, k1_1, k2_1);
		Calc5GrayCodeParam(dB1_2, dB2_2, dB3_2, dB4_2, dB5_2, Threshold_2, CodeK1MapPtr_2, CodeK2MapPtr_2, k1_2, k2_2);
		Calc5GrayCodeParam(dB1_3, dB2_3, dB3_3, dB4_3, dB5_3, Threshold_3, CodeK1MapPtr_3, CodeK2MapPtr_3, k1_3, k2_3);
		Calc5GrayCodeParam(dB1_4, dB2_4, dB3_4, dB4_4, dB5_4, Threshold_4, CodeK1MapPtr_4, CodeK2MapPtr_4, k1_4, k2_4);

		if ( Calc4PhaseParamMask(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_1, MaskA_1, PhaseNoiseDefMode) == false )
		{	return false; }		
		if ( Calc4PhaseParamMask(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_2, MaskA_2, PhaseNoiseDefMode) == false )
		{	return false; }		
		if ( Calc4PhaseParamMask(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_3, MaskA_3, PhaseNoiseDefMode) == false )
		{	return false; }		
		if ( Calc4PhaseParamMask(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_4, MaskA_4, PhaseNoiseDefMode) == false )
		{	return false; }		

		//雙週期相位合併
		PhaseM_1 = CombinePhasePeriod_GrayCode(PhaseA_1, Period, MaxN, k1_1, k2_1);
		PhaseM_2 = CombinePhasePeriod_GrayCode(PhaseA_2, Period, MaxN, k1_2, k2_2);
		PhaseM_3 = CombinePhasePeriod_GrayCode(PhaseA_3, Period, MaxN, k1_3, k2_3);
		PhaseM_4 = CombinePhasePeriod_GrayCode(PhaseA_4, Period, MaxN, k1_4, k2_4);

		if ( NULL != BasePhasePtr_1 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_1[i], PhaseM_1);	}		
		if ( NULL != BasePhasePtr_2 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_2[i], PhaseM_2);	}
		if ( NULL != BasePhasePtr_3 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_3[i], PhaseM_3);	}
		if ( NULL != BasePhasePtr_4 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_4[i], PhaseM_4);	}

		Space_1 = PhaseM_1;
		Space_2 = PhaseM_2;
		Space_3 = PhaseM_3;
		Space_4 = PhaseM_4;

		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_1);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_2, HeightFactorPtr_2, HeightFactorPtr_2_2, Space_2);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_3, HeightFactorPtr_3, HeightFactorPtr_3_2, Space_3);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_4, HeightFactorPtr_4, HeightFactorPtr_4_2, Space_4);

		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_2, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_3, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_4, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);

		Mask_1 = MaskA_1;
		Mask_2 = MaskA_2;
		Mask_3 = MaskA_3;
		Mask_4 = MaskA_4;

		if ( MULTI_CAST_MERGE_MODE_JOE_1 == CastMergeMode )
		{
			//const int GC_1[]={dB1_1, dB2_1, dB3_1, dB4_1, dB5_1};
			//const int GC_2[]={dB1_2, dB2_2, dB3_2, dB4_2, dB5_2};
			//const int GC_3[]={dB1_3, dB2_3, dB3_3, dB4_3, dB5_3};		
			//const int GC_4[]={dB1_4, dB2_4, dB3_4, dB4_4, dB5_4};
			Raw_1[0]=dA1_1;	Raw_1[1]=dA2_1;	Raw_1[2]=dA3_1;	Raw_1[3]=dA4_1;
			Raw_2[0]=dA1_2;	Raw_2[1]=dA2_2;	Raw_2[2]=dA3_2;	Raw_2[3]=dA4_2;
			Raw_3[0]=dA1_3;	Raw_3[1]=dA2_3;	Raw_3[2]=dA3_3;	Raw_3[3]=dA4_3;
			Raw_4[0]=dA1_4;	Raw_4[1]=dA2_4;	Raw_4[2]=dA3_4;	Raw_4[3]=dA4_4;
			Merge4SpaceData_Joe(NoiseParam, Raw_1, Mask_1, Space_1, Raw_2, Mask_2, Space_2, Raw_3, Mask_3, Space_3, Raw_4, Mask_4, Space_4, Mask_M, Space_M);
		}
		else
		{
			//Compare4OppositeGray(cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);//小週期
			if ( Compare4SpaceHeight(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M) == false ) 
			{	Merge4SpaceData(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M);	}
		}
		MaskPtr[i] = Mask_M;		
		SpacePtr[i] = Space_M;
		if ( NULL != CastParam1.PtrMask ) { CastParam1.PtrMask[i] = Mask_1; }
		if ( NULL != CastParam1.PtrSpace ) { CastParam1.PtrSpace[i] = Space_1; }
		if ( NULL != CastParam2.PtrMask ) { CastParam2.PtrMask[i] = Mask_2; }
		if ( NULL != CastParam2.PtrSpace ) { CastParam2.PtrSpace[i] = Space_2; }
		if ( NULL != CastParam3.PtrMask ) { CastParam3.PtrMask[i] = Mask_3; }
		if ( NULL != CastParam3.PtrSpace ) { CastParam3.PtrSpace[i] = Space_3; }
		if ( NULL != CastParam4.PtrMask ) { CastParam4.PtrMask[i] = Mask_4; }
		if ( NULL != CastParam4.PtrSpace ) { CastParam4.PtrSpace[i] = Space_4; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace3_II_MP_Fn_4X6GC(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, const TCastParam &CastParam2, const TCastParam &CastParam3, const TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4X6GC投光影像轉成高度資料-平行計算
{
	const int BufferSize = (int)(ImageStep*ImageH);
	if ( index<0 || index>=BufferSize ) { return false; }

	int   nPhase = 0;
	float phase = 0.0f;		
	int   Phase1 = 0;
	int   Phase2 = 0;	
	int   PhaseM_1 = 0;
	int   PhaseM_2 = 0;
	int   PhaseM_3 = 0;
	int   PhaseM_4 = 0;		
	int   k1_1 = 0, k2_1 = 0;
	int   k1_2 = 0, k2_2 = 0;
	int   k1_3 = 0, k2_3 = 0;
	int   k1_4 = 0, k2_4 = 0;
	int   Raw_1[4], Raw_2[4], Raw_3[4], Raw_4[4];
	float Threshold_1=0.0f, Threshold_2=0.0f, Threshold_3=0.0f, Threshold_4=0.0f;
	float Space_1=0.0f,Space_2=0.0f,Space_3=0.0f,Space_4=0.0f, Space_M=0.0f;
	MASK_DATA  Mask_1=0;
	MASK_DATA  Mask_2=0;
	MASK_DATA  Mask_3=0;
	MASK_DATA  Mask_4=0;
	MASK_DATA  Mask_M=0;
	MASK_DATA  MaskA_1=0, MaskB_1=0;
	MASK_DATA  MaskA_2=0, MaskB_2=0;
	MASK_DATA  MaskA_3=0, MaskB_3=0;
	MASK_DATA  MaskA_4=0, MaskB_4=0;

	IMAGE_DATA *PtrA1_1=NULL, *PtrA2_1=NULL, *PtrA3_1=NULL, *PtrA4_1=NULL;
	IMAGE_DATA *PtrB1_1=NULL, *PtrB2_1=NULL, *PtrB3_1=NULL, *PtrB4_1=NULL, *PtrB5_1=NULL, *PtrB6_1=NULL;
	IMAGE_DATA *PtrA1_2=NULL, *PtrA2_2=NULL, *PtrA3_2=NULL, *PtrA4_2=NULL;
	IMAGE_DATA *PtrB1_2=NULL, *PtrB2_2=NULL, *PtrB3_2=NULL, *PtrB4_2=NULL, *PtrB5_2=NULL, *PtrB6_2=NULL;
	IMAGE_DATA *PtrA1_3=NULL, *PtrA2_3=NULL, *PtrA3_3=NULL, *PtrA4_3=NULL;
	IMAGE_DATA *PtrB1_3=NULL, *PtrB2_3=NULL, *PtrB3_3=NULL, *PtrB4_3=NULL, *PtrB5_3=NULL, *PtrB6_3=NULL;
	IMAGE_DATA *PtrA1_4=NULL, *PtrA2_4=NULL, *PtrA3_4=NULL, *PtrA4_4=NULL;
	IMAGE_DATA *PtrB1_4=NULL, *PtrB2_4=NULL, *PtrB3_4=NULL, *PtrB4_4=NULL, *PtrB5_4=NULL, *PtrB6_4=NULL;
	PHASE_DATA *BasePhasePtr_1=NULL, *BasePhasePtr_2=NULL,*BasePhasePtr_3=NULL,*BasePhasePtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1=NULL, *HeightFactorPtr_2=NULL, *HeightFactorPtr_3=NULL, *HeightFactorPtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1_2=NULL, *HeightFactorPtr_2_2=NULL, *HeightFactorPtr_3_2=NULL, *HeightFactorPtr_4_2=NULL;
	double     *HeightFactor0_1 = NULL, *HeightFactor0_2 = NULL, *HeightFactor0_3 = NULL, *HeightFactor0_4 = NULL;
	double     *HeightFactor1_1 = NULL, *HeightFactor1_2 = NULL, *HeightFactor1_3 = NULL, *HeightFactor1_4 = NULL;
	double     *HeightFactor2_1 = NULL, *HeightFactor2_2 = NULL, *HeightFactor2_3 = NULL, *HeightFactor2_4 = NULL;
	unsigned char *GammaTablePtr_1=NULL, *GammaTablePtr_2=NULL, *GammaTablePtr_3=NULL, *GammaTablePtr_4=NULL;
	unsigned char *CodeK1MapPtr_1=NULL, *CodeK1MapPtr_2=NULL, *CodeK1MapPtr_3=NULL, *CodeK1MapPtr_4=NULL;
	unsigned char *CodeK2MapPtr_1=NULL, *CodeK2MapPtr_2=NULL, *CodeK2MapPtr_3=NULL, *CodeK2MapPtr_4=NULL;

	PHASE_DATA PhaseA_1=0, PhaseB_1=0;
	PHASE_DATA PhaseA_2=0, PhaseB_2=0;
	PHASE_DATA PhaseA_3=0, PhaseB_3=0;
	PHASE_DATA PhaseA_4=0, PhaseB_4=0;
	PHASE_DATA dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	PHASE_DATA dB1_1=0, dB2_1=0, dB3_1=0, dB4_1=0, dB5_1=0, dB6_1=0;
	PHASE_DATA dA1_2=0, dA2_2=0, dA3_2=0, dA4_2=0;
	PHASE_DATA dB1_2=0, dB2_2=0, dB3_2=0, dB4_2=0, dB5_2=0, dB6_2=0;
	PHASE_DATA dA1_3=0, dA2_3=0, dA3_3=0, dA4_3=0;
	PHASE_DATA dB1_3=0, dB2_3=0, dB3_3=0, dB4_3=0, dB5_3=0, dB6_3=0;
	PHASE_DATA dA1_4=0, dA2_4=0, dA3_4=0, dA4_4=0;
	PHASE_DATA dB1_4=0, dB2_4=0, dB3_4=0, dB4_4=0, dB5_4=0, dB6_4=0;	

	int    ImageX=0, ImageY=0;	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int   PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;

	const int MaxN = 32;//最多32個16週期
	const int Period = PHASE_PERIOD;

	const double PerA = CastParam1.PerA;
	const double PerB = CastParam1.PerB;
	const double PerD = PerB;	
	const float  ExpTimeRatio_1=(1.0f*CastParam1.ExpTimeB/CastParam1.ExpTimeA);	
	const float  ExpTimeRatio_2=(1.0f*CastParam2.ExpTimeB/CastParam2.ExpTimeA);	
	const float  ExpTimeRatio_3=(1.0f*CastParam3.ExpTimeB/CastParam3.ExpTimeA);	
	const float  ExpTimeRatio_4=(1.0f*CastParam4.ExpTimeB/CastParam4.ExpTimeA);	

	PtrA1_1 = CastParam1.PtrA1;	PtrA2_1 = CastParam1.PtrA2;	PtrA3_1 = CastParam1.PtrA3;	PtrA4_1 = CastParam1.PtrA4;
	PtrB1_1 = CastParam1.PtrB1;	PtrB2_1 = CastParam1.PtrB2;	PtrB3_1 = CastParam1.PtrB3;	PtrB4_1 = CastParam1.PtrB4;	PtrB5_1 = CastParam1.PtrB5;	PtrB6_1 = CastParam1.PtrB6;
	PtrA1_2 = CastParam2.PtrA1;	PtrA2_2 = CastParam2.PtrA2;	PtrA3_2 = CastParam2.PtrA3;	PtrA4_2 = CastParam2.PtrA4;
	PtrB1_2 = CastParam2.PtrB1;	PtrB2_2 = CastParam2.PtrB2;	PtrB3_2 = CastParam2.PtrB3;	PtrB4_2 = CastParam2.PtrB4;	PtrB5_2 = CastParam2.PtrB5;	PtrB6_2 = CastParam2.PtrB6;
	PtrA1_3 = CastParam3.PtrA1;	PtrA2_3 = CastParam3.PtrA2;	PtrA3_3 = CastParam3.PtrA3;	PtrA4_3 = CastParam3.PtrA4;
	PtrB1_3 = CastParam3.PtrB1;	PtrB2_3 = CastParam3.PtrB2;	PtrB3_3 = CastParam3.PtrB3;	PtrB4_3 = CastParam3.PtrB4;	PtrB5_3 = CastParam3.PtrB5;	PtrB6_3 = CastParam3.PtrB6;
	PtrA1_4 = CastParam4.PtrA1;	PtrA2_4 = CastParam4.PtrA2;	PtrA3_4 = CastParam4.PtrA3;	PtrA4_4 = CastParam4.PtrA4;
	PtrB1_4 = CastParam4.PtrB1;	PtrB2_4 = CastParam4.PtrB2;	PtrB3_4 = CastParam4.PtrB3;	PtrB4_4 = CastParam4.PtrB4;	PtrB5_4 = CastParam4.PtrB5;	PtrB6_4 = CastParam4.PtrB6;
	BasePhasePtr_1 = CastParam1.ZeroPhasePtr;
	BasePhasePtr_2 = CastParam2.ZeroPhasePtr;
	BasePhasePtr_3 = CastParam3.ZeroPhasePtr;
	BasePhasePtr_4 = CastParam4.ZeroPhasePtr;
	HeightFactorPtr_1 = CastParam1.HeightFactorPtr;
	HeightFactorPtr_2 = CastParam2.HeightFactorPtr;
	HeightFactorPtr_3 = CastParam3.HeightFactorPtr;
	HeightFactorPtr_4 = CastParam4.HeightFactorPtr;
	HeightFactor0_1 = (double*)CastParam1.HeightFactor0;
	HeightFactor1_1 = (double*)CastParam1.HeightFactor1;
	HeightFactor2_1 = (double*)CastParam1.HeightFactor2;
	HeightFactor0_2 = (double*)CastParam2.HeightFactor0;
	HeightFactor1_2 = (double*)CastParam2.HeightFactor1;
	HeightFactor2_2 = (double*)CastParam2.HeightFactor2;
	HeightFactor0_3 = (double*)CastParam3.HeightFactor0;
	HeightFactor1_3 = (double*)CastParam3.HeightFactor1;
	HeightFactor2_3 = (double*)CastParam3.HeightFactor2;
	HeightFactor0_4 = (double*)CastParam4.HeightFactor0;
	HeightFactor1_4 = (double*)CastParam4.HeightFactor1;
	HeightFactor2_4 = (double*)CastParam4.HeightFactor2;
	GammaTablePtr_1=CastParam1.GammaTablePtr;
	GammaTablePtr_2=CastParam2.GammaTablePtr;
	GammaTablePtr_3=CastParam3.GammaTablePtr;
	GammaTablePtr_4=CastParam4.GammaTablePtr;
	CodeK1MapPtr_1=CastParam1.GCK1MapPtr;
	CodeK1MapPtr_2=CastParam2.GCK1MapPtr;
	CodeK1MapPtr_3=CastParam3.GCK1MapPtr;
	CodeK1MapPtr_4=CastParam4.GCK1MapPtr;
	CodeK2MapPtr_1=CastParam1.GCK2MapPtr;
	CodeK2MapPtr_2=CastParam2.GCK2MapPtr;
	CodeK2MapPtr_3=CastParam3.GCK2MapPtr;
	CodeK2MapPtr_4=CastParam4.GCK2MapPtr;

	//CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatioA);

	const int i = index;
	const int x = i%ImageStep;
	const int y = i/ImageStep;
	{
		dA1_1 = PtrA1_1[i];	dA2_1 = PtrA2_1[i];	dA3_1 = PtrA3_1[i];	dA4_1 = PtrA4_1[i];
		dB1_1 = PtrB1_1[i];	dB2_1 = PtrB2_1[i];	dB3_1 = PtrB3_1[i];	dB4_1 = PtrB4_1[i];	dB5_1 = PtrB5_1[i];	dB6_1 = PtrB6_1[i];
		dA1_2 = PtrA1_2[i];	dA2_2 = PtrA2_2[i];	dA3_2 = PtrA3_2[i];	dA4_2 = PtrA4_2[i];
		dB1_2 = PtrB1_2[i];	dB2_2 = PtrB2_2[i];	dB3_2 = PtrB3_2[i];	dB4_2 = PtrB4_2[i];	dB5_2 = PtrB5_2[i];	dB6_2 = PtrB6_2[i];
		dA1_3 = PtrA1_3[i];	dA2_3 = PtrA2_3[i];	dA3_3 = PtrA3_3[i];	dA4_3 = PtrA4_3[i];
		dB1_3 = PtrB1_3[i];	dB2_3 = PtrB2_3[i];	dB3_3 = PtrB3_3[i];	dB4_3 = PtrB4_3[i];	dB5_3 = PtrB5_3[i];	dB6_3 = PtrB6_3[i];
		dA1_4 = PtrA1_4[i];	dA2_4 = PtrA2_4[i];	dA3_4 = PtrA3_4[i];	dA4_4 = PtrA4_4[i];
		dB1_4 = PtrB1_4[i];	dB2_4 = PtrB2_4[i];	dB3_4 = PtrB3_4[i];	dB4_4 = PtrB4_4[i];	dB5_4 = PtrB5_4[i];	dB6_4 = PtrB6_4[i];

		if ( NULL != GammaTablePtr_1 )
		{
			dA1_1 = GammaTablePtr_1[dA1_1];
			dA2_1 = GammaTablePtr_1[dA2_1];
			dA3_1 = GammaTablePtr_1[dA3_1];
			dA4_1 = GammaTablePtr_1[dA4_1];
			dB1_1 = GammaTablePtr_1[dB1_1];
			dB2_1 = GammaTablePtr_1[dB2_1];
			dB3_1 = GammaTablePtr_1[dB3_1];
			dB4_1 = GammaTablePtr_1[dB4_1];
			dB5_1 = GammaTablePtr_1[dB5_1];
			dB6_1 = GammaTablePtr_1[dB6_1];
		}

		if ( NULL != GammaTablePtr_2 )
		{
			dA1_2 = GammaTablePtr_2[dA1_2];
			dA2_2 = GammaTablePtr_2[dA2_2];
			dA3_2 = GammaTablePtr_2[dA3_2];
			dA4_2 = GammaTablePtr_2[dA4_2];
			dB1_2 = GammaTablePtr_2[dB1_2];
			dB2_2 = GammaTablePtr_2[dB2_2];
			dB3_2 = GammaTablePtr_2[dB3_2];
			dB4_2 = GammaTablePtr_2[dB4_2];
			dB5_2 = GammaTablePtr_2[dB5_2];
			dB6_2 = GammaTablePtr_2[dB6_2];
		}

		if ( NULL != GammaTablePtr_3 )
		{
			dA1_3 = GammaTablePtr_3[dA1_3];
			dA2_3 = GammaTablePtr_3[dA2_3];
			dA3_3 = GammaTablePtr_3[dA3_3];
			dA4_3 = GammaTablePtr_3[dA4_3];
			dB1_3 = GammaTablePtr_3[dB1_3];
			dB2_3 = GammaTablePtr_3[dB2_3];
			dB3_3 = GammaTablePtr_3[dB3_3];
			dB4_3 = GammaTablePtr_3[dB4_3];
			dB5_3 = GammaTablePtr_3[dB5_3];
			dB6_3 = GammaTablePtr_3[dB6_3];
		}

		if ( NULL != GammaTablePtr_4 )
		{
			dA1_4 = GammaTablePtr_4[dA1_4];
			dA2_4 = GammaTablePtr_4[dA2_4];
			dA3_4 = GammaTablePtr_4[dA3_4];
			dA4_4 = GammaTablePtr_4[dA4_4];
			dB1_4 = GammaTablePtr_4[dB1_4];
			dB2_4 = GammaTablePtr_4[dB2_4];
			dB3_4 = GammaTablePtr_4[dB3_4];
			dB4_4 = GammaTablePtr_4[dB4_4];
			dB5_4 = GammaTablePtr_4[dB5_4];
			dB6_4 = GammaTablePtr_4[dB6_4];
		}

		Threshold_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
		Threshold_1=(float)(Threshold_1*ExpTimeRatio_1);
		Threshold_2=(dA1_2+dA2_2+dA3_2+dA4_2)/4.0f;
		Threshold_2=(float)(Threshold_2*ExpTimeRatio_2);
		Threshold_3=(dA1_3+dA2_3+dA3_3+dA4_3)/4.0f;
		Threshold_3=(float)(Threshold_3*ExpTimeRatio_3);
		Threshold_4=(dA1_4+dA2_4+dA3_4+dA4_4)/4.0f;
		Threshold_4=(float)(Threshold_4*ExpTimeRatio_4);

		Calc6GrayCodeParam(dB1_1, dB2_1, dB3_1, dB4_1, dB5_1, dB6_1, Threshold_1, CodeK1MapPtr_1, CodeK2MapPtr_1, k1_1, k2_1);
		Calc6GrayCodeParam(dB1_2, dB2_2, dB3_2, dB4_2, dB5_2, dB6_2, Threshold_2, CodeK1MapPtr_2, CodeK2MapPtr_2, k1_2, k2_2);
		Calc6GrayCodeParam(dB1_3, dB2_3, dB3_3, dB4_3, dB5_3, dB6_3, Threshold_3, CodeK1MapPtr_3, CodeK2MapPtr_3, k1_3, k2_3);
		Calc6GrayCodeParam(dB1_4, dB2_4, dB3_4, dB4_4, dB5_4, dB6_4, Threshold_4, CodeK1MapPtr_4, CodeK2MapPtr_4, k1_4, k2_4);

		if ( Calc4PhaseParamMask(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_1, MaskA_1, PhaseNoiseDefMode) == false )
		{	return false; }		
		if ( Calc4PhaseParamMask(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_2, MaskA_2, PhaseNoiseDefMode) == false )
		{	return false; }		
		if ( Calc4PhaseParamMask(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_3, MaskA_3, PhaseNoiseDefMode) == false )
		{	return false; }		
		if ( Calc4PhaseParamMask(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_4, MaskA_4, PhaseNoiseDefMode) == false )
		{	return false; }		

		//雙週期相位合併
		PhaseM_1 = CombinePhasePeriod_GrayCode(PhaseA_1, Period, MaxN, k1_1, k2_1);
		PhaseM_2 = CombinePhasePeriod_GrayCode(PhaseA_2, Period, MaxN, k1_2, k2_2);
		PhaseM_3 = CombinePhasePeriod_GrayCode(PhaseA_3, Period, MaxN, k1_3, k2_3);
		PhaseM_4 = CombinePhasePeriod_GrayCode(PhaseA_4, Period, MaxN, k1_4, k2_4);

		if ( NULL != BasePhasePtr_1 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_1[i], PhaseM_1);	}		
		if ( NULL != BasePhasePtr_2 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_2[i], PhaseM_2);	}
		if ( NULL != BasePhasePtr_3 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_3[i], PhaseM_3);	}
		if ( NULL != BasePhasePtr_4 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_4[i], PhaseM_4);	}

		Space_1 = PhaseM_1;
		Space_2 = PhaseM_2;
		Space_3 = PhaseM_3;
		Space_4 = PhaseM_4;

		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_1);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_2, HeightFactorPtr_2, HeightFactorPtr_2_2, Space_2);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_3, HeightFactorPtr_3, HeightFactorPtr_3_2, Space_3);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_4, HeightFactorPtr_4, HeightFactorPtr_4_2, Space_4);

		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_2, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_3, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_4, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);

		Mask_1 = MaskA_1;
		Mask_2 = MaskA_2;
		Mask_3 = MaskA_3;
		Mask_4 = MaskA_4;

		if ( MULTI_CAST_MERGE_MODE_JOE_1 == CastMergeMode )
		{
			Raw_1[0]=dA1_1;	Raw_1[1]=dA2_1;	Raw_1[2]=dA3_1;	Raw_1[3]=dA4_1;
			Raw_2[0]=dA1_2;	Raw_2[1]=dA2_2;	Raw_2[2]=dA3_2;	Raw_2[3]=dA4_2;
			Raw_3[0]=dA1_3;	Raw_3[1]=dA2_3;	Raw_3[2]=dA3_3;	Raw_3[3]=dA4_3;
			Raw_4[0]=dA1_4;	Raw_4[1]=dA2_4;	Raw_4[2]=dA3_4;	Raw_4[3]=dA4_4;
			Merge4SpaceData_Joe(NoiseParam, Raw_1, Mask_1, Space_1, Raw_2, Mask_2, Space_2, Raw_3, Mask_3, Space_3, Raw_4, Mask_4, Space_4, Mask_M, Space_M);
		}
		else
		{
			//Compare4OppositeGray(cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);//小週期
			if ( Compare4SpaceHeight(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M) == false ) 
			{	Merge4SpaceData(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M);	}
		}
		MaskPtr[i] = Mask_M;		
		SpacePtr[i] = Space_M;
		if ( NULL != CastParam1.PtrMask ) { CastParam1.PtrMask[i] = Mask_1; }
		if ( NULL != CastParam1.PtrSpace ) { CastParam1.PtrSpace[i] = Space_1; }
		if ( NULL != CastParam2.PtrMask ) { CastParam2.PtrMask[i] = Mask_2; }
		if ( NULL != CastParam2.PtrSpace ) { CastParam2.PtrSpace[i] = Space_2; }
		if ( NULL != CastParam3.PtrMask ) { CastParam3.PtrMask[i] = Mask_3; }
		if ( NULL != CastParam3.PtrSpace ) { CastParam3.PtrSpace[i] = Space_3; }
		if ( NULL != CastParam4.PtrMask ) { CastParam4.PtrMask[i] = Mask_4; }
		if ( NULL != CastParam4.PtrSpace ) { CastParam4.PtrSpace[i] = Space_4; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace3_II_MP_Fn_4_2Step(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, const TCastParam &CastParam2, const TCastParam &CastParam3, const TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料-平行計算
{
	const int BufferSize = (int)(ImageStep*ImageH);
	if ( index<0 || index>=BufferSize ) { return false; }

	int   nPhase = 0;
	float phase = 0.0f;		
	int   Phase1 = 0;
	int   Phase2 = 0;	
	int   PhaseM_1 = 0;
	int   PhaseM_2 = 0;
	int   PhaseM_3 = 0;
	int   PhaseM_4 = 0;
	float Space_1=0.0f,Space_2=0.0f,Space_3=0.0f,Space_4=0.0f, Space_M=0.0f;
	MASK_DATA  Mask_1=0;
	MASK_DATA  Mask_2=0;
	MASK_DATA  Mask_3=0;
	MASK_DATA  Mask_4=0;
	MASK_DATA  Mask_M=0;
	MASK_DATA  MaskA_1=0, MaskB_1=0;
	MASK_DATA  MaskA_2=0, MaskB_2=0;
	MASK_DATA  MaskA_3=0, MaskB_3=0;
	MASK_DATA  MaskA_4=0, MaskB_4=0;

	IMAGE_DATA *PtrA1_1=NULL, *PtrA2_1=NULL, *PtrA3_1=NULL, *PtrA4_1=NULL;
	IMAGE_DATA *PtrB1_1=NULL, *PtrB2_1=NULL, *PtrB3_1=NULL, *PtrB4_1=NULL;
	IMAGE_DATA *PtrA1_2=NULL, *PtrA2_2=NULL, *PtrA3_2=NULL, *PtrA4_2=NULL;
	IMAGE_DATA *PtrB1_2=NULL, *PtrB2_2=NULL, *PtrB3_2=NULL, *PtrB4_2=NULL;
	IMAGE_DATA *PtrA1_3=NULL, *PtrA2_3=NULL, *PtrA3_3=NULL, *PtrA4_3=NULL;
	IMAGE_DATA *PtrB1_3=NULL, *PtrB2_3=NULL, *PtrB3_3=NULL, *PtrB4_3=NULL;
	IMAGE_DATA *PtrA1_4=NULL, *PtrA2_4=NULL, *PtrA3_4=NULL, *PtrA4_4=NULL;
	IMAGE_DATA *PtrB1_4=NULL, *PtrB2_4=NULL, *PtrB3_4=NULL, *PtrB4_4=NULL;
	PHASE_DATA *BasePhasePtr_1=NULL, *BasePhasePtr_2=NULL,*BasePhasePtr_3=NULL,*BasePhasePtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1=NULL, *HeightFactorPtr_2=NULL, *HeightFactorPtr_3=NULL, *HeightFactorPtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1_2=NULL, *HeightFactorPtr_2_2=NULL, *HeightFactorPtr_3_2=NULL, *HeightFactorPtr_4_2=NULL;
	double     *HeightFactor0_1 = NULL, *HeightFactor0_2 = NULL, *HeightFactor0_3 = NULL, *HeightFactor0_4 = NULL;
	double     *HeightFactor1_1 = NULL, *HeightFactor1_2 = NULL, *HeightFactor1_3 = NULL, *HeightFactor1_4 = NULL;
	double     *HeightFactor2_1 = NULL, *HeightFactor2_2 = NULL, *HeightFactor2_3 = NULL, *HeightFactor2_4 = NULL;
	unsigned char *GammaTablePtr_1=NULL, *GammaTablePtr_2=NULL, *GammaTablePtr_3=NULL, *GammaTablePtr_4=NULL;

	PHASE_DATA PhaseA_1=0, PhaseB_1=0;
	PHASE_DATA PhaseA_2=0, PhaseB_2=0;
	PHASE_DATA PhaseA_3=0, PhaseB_3=0;
	PHASE_DATA PhaseA_4=0, PhaseB_4=0;
	PHASE_DATA dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	PHASE_DATA dB1_1=0, dB2_1=0, dB3_1=0;
	PHASE_DATA dA1_2=0, dA2_2=0, dA3_2=0, dA4_2=0;
	PHASE_DATA dB1_2=0, dB2_2=0, dB3_2=0;
	PHASE_DATA dA1_3=0, dA2_3=0, dA3_3=0, dA4_3=0;
	PHASE_DATA dB1_3=0, dB2_3=0, dB3_3=0;
	PHASE_DATA dA1_4=0, dA2_4=0, dA3_4=0, dA4_4=0;
	PHASE_DATA dB1_4=0, dB2_4=0, dB3_4=0;	

	//#ifdef _DEBUG
	PHASE_DATA cT_1=0;
	PHASE_DATA cT_2=0;
	PHASE_DATA cT_3=0;
	PHASE_DATA cT_4=0;
	int   aT_1=0, bT_1=0;
	int   aT_2=0, bT_2=0;
	int   aT_3=0, bT_3=0;
	int   aT_4=0, bT_4=0;	
	PHASE_DATA PhaseT_1=0;
	PHASE_DATA PhaseT_2=0;
	PHASE_DATA PhaseT_3=0;
	PHASE_DATA PhaseT_4=0;
	PHASE_DATA dT1_1=0, dT2_1=0, dT3_1=0, dT4_1=0;
	PHASE_DATA dT1_2=0, dT2_2=0, dT3_2=0, dT4_2=0;
	PHASE_DATA dT1_3=0, dT2_3=0, dT3_3=0, dT4_3=0;
	PHASE_DATA dT1_4=0, dT2_4=0, dT3_4=0, dT4_4=0;
	//#endif//_DEBUG

	int    ImageX=0, ImageY=0;	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int   PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	

	const double PerA = CastParam1.PerA;
	const double PerB = CastParam1.PerB;
	const double PerD = Calc2PhaseNewPeriode(PerA, PerB);	
	const float  ExpTimeRatio_1 = (1.0f*CastParam1.ExpTimeB)/CastParam1.ExpTimeA;
	const float  ExpTimeRatio_2 = (1.0f*CastParam2.ExpTimeB)/CastParam2.ExpTimeA;
	const float  ExpTimeRatio_3 = (1.0f*CastParam3.ExpTimeB)/CastParam3.ExpTimeA;
	const float  ExpTimeRatio_4 = (1.0f*CastParam4.ExpTimeB)/CastParam4.ExpTimeA;

	PtrA1_1 = CastParam1.PtrA1;	PtrA2_1 = CastParam1.PtrA2;	PtrA3_1 = CastParam1.PtrA3;	PtrA4_1 = CastParam1.PtrA4;
	PtrB1_1 = CastParam1.PtrB1;	PtrB2_1 = CastParam1.PtrB2;	PtrB3_1 = CastParam1.PtrB3;	PtrB4_1 = CastParam1.PtrB4;
	PtrA1_2 = CastParam2.PtrA1;	PtrA2_2 = CastParam2.PtrA2;	PtrA3_2 = CastParam2.PtrA3;	PtrA4_2 = CastParam2.PtrA4;
	PtrB1_2 = CastParam2.PtrB1;	PtrB2_2 = CastParam2.PtrB2;	PtrB3_2 = CastParam2.PtrB3;	PtrB4_2 = CastParam2.PtrB4;
	PtrA1_3 = CastParam3.PtrA1;	PtrA2_3 = CastParam3.PtrA2;	PtrA3_3 = CastParam3.PtrA3;	PtrA4_3 = CastParam3.PtrA4;
	PtrB1_3 = CastParam3.PtrB1;	PtrB2_3 = CastParam3.PtrB2;	PtrB3_3 = CastParam3.PtrB3;	PtrB4_3 = CastParam3.PtrB4;
	PtrA1_4 = CastParam4.PtrA1;	PtrA2_4 = CastParam4.PtrA2;	PtrA3_4 = CastParam4.PtrA3;	PtrA4_4 = CastParam4.PtrA4;
	PtrB1_4 = CastParam4.PtrB1;	PtrB2_4 = CastParam4.PtrB2;	PtrB3_4 = CastParam4.PtrB3;	PtrB4_4 = CastParam4.PtrB4;
	BasePhasePtr_1 = CastParam1.ZeroPhasePtr;
	BasePhasePtr_2 = CastParam2.ZeroPhasePtr;
	BasePhasePtr_3 = CastParam3.ZeroPhasePtr;
	BasePhasePtr_4 = CastParam4.ZeroPhasePtr;
	HeightFactorPtr_1 = CastParam1.HeightFactorPtr;
	HeightFactorPtr_2 = CastParam2.HeightFactorPtr;
	HeightFactorPtr_3 = CastParam3.HeightFactorPtr;
	HeightFactorPtr_4 = CastParam4.HeightFactorPtr;
	HeightFactor0_1 = (double*)CastParam1.HeightFactor0;
	HeightFactor1_1 = (double*)CastParam1.HeightFactor1;
	HeightFactor2_1 = (double*)CastParam1.HeightFactor2;
	HeightFactor0_2 = (double*)CastParam2.HeightFactor0;
	HeightFactor1_2 = (double*)CastParam2.HeightFactor1;
	HeightFactor2_2 = (double*)CastParam2.HeightFactor2;
	HeightFactor0_3 = (double*)CastParam3.HeightFactor0;
	HeightFactor1_3 = (double*)CastParam3.HeightFactor1;
	HeightFactor2_3 = (double*)CastParam3.HeightFactor2;
	HeightFactor0_4 = (double*)CastParam4.HeightFactor0;
	HeightFactor1_4 = (double*)CastParam4.HeightFactor1;
	HeightFactor2_4 = (double*)CastParam4.HeightFactor2;
	GammaTablePtr_1=CastParam1.GammaTablePtr;
	GammaTablePtr_2=CastParam2.GammaTablePtr;
	GammaTablePtr_3=CastParam3.GammaTablePtr;
	GammaTablePtr_4=CastParam4.GammaTablePtr;	

	//BasePhasePtr_1 = NULL;

	double dRatioA=1.0;
	double dRatioB=1.0;	
	if ( PerB > PerA )//PB 為主
	{	
		dRatioA = PerB/PerA;
		dRatioB = 1;
	}
	else //PA為主 
	{	
		dRatioA = 1;
		dRatioB = PerA/PerB;
	}
	CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatioA);

	const int i = index;
	const int x = i%ImageStep;
	const int y = i/ImageStep;
	//if ( 9491958 == index )
	//{	index = index; }
	{
		dA1_1 = PtrA1_1[i];	dA2_1 = PtrA2_1[i];	dA3_1 = PtrA3_1[i];	dA4_1 = PtrA4_1[i];
		dB1_1 = PtrB1_1[i];	dB3_1 = PtrB3_1[i];
		dA1_2 = PtrA1_2[i];	dA2_2 = PtrA2_2[i];	dA3_2 = PtrA3_2[i];	dA4_2 = PtrA4_2[i];
		dB1_2 = PtrB1_2[i];	dB3_2 = PtrB3_2[i];
		dA1_3 = PtrA1_3[i];	dA2_3 = PtrA2_3[i];	dA3_3 = PtrA3_3[i];	dA4_3 = PtrA4_3[i];
		dB1_3 = PtrB1_3[i];	dB3_3 = PtrB3_3[i];
		dA1_4 = PtrA1_4[i];	dA2_4 = PtrA2_4[i];	dA3_4 = PtrA3_4[i];	dA4_4 = PtrA4_4[i];
		dB1_4 = PtrB1_4[i];	dB3_4 = PtrB3_4[i];

		//SIN = COS(+270)
		//COS = SIN(+090)
		//1:000, 2:270, 3:180, 4:090
		dB1_1 = PtrB1_1[i];	dB3_1 = PtrB4_1[i];
		dB1_2 = PtrB1_2[i];	dB3_2 = PtrB4_2[i];
		dB1_3 = PtrB1_3[i];	dB3_3 = PtrB4_3[i];
		dB1_4 = PtrB1_4[i];	dB3_4 = PtrB4_4[i];		

		dB2_1 = (dA1_1+dA2_1+dA3_1+dA4_1)/4;
		dB2_2 = (dA1_2+dA2_2+dA3_2+dA4_2)/4;
		dB2_3 = (dA1_3+dA2_3+dA3_3+dA4_3)/4;
		dB2_4 = (dA1_4+dA2_4+dA3_4+dA4_4)/4;

		//曝光比例
		dB2_1 = (int)((dB2_1*ExpTimeRatio_1)+0.5);
		dB2_2 = (int)((dB2_2*ExpTimeRatio_2)+0.5);
		dB2_3 = (int)((dB2_3*ExpTimeRatio_3)+0.5);
		dB2_4 = (int)((dB2_4*ExpTimeRatio_4)+0.5);

		//補真的平均灰階-127
		//dB2_1 = (PtrB3_1[i]);
		//dB2_2 = (PtrB3_2[i]);
		//dB2_3 = (PtrB3_3[i]);
		//dB2_4 = (PtrB3_4[i]);

		//使用原始週期的平均
		//dB2_1 = (PtrB1_1[i]+PtrB2_1[i]+PtrB3_1[i]+PtrB4_1[i])/4;
		//dB2_2 = (PtrB1_2[i]+PtrB2_2[i]+PtrB3_2[i]+PtrB4_2[i])/4;
		//dB2_3 = (PtrB1_3[i]+PtrB2_3[i]+PtrB3_3[i]+PtrB4_3[i])/4;
		//dB2_4 = (PtrB1_4[i]+PtrB2_4[i]+PtrB3_4[i]+PtrB4_4[i])/4;

		//混者用
		//dB2_1 = (((dB1_1+dB3_1)/2)+dB2_1)/2;
		//dB2_2 = (((dB1_2+dB3_2)/2)+dB2_2)/2;
		//dB2_3 = (((dB1_3+dB3_3)/2)+dB2_3)/2;
		//dB2_4 = (((dB1_4+dB3_4)/2)+dB2_4)/2;

		if ( NULL != GammaTablePtr_1 )
		{
			dA1_1 = GammaTablePtr_1[dA1_1];
			dA2_1 = GammaTablePtr_1[dA2_1];
			dA3_1 = GammaTablePtr_1[dA3_1];
			dA4_1 = GammaTablePtr_1[dA4_1];
			dB1_1 = GammaTablePtr_1[dB1_1];
			dB2_1 = GammaTablePtr_1[dB2_1];
			dB3_1 = GammaTablePtr_1[dB3_1];			
		}

		if ( NULL != GammaTablePtr_2 )
		{
			dA1_2 = GammaTablePtr_2[dA1_2];
			dA2_2 = GammaTablePtr_2[dA2_2];
			dA3_2 = GammaTablePtr_2[dA3_2];
			dA4_2 = GammaTablePtr_2[dA4_2];
			dB1_2 = GammaTablePtr_2[dB1_2];
			dB2_2 = GammaTablePtr_2[dB2_2];
			dB3_2 = GammaTablePtr_2[dB3_2];			
		}

		if ( NULL != GammaTablePtr_3 )
		{
			dA1_3 = GammaTablePtr_3[dA1_3];
			dA2_3 = GammaTablePtr_3[dA2_3];
			dA3_3 = GammaTablePtr_3[dA3_3];
			dA4_3 = GammaTablePtr_3[dA4_3];
			dB1_3 = GammaTablePtr_3[dB1_3];
			dB2_3 = GammaTablePtr_3[dB2_3];
			dB3_3 = GammaTablePtr_3[dB3_3];			
		}

		if ( NULL != GammaTablePtr_4 )
		{
			dA1_4 = GammaTablePtr_4[dA1_4];
			dA2_4 = GammaTablePtr_4[dA2_4];
			dA3_4 = GammaTablePtr_4[dA3_4];
			dA4_4 = GammaTablePtr_4[dA4_4];
			dB1_4 = GammaTablePtr_4[dB1_4];
			dB2_4 = GammaTablePtr_4[dB2_4];
			dB3_4 = GammaTablePtr_4[dB3_4];			
		}

		if ( Calc4PhaseParamMask(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_1, MaskA_1, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dB1_1, dB2_1, dB3_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_1, MaskB_1) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_2, MaskA_2, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dB1_2, dB2_2, dB3_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_2, MaskB_2) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_3, MaskA_3, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dB1_3, dB2_3, dB3_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_3, MaskB_3) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_4, MaskA_4, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc21PhaseParamMask(dB1_4, dB2_4, dB3_4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_4, MaskB_4) == false )
		{	return false; }

		/*
		dT1_1 = PtrB1_1[i];	dT2_1 = PtrB2_1[i];	dT3_1 = PtrB3_1[i];	dT4_1 = PtrB4_1[i];
		dT1_2 = PtrB1_2[i];	dT2_2 = PtrB2_2[i];	dT3_2 = PtrB3_2[i];	dT4_2 = PtrB4_2[i];
		dT1_3 = PtrB1_3[i];	dT2_3 = PtrB2_3[i];	dT3_3 = PtrB3_3[i];	dT4_3 = PtrB4_3[i];
		dT1_4 = PtrB1_4[i];	dT2_4 = PtrB2_4[i];	dT3_4 = PtrB3_4[i];	dT4_4 = PtrB4_4[i];		

		Calc4PhaseParam(dT1_1, dT2_1, dT3_1, dT4_1, aT_1, bT_1, cT_1);
		Calc4PhaseParam(dT1_2, dT2_2, dT3_2, dT4_2, aT_2, bT_2, cT_2);
		Calc4PhaseParam(dT1_3, dT2_3, dT3_3, dT4_3, aT_3, bT_3, cT_3);
		Calc4PhaseParam(dT1_4, dT2_4, dT3_4, dT4_4, aT_4, bT_4, cT_4);
		*/		
#ifdef _DEBUG
		dT1_1 = PtrB1_1[i];	dT2_1 = PtrB2_1[i];	dT3_1 = PtrB3_1[i];	dT4_1 = PtrB4_1[i];
		dT1_2 = PtrB1_2[i];	dT2_2 = PtrB2_2[i];	dT3_2 = PtrB3_2[i];	dT4_2 = PtrB4_2[i];
		dT1_3 = PtrB1_3[i];	dT2_3 = PtrB2_3[i];	dT3_3 = PtrB3_3[i];	dT4_3 = PtrB4_3[i];
		dT1_4 = PtrB1_4[i];	dT2_4 = PtrB2_4[i];	dT3_4 = PtrB3_4[i];	dT4_4 = PtrB4_4[i];		

		Calc4PhaseParam(dT1_1, dT2_1, dT3_1, dT4_1, aT_1, bT_1, cT_1);
		Calc4PhaseParam(dT1_2, dT2_2, dT3_2, dT4_2, aT_2, bT_2, cT_2);
		Calc4PhaseParam(dT1_3, dT2_3, dT3_3, dT4_3, aT_3, bT_3, cT_3);
		Calc4PhaseParam(dT1_4, dT2_4, dT3_4, dT4_4, aT_4, bT_4, cT_4);

		if ( this->CalcArctangent(aT_1, bT_1, PhaseT_1) == false )//225 ms, 200ms-Inline
		{	return false;	}		
		if ( this->CalcArctangent(aT_2, bT_2, PhaseT_2) == false )//225 ms, 200ms-Inline
		{	return false;	}		
		if ( this->CalcArctangent(aT_3, bT_3, PhaseT_3) == false )//225 ms, 200ms-Inline
		{	return false;	}		
		if ( this->CalcArctangent(aT_4, bT_4, PhaseT_4) == false )//225 ms, 200ms-Inline
		{	return false;	}		
		int Dif_1 = abs(PhaseT_1-PhaseB_1);
		int Dif_2 = abs(PhaseT_2-PhaseB_2);
		int Dif_3 = abs(PhaseT_3-PhaseB_3);
		int Dif_4 = abs(PhaseT_4-PhaseB_4);
		const int DifMax=100;
		if ( Dif_1>DifMax || Dif_2>DifMax || Dif_3>DifMax || Dif_4>DifMax )
		{
			Dif_1 = Dif_1;
		}
#endif//_DEBUG		

		//雙週期相位合併		
		if ( PerA < PerB )
		{	
			PhaseM_1 = CombinePhasePeriod(CombinePeriodMode, PhaseA_1, PhaseB_1, dRatioA);
			PhaseM_2 = CombinePhasePeriod(CombinePeriodMode, PhaseA_2, PhaseB_2, dRatioA);
			PhaseM_3 = CombinePhasePeriod(CombinePeriodMode, PhaseA_3, PhaseB_3, dRatioA);
			PhaseM_4 = CombinePhasePeriod(CombinePeriodMode, PhaseA_4, PhaseB_4, dRatioA);			
		}
		else
		{
			PhaseM_1 = CombinePhasePeriod(CombinePeriodMode, PhaseB_1, PhaseA_1, dRatioA);//注意相位次序
			PhaseM_2 = CombinePhasePeriod(CombinePeriodMode, PhaseB_2, PhaseA_2, dRatioA);//注意相位次序			
			PhaseM_3 = CombinePhasePeriod(CombinePeriodMode, PhaseB_3, PhaseA_3, dRatioA);//注意相位次序
			PhaseM_4 = CombinePhasePeriod(CombinePeriodMode, PhaseB_4, PhaseA_4, dRatioA);//注意相位次序
		}			
		if ( NULL != BasePhasePtr_1 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_1[i], PhaseM_1);	}		
		if ( NULL != BasePhasePtr_2 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_2[i], PhaseM_2);	}
		if ( NULL != BasePhasePtr_3 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_3[i], PhaseM_3);	}
		if ( NULL != BasePhasePtr_4 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_4[i], PhaseM_4);	}

		Space_1 = PhaseM_1;
		Space_2 = PhaseM_2;
		Space_3 = PhaseM_3;
		Space_4 = PhaseM_4;

		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_1);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_2, HeightFactorPtr_2, HeightFactorPtr_2_2, Space_2);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_3, HeightFactorPtr_3, HeightFactorPtr_3_2, Space_3);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_4, HeightFactorPtr_4, HeightFactorPtr_4_2, Space_4);

		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_2, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_3, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_4, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);

		Mask_1 = CombinePhaseMask(MaskA_1, MaskB_1);
		Mask_2 = CombinePhaseMask(MaskA_2, MaskB_2);
		Mask_3 = CombinePhaseMask(MaskA_3, MaskB_3);
		Mask_4 = CombinePhaseMask(MaskA_4, MaskB_4);

		//Compare4OppositeGray(cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);//小週期
		if ( Compare4SpaceHeight(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M) == false ) 
		{	Merge4SpaceData(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M);	}
		MaskPtr[i] = Mask_M;		
		SpacePtr[i] = Space_M;

		if ( NULL != CastParam1.PtrMask ) { CastParam1.PtrMask[i] = Mask_1; }
		if ( NULL != CastParam1.PtrSpace ) { CastParam1.PtrSpace[i] = Space_1; }
		if ( NULL != CastParam2.PtrMask ) { CastParam2.PtrMask[i] = Mask_2; }
		if ( NULL != CastParam2.PtrSpace ) { CastParam2.PtrSpace[i] = Space_2; }
		if ( NULL != CastParam3.PtrMask ) { CastParam3.PtrMask[i] = Mask_3; }
		if ( NULL != CastParam3.PtrSpace ) { CastParam3.PtrSpace[i] = Space_3; }
		if ( NULL != CastParam4.PtrMask ) { CastParam4.PtrMask[i] = Mask_4; }
		if ( NULL != CastParam4.PtrSpace ) { CastParam4.PtrSpace[i] = Space_4; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace3_II_MP_Fn_4_3Step(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, const TCastParam &CastParam2, const TCastParam &CastParam3, const TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4+3投光影像轉成高度資料-平行計算
{
	const int BufferSize = (int)(ImageStep*ImageH);
	if ( index<0 || index>=BufferSize ) { return false; }

	int   nPhase = 0;
	float phase = 0.0f;		
	int   Phase1 = 0;
	int   Phase2 = 0;	
	int   PhaseM_1 = 0;
	int   PhaseM_2 = 0;
	int   PhaseM_3 = 0;
	int   PhaseM_4 = 0;	
	float Space_1=0.0f,Space_2=0.0f,Space_3=0.0f,Space_4=0.0f, Space_M=0.0f;
	MASK_DATA  Mask_1=0;
	MASK_DATA  Mask_2=0;
	MASK_DATA  Mask_3=0;
	MASK_DATA  Mask_4=0;
	MASK_DATA  Mask_M=0;
	MASK_DATA  MaskA_1=0, MaskB_1=0;
	MASK_DATA  MaskA_2=0, MaskB_2=0;
	MASK_DATA  MaskA_3=0, MaskB_3=0;
	MASK_DATA  MaskA_4=0, MaskB_4=0;

	IMAGE_DATA *PtrA1_1=NULL, *PtrA2_1=NULL, *PtrA3_1=NULL, *PtrA4_1=NULL;
	IMAGE_DATA *PtrB1_1=NULL, *PtrB2_1=NULL, *PtrB3_1=NULL, *PtrB4_1=NULL;
	IMAGE_DATA *PtrA1_2=NULL, *PtrA2_2=NULL, *PtrA3_2=NULL, *PtrA4_2=NULL;
	IMAGE_DATA *PtrB1_2=NULL, *PtrB2_2=NULL, *PtrB3_2=NULL, *PtrB4_2=NULL;
	IMAGE_DATA *PtrA1_3=NULL, *PtrA2_3=NULL, *PtrA3_3=NULL, *PtrA4_3=NULL;
	IMAGE_DATA *PtrB1_3=NULL, *PtrB2_3=NULL, *PtrB3_3=NULL, *PtrB4_3=NULL;
	IMAGE_DATA *PtrA1_4=NULL, *PtrA2_4=NULL, *PtrA3_4=NULL, *PtrA4_4=NULL;
	IMAGE_DATA *PtrB1_4=NULL, *PtrB2_4=NULL, *PtrB3_4=NULL, *PtrB4_4=NULL;
	PHASE_DATA *BasePhasePtr_1=NULL, *BasePhasePtr_2=NULL,*BasePhasePtr_3=NULL,*BasePhasePtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1=NULL, *HeightFactorPtr_2=NULL, *HeightFactorPtr_3=NULL, *HeightFactorPtr_4=NULL;
	SPACE_DATA *HeightFactorPtr_1_2=NULL, *HeightFactorPtr_2_2=NULL, *HeightFactorPtr_3_2=NULL, *HeightFactorPtr_4_2=NULL;
	double     *HeightFactor0_1 = NULL, *HeightFactor0_2 = NULL, *HeightFactor0_3 = NULL, *HeightFactor0_4 = NULL;
	double     *HeightFactor1_1 = NULL, *HeightFactor1_2 = NULL, *HeightFactor1_3 = NULL, *HeightFactor1_4 = NULL;
	double     *HeightFactor2_1 = NULL, *HeightFactor2_2 = NULL, *HeightFactor2_3 = NULL, *HeightFactor2_4 = NULL;
	unsigned char *GammaTablePtr_1=NULL, *GammaTablePtr_2=NULL, *GammaTablePtr_3=NULL, *GammaTablePtr_4=NULL;

	PHASE_DATA PhaseA_1=0, PhaseB_1=0;
	PHASE_DATA PhaseA_2=0, PhaseB_2=0;
	PHASE_DATA PhaseA_3=0, PhaseB_3=0;
	PHASE_DATA PhaseA_4=0, PhaseB_4=0;
	PHASE_DATA dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	PHASE_DATA dB1_1=0, dB2_1=0, dB3_1=0;
	PHASE_DATA dA1_2=0, dA2_2=0, dA3_2=0, dA4_2=0;
	PHASE_DATA dB1_2=0, dB2_2=0, dB3_2=0;
	PHASE_DATA dA1_3=0, dA2_3=0, dA3_3=0, dA4_3=0;
	PHASE_DATA dB1_3=0, dB2_3=0, dB3_3=0;
	PHASE_DATA dA1_4=0, dA2_4=0, dA3_4=0, dA4_4=0;
	PHASE_DATA dB1_4=0, dB2_4=0, dB3_4=0;	

	//#ifdef _DEBUG
	PHASE_DATA cT_1=0;
	PHASE_DATA cT_2=0;
	PHASE_DATA cT_3=0;
	PHASE_DATA cT_4=0;
	int   aT_1=0, bT_1=0;
	int   aT_2=0, bT_2=0;
	int   aT_3=0, bT_3=0;
	int   aT_4=0, bT_4=0;	
	PHASE_DATA PhaseT_1=0;
	PHASE_DATA PhaseT_2=0;
	PHASE_DATA PhaseT_3=0;
	PHASE_DATA PhaseT_4=0;
	PHASE_DATA dT1_1=0, dT2_1=0, dT3_1=0, dT4_1=0;
	PHASE_DATA dT1_2=0, dT2_2=0, dT3_2=0, dT4_2=0;
	PHASE_DATA dT1_3=0, dT2_3=0, dT3_3=0, dT4_3=0;
	PHASE_DATA dT1_4=0, dT2_4=0, dT3_4=0, dT4_4=0;
	//#endif//_DEBUG

	int    ImageX=0, ImageY=0;	
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int   PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();	
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	

	const double PerA = CastParam1.PerA;
	const double PerB = CastParam1.PerB;
	const double PerD = Calc2PhaseNewPeriode(PerA, PerB);	
	const float  ExpTimeRatio_1 = (1.0f*CastParam1.ExpTimeB)/CastParam1.ExpTimeA;
	const float  ExpTimeRatio_2 = (1.0f*CastParam2.ExpTimeB)/CastParam2.ExpTimeA;
	const float  ExpTimeRatio_3 = (1.0f*CastParam3.ExpTimeB)/CastParam3.ExpTimeA;
	const float  ExpTimeRatio_4 = (1.0f*CastParam4.ExpTimeB)/CastParam4.ExpTimeA;

	PtrA1_1 = CastParam1.PtrA1;	PtrA2_1 = CastParam1.PtrA2;	PtrA3_1 = CastParam1.PtrA3;	PtrA4_1 = CastParam1.PtrA4;
	PtrB1_1 = CastParam1.PtrB1;	PtrB2_1 = CastParam1.PtrB2;	PtrB3_1 = CastParam1.PtrB3;	PtrB4_1 = CastParam1.PtrB4;
	PtrA1_2 = CastParam2.PtrA1;	PtrA2_2 = CastParam2.PtrA2;	PtrA3_2 = CastParam2.PtrA3;	PtrA4_2 = CastParam2.PtrA4;
	PtrB1_2 = CastParam2.PtrB1;	PtrB2_2 = CastParam2.PtrB2;	PtrB3_2 = CastParam2.PtrB3;	PtrB4_2 = CastParam2.PtrB4;
	PtrA1_3 = CastParam3.PtrA1;	PtrA2_3 = CastParam3.PtrA2;	PtrA3_3 = CastParam3.PtrA3;	PtrA4_3 = CastParam3.PtrA4;
	PtrB1_3 = CastParam3.PtrB1;	PtrB2_3 = CastParam3.PtrB2;	PtrB3_3 = CastParam3.PtrB3;	PtrB4_3 = CastParam3.PtrB4;
	PtrA1_4 = CastParam4.PtrA1;	PtrA2_4 = CastParam4.PtrA2;	PtrA3_4 = CastParam4.PtrA3;	PtrA4_4 = CastParam4.PtrA4;
	PtrB1_4 = CastParam4.PtrB1;	PtrB2_4 = CastParam4.PtrB2;	PtrB3_4 = CastParam4.PtrB3;	PtrB4_4 = CastParam4.PtrB4;
	BasePhasePtr_1 = CastParam1.ZeroPhasePtr;
	BasePhasePtr_2 = CastParam2.ZeroPhasePtr;
	BasePhasePtr_3 = CastParam3.ZeroPhasePtr;
	BasePhasePtr_4 = CastParam4.ZeroPhasePtr;
	HeightFactorPtr_1 = CastParam1.HeightFactorPtr;
	HeightFactorPtr_2 = CastParam2.HeightFactorPtr;
	HeightFactorPtr_3 = CastParam3.HeightFactorPtr;
	HeightFactorPtr_4 = CastParam4.HeightFactorPtr;
	HeightFactor0_1 = (double*)CastParam1.HeightFactor0;
	HeightFactor1_1 = (double*)CastParam1.HeightFactor1;
	HeightFactor2_1 = (double*)CastParam1.HeightFactor2;
	HeightFactor0_2 = (double*)CastParam2.HeightFactor0;
	HeightFactor1_2 = (double*)CastParam2.HeightFactor1;
	HeightFactor2_2 = (double*)CastParam2.HeightFactor2;
	HeightFactor0_3 = (double*)CastParam3.HeightFactor0;
	HeightFactor1_3 = (double*)CastParam3.HeightFactor1;
	HeightFactor2_3 = (double*)CastParam3.HeightFactor2;
	HeightFactor0_4 = (double*)CastParam4.HeightFactor0;
	HeightFactor1_4 = (double*)CastParam4.HeightFactor1;
	HeightFactor2_4 = (double*)CastParam4.HeightFactor2;
	GammaTablePtr_1=CastParam1.GammaTablePtr;
	GammaTablePtr_2=CastParam2.GammaTablePtr;
	GammaTablePtr_3=CastParam3.GammaTablePtr;
	GammaTablePtr_4=CastParam4.GammaTablePtr;	

	//BasePhasePtr_1 = NULL;

	double dRatioA=1.0;
	double dRatioB=1.0;	
	if ( PerB > PerA )//PB 為主
	{	
		dRatioA = PerB/PerA;
		dRatioB = 1;
	}
	else //PA為主 
	{	
		dRatioA = 1;
		dRatioB = PerA/PerB;
	}
	CalcCombinePhasePeriodRatio(CombinePeriodMode, PerA, PerB, dRatioA);

	const int i = index;
	const int x = i%ImageStep;
	const int y = i/ImageStep;
	//if ( 9491958 == index )
	//{	index = index; }
	{
		dA1_1 = PtrA1_1[i];	dA2_1 = PtrA2_1[i];	dA3_1 = PtrA3_1[i];	dA4_1 = PtrA4_1[i];
		dB1_1 = PtrB1_1[i];	dB3_1 = PtrB3_1[i];
		dA1_2 = PtrA1_2[i];	dA2_2 = PtrA2_2[i];	dA3_2 = PtrA3_2[i];	dA4_2 = PtrA4_2[i];
		dB1_2 = PtrB1_2[i];	dB3_2 = PtrB3_2[i];
		dA1_3 = PtrA1_3[i];	dA2_3 = PtrA2_3[i];	dA3_3 = PtrA3_3[i];	dA4_3 = PtrA4_3[i];
		dB1_3 = PtrB1_3[i];	dB3_3 = PtrB3_3[i];
		dA1_4 = PtrA1_4[i];	dA2_4 = PtrA2_4[i];	dA3_4 = PtrA3_4[i];	dA4_4 = PtrA4_4[i];
		dB1_4 = PtrB1_4[i];	dB3_4 = PtrB3_4[i];		

		//3Step 0, 120, 240
		dB1_1 = PtrB1_1[i];	dB2_1 = PtrB2_1[i]; dB3_1 = PtrB3_1[i];
		dB1_2 = PtrB1_2[i];	dB2_2 = PtrB2_2[i];	dB3_2 = PtrB3_2[i];
		dB1_3 = PtrB1_3[i];	dB2_3 = PtrB2_3[i];	dB3_3 = PtrB3_3[i];
		dB1_4 = PtrB1_4[i];	dB2_4 = PtrB2_4[i];	dB3_4 = PtrB3_4[i];			

		if ( NULL != GammaTablePtr_1 )
		{
			dA1_1 = GammaTablePtr_1[dA1_1];
			dA2_1 = GammaTablePtr_1[dA2_1];
			dA3_1 = GammaTablePtr_1[dA3_1];
			dA4_1 = GammaTablePtr_1[dA4_1];
			dB1_1 = GammaTablePtr_1[dB1_1];
			dB2_1 = GammaTablePtr_1[dB2_1];
			dB3_1 = GammaTablePtr_1[dB3_1];			
		}

		if ( NULL != GammaTablePtr_2 )
		{
			dA1_2 = GammaTablePtr_2[dA1_2];
			dA2_2 = GammaTablePtr_2[dA2_2];
			dA3_2 = GammaTablePtr_2[dA3_2];
			dA4_2 = GammaTablePtr_2[dA4_2];
			dB1_2 = GammaTablePtr_2[dB1_2];
			dB2_2 = GammaTablePtr_2[dB2_2];
			dB3_2 = GammaTablePtr_2[dB3_2];			
		}

		if ( NULL != GammaTablePtr_3 )
		{
			dA1_3 = GammaTablePtr_3[dA1_3];
			dA2_3 = GammaTablePtr_3[dA2_3];
			dA3_3 = GammaTablePtr_3[dA3_3];
			dA4_3 = GammaTablePtr_3[dA4_3];
			dB1_3 = GammaTablePtr_3[dB1_3];
			dB2_3 = GammaTablePtr_3[dB2_3];
			dB3_3 = GammaTablePtr_3[dB3_3];			
		}

		if ( NULL != GammaTablePtr_4 )
		{
			dA1_4 = GammaTablePtr_4[dA1_4];
			dA2_4 = GammaTablePtr_4[dA2_4];
			dA3_4 = GammaTablePtr_4[dA3_4];
			dA4_4 = GammaTablePtr_4[dA4_4];
			dB1_4 = GammaTablePtr_4[dB1_4];
			dB2_4 = GammaTablePtr_4[dB2_4];
			dB3_4 = GammaTablePtr_4[dB3_4];			
		}

		if ( Calc4PhaseParamMask(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_1, MaskA_1, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc3PhaseParamMask(dB1_1, dB2_1, dB3_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_1, MaskB_1) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_2, MaskA_2, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc3PhaseParamMask(dB1_2, dB2_2, dB3_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_2, MaskB_2) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_3, MaskA_3, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc3PhaseParamMask(dB1_3, dB2_3, dB3_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_3, MaskB_3) == false )
		{	return false; }
		if ( Calc4PhaseParamMask(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, PhaseA_4, MaskA_4, PhaseNoiseDefMode) == false )
		{	return false; }
		if ( Calc3PhaseParamMask(dB1_4, dB2_4, dB3_4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, PhaseB_4, MaskB_4) == false )
		{	return false; }

		/*
		dT1_1 = PtrB1_1[i];	dT2_1 = PtrB2_1[i];	dT3_1 = PtrB3_1[i];	dT4_1 = PtrB4_1[i];
		dT1_2 = PtrB1_2[i];	dT2_2 = PtrB2_2[i];	dT3_2 = PtrB3_2[i];	dT4_2 = PtrB4_2[i];
		dT1_3 = PtrB1_3[i];	dT2_3 = PtrB2_3[i];	dT3_3 = PtrB3_3[i];	dT4_3 = PtrB4_3[i];
		dT1_4 = PtrB1_4[i];	dT2_4 = PtrB2_4[i];	dT3_4 = PtrB3_4[i];	dT4_4 = PtrB4_4[i];		

		Calc4PhaseParam(dT1_1, dT2_1, dT3_1, dT4_1, aT_1, bT_1, cT_1);
		Calc4PhaseParam(dT1_2, dT2_2, dT3_2, dT4_2, aT_2, bT_2, cT_2);
		Calc4PhaseParam(dT1_3, dT2_3, dT3_3, dT4_3, aT_3, bT_3, cT_3);
		Calc4PhaseParam(dT1_4, dT2_4, dT3_4, dT4_4, aT_4, bT_4, cT_4);
		*/		

#ifdef _DEBUG
		dT1_1 = PtrB1_1[i];	dT2_1 = PtrB2_1[i];	dT3_1 = PtrB3_1[i];	dT4_1 = PtrB4_1[i];
		dT1_2 = PtrB1_2[i];	dT2_2 = PtrB2_2[i];	dT3_2 = PtrB3_2[i];	dT4_2 = PtrB4_2[i];
		dT1_3 = PtrB1_3[i];	dT2_3 = PtrB2_3[i];	dT3_3 = PtrB3_3[i];	dT4_3 = PtrB4_3[i];
		dT1_4 = PtrB1_4[i];	dT2_4 = PtrB2_4[i];	dT3_4 = PtrB3_4[i];	dT4_4 = PtrB4_4[i];		

		Calc4PhaseParam(dT1_1, dT2_1, dT3_1, dT4_1, aT_1, bT_1, cT_1);
		Calc4PhaseParam(dT1_2, dT2_2, dT3_2, dT4_2, aT_2, bT_2, cT_2);
		Calc4PhaseParam(dT1_3, dT2_3, dT3_3, dT4_3, aT_3, bT_3, cT_3);
		Calc4PhaseParam(dT1_4, dT2_4, dT3_4, dT4_4, aT_4, bT_4, cT_4);

		if ( this->CalcArctangent(aT_1, bT_1, PhaseT_1) == false )//225 ms, 200ms-Inline
		{	return false;	}		
		if ( this->CalcArctangent(aT_2, bT_2, PhaseT_2) == false )//225 ms, 200ms-Inline
		{	return false;	}		
		if ( this->CalcArctangent(aT_3, bT_3, PhaseT_3) == false )//225 ms, 200ms-Inline
		{	return false;	}		
		if ( this->CalcArctangent(aT_4, bT_4, PhaseT_4) == false )//225 ms, 200ms-Inline
		{	return false;	}		
		int Dif_1 = abs(PhaseT_1-PhaseB_1);
		int Dif_2 = abs(PhaseT_2-PhaseB_2);
		int Dif_3 = abs(PhaseT_3-PhaseB_3);
		int Dif_4 = abs(PhaseT_4-PhaseB_4);
		const int DifMax=100;
		if ( Dif_1>DifMax || Dif_2>DifMax || Dif_3>DifMax || Dif_4>DifMax )
		{
			Dif_1 = Dif_1;
		}
#endif//_DEBUG		

		//雙週期相位合併		
		if ( PerA < PerB )
		{	
			PhaseM_1 = CombinePhasePeriod(CombinePeriodMode, PhaseA_1, PhaseB_1, dRatioA);
			PhaseM_2 = CombinePhasePeriod(CombinePeriodMode, PhaseA_2, PhaseB_2, dRatioA);
			PhaseM_3 = CombinePhasePeriod(CombinePeriodMode, PhaseA_3, PhaseB_3, dRatioA);
			PhaseM_4 = CombinePhasePeriod(CombinePeriodMode, PhaseA_4, PhaseB_4, dRatioA);			
		}
		else
		{
			PhaseM_1 = CombinePhasePeriod(CombinePeriodMode, PhaseB_1, PhaseA_1, dRatioA);//注意相位次序
			PhaseM_2 = CombinePhasePeriod(CombinePeriodMode, PhaseB_2, PhaseA_2, dRatioA);//注意相位次序			
			PhaseM_3 = CombinePhasePeriod(CombinePeriodMode, PhaseB_3, PhaseA_3, dRatioA);//注意相位次序
			PhaseM_4 = CombinePhasePeriod(CombinePeriodMode, PhaseB_4, PhaseA_4, dRatioA);//注意相位次序
		}

		//PhaseM_1 = PhaseB_1;
		//PhaseM_2 = PhaseB_2;
		//PhaseM_3 = PhaseB_3;
		//PhaseM_4 = PhaseB_4;

		if ( NULL != BasePhasePtr_1 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_1[i], PhaseM_1);	}		
		if ( NULL != BasePhasePtr_2 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_2[i], PhaseM_2);	}
		if ( NULL != BasePhasePtr_3 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_3[i], PhaseM_3);	}
		if ( NULL != BasePhasePtr_4 )//扣除相平面
		{	DeductBasePhase(BasePhasePtr_4[i], PhaseM_4);	}		

		Space_1 = PhaseM_1;
		Space_2 = PhaseM_2;
		Space_3 = PhaseM_3;
		Space_4 = PhaseM_4;

		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_1, HeightFactorPtr_1, HeightFactorPtr_1_2, Space_1);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_2, HeightFactorPtr_2, HeightFactorPtr_2_2, Space_2);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_3, HeightFactorPtr_3, HeightFactorPtr_3_2, Space_3);
		ConvertPhaseToSpace(PhaseConvertHeightMode, i, Space_4, HeightFactorPtr_4, HeightFactorPtr_4_2, Space_4);

		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_2, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_3, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		ConvertPhaseToSpaceMapFunc(PhaseConvertHeightMode, x, y, PhaseM_4, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);

		Mask_1 = CombinePhaseMask(MaskA_1, MaskB_1);
		Mask_2 = CombinePhaseMask(MaskA_2, MaskB_2);
		Mask_3 = CombinePhaseMask(MaskA_3, MaskB_3);
		Mask_4 = CombinePhaseMask(MaskA_4, MaskB_4);

		//Compare4OppositeGray(cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);//小週期
		if ( Compare4SpaceHeight(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M) == false ) 
		{	Merge4SpaceData(Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, Mask_M, Space_M);	}
		MaskPtr[i] = Mask_M;		
		SpacePtr[i] = Space_M;

		//MaskPtr[i] = Mask_1;		
		//SpacePtr[i] = PhaseM_1;

		if ( NULL != CastParam1.PtrMask ) { CastParam1.PtrMask[i] = Mask_1; }
		if ( NULL != CastParam1.PtrSpace ) { CastParam1.PtrSpace[i] = Space_1; }
		if ( NULL != CastParam2.PtrMask ) { CastParam2.PtrMask[i] = Mask_2; }
		if ( NULL != CastParam2.PtrSpace ) { CastParam2.PtrSpace[i] = Space_2; }
		if ( NULL != CastParam3.PtrMask ) { CastParam3.PtrMask[i] = Mask_3; }
		if ( NULL != CastParam3.PtrSpace ) { CastParam3.PtrSpace[i] = Space_3; }
		if ( NULL != CastParam4.PtrMask ) { CastParam4.PtrMask[i] = Mask_4; }
		if ( NULL != CastParam4.PtrSpace ) { CastParam4.PtrSpace[i] = Space_4; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace2Exp(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam1, TCastParam &CastParam2, TCastParam &CastParam3, TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, bool bOpenMP, MASK_PTR &MaskPtr, SPACE_PTR &SpacePtr)//4投光影像轉成高度資料
{
	const char fnName[] = "CImageAPI::PatternCast4ToSpace2Exp";
	if ( CheckCastParamExp2(CastParam1) == false )
	{	return false; }		
	if ( CheckCastParamExp2(CastParam2) == false )
	{	return false; }	
	if ( CheckCastParamExp2(CastParam3) == false )
	{	return false; }		
	if ( CheckCastParamExp2(CastParam4) == false )
	{	return false; }	
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam1) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam2) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam3) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam4) == false )
	{	return false; }

	JetMemory.free_func(MaskPtr);
	JetMemory.free_func(SpacePtr);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false ||
		JetMemory.alloc_func(BufferSize, SpacePtr, fnName, "SpacePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(SpacePtr);
		return false;
	}
	//::memset(MaskPtr, 0x00, sizeof(MASK_DATA)*BufferSize);
	//::memset(SpacePtr, 0x00, sizeof(SPACE_DATA)*BufferSize);
	if ( PatternCast4ToSpace2Exp3(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, bOpenMP, MaskPtr, SpacePtr) == false )
	{
		JetMemory.free_func(MaskPtr);
		JetMemory.free_func(SpacePtr);
		return false;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace2Exp3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam1, TCastParam &CastParam2, TCastParam &CastParam3, TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, bool bOpenMP, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料
{	
	bool IsOK = false;		
	//IsOK =  PatternCast4ToSpace2Exp3_I(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, bOpenMP, MaskPtr, SpacePtr);
	IsOK =  PatternCast4ToSpace2Exp3_II(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, bOpenMP, MaskPtr, SpacePtr);
	if ( false == IsOK )
	{	return false; }	
	return true;
	//以下是驗證Cuda與Cpu計算的誤差
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	//if ( SysParam.m_CudaFnEnabled==FN_DISABLE || false==IsCudaDeviceUse )
	const char fnName[] = "CImageAPI::PatternCast4ToSpace2Exp3";
	CString str;
	CString Folder = AOIDataCollect.GetAOITempDirectory();	
	str.Format(_T("%s\\%s"), Folder, _T("CpuMask.PNG"));
	SaveImage(str, ImageW, ImageH, ImageStep, 8, MaskPtr, true);	

	size_t   i=0;
	MASK_PTR MaskPtrTmp = NULL;
	SPACE_PTR SpacePtrTmp = NULL;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, MaskPtrTmp, fnName, "MaskPtrTmp") == false ||
		JetMemory.alloc_func(BufferSize, SpacePtrTmp, fnName, "SpacePtrTmp") == false )
	{
		JetMemory.free_func(MaskPtrTmp);
		JetMemory.free_func(SpacePtrTmp);
		return false;
	}
	::memset(MaskPtrTmp, 0x00, sizeof(MASK_DATA)*BufferSize);
	::memset(SpacePtrTmp, 0x00, sizeof(SPACE_DATA)*BufferSize);
	const int CudaBlockNumber = SysParam.m_CudaBlockNumber;
	const int CudaThreadNumber = SysParam.m_CudaThreadNumber;
	CudaFunc.CudaSolveSpace4Frames2Period4Cast2Exp(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtrTmp, SpacePtrTmp, CudaThreadNumber, CudaBlockNumber);
	//CudaFunc.CudaSolveSpace4Frames2Period3Cast2Exp(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, NoiseParam, MaskPtrTmp, SpacePtrTmp, CudaThreadNumber, CudaBlockNumber);
	//PatternCast4ToSpace2Exp3_I(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, bOpenMP, MaskPtrTmp, SpacePtrTmp);
	str.Format(_T("%s\\%s"), Folder, _T("CudaMask.PNG"));
	SaveImage(str, ImageW, ImageH, ImageStep, 8, MaskPtrTmp, true);

	float  ErrSpace=0.0f;
	float  ErrSpaceMax=0.0f;
	size_t ErrMaskCnt=0;
	size_t ErrSpaceCnt=0;
	for ( i=0; i<BufferSize; i++ )
	{
		if ( MaskPtr[i] != MaskPtrTmp[i] )
		{	ErrMaskCnt ++; }

		ErrSpace = SpacePtr[i]-SpacePtrTmp[i];
		ErrSpace = ::fabs(ErrSpace);		
		if ( ErrSpace > 1.0 )
		{	ErrSpaceCnt ++; }

		if ( ErrSpaceMax < ErrSpace ) 
		{	ErrSpaceMax = ErrSpace; }
	}
	//ErrSpaceMax < 0.5 um
	JetMemory.free_func(MaskPtrTmp);
	JetMemory.free_func(SpacePtrTmp);
	//*/	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace2Exp3_I(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam1, TCastParam &CastParam2, TCastParam &CastParam3, TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, bool bOpenMP, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料
{
#ifdef CUDA_USE
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if ( SysParam.m_CudaFnEnabled==FN_ENABLE && true==IsCudaDeviceUse )
	{
		const int CudaBlockNumber = SysParam.m_CudaBlockNumber;
		const int CudaThreadNumber = SysParam.m_CudaThreadNumber;
		if ( CudaFunc.CudaSolveSpace4Frames2Period4Cast2Exp(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr, CudaThreadNumber, CudaBlockNumber) == false )
		{
			SetErrorString(CudaFunc.GetErrorString());
			return false;
		}
		return true;
	}	
#endif//CUDA_USE

	const char fnName[] = "CImageAPI::PatternCast4ToSpace2Exp3_I";
	if ( CheckCastParamExp2(CastParam1) == false )
	{	return false; }		
	if ( CheckCastParamExp2(CastParam2) == false )
	{	return false; }	
	if ( CheckCastParamExp2(CastParam3) == false )
	{	return false; }		
	if ( CheckCastParamExp2(CastParam4) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam1) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam2) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam3) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam4) == false )
	{	return false; }

	MASK_PTR MaskPtr1 = NULL;
	MASK_PTR MaskPtr2 = NULL;
	MASK_PTR MaskPtr3 = NULL;
	MASK_PTR MaskPtr4 = NULL;
	SPACE_PTR SpacePtr1 = NULL;
	SPACE_PTR SpacePtr2 = NULL;	
	SPACE_PTR SpacePtr3 = NULL;	
	SPACE_PTR SpacePtr4 = NULL;	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);	
	if ( JetMemory.alloc_func(BufferSize, MaskPtr1, fnName, "MaskPtr1") == false ||
		JetMemory.alloc_func(BufferSize, MaskPtr2, fnName, "MaskPtr2") == false ||
		JetMemory.alloc_func(BufferSize, MaskPtr3, fnName, "MaskPtr3") == false ||
		JetMemory.alloc_func(BufferSize, MaskPtr4, fnName, "MaskPtr4") == false ||
		JetMemory.alloc_func(BufferSize, SpacePtr1, fnName, "SpacePtr1") == false ||
		JetMemory.alloc_func(BufferSize, SpacePtr2, fnName, "SpacePtr2") == false ||
		JetMemory.alloc_func(BufferSize, SpacePtr3, fnName, "SpacePtr3") == false ||
		JetMemory.alloc_func(BufferSize, SpacePtr4, fnName, "SpacePtr4") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(MaskPtr1);
		JetMemory.free_func(MaskPtr2);
		JetMemory.free_func(MaskPtr3);
		JetMemory.free_func(MaskPtr4);
		JetMemory.free_func(SpacePtr1);
		JetMemory.free_func(SpacePtr2);
		JetMemory.free_func(SpacePtr3);
		JetMemory.free_func(SpacePtr4);
		return false;
	}

	if ( PatternCast1ToSpace2Exp3(ImageW, ImageH, ImageStep, CastParam1, NoiseParam, bOpenMP, MaskPtr1, SpacePtr1) == false ||
		PatternCast1ToSpace2Exp3(ImageW, ImageH, ImageStep, CastParam2, NoiseParam, bOpenMP, MaskPtr2, SpacePtr2) == false ||
		PatternCast1ToSpace2Exp3(ImageW, ImageH, ImageStep, CastParam3, NoiseParam, bOpenMP, MaskPtr3, SpacePtr3) == false ||
		PatternCast1ToSpace2Exp3(ImageW, ImageH, ImageStep, CastParam4, NoiseParam, bOpenMP, MaskPtr4, SpacePtr4) == false )
	{
		JetMemory.free_func(MaskPtr1);
		JetMemory.free_func(MaskPtr2);
		JetMemory.free_func(MaskPtr3);
		JetMemory.free_func(MaskPtr4);
		JetMemory.free_func(SpacePtr1);
		JetMemory.free_func(SpacePtr2);
		JetMemory.free_func(SpacePtr3);
		JetMemory.free_func(SpacePtr4);
		return false;
	}

	if ( Merge4SpaceImage3(ImageW, ImageH, ImageStep, SpacePtr1, MaskPtr1, SpacePtr2, MaskPtr2, SpacePtr3, MaskPtr3, SpacePtr4, MaskPtr4, bOpenMP, SpacePtr, MaskPtr) == false )
	{
		JetMemory.free_func(MaskPtr1);
		JetMemory.free_func(MaskPtr2);
		JetMemory.free_func(MaskPtr3);
		JetMemory.free_func(MaskPtr4);
		JetMemory.free_func(SpacePtr1);
		JetMemory.free_func(SpacePtr2);
		JetMemory.free_func(SpacePtr3);
		JetMemory.free_func(SpacePtr4);
		return false;
	}	
	JetMemory.free_func(MaskPtr1);
	JetMemory.free_func(MaskPtr2);
	JetMemory.free_func(MaskPtr3);
	JetMemory.free_func(MaskPtr4);
	JetMemory.free_func(SpacePtr1);
	JetMemory.free_func(SpacePtr2);
	JetMemory.free_func(SpacePtr3);
	JetMemory.free_func(SpacePtr4);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace2Exp3_II(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam1, TCastParam &CastParam2, TCastParam &CastParam3, TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, bool bOpenMP, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料
{
#ifdef CUDA_USE
	const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	if ( SysParam.m_CudaFnEnabled==FN_ENABLE && true==IsCudaDeviceUse )
	{
		const int CudaBlockNumber = SysParam.m_CudaBlockNumber;
		const int CudaThreadNumber = SysParam.m_CudaThreadNumber;
		if ( CudaFunc.CudaSolveSpace4Frames2Period4Cast2Exp(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr, CudaThreadNumber, CudaBlockNumber) == false )
		{
			SetErrorString(CudaFunc.GetErrorString());
			return false;
		}
		return true;
	}	
#endif//CUDA_USE

	bool IsOK = true;	
	const int nImageSize = (ImageW)*(ImageH);
	const bool OpenMPUsed = AOIDataCollect.CheckOpenMPUsed_CalcPhase(nImageSize);
	if ( false == OpenMPUsed )
	{	bOpenMP = false; }
	if ( true == bOpenMP )
	{	IsOK = PatternCast4ToSpace2Exp3_II_MP(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);	}
	else
	{	IsOK = PatternCast4ToSpace2Exp3_II_SP(ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);	}
	if ( false == IsOK )
	{	return false; }
	if ( SysParam.m_SpaceNoiseMultiCastPatchSize > 0 ) 
	{	IsOK = Merge4SpaceImage3(ImageW, ImageH, ImageStep, CastParam1.PtrSpace, CastParam1.PtrMask, CastParam2.PtrSpace, CastParam2.PtrMask, CastParam3.PtrSpace, CastParam3.PtrMask, CastParam4.PtrSpace, CastParam4.PtrMask, bOpenMP, SpacePtr, MaskPtr);	}
	return IsOK;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace2Exp3_II_SP(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam1, TCastParam &CastParam2, TCastParam &CastParam3, TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料-序列計算
{
	if ( CheckCastParamExp2(CastParam1) == false )
	{	return false; }		
	if ( CheckCastParamExp2(CastParam2) == false )
	{	return false; }	
	if ( CheckCastParamExp2(CastParam3) == false )
	{	return false; }		
	if ( CheckCastParamExp2(CastParam4) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam1) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam2) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam3) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam4) == false )
	{	return false; }	
	//if ( 16!=CastParam1.ImageCount || 16!=CastParam2.ImageCount || 16!=CastParam3.ImageCount || 16!=CastParam4.ImageCount)
	//{	return false; }	

	int           i=0;
	int           ImageX=0, ImageY=0;		
	unsigned char GammaTable_1[256];
	unsigned char GammaTable_2[256];
	unsigned char GammaTable_3[256];
	unsigned char GammaTable_4[256];	
	const int     BufferSize = (int)(ImageStep*ImageH);
	float         Gamma_1=1.0f, Gamma_2=1.0f, Gamma_3=1.0f, Gamma_4=1.0f;
	const bool    bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();

	Gamma_1 = CastParam1.Gamma;
	Gamma_2 = CastParam2.Gamma;
	Gamma_3 = CastParam3.Gamma;
	Gamma_4 = CastParam4.Gamma;	
	if ( true == bUseGamma )
	{	
		BuildGammaLookUpTable(Gamma_1, GammaTable_1); 
		BuildGammaLookUpTable(Gamma_2, GammaTable_2); 
		BuildGammaLookUpTable(Gamma_3, GammaTable_3); 
		BuildGammaLookUpTable(Gamma_4, GammaTable_4); 
		CastParam1.GammaTablePtr = GammaTable_1;
		CastParam2.GammaTablePtr = GammaTable_2;
		CastParam3.GammaTablePtr = GammaTable_3;
		CastParam4.GammaTablePtr = GammaTable_4;
	}
	else
	{
		CastParam1.GammaTablePtr = NULL;
		CastParam2.GammaTablePtr = NULL;
		CastParam3.GammaTablePtr = NULL;
		CastParam4.GammaTablePtr = NULL;
	}	

	std::vector<unsigned char> CodeMap3;
	std::vector<unsigned char> CodeMap4;
	std::vector<unsigned char> CodeMap5;
	std::vector<unsigned char> CodeMap6;
	BuildGrayCodeMapTable(3, CodeMap3);
	BuildGrayCodeMapTable(4, CodeMap4);
	BuildGrayCodeMapTable(5, CodeMap5);
	BuildGrayCodeMapTable(6, CodeMap6);
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam1) == false )
	{	return false; }
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam2) == false )
	{	return false; }
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam3) == false )
	{	return false; }
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam4) == false )
	{	return false; }

	for ( i=0; i<BufferSize; i++ )
	{			
#ifdef _DEBUG
		ImageX = i%ImageStep;
		ImageY = i/ImageStep;
		if ( 2240==ImageX && 584==ImageY )
		{	i = i; }
#endif//ImageX=0, ImageY=0;
		//20190530
		//if ( 772687 == i )//Compare JET6500
		//{	i = 772687;	}		
		if ( PatternCast4ToSpace2Exp3_II_MP_Fn(i, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr) == false )
		{
			CastParam1.GammaTablePtr = NULL;
			CastParam2.GammaTablePtr = NULL;
			CastParam3.GammaTablePtr = NULL;
			CastParam4.GammaTablePtr = NULL;
			return false; 
		}
	}	
	CastParam1.GammaTablePtr = NULL;
	CastParam2.GammaTablePtr = NULL;
	CastParam3.GammaTablePtr = NULL;
	CastParam4.GammaTablePtr = NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace2Exp3_II_MP(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, TCastParam &CastParam1, TCastParam &CastParam2, TCastParam &CastParam3, TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料-平行計算
{
	if ( CheckCastParamExp2(CastParam1) == false )
	{	return false; }		
	if ( CheckCastParamExp2(CastParam2) == false )
	{	return false; }	
	if ( CheckCastParamExp2(CastParam3) == false )
	{	return false; }		
	if ( CheckCastParamExp2(CastParam4) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam1) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam2) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam3) == false )
	{	return false; }
	if ( CheckCastParam(ImageW, ImageH, ImageStep, CastParam4) == false )
	{	return false; }		
	//if ( 16!=CastParam1.ImageCount || 16!=CastParam2.ImageCount || 16!=CastParam3.ImageCount || 16!=CastParam4.ImageCount)
	//{	return false; }

	unsigned char GammaTable_1[256];
	unsigned char GammaTable_2[256];
	unsigned char GammaTable_3[256];
	unsigned char GammaTable_4[256];
	float Gamma_1=1.0f, Gamma_2=1.0f, Gamma_3=1.0f, Gamma_4=1.0f;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();

	Gamma_1 = CastParam1.Gamma;
	Gamma_2 = CastParam2.Gamma;
	Gamma_3 = CastParam3.Gamma;
	Gamma_4 = CastParam4.Gamma;
	if ( true == bUseGamma )
	{	
		BuildGammaLookUpTable(Gamma_1, GammaTable_1); 
		BuildGammaLookUpTable(Gamma_2, GammaTable_2); 
		BuildGammaLookUpTable(Gamma_3, GammaTable_3); 
		BuildGammaLookUpTable(Gamma_4, GammaTable_4); 
		CastParam1.GammaTablePtr = GammaTable_1;
		CastParam2.GammaTablePtr = GammaTable_2;
		CastParam3.GammaTablePtr = GammaTable_3;
		CastParam4.GammaTablePtr = GammaTable_4;
	}
	else
	{
		CastParam1.GammaTablePtr = NULL;
		CastParam2.GammaTablePtr = NULL;
		CastParam3.GammaTablePtr = NULL;
		CastParam4.GammaTablePtr = NULL;
	}

	std::vector<unsigned char> CodeMap3;
	std::vector<unsigned char> CodeMap4;
	std::vector<unsigned char> CodeMap5;
	std::vector<unsigned char> CodeMap6;
	BuildGrayCodeMapTable(3, CodeMap3);
	BuildGrayCodeMapTable(4, CodeMap4);
	BuildGrayCodeMapTable(5, CodeMap5);
	BuildGrayCodeMapTable(6, CodeMap6);
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam1) == false )
	{	return false; }
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam2) == false )
	{	return false; }
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam3) == false )
	{	return false; }
	if ( AssignCastParamGCPtr(CodeMap3.data(), CodeMap4.data(), CodeMap5.data(), CodeMap6.data(), CastParam4) == false )
	{	return false; }

	const int BufferSize = (int)(ImageStep*ImageH);
	const int OpenMPCount = AOIDataCollect.GetOpenMPCount_General();
#pragma omp parallel for num_threads(OpenMPCount)
	for ( int i=0; i<BufferSize; i++ )
	{	PatternCast4ToSpace2Exp3_II_MP_Fn(i, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);	}

	CastParam1.GammaTablePtr = NULL;
	CastParam2.GammaTablePtr = NULL;
	CastParam3.GammaTablePtr = NULL;
	CastParam4.GammaTablePtr = NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PatternCast4ToSpace2Exp3_II_MP_Fn(int index, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const TCastParam &CastParam1, const TCastParam &CastParam2, const TCastParam &CastParam3, const TCastParam &CastParam4, TPhaseNoiseParam &NoiseParam, MASK_PTR MaskPtr, SPACE_PTR SpacePtr)//4投光影像轉成高度資料-平行計算
{
	bool IsOK = true;
	switch ( CastParam1.DecodeMode )
	{
	case DECODE_PHASE_2_2STEP_2:
		IsOK = PatternCast4ToSpace2Exp3_II_MP_Fn_2X2(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);
		break;
	case DECODE_PHASE_4_2STEP_2:
		IsOK = PatternCast4ToSpace2Exp3_II_MP_Fn_4X2(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);
		break;
	case DECODE_PHASE_4STEP_4GC_2:		
		IsOK = PatternCast4ToSpace2Exp3_II_MP_Fn_4X4GC(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);
		break;
	case DECODE_PHASE_4STEP_5GC_2:		
		IsOK = PatternCast4ToSpace2Exp3_II_MP_Fn_4X5GC(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);
		break;
	case DECODE_PHASE_4STEP_6GC_2:		
		IsOK = PatternCast4ToSpace2Exp3_II_MP_Fn_4X6GC(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);
		break;
	default:
		IsOK = PatternCast4ToSpace2Exp3_II_MP_Fn_4X4(index, ImageW, ImageH, ImageStep, CastParam1, CastParam2, CastParam3, CastParam4, NoiseParam, MaskPtr, SpacePtr);	
		break;
	}
	return IsOK;
}
