	if (index<0 || index >= BufferSize) { return false; }

	int   PhaseM_1 = 0;
	int   PhaseM_2 = 0;
	int   PhaseM_3 = 0;
	int   PhaseM_4 = 0;
	int   PhaseM_AB_1 = 0;
	int   PhaseM_AB_2 = 0;
