	float Space_AB_3 = 0.0f, Space_CD_3 = 0.0f;
	float Space_AB_4 = 0.0f, Space_CD_4 = 0.0f;
	MASK_DATA  Mask_1 = 0;
	MASK_DATA  Mask_2 = 0;
