	MASK_DATA  Mask_AB_1 = 0;
	MASK_DATA  Mask_AB_2 = 0;
	MASK_DATA  Mask_AB_3 = 0;
	MASK_DATA  Mask_AB_4 = 0;
	MASK_DATA  Mask_CD_1 = 0;
	MASK_DATA  Mask_CD_2 = 0;
	MASK_DATA  Mask_CD_3 = 0;
	MASK_DATA  Mask_CD_4 = 0;
	MASK_DATA  MaskA_1 = 0, MaskB_1 = 0;
	MASK_DATA  MaskA_2 = 0, MaskB_2 = 0;
	MASK_DATA  MaskA_3 = 0, MaskB_3 = 0;
	MASK_DATA  MaskA_4 = 0, MaskB_4 = 0;
	MASK_DATA  MaskC_1 = 0, MaskD_1 = 0;
	MASK_DATA  MaskC_2 = 0, MaskD_2 = 0;
	MASK_DATA  MaskC_3 = 0, MaskD_3 = 0;
	MASK_DATA  MaskC_4 = 0, MaskD_4 = 0;

	IMAGE_DATA *PtrA1_1 = NULL, *PtrA2_1 = NULL;
	IMAGE_DATA *PtrB1_1 = NULL, *PtrB2_1 = NULL, *PtrB3_1 = NULL;
	IMAGE_DATA *PtrA1_2 = NULL, *PtrA2_2 = NULL;
	IMAGE_DATA *PtrB1_2 = NULL, *PtrB2_2 = NULL, *PtrB3_2 = NULL;
	IMAGE_DATA *PtrA1_3 = NULL, *PtrA2_3 = NULL;
	IMAGE_DATA *PtrB1_3 = NULL, *PtrB2_3 = NULL, *PtrB3_3 = NULL;
	IMAGE_DATA *PtrA1_4 = NULL, *PtrA2_4 = NULL;
	IMAGE_DATA *PtrB1_4 = NULL, *PtrB2_4 = NULL, *PtrB3_4 = NULL;
	IMAGE_DATA *PtrC1_1 = NULL, *PtrC2_1 = NULL;
	IMAGE_DATA *PtrD1_1 = NULL, *PtrD2_1 = NULL, *PtrD3_1 = NULL;
	IMAGE_DATA *PtrC1_2 = NULL, *PtrC2_2 = NULL;
	IMAGE_DATA *PtrD1_2 = NULL, *PtrD2_2 = NULL, *PtrD3_2 = NULL;
	IMAGE_DATA *PtrC1_3 = NULL, *PtrC2_3 = NULL;
	IMAGE_DATA *PtrD1_3 = NULL, *PtrD2_3 = NULL, *PtrD3_3 = NULL;
	IMAGE_DATA *PtrC1_4 = NULL, *PtrC2_4 = NULL;
	IMAGE_DATA *PtrD1_4 = NULL, *PtrD2_4 = NULL, *PtrD3_4 = NULL;
	PHASE_DATA *BasePhasePtr_1 = NULL, *BasePhasePtr_2 = NULL, *BasePhasePtr_3 = NULL, *BasePhasePtr_4 = NULL;
	SPACE_DATA *HeightFactorPtr_1 = NULL, *HeightFactorPtr_2 = NULL, *HeightFactorPtr_3 = NULL, *HeightFactorPtr_4 = NULL;
	SPACE_DATA *HeightFactorPtr_1_2 = NULL, *HeightFactorPtr_2_2 = NULL, *HeightFactorPtr_3_2 = NULL, *HeightFactorPtr_4_2 = NULL;
	double     *HeightFactor0_1 = NULL, *HeightFactor0_2 = NULL, *HeightFactor0_3 = NULL, *HeightFactor0_4 = NULL;
	double     *HeightFactor1_1 = NULL, *HeightFactor1_2 = NULL, *HeightFactor1_3 = NULL, *HeightFactor1_4 = NULL;
	double     *HeightFactor2_1 = NULL, *HeightFactor2_2 = NULL, *HeightFactor2_3 = NULL, *HeightFactor2_4 = NULL;
	unsigned char *GammaTablePtr_1 = NULL, *GammaTablePtr_2 = NULL, *GammaTablePtr_3 = NULL, *GammaTablePtr_4 = NULL;

	PHASE_DATA PhaseA_1 = 0, PhaseB_1 = 0;
	PHASE_DATA PhaseA_2 = 0, PhaseB_2 = 0;
	PHASE_DATA PhaseA_3 = 0, PhaseB_3 = 0;
	PHASE_DATA PhaseA_4 = 0, PhaseB_4 = 0;
	PHASE_DATA PhaseC_1 = 0, PhaseD_1 = 0;
	PHASE_DATA PhaseC_2 = 0, PhaseD_2 = 0;
	PHASE_DATA PhaseC_3 = 0, PhaseD_3 = 0;
	PHASE_DATA PhaseC_4 = 0, PhaseD_4 = 0;

	PHASE_DATA dA1_1 = 0, dA2_1 = 0;
	PHASE_DATA dB1_1 = 0, dB2_1 = 0, dB3_1 = 0;
	PHASE_DATA dA1_2 = 0, dA2_2 = 0;
	PHASE_DATA dB1_2 = 0, dB2_2 = 0, dB3_2 = 0;
	PHASE_DATA dA1_3 = 0, dA2_3 = 0;
	PHASE_DATA dB1_3 = 0, dB2_3 = 0, dB3_3 = 0;
	PHASE_DATA dA1_4 = 0, dA2_4 = 0;
	PHASE_DATA dB1_4 = 0, dB2_4 = 0, dB3_4 = 0;
	PHASE_DATA dC1_1 = 0, dC2_1 = 0;
	PHASE_DATA dD1_1 = 0, dD2_1 = 0, dD3_1 = 0;
	PHASE_DATA dC1_2 = 0, dC2_2 = 0;
	PHASE_DATA dD1_2 = 0, dD2_2 = 0, dD3_2 = 0;
	PHASE_DATA dC1_3 = 0, dC2_3 = 0;
	PHASE_DATA dD1_3 = 0, dD2_3 = 0, dD3_3 = 0;
	PHASE_DATA dC1_4 = 0, dC2_4 = 0;
	PHASE_DATA dD1_4 = 0, dD2_4 = 0, dD3_4 = 0;

	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int   PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const bool  bUseGamma = AOIDataCollect.GetPhaseUseGammaCalibration();
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;

	const double PerA = CastParam1.PerA;
	const double PerB = CastParam1.PerB;
	//const double PerD = Calc2PhaseNewPeriode(PerA, PerB);

	PtrA1_1 = CastParam1.PtrA1;	PtrA2_1 = CastParam1.PtrA2;
	PtrB1_1 = CastParam1.PtrB1;	PtrB2_1 = CastParam1.PtrB2;	PtrB3_1 = CastParam1.PtrB3;
	PtrA1_2 = CastParam2.PtrA1;	PtrA2_2 = CastParam2.PtrA2;
	PtrB1_2 = CastParam2.PtrB1;	PtrB2_2 = CastParam2.PtrB2;	PtrB3_2 = CastParam2.PtrB3;
	PtrA1_3 = CastParam3.PtrA1;	PtrA2_3 = CastParam3.PtrA2;
	PtrB1_3 = CastParam3.PtrB1;	PtrB2_3 = CastParam3.PtrB2;	PtrB3_3 = CastParam3.PtrB3;
	PtrA1_4 = CastParam4.PtrA1;	PtrA2_4 = CastParam4.PtrA2;
	PtrB1_4 = CastParam4.PtrB1;	PtrB2_4 = CastParam4.PtrB2;	PtrB3_4 = CastParam4.PtrB3;

	PtrC1_1 = CastParam1.PtrC1;	PtrC2_1 = CastParam1.PtrC2;
	PtrD1_1 = CastParam1.PtrD1;	PtrD2_1 = CastParam1.PtrD2;	PtrD3_1 = CastParam1.PtrD3;
	PtrC1_2 = CastParam2.PtrC1;	PtrC2_2 = CastParam2.PtrC2;
	PtrD1_2 = CastParam2.PtrD1;	PtrD2_2 = CastParam2.PtrD2;	PtrD3_2 = CastParam2.PtrD3;
	PtrC1_3 = CastParam3.PtrC1;	PtrC2_3 = CastParam3.PtrC2;
	PtrD1_3 = CastParam3.PtrD1;	PtrD2_3 = CastParam3.PtrD2;	PtrD3_3 = CastParam3.PtrD3;
	PtrC1_4 = CastParam4.PtrC1;	PtrC2_4 = CastParam4.PtrC2;
	PtrD1_4 = CastParam4.PtrD1;	PtrD2_4 = CastParam4.PtrD2;	PtrD3_4 = CastParam4.PtrD3;

	BasePhasePtr_1 = CastParam1.ZeroPhasePtr;
	BasePhasePtr_2 = CastParam2.ZeroPhasePtr;
	BasePhasePtr_3 = CastParam3.ZeroPhasePtr;
	BasePhasePtr_4 = CastParam4.ZeroPhasePtr;
	HeightFactorPtr_1 = CastParam1.HeightFactorPtr;
	HeightFactorPtr_2 = CastParam2.HeightFactorPtr;
	HeightFactorPtr_3 = CastParam3.HeightFactorPtr;
	HeightFactorPtr_4 = CastParam4.HeightFactorPtr;
