	PtrC1_4 = CastParam4.PtrC1;	PtrC2_4 = CastParam4.PtrC2;	PtrC3_4 = CastParam4.PtrC3;	PtrC4_4 = CastParam4.PtrC4;
	PtrD1_4 = CastParam4.PtrD1;	PtrD2_4 = CastParam4.PtrD2;	PtrD3_4 = CastParam4.PtrD3;	PtrD4_4 = CastParam4.PtrD4;

